def _normalize_virtual_path(value: str) -> str:
    return str(value or "").replace("\\", "/").strip().lower()


def _mesh_import_candidate_virtual_paths(source_path: Path) -> Tuple[str, ...]:
    normalized_parts = [part for part in source_path.expanduser().parts if part]
    if not normalized_parts:
        return ()
    lowered_parts = [str(part).strip() for part in normalized_parts]
    ordered: List[str] = []
    seen: set[str] = set()

    def _append(parts: Sequence[str]) -> None:
        candidate = PurePosixPath(*parts).as_posix().strip()
        normalized_candidate = _normalize_virtual_path(candidate)
        if not normalized_candidate or normalized_candidate in seen:
            return
        seen.add(normalized_candidate)
        ordered.append(candidate)

    for index, part in enumerate(lowered_parts):
        if str(part).strip().lower() == "files" and index + 1 < len(lowered_parts):
            _append(lowered_parts[index + 1 :])
            break

    for index, part in enumerate(lowered_parts):
        if str(part).strip().lower() in _MESH_IMPORT_ASSET_ROOT_MARKERS:
            _append(lowered_parts[index:])
            break

    _append([source_path.name])
    return tuple(ordered)


def _mesh_import_loose_texture_preferred_paths(source_path: Path) -> Tuple[str, ...]:
    if source_path.suffix.lower() != ".dds":
        return ()
    if not any(str(part).strip().lower() == "files" for part in source_path.expanduser().parts):
        return ()

    ordered: List[str] = []
    seen: set[str] = set()

    def _append(value: str) -> None:
        normalized = _normalize_virtual_path(value)
        if not normalized or normalized in seen:
            return
        seen.add(normalized)
        ordered.append(value.replace("\\", "/"))

    for candidate in _mesh_import_candidate_virtual_paths(source_path):
        parts = tuple(part for part in PurePosixPath(candidate.replace("\\", "/")).parts if part)
        if len(parts) < 2 or parts[0].lower() not in _MESH_IMPORT_ASSET_ROOT_MARKERS:
            continue
        basename = parts[-1]
        if not basename.lower().endswith(".dds"):
            continue
        if len(parts) == 2:
            _append(PurePosixPath(parts[0], "texture", basename).as_posix())
        elif parts[1].lower() in {"texture", "textures"}:
            _append(PurePosixPath(parts[0], "texture", basename).as_posix())
    return tuple(ordered)


def _mesh_import_modelproperty_variant(mesh_path: str) -> str:
    parts = list(PurePosixPath(str(mesh_path or "").replace("\\", "/")).parts)
    for index, part in enumerate(parts):
        if part.lower() == "model":
            parts[index] = "modelproperty"
            return PurePosixPath(*parts).as_posix()
    return ""


def _mesh_import_companion_stem(path: str) -> str:
    pure = PurePosixPath(str(path or "").replace("\\", "/").strip())
    name = pure.name.lower()
    for suffix in (".pac.xml", ".pam.xml", ".pamlod.xml"):
        if name.endswith(suffix):
            return name[: -len(suffix)]
    suffix = pure.suffix.lower()
    if suffix in {".pac_xml", ".pam_xml", ".pamlod_xml", ".pami", ".xml", ".hkx", ".hkt", ".meshinfo"}:
        return pure.stem.lower()
    return pure.stem.lower()


def _mesh_import_is_exact_runtime_companion(primary_entry: ArchiveEntry, related_entry: ArchiveEntry) -> bool:
    related_extension = str(getattr(related_entry, "extension", "") or "").strip().lower()
    if related_extension not in _MESH_IMPORT_AUTOCOPY_COMPANION_EXTENSIONS:
        return False
    primary_path = str(getattr(primary_entry, "path", "") or "").replace("\\", "/").strip()
    related_path = str(getattr(related_entry, "path", "") or "").replace("\\", "/").strip()
    if not primary_path or not related_path or primary_path.lower() == related_path.lower():
        return False
    primary_stem = PurePosixPath(primary_path).stem.lower()
    related_stem = _mesh_import_companion_stem(related_path)
    if not primary_stem or related_stem != primary_stem:
        return False
    lowered_related = related_path.lower()
    if related_extension in {".hkx", ".hkt"}:
        return "meshphysics" in lowered_related or "physics" in lowered_related
    if related_extension == ".meshinfo":
        return True
    return "modelproperty" in lowered_related or related_extension in {".pami", ".xml"}


def _mesh_import_auto_companion_entries(
    primary_entry: ArchiveEntry,
    preview_result: MeshImportPreviewResult,
) -> Tuple[ArchiveEntry, ...]:
    entries: List[ArchiveEntry] = []
    seen: set[str] = set()
    for reference in tuple(getattr(preview_result, "texture_references", ()) or ()):
        related_entry = getattr(reference, "resolved_entry", None)
        if not isinstance(related_entry, ArchiveEntry):
            continue
        related_extension = str(getattr(related_entry, "extension", "") or "").strip().lower()
        if related_extension in MESH_IMPORT_SIDECAR_EXTENSIONS:
            # Unchanged material XML is optional for mesh-only edits.  Generated
            # or user-selected sidecars still flow through supplemental/related
            # export paths with explicit manifest notes.
            continue
        if related_extension in {".hkx", ".hkt"}:
            # Physics/collision companions are often unchanged archive data.  Keep
            # them out of source-owned loose packages unless the user explicitly
            # selects them in the related-file picker.
            continue
        if not _mesh_import_is_exact_runtime_companion(primary_entry, related_entry):
            continue
        key = str(getattr(related_entry, "path", "") or "").replace("\\", "/").strip().lower()
        if not key or key in seen:
            continue
        entries.append(related_entry)
        seen.add(key)
    return tuple(entries)


def _mesh_import_target_sidecar_candidates_for_base(
    mesh_path: str,
    source_sidecar_path: Path,
) -> Tuple[str, ...]:
    mesh_pure = PurePosixPath(str(mesh_path or "").replace("\\", "/").strip())
    if not mesh_pure.name:
        return ()

    mesh_extension = mesh_pure.suffix.lower()
    source_extension = source_sidecar_path.suffix.lower()
    source_name = source_sidecar_path.name.lower()
    candidates: List[str] = []

    def _append(candidate: PurePosixPath) -> None:
        value = candidate.as_posix().strip()
        if value and value not in candidates:
            candidates.append(value)

    if source_extension in {".pac_xml", ".pam_xml", ".pamlod_xml", ".app_xml", ".prefabdata_xml"}:
        _append(mesh_pure.with_suffix(source_extension))
    elif source_extension == ".pami":
        _append(mesh_pure.with_suffix(".pami"))
    elif source_extension == ".xml":
        if source_name.endswith(".pac.xml") or mesh_extension == ".pac":
            _append(mesh_pure.with_name(f"{mesh_pure.name}.xml"))
            _append(mesh_pure.with_suffix(".pac_xml"))
        elif source_name.endswith(".pam.xml") or mesh_extension == ".pam":
            _append(mesh_pure.with_name(f"{mesh_pure.name}.xml"))
            _append(mesh_pure.with_suffix(".pam_xml"))
        elif source_name.endswith(".pamlod.xml") or mesh_extension == ".pamlod":
            _append(mesh_pure.with_name(f"{mesh_pure.name}.xml"))
            _append(mesh_pure.with_suffix(".pamlod_xml"))
        elif source_name.endswith(".app.xml"):
            _append(mesh_pure.with_suffix(".app_xml"))
        elif source_name.endswith(".prefabdata.xml"):
            _append(mesh_pure.with_suffix(".prefabdata_xml"))
        else:
            _append(mesh_pure.with_suffix(".xml"))
    return tuple(candidates)


def _mesh_import_sidecar_preferred_paths(
    entry: ArchiveEntry,
    source_sidecar_path: Path,
    related_entries_by_extension: Mapping[str, Sequence[ArchiveEntry]],
) -> Tuple[str, ...]:
    source_extension = source_sidecar_path.suffix.lower()
    ordered: List[str] = []
    seen: set[str] = set()

    def _append(value: str) -> None:
        normalized = _normalize_virtual_path(value)
        if not normalized or normalized in seen:
            return
        seen.add(normalized)
        ordered.append(str(value).replace("\\", "/"))

    target_names = {
        PurePosixPath(path).name.lower()
        for base_path in (entry.path, _mesh_import_modelproperty_variant(entry.path))
        for path in _mesh_import_target_sidecar_candidates_for_base(base_path, source_sidecar_path)
        if path
    }
    related_by_extension = list(related_entries_by_extension.get(source_extension, ()))
    for related_entry in related_by_extension:
        if PurePosixPath(related_entry.path.replace("\\", "/")).name.lower() in target_names:
            _append(related_entry.path)
    if len(related_by_extension) == 1:
        _append(related_by_extension[0].path)

    modelproperty_path = _mesh_import_modelproperty_variant(entry.path)
    for base_path in (modelproperty_path, entry.path):
        if not base_path:
            continue
        for candidate in _mesh_import_target_sidecar_candidates_for_base(base_path, source_sidecar_path):
            _append(candidate)
    return tuple(ordered)


def _resolve_supplemental_target_entry(
    source_path: Path,
    *,
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    preferred_paths: Sequence[str] = (),
) -> Tuple[Optional[ArchiveEntry], str]:
    candidate_virtual_paths: List[str] = []
    seen_virtual_paths: set[str] = set()
    for raw_path in list(preferred_paths) + list(_mesh_import_candidate_virtual_paths(source_path)):
        normalized = _normalize_virtual_path(raw_path)
        if not normalized or normalized in seen_virtual_paths:
            continue
        seen_virtual_paths.add(normalized)
        candidate_virtual_paths.append(raw_path)

    if archive_entries_by_normalized_path is not None:
        for candidate_virtual_path in candidate_virtual_paths:
            normalized = _normalize_virtual_path(candidate_virtual_path)
            entries = archive_entries_by_normalized_path.get(normalized, ())
            if entries:
                return entries[0], candidate_virtual_path.replace("\\", "/")

    basename = source_path.name.lower()
    if archive_entries_by_basename is not None and basename:
        entries = archive_entries_by_basename.get(basename, ())
        if len(entries) == 1:
            return entries[0], entries[0].path

    if candidate_virtual_paths:
        return None, candidate_virtual_paths[0].replace("\\", "/")
    return None, ""


def _build_mesh_import_local_dds_lookup(
    supplemental_files: Sequence[Path],
) -> Tuple[Dict[str, Path], Dict[str, Path]]:
    by_normalized_path: Dict[str, Path] = {}
    by_basename: Dict[str, Path] = {}
    for supplemental_path in supplemental_files:
        if supplemental_path.suffix.lower() != ".dds":
            continue
        resolved_path = supplemental_path.expanduser().resolve()
        for candidate_virtual_path in _mesh_import_candidate_virtual_paths(resolved_path):
            normalized = _normalize_virtual_path(candidate_virtual_path)
            if normalized and normalized not in by_normalized_path:
                by_normalized_path[normalized] = resolved_path
        basename = resolved_path.name.lower()
        if basename and basename not in by_basename:
            by_basename[basename] = resolved_path
    return by_normalized_path, by_basename


def _apply_mesh_import_local_sidecar_texture_overrides(
    preview_model: ModelPreviewData,
    parsed_mesh: Optional[ParsedMesh],
    sidecar_texture_bindings: Sequence[object],
    supplemental_dds_by_normalized_path: Mapping[str, Path],
    supplemental_dds_by_basename: Mapping[str, Path],
    *,
    texconv_path: Optional[Path],
) -> List[str]:
    if not getattr(preview_model, "meshes", None) or not sidecar_texture_bindings:
        return []

    from cdmw.core.archive import (
        _is_visible_model_texture_type,
        _is_anonymous_model_submesh_reference_key,
        _iter_model_submesh_reference_candidates,
        _iter_parsed_model_submeshes,
        _model_texture_hint_priority,
        _model_texture_semantic_priority,
        _normalize_model_submesh_reference,
        _resolve_model_texture_semantics,
    )
    from cdmw.core.pipeline import ensure_dds_display_preview_png, parse_dds
    from cdmw.core.upscale_profiles import normalize_texture_reference_for_sidecar_lookup

    resolved_texconv_path = texconv_path.expanduser().resolve() if texconv_path is not None and texconv_path.expanduser().is_file() else None
    parsed_submeshes = _iter_parsed_model_submeshes(parsed_mesh)
    preview_cache: Dict[str, str] = {}
    resolved_by_submesh: Dict[str, Tuple[Tuple[int, int, int, int], Path, str, str, str]] = {}
    global_visible_bindings: List[Tuple[Path, str, str, str]] = []
    fallback_visible_bindings: List[Tuple[Tuple[int, int, int, int], Path, str, str, str]] = []
    seen_fallback_binding_keys: set[Tuple[str, str, str]] = set()
    seen_global_binding_keys: set[Tuple[str, str]] = set()
    promoted_anonymous_fallback = False

    for binding in sidecar_texture_bindings:
        texture_path = str(getattr(binding, "texture_path", "") or "").strip()
        if not texture_path:
            continue
        normalized_texture_path = normalize_texture_reference_for_sidecar_lookup(texture_path)
        basename = PurePosixPath(normalized_texture_path or texture_path.replace("\\", "/")).name.lower()
        override_path = supplemental_dds_by_normalized_path.get(normalized_texture_path)
        if override_path is None and basename:
            override_path = supplemental_dds_by_basename.get(basename)
        if override_path is None:
            continue

        parameter_name = str(getattr(binding, "parameter_name", "") or "").strip()
        texture_type, semantic_subtype, confidence = _resolve_model_texture_semantics(texture_path)
        priority = _model_texture_hint_priority(parameter_name)
        if priority is None:
            priority = _model_texture_semantic_priority(texture_type, semantic_subtype)
        if priority[0] <= 0 and not _is_visible_model_texture_type(texture_type):
            continue

        candidate_key = (priority[0], priority[1], confidence, -len(texture_path or override_path.name))
        submesh_name = str(getattr(binding, "submesh_name", "") or "").strip()
        submesh_keys = _iter_model_submesh_reference_candidates(submesh_name)
        fallback_binding_key = (
            _normalize_model_submesh_reference(submesh_name),
            basename,
            parameter_name.lower(),
        )
        if fallback_binding_key not in seen_fallback_binding_keys:
            seen_fallback_binding_keys.add(fallback_binding_key)
            fallback_visible_bindings.append((candidate_key, override_path, parameter_name, submesh_name, texture_path))
        if submesh_keys:
            for submesh_key in submesh_keys:
                existing = resolved_by_submesh.get(submesh_key)
                if existing is None or candidate_key > existing[0]:
                    resolved_by_submesh[submesh_key] = (
                        candidate_key,
                        override_path,
                        parameter_name,
                        submesh_name,
                        texture_path,
                    )
        else:
            global_key = (basename, parameter_name.lower())
            if global_key not in seen_global_binding_keys:
                seen_global_binding_keys.add(global_key)
                global_visible_bindings.append((override_path, parameter_name, submesh_name, texture_path))

    def _preview_path_for_dds(dds_path: Path) -> str:
        cache_key = str(dds_path).lower()
        preview_path = preview_cache.get(cache_key, "")
        if preview_path:
            return preview_path
        dds_info = None
        try:
            dds_info = parse_dds(dds_path)
        except Exception:
            dds_info = None
        preview_path = ensure_dds_display_preview_png(
            resolved_texconv_path,
            dds_path,
            dds_info=dds_info,
        )
        preview_cache[cache_key] = preview_path
        return preview_path

    assigned_count = 0
    unresolved_meshes: List[ModelPreviewMesh] = []
    unresolved_mesh_indices_by_id: Dict[int, int] = {}

    def _mesh_reference_candidates_for_index(mesh_index: int, mesh: ModelPreviewMesh) -> Tuple[str, ...]:
        parsed_submesh = parsed_submeshes[mesh_index] if 0 <= mesh_index < len(parsed_submeshes) else None
        return _iter_model_submesh_reference_candidates(
            str(getattr(parsed_submesh, "name", "") or ""),
            str(getattr(parsed_submesh, "material", "") or ""),
            str(getattr(parsed_submesh, "texture", "") or ""),
            str(getattr(mesh, "material_name", "") or ""),
            str(getattr(mesh, "texture_name", "") or ""),
        )

    def _mesh_preview_identity_is_anonymous(mesh_index: int, mesh: ModelPreviewMesh) -> bool:
        candidate_keys = _mesh_reference_candidates_for_index(mesh_index, mesh)
        return not candidate_keys or all(_is_anonymous_model_submesh_reference_key(candidate_key) for candidate_key in candidate_keys)

    for mesh_index, mesh in enumerate(preview_model.meshes):
        if str(getattr(mesh, "preview_texture_path", "") or "").strip():
            continue
        candidate_keys = _mesh_reference_candidates_for_index(mesh_index, mesh)
        best_match: Optional[Tuple[Tuple[int, int, int, int], Path, str, str, str]] = None
        for candidate_key_text in candidate_keys:
            resolved = resolved_by_submesh.get(candidate_key_text)
            if resolved is None:
                continue
            if best_match is None or resolved[0] > best_match[0]:
                best_match = resolved
        if best_match is None:
            unresolved_meshes.append(mesh)
            unresolved_mesh_indices_by_id[id(mesh)] = mesh_index
            continue
        _candidate_key, override_path, _parameter_name, submesh_name, texture_path = best_match
        try:
            mesh.preview_texture_path = _preview_path_for_dds(override_path)
            mesh.texture_name = texture_path or override_path.name
            mesh.preview_texture_flip_vertical = False
            current_material_name = str(getattr(mesh, "material_name", "") or "").strip()
            if submesh_name and not current_material_name:
                mesh.material_name = submesh_name
            assigned_count += 1
        except Exception:
            continue

    if not global_visible_bindings and unresolved_meshes and fallback_visible_bindings:
        unresolved_meshes_are_anonymous = all(
            _mesh_preview_identity_is_anonymous(unresolved_mesh_indices_by_id.get(id(mesh), -1), mesh)
            for mesh in unresolved_meshes
        )
        unique_named_sidecar_submeshes = {
            _normalize_model_submesh_reference(submesh_name)
            for _candidate_key, _override_path, _parameter_name, submesh_name, _texture_path in fallback_visible_bindings
            if _normalize_model_submesh_reference(submesh_name)
        }
        should_promote_fallback = (
            len(preview_model.meshes) == 1
            or (
                unresolved_meshes_are_anonymous
                and (
                    len(unresolved_meshes) == 1
                    or len(parsed_submeshes) <= 1
                    or len(unique_named_sidecar_submeshes) == 1
                )
            )
        )
        if should_promote_fallback:
            fallback_visible_bindings.sort(key=lambda item: item[0], reverse=True)
            _candidate_key, override_path, parameter_name, submesh_name, texture_path = fallback_visible_bindings[0]
            global_visible_bindings.append((override_path, parameter_name, submesh_name, texture_path))
            promoted_anonymous_fallback = True

    if global_visible_bindings and unresolved_meshes:
        if len(global_visible_bindings) == 1:
            override_path, _parameter_name, submesh_name, texture_path = global_visible_bindings[0]
            for mesh in unresolved_meshes:
                if str(getattr(mesh, "preview_texture_path", "") or "").strip():
                    continue
                try:
                    mesh.preview_texture_path = _preview_path_for_dds(override_path)
                    mesh.texture_name = texture_path or override_path.name
                    mesh.preview_texture_flip_vertical = False
                    current_material_name = str(getattr(mesh, "material_name", "") or "").strip()
                    if submesh_name and not current_material_name:
                        mesh.material_name = submesh_name
                    assigned_count += 1
                except Exception:
                    continue
        else:
            binding_index = 0
            for mesh in unresolved_meshes:
                if str(getattr(mesh, "preview_texture_path", "") or "").strip():
                    continue
                if binding_index >= len(global_visible_bindings):
                    break
                override_path, _parameter_name, submesh_name, texture_path = global_visible_bindings[binding_index]
                binding_index += 1
                try:
                    mesh.preview_texture_path = _preview_path_for_dds(override_path)
                    mesh.texture_name = texture_path or override_path.name
                    mesh.preview_texture_flip_vertical = False
                    current_material_name = str(getattr(mesh, "material_name", "") or "").strip()
                    if submesh_name and not current_material_name:
                        mesh.material_name = submesh_name
                    assigned_count += 1
                except Exception:
                    continue

    if assigned_count <= 0:
        return []
    info_lines = [
        f"Applied {assigned_count:,} local sidecar-driven texture preview binding(s) from the selected supplemental files."
    ]
    if promoted_anonymous_fallback:
        info_lines.append(
            "Used a local sidecar texture fallback because the rebuilt preview did not preserve a reliable submesh/material name match."
        )
    return info_lines


def _apply_mesh_import_local_support_texture_overrides(
    preview_model: ModelPreviewData,
    parsed_mesh: Optional[ParsedMesh],
    sidecar_texture_bindings: Sequence[object],
    supplemental_dds_by_normalized_path: Mapping[str, Path],
    supplemental_dds_by_basename: Mapping[str, Path],
    *,
    texconv_path: Optional[Path],
) -> List[str]:
    if not getattr(preview_model, "meshes", None) or not sidecar_texture_bindings:
        return []

    from collections import defaultdict

    from cdmw.core.archive import (
        _infer_model_preview_normal_strength,
        _infer_model_preview_texture_slot,
        _iter_model_submesh_reference_candidates,
        _iter_parsed_model_submeshes,
        _model_texture_candidate_slot_priority,
        _model_texture_slot_hint_priority,
        _normalize_model_submesh_reference,
        _refine_model_texture_semantic_from_hint,
        _resolve_model_texture_semantic_details,
    )
    from cdmw.core.pipeline import ensure_dds_display_preview_png, parse_dds
    from cdmw.core.upscale_profiles import normalize_texture_reference_for_sidecar_lookup

    resolved_texconv_path = texconv_path.expanduser().resolve() if texconv_path is not None and texconv_path.expanduser().is_file() else None
    parsed_submeshes = _iter_parsed_model_submeshes(parsed_mesh)
    preview_cache: Dict[str, str] = {}
    support_slots = ("normal", "material", "height")
    slot_labels = {
        "normal": "local normal-map override(s)",
        "material": "local material-mask override(s)",
        "height": "local height/displacement override(s)",
    }
    resolved_by_submesh: Dict[Tuple[str, str], Tuple[Tuple[int, int, int, int], Path, str, str, str]] = {}
    global_bindings: Dict[str, List[Tuple[Tuple[int, int, int, int], Path, str, str, str]]] = defaultdict(list)
    seen_global_keys: set[Tuple[str, str, str]] = set()
    assigned_by_slot: Dict[str, int] = {slot: 0 for slot in support_slots}

    for binding in sidecar_texture_bindings:
        texture_path = str(getattr(binding, "texture_path", "") or "").strip()
        if not texture_path:
            continue
        parameter_name = str(getattr(binding, "parameter_name", "") or "").strip()
        slot_name = _infer_model_preview_texture_slot(texture_path, semantic_hint=parameter_name)
        if slot_name not in support_slots:
            continue
        normalized_texture_path = normalize_texture_reference_for_sidecar_lookup(texture_path)
        basename = PurePosixPath(normalized_texture_path or texture_path.replace("\\", "/")).name.lower()
        override_path = supplemental_dds_by_normalized_path.get(normalized_texture_path)
        if override_path is None and basename:
            override_path = supplemental_dds_by_basename.get(basename)
        if override_path is None:
            continue

        slot_priority = (
            _model_texture_slot_hint_priority(slot_name, parameter_name)
            or _model_texture_candidate_slot_priority(slot_name, texture_path)
            or (0, 0)
        )
        candidate_key = (
            slot_priority[0],
            slot_priority[1],
            len(parameter_name),
            -len(texture_path or override_path.name),
        )
        submesh_name = str(getattr(binding, "submesh_name", "") or "").strip()
        submesh_keys = _iter_model_submesh_reference_candidates(submesh_name)
        if submesh_keys:
            for submesh_key in submesh_keys:
                resolved_key = (slot_name, submesh_key)
                existing = resolved_by_submesh.get(resolved_key)
                if existing is None or candidate_key > existing[0]:
                    resolved_by_submesh[resolved_key] = (
                        candidate_key,
                        override_path,
                        parameter_name,
                        submesh_name,
                        texture_path,
                    )
        else:
            global_key = (slot_name, basename, parameter_name.lower())
            if global_key not in seen_global_keys:
                seen_global_keys.add(global_key)
                global_bindings[slot_name].append(
                    (
                        candidate_key,
                        override_path,
                        parameter_name,
                        submesh_name,
                        texture_path,
                    )
                )

    def _preview_path_for_dds(dds_path: Path) -> str:
        cache_key = str(dds_path).lower()
        preview_path = preview_cache.get(cache_key, "")
        if preview_path:
            return preview_path
        dds_info = None
        try:
            dds_info = parse_dds(dds_path)
        except Exception:
            dds_info = None
        preview_path = ensure_dds_display_preview_png(
            resolved_texconv_path,
            dds_path,
            dds_info=dds_info,
        )
        preview_cache[cache_key] = preview_path
        return preview_path

    def _assign_slot(
        mesh: ModelPreviewMesh,
        slot_name: str,
        override_path: Path,
        parameter_name: str,
        texture_path: str,
    ) -> bool:
        try:
            preview_path = _preview_path_for_dds(override_path)
        except Exception:
            return False
        if slot_name == "normal":
            mesh.preview_normal_texture_path = preview_path
            mesh.preview_normal_texture_name = texture_path or override_path.name
            mesh.preview_normal_texture_strength = _infer_model_preview_normal_strength(
                base_texture_path=str(getattr(mesh, "texture_name", "") or "").strip(),
                normal_texture_path=texture_path or override_path.name,
                material_name=str(getattr(mesh, "material_name", "") or "").strip(),
                semantic_hint=parameter_name,
                prefer_stronger=False,
            )
            return True
        if slot_name == "material":
            semantic_type, semantic_subtype, _confidence, packed_channels = _resolve_model_texture_semantic_details(
                texture_path or override_path.name
            )
            semantic_type, semantic_subtype = _refine_model_texture_semantic_from_hint(
                semantic_type,
                semantic_subtype,
                parameter_name,
            )
            mesh.preview_material_texture_path = preview_path
            mesh.preview_material_texture_name = texture_path or override_path.name
            mesh.preview_material_texture_type = semantic_type
            mesh.preview_material_texture_subtype = semantic_subtype
            mesh.preview_material_texture_packed_channels = tuple(packed_channels)
            return True
        if slot_name == "height":
            mesh.preview_height_texture_path = preview_path
            mesh.preview_height_texture_name = texture_path or override_path.name
            return True
        return False

    for mesh_index, mesh in enumerate(preview_model.meshes):
        parsed_submesh = parsed_submeshes[mesh_index] if mesh_index < len(parsed_submeshes) else None
        candidate_keys = _iter_model_submesh_reference_candidates(
            str(getattr(parsed_submesh, "name", "") or ""),
            str(getattr(parsed_submesh, "material", "") or ""),
            str(getattr(parsed_submesh, "texture", "") or ""),
            str(getattr(mesh, "material_name", "") or ""),
            str(getattr(mesh, "texture_name", "") or ""),
        )
        for slot_name in support_slots:
            best_match: Optional[Tuple[Tuple[int, int, int, int], Path, str, str, str]] = None
            for candidate_key_text in candidate_keys:
                resolved = resolved_by_submesh.get((slot_name, candidate_key_text))
                if resolved is None:
                    continue
                if best_match is None or resolved[0] > best_match[0]:
                    best_match = resolved
            if best_match is None:
                continue
            _candidate_key, override_path, parameter_name, _submesh_name, texture_path = best_match
            if _assign_slot(mesh, slot_name, override_path, parameter_name, texture_path):
                assigned_by_slot[slot_name] += 1

    for slot_name in support_slots:
        bindings = global_bindings.get(slot_name, [])
        if not bindings:
            continue
        bindings.sort(key=lambda item: item[0], reverse=True)
        unresolved_meshes = [
            mesh
            for mesh in preview_model.meshes
            if not str(getattr(mesh, f"preview_{slot_name}_texture_path", "") or "").strip()
        ]
        if not unresolved_meshes:
            continue
        if len(bindings) == 1:
            _candidate_key, override_path, parameter_name, _submesh_name, texture_path = bindings[0]
            for mesh in unresolved_meshes:
                if _assign_slot(mesh, slot_name, override_path, parameter_name, texture_path):
                    assigned_by_slot[slot_name] += 1
            continue
        binding_index = 0
        for mesh in unresolved_meshes:
            if binding_index >= len(bindings):
                break
            _candidate_key, override_path, parameter_name, _submesh_name, texture_path = bindings[binding_index]
            binding_index += 1
            if _assign_slot(mesh, slot_name, override_path, parameter_name, texture_path):
                assigned_by_slot[slot_name] += 1

    total_assigned = sum(assigned_by_slot.values())
    if total_assigned <= 0:
        return []
    info_lines = [f"Applied {total_assigned:,} local DDS support-map override(s) from the selected supplemental files."]
    for slot_name in support_slots:
        count = assigned_by_slot[slot_name]
        if count > 0:
            info_lines.append(f"{slot_labels[slot_name].capitalize()}: {count:,}.")
    return info_lines


def _apply_mesh_import_local_texture_overrides(
    preview_model: ModelPreviewData,
    supplemental_dds_by_normalized_path: Mapping[str, Path],
    supplemental_dds_by_basename: Mapping[str, Path],
    *,
    texconv_path: Optional[Path],
) -> List[str]:
    if not getattr(preview_model, "meshes", None):
        return []

    from cdmw.core.pipeline import ensure_dds_display_preview_png, parse_dds

    resolved_texconv_path = texconv_path.expanduser().resolve() if texconv_path is not None and texconv_path.expanduser().is_file() else None
    preview_cache: Dict[str, str] = {}
    override_count = 0
    unresolved_names: List[str] = []
    for mesh in preview_model.meshes:
        texture_name = str(getattr(mesh, "texture_name", "") or "").strip()
        if not texture_name:
            continue
        normalized_texture_name = _normalize_virtual_path(texture_name)
        basename = PurePosixPath(texture_name.replace("\\", "/")).name.lower()
        override_path = supplemental_dds_by_normalized_path.get(normalized_texture_name)
        if override_path is None and basename:
            override_path = supplemental_dds_by_basename.get(basename)
        if override_path is None:
            if texture_name not in unresolved_names and len(unresolved_names) < 5:
                unresolved_names.append(texture_name)
            continue
        cache_key = str(override_path).lower()
        preview_path = preview_cache.get(cache_key, "")
        if not preview_path:
            dds_info = None
            try:
                dds_info = parse_dds(override_path)
            except Exception:
                dds_info = None
            preview_path = ensure_dds_display_preview_png(
                resolved_texconv_path,
                override_path,
                dds_info=dds_info,
            )
            preview_cache[cache_key] = preview_path
        mesh.preview_texture_path = preview_path
        mesh.preview_texture_flip_vertical = False
        override_count += 1

    info_lines: List[str] = []
    if override_count > 0:
        info_lines.append(f"Applied {override_count:,} local DDS override texture(s) from the selected supplemental files.")
    return info_lines


def _merge_sidecar_text_maps(
    base_map: Mapping[str, Tuple[str, ...]],
    extra_map: Mapping[str, Tuple[str, ...]],
) -> Dict[str, Tuple[str, ...]]:
    merged: Dict[str, List[str]] = {key: list(values) for key, values in base_map.items()}
    for key, values in extra_map.items():
        bucket = merged.setdefault(key, [])
        for value in values:
            if value not in bucket:
                bucket.append(value)
    return {key: tuple(values) for key, values in merged.items()}


def _safe_log(log: Optional[Callable[[str], None]], message: str) -> None:
    if log is not None:
        log(message)


def _merge_note_text(existing_note: str, new_note: str) -> str:
    existing_parts = [part.strip() for part in str(existing_note or "").split(";") if part.strip()]
    for part in [part.strip() for part in str(new_note or "").split(";") if part.strip()]:
        if part not in existing_parts:
            existing_parts.append(part)
    return "; ".join(existing_parts)


def _dedupe_mesh_loose_file_rows(file_rows: Sequence["MeshLooseModFile"]) -> List["MeshLooseModFile"]:
    deduped: List["MeshLooseModFile"] = []
    by_path: Dict[str, "MeshLooseModFile"] = {}
    for row in file_rows:
        path_key = str(getattr(row, "path", "") or "").replace("\\", "/").strip().lower()
        if not path_key:
            continue
        existing = by_path.get(path_key)
        if existing is None:
            by_path[path_key] = row
            deduped.append(row)
            continue
        if not getattr(existing, "package_group", "") and getattr(row, "package_group", ""):
            existing.package_group = row.package_group
        if not getattr(existing, "format", "") and getattr(row, "format", ""):
            existing.format = row.format
        if not getattr(existing, "generated_from", "") and getattr(row, "generated_from", ""):
            existing.generated_from = row.generated_from
        existing.note = _merge_note_text(getattr(existing, "note", ""), getattr(row, "note", ""))
    return deduped


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _export_related_archive_entries(
    entries: Sequence[ArchiveEntry],
    output_root: Path,
    *,
    on_log: Optional[Callable[[str], None]] = None,
) -> List[Path]:
    from cdmw.core.archive import extract_archive_entry

    written_paths: List[Path] = []
    seen_paths: set[str] = set()
    for entry in entries:
        normalized_path = _normalize_virtual_path(entry.path)
        if not normalized_path or normalized_path in seen_paths:
            continue
        seen_paths.add(normalized_path)
        relative_parts = PurePosixPath(entry.path.replace("\\", "/")).parts
        if not relative_parts:
            continue
        target_path = output_root.joinpath(*relative_parts)
        target_path.parent.mkdir(parents=True, exist_ok=True)
        try:
            _safe_log(on_log, f"Copying related file: {target_path.relative_to(output_root).as_posix()}")
            extract_archive_entry(entry, target_path)
            written_paths.append(target_path)
        except Exception as exc:
            _safe_log(
                on_log,
                f"Warning: could not export related file {entry.path}: {exc}",
            )
    return written_paths


def _parse_mutable_pamt(pamt_path: Path) -> _MutablePamt:
    data = bytearray(pamt_path.read_bytes())
    if len(data) < 12:
        raise ValueError(f"{pamt_path} is too small to be a valid PAMT file.")

    off = 0
    _header_crc, paz_count, _unknown = struct.unpack_from("<III", data, off)
    off += 12

    paz_records: Dict[int, _MutablePazRecord] = {}
    for paz_index in range(paz_count):
        record_offset = off + (paz_index * 12)
        checksum, size, _reserved = struct.unpack_from("<III", data, record_offset)
        paz_records[paz_index] = _MutablePazRecord(
            index=paz_index,
            entry_offset=record_offset,
            checksum=checksum,
            size=size,
        )
    off += paz_count * 12

    if off + 4 > len(data):
        raise ValueError(f"{pamt_path.name} directory block length is truncated.")
    dir_block_size = struct.unpack_from("<I", data, off)[0]
    off += 4
    directory_data = bytes(data[off : off + dir_block_size])
    off += dir_block_size

    if off + 4 > len(data):
        raise ValueError(f"{pamt_path.name} file-name block length is truncated.")
    file_name_block_size = struct.unpack_from("<I", data, off)[0]
    off += 4
    file_names = bytes(data[off : off + file_name_block_size])
    off += file_name_block_size

    if off + 4 > len(data):
        raise ValueError(f"{pamt_path.name} folder table length is truncated.")
    folder_count = struct.unpack_from("<I", data, off)[0]
    off += 4
    folder_table_size = folder_count * 16
    if off + folder_table_size > len(data):
        raise ValueError(f"{pamt_path.name} folder table is truncated.")
    folder_table = memoryview(data)[off : off + folder_table_size]
    off += folder_table_size

    if off + 4 > len(data):
        raise ValueError(f"{pamt_path.name} file table length is truncated.")
    file_count = struct.unpack_from("<I", data, off)[0]
    off += 4
    file_table_offset = off
    file_table_size = file_count * struct.calcsize("<IIIIHH")
    if file_table_offset + file_table_size > len(data):
        raise ValueError(f"{pamt_path.name} file table is truncated.")
    file_table = memoryview(data)[file_table_offset : file_table_offset + file_table_size]

    resolver = _VfsPathResolver(file_names)
    dir_resolver = _VfsPathResolver(directory_data, max_cache_entries=50_000)
    folder_ranges = sorted(
        (
            file_start_index,
            file_start_index + folder_file_count,
            dir_resolver.get_full_path(name_offset).replace("\\", "/").strip("/"),
        )
        for _folder_hash, name_offset, file_start_index, folder_file_count in struct.iter_unpack("<IIII", folder_table)
        if folder_file_count > 0
    )

    file_records: Dict[str, _MutableFileRecord] = {}
    folder_cursor = 0
    record_stride = struct.calcsize("<IIIIHH")
    for entry_index, (name_offset, paz_offset, comp_size, orig_size, paz_index, flags) in enumerate(struct.iter_unpack("<IIIIHH", file_table)):
        relative_path = resolver.get_full_path(name_offset).replace("\\", "/").strip("/")
        guessed_dir = ""
        while folder_cursor < len(folder_ranges) and entry_index >= folder_ranges[folder_cursor][1]:
            folder_cursor += 1
        if folder_cursor < len(folder_ranges):
            start, end, candidate_dir = folder_ranges[folder_cursor]
            if start <= entry_index < end:
                guessed_dir = candidate_dir
        full_path = f"{guessed_dir}/{relative_path}".strip("/") if guessed_dir else relative_path
        normalized_path = _normalize_virtual_path(full_path)
        file_records[normalized_path] = _MutableFileRecord(
            path=full_path,
            paz_index=int(paz_index),
            flags=int(flags),
            record_offset=file_table_offset + (entry_index * record_stride),
            offset=int(paz_offset),
            comp_size=int(comp_size),
            orig_size=int(orig_size),
        )

    return _MutablePamt(path=pamt_path, raw=data, paz_records=paz_records, file_records=file_records)


def _calculate_pa_checksum(value: bytes) -> int:
    from cdmw.core.archive import calculate_pa_checksum

    return int(calculate_pa_checksum(value))


def _crypt_archive_payload(data: bytes, basename: str) -> bytes:
    from cdmw.core.archive import crypt_chacha20_filename

    return crypt_chacha20_filename(data, basename)


def _compress_archive_payload(data: bytes, compression_type: int) -> bytes:
    _validate_archive_patch_compression_type(compression_type)
    if compression_type in {0, 1}:
        return data
    if compression_type == 2:
        if lz4_block is None:
            raise ValueError("LZ4 support is not available in this build.")
        return lz4_block.compress(data, store_size=False)
    raise ValueError(f"Archive patching does not support compression type {compression_type} yet.")


def _validate_archive_patch_compression_type(compression_type: int) -> None:
    if int(compression_type) not in {0, 1, 2}:
        raise ValueError(f"Archive patching does not support compression type {compression_type} yet.")


def _preflight_archive_patch_requests(
    papgt_path: Path,
    grouped_requests: Mapping[Path, Sequence[ArchivePatchRequest]],
) -> Dict[Path, _MutablePamt]:
    for pamt_path in grouped_requests:
        if not pamt_path.is_file():
            raise FileNotFoundError(f"Could not find archive metadata file {pamt_path}.")
    _verify_crc_chain(papgt_path, grouped_requests.keys())

    mutable_by_pamt: Dict[Path, _MutablePamt] = {}
    for pamt_path, group_requests in grouped_requests.items():
        mutable = _parse_mutable_pamt(pamt_path)
        mutable_by_pamt[pamt_path] = mutable

        for request in group_requests:
            _validate_archive_patch_compression_type(request.entry.compression_type)
            normalized_path = _normalize_virtual_path(request.entry.path)
            mutable_record = mutable.file_records.get(normalized_path)
            if mutable_record is None:
                raise ValueError(f"Could not locate {request.entry.path} inside {pamt_path.name}.")
            if int(mutable_record.paz_index) != int(request.entry.paz_index):
                raise ValueError(
                    f"Archive entry {request.entry.path} no longer points at PAZ index {request.entry.paz_index}; "
                    f"current PAMT record points at PAZ index {mutable_record.paz_index}."
                )
            if mutable_record.paz_index not in mutable.paz_records:
                raise ValueError(f"PAMT {pamt_path.name} is missing PAZ table entry {mutable_record.paz_index}.")

            expected_paz_path = (pamt_path.parent / f"{mutable_record.paz_index}.paz").resolve()
            entry_paz_path = request.entry.paz_file.resolve()
            if entry_paz_path != expected_paz_path:
                raise ValueError(
                    f"Archive entry {request.entry.path} points at {entry_paz_path.name}, "
                    f"but the current PAMT record expects {expected_paz_path.name}."
                )
            if not expected_paz_path.is_file():
                raise FileNotFoundError(f"Could not find archive payload file {expected_paz_path}.")

    return mutable_by_pamt


def _write_bytes_preserve_timestamps(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    with temp_path.open("wb") as handle:
        handle.write(data)
    os.replace(temp_path, path)


def _pad_to_16(data: bytes) -> bytes:
    padding = (-len(data)) % 16
    if padding <= 0:
        return data
    return data + (b"\x00" * padding)


def _format_progress_size(size_bytes: int) -> str:
    if size_bytes < 1024:
        return f"{size_bytes} B"
    if size_bytes < 1024 * 1024:
        return f"{size_bytes / 1024.0:.1f} KB"
    if size_bytes < 1024 * 1024 * 1024:
        return f"{size_bytes / (1024.0 * 1024.0):.1f} MB"
    return f"{size_bytes / (1024.0 * 1024.0 * 1024.0):.2f} GB"


def _copy_file_with_progress(
    source: Path,
    target: Path,
    *,
    on_log: Optional[Callable[[str], None]] = None,
    label: str = "",
) -> None:
    total_size = max(0, int(source.stat().st_size))
    copied = 0
    last_logged_percent = -10
    target.parent.mkdir(parents=True, exist_ok=True)
    with source.open("rb") as src_handle, target.open("wb") as dst_handle:
        while True:
            chunk = src_handle.read(16 * 1024 * 1024)
            if not chunk:
                break
            dst_handle.write(chunk)
            copied += len(chunk)
            if on_log is None or total_size <= 0:
                continue
            percent = min(100, int((copied * 100) / total_size))
            if percent >= 100 or percent - last_logged_percent >= 10:
                last_logged_percent = percent
                prefix = f"{label}: " if label else ""
                _safe_log(
                    on_log,
                    f"{prefix}{percent}% ({_format_progress_size(copied)} / {_format_progress_size(total_size)})",
                )
    shutil.copystat(source, target)


def _write_paz_payload(entry: ArchiveEntry, payload: bytes) -> int:
    padded_payload = _pad_to_16(payload)
    paz_path = entry.paz_file

    # Always append a new payload instead of overwriting or clearing the old slot.
    # This keeps the previous archive bytes intact until the updated PAMT has been
    # written successfully, which makes forced-close failures recoverable.
    with paz_path.open("r+b") as handle:
        handle.seek(0, os.SEEK_END)
        paz_size = handle.tell()
        new_offset = (paz_size + 15) & ~15
        if new_offset > paz_size:
            handle.write(b"\x00" * (new_offset - paz_size))
        handle.write(padded_payload)
        handle.flush()
        try:
            os.fsync(handle.fileno())
        except OSError:
            pass
    return new_offset


def _package_root_from_entry(entry: ArchiveEntry) -> Path:
    return entry.pamt_path.parent.parent


def _resolve_papgt_path(entry: ArchiveEntry) -> Path:
    root = _package_root_from_entry(entry)
    papgt_path = root / "meta" / "0.papgt"
    if not papgt_path.is_file():
        raise FileNotFoundError(f"Could not find PAPGT root index at {papgt_path}.")
    return papgt_path


def _read_printable_build_text(path: Path, *, limit: int = 4096) -> str:
    try:
        raw = path.read_bytes()[:limit]
    except OSError:
        return ""
    text = raw.decode("utf-8", errors="ignore")
    text = "".join(ch if ch.isprintable() or ch in "\r\n\t" else " " for ch in text)
    return " ".join(text.split())[:240]


def _detect_archive_game_metadata(entry: ArchiveEntry) -> Dict[str, object]:
    metadata: Dict[str, object] = {
        "primary_package_group": str(getattr(entry.pamt_path.parent, "name", "") or ""),
    }
    root = _package_root_from_entry(entry)
    paver_path = root / "meta" / "0.paver"
    paver_text = _read_printable_build_text(paver_path)
    if paver_text:
        metadata["game_build"] = paver_text
    try:
        papgt_path = _resolve_papgt_path(entry)
        papgt_data = papgt_path.read_bytes()
        payload = papgt_data[12:] if len(papgt_data) >= 12 else papgt_data
        metadata["papgt_crc"] = f"0x{_calculate_pa_checksum(payload):08X}"
        metadata["papgt_size"] = len(papgt_data)
        metadata["papgt_sha256"] = hashlib.sha256(papgt_data).hexdigest()
    except Exception:
        pass
    try:
        pamt_data = entry.pamt_path.read_bytes()
        payload = pamt_data[12:] if len(pamt_data) >= 12 else pamt_data
        metadata["pamt_crc"] = f"0x{_calculate_pa_checksum(payload):08X}"
        metadata["pamt_size"] = len(pamt_data)
        metadata["pamt_sha256"] = hashlib.sha256(pamt_data).hexdigest()
    except Exception:
        pass
    if "game_build" not in metadata and "papgt_crc" in metadata:
        metadata["game_build"] = f"0.papgt {metadata['papgt_crc']}"
    return metadata


def _package_group_sort_order(package_root: Path) -> List[str]:
    groups: List[str] = []
    for child in sorted(package_root.iterdir()):
        if child.is_dir() and (child / "0.pamt").is_file():
            groups.append(child.name)
    return groups


def _papgt_crc_offset(papgt_path: Path, package_group: str) -> int:
    package_root = papgt_path.parent.parent
    groups = _package_group_sort_order(package_root)
    if package_group not in groups:
        raise ValueError(f"Package group {package_group} is not present under {package_root}.")
    index = groups.index(package_group)
    return 12 + (index * 12) + 8


def _verify_crc_chain(papgt_path: Path, touched_pamt_paths: Iterable[Path]) -> None:
    papgt_data = papgt_path.read_bytes()
    stored_papgt_crc = struct.unpack_from("<I", papgt_data, 4)[0]
    computed_papgt_crc = _calculate_pa_checksum(papgt_data[12:])
    if stored_papgt_crc != computed_papgt_crc:
        raise ValueError(
            f"PAPGT checksum verification failed: stored=0x{stored_papgt_crc:08X} computed=0x{computed_papgt_crc:08X}"
        )

    for pamt_path in touched_pamt_paths:
        pamt_data = pamt_path.read_bytes()
        stored_pamt_crc = struct.unpack_from("<I", pamt_data, 0)[0]
        computed_pamt_crc = _calculate_pa_checksum(pamt_data[12:])
        if stored_pamt_crc != computed_pamt_crc:
            raise ValueError(
                f"PAMT checksum verification failed for {pamt_path.name}: "
                f"stored=0x{stored_pamt_crc:08X} computed=0x{computed_pamt_crc:08X}"
            )


def _create_backup(
    files: Sequence[Path],
    *,
    description: str,
    on_log: Optional[Callable[[str], None]] = None,
) -> Path:
    backup_root = ARCHIVE_PATCH_BACKUP_ROOT
    backup_root.mkdir(parents=True, exist_ok=True)
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    backup_dir = backup_root / timestamp
    counter = 1
    while backup_dir.exists():
        backup_dir = backup_root / f"{timestamp}_{counter:02d}"
        counter += 1
    backup_dir.mkdir(parents=True, exist_ok=True)

    manifest: List[Dict[str, str]] = []
    for path in files:
        if not path.exists():
            continue
        target_name = f"{path.parent.name}_{path.name}"
        target_path = backup_dir / target_name
        _safe_log(
            on_log,
            f"Backing up {path.name} to {backup_dir.name} ({_format_progress_size(path.stat().st_size)})...",
        )
        _copy_file_with_progress(path, target_path, on_log=on_log, label=f"Backup {path.name}")
        manifest.append(
            {
                "original_path": str(path),
                "backup_path": str(target_path),
            }
        )
    manifest_path = backup_dir / "backup_manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "description": description,
                "created_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "files": manifest,
            },
            indent=2,
        ),
        encoding="utf-8",
    )
    return backup_dir


def _restore_backup(backup_dir: Path, *, on_log: Optional[Callable[[str], None]] = None) -> None:
    manifest_path = backup_dir / "backup_manifest.json"
    if not manifest_path.is_file():
        raise FileNotFoundError(f"Backup manifest was not found under {backup_dir}.")
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    for file_info in manifest.get("files", []):
        source = Path(str(file_info.get("backup_path", "")))
        target = Path(str(file_info.get("original_path", "")))
        if source.is_file():
            _safe_log(
                on_log,
                f"Restoring {target.name} from backup ({_format_progress_size(source.stat().st_size)})...",
            )
            target.parent.mkdir(parents=True, exist_ok=True)
            temp_target = target.with_name(f".{target.name}.{os.getpid()}.restore.tmp")
            try:
                _copy_file_with_progress(source, temp_target, on_log=on_log, label=f"Restore {target.name}")
                os.replace(temp_target, target)
            finally:
                if temp_target.exists():
                    try:
                        temp_target.unlink()
                    except OSError:
                        pass


def list_archive_patch_backups(*, limit: Optional[int] = None) -> List[Path]:
    if not ARCHIVE_PATCH_BACKUP_ROOT.is_dir():
        return []
    backups = [
        path
        for path in ARCHIVE_PATCH_BACKUP_ROOT.iterdir()
        if path.is_dir() and (path / "backup_manifest.json").is_file()
    ]
    backups.sort(key=lambda path: path.name, reverse=True)
    if limit is not None:
        return backups[: max(0, int(limit))]
    return backups


def restore_archive_patch_backup(
    backup_dir: Path,
    *,
    on_log: Optional[Callable[[str], None]] = None,
) -> Path:
    resolved = backup_dir.expanduser().resolve()
    if not resolved.is_dir():
        raise FileNotFoundError(f"Archive patch backup directory was not found: {resolved}")
    _restore_backup(resolved, on_log=on_log)
    return resolved


def get_archive_texture_patch_blocker(entry: ArchiveEntry) -> str:
    if entry.extension != ".dds":
        return f"{entry.path} is not a DDS archive entry."
    if entry.compression_type == 1:
        return (
            "Direct archive patching for Partial DDS entries is not supported yet. "
            "Write a mod-ready loose replacement instead."
        )
    return ""


def build_archive_texture_payload_from_dds(
    entry: ArchiveEntry,
    replacement_dds_path: Path,
    *,
    on_log: Optional[Callable[[str], None]] = None,
) -> bytes:
    from cdmw.core.pipeline import inspect_crimson_dds, parse_dds

    if entry.extension != ".dds":
        raise ValueError(f"{entry.path} is not a DDS archive entry.")

    resolved_path = replacement_dds_path.expanduser().resolve()
    if not resolved_path.is_file():
        raise FileNotFoundError(f"Replacement DDS was not found: {resolved_path}")

    pathc_last4: Optional[int] = None
    try:
        from cdmw.core.archive import load_pathc_collection, resolve_archive_pathc_path

        pathc_path = resolve_archive_pathc_path(entry)
        if pathc_path.is_file():
            pathc_header = load_pathc_collection(pathc_path).get_file_header(entry.path)
            if len(pathc_header) >= 128 and pathc_header[:4] == DDS_MAGIC:
                pathc_last4 = struct.unpack_from("<I", pathc_header, 124)[0] or None
    except Exception:
        pathc_last4 = None

    crimson_info = inspect_crimson_dds(resolved_path, vpath=entry.path, pathc_last4=pathc_last4)
    fatal_messages = [finding.message for finding in crimson_info.findings if finding.severity == "fatal"]
    if fatal_messages:
        raise ValueError("; ".join(fatal_messages))
    for finding in crimson_info.findings:
        if finding.severity == "warning":
            _safe_log(on_log, f"Crimson DDS warning for {entry.path}: {finding.message}")
        elif finding.severity == "info" and finding.code == "requires_pathc":
            _safe_log(on_log, f"Crimson DDS note for {entry.path}: {finding.message}")

    parse_dds(resolved_path)
    return resolved_path.read_bytes()


def build_archive_texture_payload_from_png(
    entry: ArchiveEntry,
    replacement_png_path: Path,
    *,
    texconv_path: Optional[Path],
    on_log: Optional[Callable[[str], None]] = None,
) -> bytes:
    from cdmw.core.archive import ensure_archive_preview_source
    from cdmw.core.pipeline import (
        build_texconv_command,
        max_mips_for_size,
        parse_dds,
    )

    if entry.extension != ".dds":
        raise ValueError(f"{entry.path} is not a DDS archive entry.")

    resolved_png = replacement_png_path.expanduser().resolve()
    if not resolved_png.is_file():
        raise FileNotFoundError(f"Replacement PNG was not found: {resolved_png}")

    original_dds_path, _note = ensure_archive_preview_source(entry)
    original_info = parse_dds(original_dds_path)

    target_stem = PurePosixPath(entry.path.replace("\\", "/")).stem or "replacement"
    with tempfile.TemporaryDirectory(prefix="ctf_archive_texture_rebuild_") as temp_dir_text:
        temp_dir = Path(temp_dir_text)
        normalized_png_path = temp_dir / f"{target_stem}.png"
        shutil.copy2(resolved_png, normalized_png_path)
        output_dir = temp_dir / "rebuilt"
        output_dir.mkdir(parents=True, exist_ok=True)
        mip_count = max(
            1,
            min(
                max_mips_for_size(original_info.width, original_info.height),
                int(original_info.mip_count or 1),
            ),
        )
        native_output_path = output_dir / f"{target_stem}.dds"
        try:
            from cdmw.core.texture_native import encode_dds_with_directxtex

            native_report = encode_dds_with_directxtex(
                normalized_png_path,
                native_output_path,
                dds_format=original_info.texconv_format,
                width=original_info.width,
                height=original_info.height,
                mip_count=mip_count,
                timeout_seconds=120.0,
            )
        except Exception as exc:
            native_report = None
            _safe_log(on_log, f"DirectXTex native DDS rebuild unavailable for {entry.path}: {exc}")
        if native_report and native_output_path.is_file():
            _safe_log(
                on_log,
                (
                    f"Rebuilt DDS for {entry.path} from {resolved_png.name} "
                    f"with DirectXTex native backend using {original_info.texconv_format} "
                    f"at {original_info.width}x{original_info.height}."
                ),
            )
            return native_output_path.read_bytes()

        if texconv_path is None:
            raise FileNotFoundError(
                "DirectXTex native DDS rebuild failed or is unavailable, and no texconv.exe path was provided."
            )
        resolved_texconv = texconv_path.expanduser().resolve()
        if not resolved_texconv.is_file():
            raise FileNotFoundError(f"texconv.exe was not found: {resolved_texconv}")

        texconv_cmd = build_texconv_command(
            resolved_texconv,
            normalized_png_path,
            output_dir,
            original_info.texconv_format,
            mip_count,
            original_info.width,
            original_info.height,
            overwrite_existing_dds=True,
        )
        _safe_log(
            on_log,
            (
                f"Rebuilding DDS for {entry.path} from {resolved_png.name} "
                f"using {original_info.texconv_format} at {original_info.width}x{original_info.height}."
            ),
        )
        return_code, stdout, stderr = run_process_with_cancellation(texconv_cmd)
        if return_code != 0:
            failure_text = stderr.strip() or stdout.strip() or f"texconv exited with code {return_code}"
            raise RuntimeError(f"texconv failed while rebuilding {entry.basename}: {failure_text}")
        rebuilt_dds_path = output_dir / f"{target_stem}.dds"
        if not rebuilt_dds_path.is_file():
            raise FileNotFoundError(f"texconv did not produce the expected DDS output: {rebuilt_dds_path}")
        return rebuilt_dds_path.read_bytes()


def _add_jmm_descriptor_alias_payloads(
    package_root: Path,
    *,
    written_files: List[Path],
    written_virtual_paths: set[str],
    payload_paths: List[str],
    new_file_paths: List[str],
    on_log: Optional[Callable[[str], None]] = None,
) -> None:
    for left, right in _JMM_DESCRIPTOR_ALIAS_PAIRS:
        left_key = left.casefold()
        right_key = right.casefold()
        if left_key in written_virtual_paths and right_key not in written_virtual_paths:
            source_rel, target_rel = left, right
        elif right_key in written_virtual_paths and left_key not in written_virtual_paths:
            source_rel, target_rel = right, left
        else:
            continue
        source_path = package_root.joinpath(*PurePosixPath(source_rel).parts)
        if not source_path.is_file():
            continue
        target_path = package_root.joinpath(*PurePosixPath(target_rel).parts)
        target_path.parent.mkdir(parents=True, exist_ok=True)
        target_path.write_bytes(source_path.read_bytes())
        written_files.append(target_path)
        written_virtual_paths.add(target_rel.casefold())
        payload_paths.append(target_rel)
        new_file_paths.append(target_rel)
        _safe_log(on_log, f"Writing JMM descriptor alias payload: {target_rel}")


def export_archive_payloads_to_mod_ready_loose(
    requests: Sequence[ArchivePatchRequest],
    *,
    parent_root: Path,
    package_info: ModPackageInfo,
    export_options: Optional["ModPackageExportOptions"] = None,
    create_no_encrypt_file: bool = True,
    extra_payloads_to_include: Sequence[MeshImportSupplementalFileSpec] = (),
    on_log: Optional[Callable[[str], None]] = None,
) -> ArchiveLooseExportResult:
    from cdmw.core.mod_package import (
        mod_package_expanded_export_options,
        normalize_mod_package_payload_path,
        resolve_mod_package_profile_root,
        write_mod_package_manifest,
    )
    from cdmw.core.mod_package import ModPackageExportOptions

    if not requests:
        raise ValueError("No archive payloads were provided for mod-ready loose export.")

    base_options = export_options if isinstance(export_options, ModPackageExportOptions) else ModPackageExportOptions()
    expanded_options = mod_package_expanded_export_options(base_options, kind="archive_loose_mod")
    if len(expanded_options) > 1:
        results: List[ArchiveLooseExportResult] = []
        for profile, profile_options in expanded_options:
            _safe_log(on_log, f"Writing {profile} mod-ready loose package...")
            results.append(
                export_archive_payloads_to_mod_ready_loose(
                    requests,
                    parent_root=parent_root,
                    package_info=package_info,
                    export_options=profile_options,
                    create_no_encrypt_file=create_no_encrypt_file,
                    extra_payloads_to_include=extra_payloads_to_include,
                    on_log=on_log,
                )
            )
        first_root = results[0].package_root
        return ArchiveLooseExportResult(
            package_root=first_root,
            written_files=[path for result in results for path in result.written_files],
            package_roots=tuple(result.package_root for result in results),
        )

    profile, active_export_options = expanded_options[0]
    resolved_parent_root = parent_root.expanduser().resolve()
    package_root = resolve_mod_package_profile_root(
        resolved_parent_root,
        package_info,
        str(getattr(active_export_options, "output_profile_suffix", "") or profile),
        multi_profile=bool(getattr(active_export_options, "output_profile_suffix", "")),
    )
    package_root.mkdir(parents=True, exist_ok=True)

    written_files: List[Path] = []
    written_virtual_paths: set[str] = set()
    payload_paths: List[str] = []
    new_file_paths: List[str] = []
    for request in requests:
        normalized_request_path = normalize_mod_package_payload_path(request.entry.path).as_posix()
        relative_parts = PurePosixPath(normalized_request_path).parts
        if not relative_parts:
            raise ValueError(f"Archive path is invalid: {request.entry.path}")
        normalized_key = normalized_request_path.lower()
        if normalized_key in written_virtual_paths:
            continue
        target_path = package_root.joinpath(*relative_parts)
        target_path.parent.mkdir(parents=True, exist_ok=True)
        _safe_log(on_log, f"Writing loose mod payload: {target_path.relative_to(package_root)}")
        target_path.write_bytes(request.payload_data)
        written_files.append(target_path)
        written_virtual_paths.add(normalized_key)
        payload_paths.append(normalized_request_path)

    for spec in tuple(extra_payloads_to_include or ()):
        if not isinstance(spec, MeshImportSupplementalFileSpec):
            continue
        normalized_target_path = normalize_mod_package_payload_path(spec.target_path or "").as_posix()
        if not normalized_target_path:
            _safe_log(on_log, f"Skipping extra source payload without a mapped loose target: {spec.source_path.name}")
            continue
        normalized_key = normalized_target_path.lower()
        if normalized_key in written_virtual_paths:
            continue
        payload_data = bytes(spec.payload_data or b"")
        if not payload_data:
            source_path = spec.source_path.expanduser().resolve()
            if not source_path.is_file():
                _safe_log(on_log, f"Skipping missing extra source payload: {spec.source_path}")
                continue
            payload_data = source_path.read_bytes()
        relative_parts = PurePosixPath(normalized_target_path).parts
        if not relative_parts:
            continue
        target_path = package_root.joinpath(*relative_parts)
        target_path.parent.mkdir(parents=True, exist_ok=True)
        _safe_log(on_log, f"Writing extra loose mod payload: {target_path.relative_to(package_root)}")
        target_path.write_bytes(payload_data)
        written_files.append(target_path)
        written_virtual_paths.add(normalized_key)
        payload_paths.append(normalized_target_path)
        if not isinstance(spec.target_entry, ArchiveEntry):
            new_file_paths.append(normalized_target_path)

    manager_targets = {
        str(target or "").strip().casefold()
        for target in tuple(getattr(active_export_options, "manager_targets", ()) or ())
        if str(target or "").strip()
    }
    if "jmm" in manager_targets:
        _add_jmm_descriptor_alias_payloads(
            package_root,
            written_files=written_files,
            written_virtual_paths=written_virtual_paths,
            payload_paths=payload_paths,
            new_file_paths=new_file_paths,
            on_log=on_log,
        )

    manifest_path = write_mod_package_manifest(
        package_root,
        package_info,
        kind="archive_loose_mod",
        extra_fields={"file_count": len(written_files)},
        new_file_paths=new_file_paths,
        all_payload_paths=payload_paths or [path.relative_to(package_root).as_posix() for path in written_files],
        export_options=active_export_options,
        create_no_encrypt_file=create_no_encrypt_file,
    )
    written_files.append(manifest_path)

    return ArchiveLooseExportResult(package_root=package_root, written_files=written_files, package_roots=(package_root,))


def export_archive_mesh_payloads_to_mod_ready_loose(
    requests: Sequence[ArchivePatchRequest],
    *,
    primary_entry: ArchiveEntry,
    preview_result: MeshImportPreviewResult,
    source_obj_path: Path,
    source_display_label: str = "",
    parent_root: Path,
    package_info: ModPackageInfo,
    export_options: Optional["ModPackageExportOptions"] = None,
    create_no_encrypt_file: bool = True,
    include_related_files: bool = False,
    related_entries_to_include: Optional[Sequence[ArchiveEntry]] = None,
    supplemental_files_to_include: Sequence[MeshImportSupplementalFileSpec] = (),
    on_log: Optional[Callable[[str], None]] = None,
) -> ArchiveLooseExportResult:
    from cdmw.core.mod_package import (
        MeshLooseModAsset,
        MeshLooseModFile,
        mod_package_expanded_export_options,
        normalize_mod_package_payload_path,
        resolve_mod_package_profile_root,
        write_mesh_loose_mod_package_metadata,
    )
    from cdmw.core.mod_package import ModPackageExportOptions
    from cdmw.core.archive import extract_archive_entry

    if not requests:
        raise ValueError("No archive payloads were provided for mesh mod-ready loose export.")

    base_options = export_options if isinstance(export_options, ModPackageExportOptions) else ModPackageExportOptions()
    expanded_options = mod_package_expanded_export_options(base_options, kind="mesh_loose_mod")
    if len(expanded_options) > 1:
        results: List[ArchiveLooseExportResult] = []
        for profile, profile_options in expanded_options:
            _safe_log(on_log, f"Writing {profile} mod-ready mesh package...")
            results.append(
                export_archive_mesh_payloads_to_mod_ready_loose(
                    requests,
                    primary_entry=primary_entry,
                    preview_result=preview_result,
                    source_obj_path=source_obj_path,
                    source_display_label=source_display_label,
                    parent_root=parent_root,
                    package_info=package_info,
                    export_options=profile_options,
                    create_no_encrypt_file=create_no_encrypt_file,
                    include_related_files=include_related_files,
                    related_entries_to_include=related_entries_to_include,
                    supplemental_files_to_include=supplemental_files_to_include,
                    on_log=on_log,
                )
            )
        first_root = results[0].package_root
        return ArchiveLooseExportResult(
            package_root=first_root,
            written_files=[path for result in results for path in result.written_files],
            authority_audit_path=results[0].authority_audit_path,
            authority_mismatch_count=sum(result.authority_mismatch_count for result in results),
            package_roots=tuple(result.package_root for result in results),
        )

    profile, active_export_options = expanded_options[0]
    resolved_parent_root = parent_root.expanduser().resolve()
    package_root = resolve_mod_package_profile_root(
        resolved_parent_root,
        package_info,
        str(getattr(active_export_options, "output_profile_suffix", "") or profile),
        multi_profile=bool(getattr(active_export_options, "output_profile_suffix", "")),
    )
    _safe_log(on_log, f"Mod-ready mesh package root: {package_root}")
    _clear_existing_mesh_loose_package_root(package_root, resolved_parent_root, on_log=on_log)
    package_root.mkdir(parents=True, exist_ok=True)

    written_files: List[Path] = []
    file_rows: List[MeshLooseModFile] = []
    source_obj_display = source_display_label.strip() or source_obj_path.expanduser().resolve().as_posix()
    paired_lod_path = (preview_result.paired_lod_path or "").strip().replace("\\", "/")
    primary_path = primary_entry.path.replace("\\", "/")
    primary_manifest_path = _mesh_loose_export_payload_path(primary_path, active_export_options)
    written_virtual_paths: set[str] = set()
    for request in requests:
        normalized_request_path = normalize_mod_package_payload_path(request.entry.path).as_posix()
        output_request_path = _mesh_loose_export_payload_path(normalized_request_path, active_export_options)
        relative_parts = PurePosixPath(normalized_request_path).parts
        if not relative_parts:
            raise ValueError(f"Archive path is invalid: {request.entry.path}")
        output_relative_parts = PurePosixPath(output_request_path).parts
        if not output_relative_parts:
            raise ValueError(f"Archive path is invalid: {request.entry.path}")
        target_path = package_root.joinpath(*output_relative_parts)
        target_path.parent.mkdir(parents=True, exist_ok=True)
        _safe_log(on_log, f"Writing loose mesh payload: {target_path.relative_to(package_root).as_posix()}")
        target_path.write_bytes(request.payload_data)
        written_files.append(target_path)
        note = ""
        written_virtual_paths.add(output_request_path.lower())
        if paired_lod_path and normalized_request_path == paired_lod_path and normalized_request_path != primary_path:
            note = f"Auto-generated paired LOD for {primary_entry.path}"
        file_rows.append(
            MeshLooseModFile(
                path=output_request_path,
                package_group=request.entry.pamt_path.parent.name,
                format=request.entry.extension.lstrip(".").lower(),
                is_new=False,
                generated_from=source_obj_display,
                note=note,
            )
        )

    supplemental_specs = [
        spec
        for spec in supplemental_files_to_include
        if isinstance(spec, MeshImportSupplementalFileSpec)
        and (bool(spec.payload_data) or spec.source_path.expanduser().resolve().is_file())
    ]
    for spec in supplemental_specs:
        normalized_target_path = normalize_mod_package_payload_path(spec.target_path or "").as_posix()
        if not normalized_target_path:
            _safe_log(
                on_log,
                f"Skipping selected supplemental file without a mapped loose target: {spec.source_path.name}",
            )
            continue
        output_target_path = _mesh_loose_export_payload_path(normalized_target_path, active_export_options)
        output_relative_parts = PurePosixPath(output_target_path).parts
        if not output_relative_parts:
            _safe_log(
                on_log,
                f"Skipping selected supplemental file with an invalid target path: {spec.source_path.name}",
            )
            continue
        normalized_target_key = output_target_path.lower()
        if normalized_target_key in written_virtual_paths:
            _safe_log(
                on_log,
                f"Skipping selected supplemental file already written in this package: {output_target_path}",
            )
            continue
        target_path = package_root.joinpath(*output_relative_parts)
        target_path.parent.mkdir(parents=True, exist_ok=True)
        if spec.payload_data:
            _safe_log(
                on_log,
                f"Writing generated supplemental payload: {target_path.relative_to(package_root).as_posix()}",
            )
            target_path.write_bytes(spec.payload_data)
        else:
            _safe_log(
                on_log,
                f"Copying selected supplemental file: {target_path.relative_to(package_root).as_posix()}",
            )
            shutil.copy2(spec.source_path, target_path)
        if target_path not in written_files:
            written_files.append(target_path)
        written_virtual_paths.add(normalized_target_key)
        if spec.note:
            note = spec.note
        elif spec.kind == "sidecar":
            note = f"Selected local sidecar included for {primary_entry.path}"
        elif spec.kind == "sidecar_generated":
            note = f"Patched material sidecar generated for {primary_entry.path}"
        elif spec.kind == "texture_generated":
            note = f"Generated replacement texture for {primary_entry.path}"
        elif spec.kind == "texture":
            note = f"Selected local texture override included for {primary_entry.path}"
        elif spec.kind == "companion":
            note = f"Selected Crimson companion metadata included for {primary_entry.path}"
        else:
            note = f"Selected local file included for {primary_entry.path}"
        package_group = ""
        is_new_file = not isinstance(spec.target_entry, ArchiveEntry)
        if isinstance(spec.target_entry, ArchiveEntry):
            package_group = spec.target_entry.pamt_path.parent.name
        file_rows.append(
            MeshLooseModFile(
                path=output_target_path,
                package_group=package_group,
                format=PurePosixPath(normalized_target_path).suffix.lstrip(".").lower()
                or spec.source_path.suffix.lstrip(".").lower(),
                is_new=is_new_file,
                generated_from=spec.source_path.as_posix(),
                note=note,
            )
        )

    related_entries: List[ArchiveEntry] = []
    if related_entries_to_include is not None:
        related_entries.extend(entry for entry in related_entries_to_include if isinstance(entry, ArchiveEntry))
    elif include_related_files:
        for reference in preview_result.texture_references:
            related_entry = getattr(reference, "resolved_entry", None)
            if isinstance(related_entry, ArchiveEntry):
                related_entries.append(related_entry)
    auto_companion_entries = _mesh_import_auto_companion_entries(primary_entry, preview_result)
    if auto_companion_entries:
        existing_related_keys = {
            str(getattr(entry, "path", "") or "").replace("\\", "/").strip().lower()
            for entry in related_entries
            if isinstance(entry, ArchiveEntry)
        }
        added_auto_companions: List[ArchiveEntry] = []
        for companion_entry in auto_companion_entries:
            key = str(getattr(companion_entry, "path", "") or "").replace("\\", "/").strip().lower()
            output_key = _mesh_loose_export_payload_path(key, active_export_options).lower() if key else ""
            if not key or key in existing_related_keys or output_key in written_virtual_paths:
                continue
            related_entries.append(companion_entry)
            existing_related_keys.add(key)
            added_auto_companions.append(companion_entry)
        if added_auto_companions:
            _safe_log(
                on_log,
                "Auto-including exact mesh companion file(s): "
                + ", ".join(entry.basename for entry in added_auto_companions[:6])
                + (" ..." if len(added_auto_companions) > 6 else ""),
            )

    if related_entries:
        for related_entry in related_entries:
            normalized_related_path = normalize_mod_package_payload_path(related_entry.path).as_posix()
            output_related_path = _mesh_loose_export_payload_path(normalized_related_path, active_export_options)
            if output_related_path.lower() in written_virtual_paths:
                continue
            output_relative_parts = PurePosixPath(output_related_path).parts
            if not output_relative_parts:
                continue
            target_path = package_root.joinpath(*output_relative_parts)
            target_path.parent.mkdir(parents=True, exist_ok=True)
            try:
                _safe_log(on_log, f"Copying related file: {target_path.relative_to(package_root).as_posix()}")
                extract_archive_entry(related_entry, target_path)
                written_files.append(target_path)
                written_virtual_paths.add(output_related_path.lower())
                if related_entry.extension == ".dds":
                    note = f"Referenced texture copied from archive for {primary_entry.path}"
                elif related_entry.extension.lower() in MESH_IMPORT_SIDECAR_EXTENSIONS:
                    note = f"Unchanged original sidecar copied for {primary_entry.path}"
                else:
                    note = f"Selected archive related file copied for {primary_entry.path}"
                file_rows.append(
                    MeshLooseModFile(
                        path=output_related_path,
                        package_group=related_entry.pamt_path.parent.name,
                        format=related_entry.extension.lstrip(".").lower(),
                        is_new=False,
                        generated_from=source_obj_display,
                        note=note,
                    )
                )
            except Exception as exc:
                _safe_log(
                    on_log,
                    f"Warning: could not include related file {related_entry.path}: {exc}",
                )

    asset_rows = [
        MeshLooseModAsset(
            entry_path=primary_manifest_path,
            package_group=primary_entry.pamt_path.parent.name,
            format=primary_entry.extension.lstrip(".").lower(),
            obj_path=source_obj_display,
            vertices=int(preview_result.parsed_mesh.total_vertices or 0),
            faces=int(preview_result.parsed_mesh.total_faces or 0),
            submeshes=len(preview_result.parsed_mesh.submeshes),
        )
    ]
    deduped_file_rows = _dedupe_mesh_loose_file_rows(file_rows)
    duplicate_row_count = len(file_rows) - len(deduped_file_rows)
    if duplicate_row_count > 0:
        _safe_log(on_log, f"Removed {duplicate_row_count:,} duplicate file metadata row(s) before writing manifest.json.")
    game_metadata = _detect_archive_game_metadata(primary_entry)

    metadata_files = write_mesh_loose_mod_package_metadata(
        package_root,
        package_info,
        assets=asset_rows,
        files=deduped_file_rows,
        include_paired_lod=bool(paired_lod_path),
        export_options=active_export_options,
        create_no_encrypt_file=create_no_encrypt_file,
        game_build=str(game_metadata.get("game_build", "") or ""),
        game_metadata=game_metadata,
    )
    primary_lower = primary_path.casefold()
    cloth_like = any(token in primary_lower for token in ("cloak", "cloth", "cape", "pbd"))
    wrote_physics_companion = any(
        str(path.suffix).casefold() in {".hkx", ".hkt", ".meshinfo"}
        for path in written_files
    )
    if cloth_like and not wrote_physics_companion:
        _safe_log(
            on_log,
            "Cloth/PBD note: mesh-only cloak/cloth export changed the PAC payload, but unchanged .pac_xml "
            "alone does not update cloth physics. If the game still shows the old shape, verify the equipped "
            "variant, paired LOD, and physics/PBD companion files.",
        )
    authority_audit: Optional[ActiveFileAuthorityAuditResult] = None
    try:
        authority_audit = audit_loose_package_active_file_authority(
            package_root,
            game_root=_package_root_from_entry(primary_entry),
            payload_files=written_files,
            write_audit_file=True,
            audit_output_path=package_root.with_name(f"{package_root.name}_cdmw_active_file_authority_audit.json"),
            on_log=on_log,
        )
        if authority_audit.audit_path is not None:
            try:
                audit_display = authority_audit.audit_path.relative_to(package_root.parent).as_posix()
            except ValueError:
                audit_display = authority_audit.audit_path.as_posix()
            _safe_log(
                on_log,
                "Active file authority audit report written outside package: "
                f"{audit_display}",
            )
        for row in authority_audit.rows[:8]:
            _safe_log(
                on_log,
                "Active file authority: "
                f"{row.status} {row.virtual_path} "
                f"(package {row.local_size:,} bytes {row.local_sha256[:16]}"
                + (
                    f"; active {row.active_source} {row.active_size:,} bytes {row.active_sha256[:16]}"
                    if row.active_source
                    else "; no active archive/loose match"
                )
                + ").",
            )
        for warning in authority_audit.warnings[:12]:
            _safe_log(on_log, warning)
        if authority_audit.mismatch_count:
            _safe_log(
                on_log,
                f"Active file authority audit found {authority_audit.mismatch_count:,} mismatch(es); "
                "clean/disable stale active archives before judging in-game materials.",
            )
    except Exception as exc:
        _safe_log(on_log, f"Warning: active file authority audit failed: {exc}")
    _safe_log(
        on_log,
        f"Finished mod-ready mesh package with {len(written_files):,} payload file(s) and {len(metadata_files):,} metadata file(s).",
    )

    return ArchiveLooseExportResult(
        package_root=package_root,
        written_files=[*written_files, *metadata_files],
        authority_audit_path=authority_audit.audit_path if authority_audit is not None else None,
        authority_mismatch_count=authority_audit.mismatch_count if authority_audit is not None else 0,
        package_roots=(package_root,),
    )


def _clear_existing_mesh_loose_package_root(
    package_root: Path,
    resolved_parent_root: Path,
    *,
    on_log: Optional[Callable[[str], None]] = None,
) -> None:
    resolved_package_root = package_root.expanduser().resolve()
    if not resolved_package_root.exists():
        return
    if resolved_package_root == resolved_parent_root:
        raise ValueError(f"Refusing to clear loose export parent directory: {resolved_package_root}")
    try:
        resolved_package_root.relative_to(resolved_parent_root)
    except ValueError as exc:
        raise ValueError(
            f"Refusing to clear loose export folder outside the selected export root: {resolved_package_root}"
        ) from exc
    _safe_log(on_log, f"Clearing existing loose mesh package folder: {resolved_package_root}")
    for child in resolved_package_root.iterdir():
        if child.is_dir():
            shutil.rmtree(child)
        else:
            child.unlink()


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _loose_authority_virtual_path(package_root: Path, local_path: Path) -> str:
    try:
        relative = local_path.resolve().relative_to(package_root.resolve()).as_posix()
    except ValueError:
        relative = local_path.as_posix()
    parts = tuple(part for part in PurePosixPath(relative).parts if part)
    if not parts:
        return ""
    if parts[0].casefold() == "files" and len(parts) > 1:
        parts = parts[1:]
    if parts[0].casefold() in {"assets", "metadata"}:
        return ""
    if PurePosixPath(*parts).name.casefold() in {
        "manifest.json",
        "mod.json",
        "modinfo.json",
        "info.json",
        "readme.txt",
        ".no_encrypt",
        "cdmw_active_file_authority_audit.json",
    }:
        return ""
    return PurePosixPath(*parts).as_posix()


def _is_active_file_authority_audit_path(path: Path) -> bool:
    name = path.name.casefold()
    return name == "cdmw_active_file_authority_audit.json" or name.endswith(
        "_cdmw_active_file_authority_audit.json"
    )


def audit_loose_package_active_file_authority(
    package_root: Path,
    *,
    game_root: Path,
    payload_files: Sequence[Path],
    write_audit_file: bool = True,
    audit_output_path: Optional[Path] = None,
    on_log: Optional[Callable[[str], None]] = None,
) -> ActiveFileAuthorityAuditResult:
    """Compare loose package payload hashes with active archive entries.

    This catches stale DMM/archive installs where preview validates the newly
    exported loose folder but the game loads an older active package instead.
    """

    from cdmw.core.archive import (
        archive_entry_is_mod_package,
        active_archive_entry_for_virtual_path,
        discover_pamt_files,
        parse_archive_pamt,
        read_archive_entry_data,
    )

    root = Path(package_root).expanduser().resolve()
    resolved_game_root = Path(game_root).expanduser().resolve()
    result = ActiveFileAuthorityAuditResult(package_root=root, game_root=resolved_game_root)
    manifest_summary: Dict[str, object] = {}
    manifest_path = root / "manifest.json"
    if manifest_path.is_file():
        try:
            manifest_payload = json.loads(manifest_path.read_text(encoding="utf-8"))
            if isinstance(manifest_payload, Mapping):
                manifest_summary = {
                    "structure": str(manifest_payload.get("structure", "") or ""),
                    "files_root": str(manifest_payload.get("files_root", "") or ""),
                    "manager_targets": list(manifest_payload.get("manager_targets", ()) or ()),
                    "file_count": int(manifest_payload.get("file_count", 0) or 0),
                    "assets": list(manifest_payload.get("assets", ()) or ())[:8],
                    "files": list(manifest_payload.get("files", ()) or ())[:32],
                }
        except Exception as exc:
            result_hint = f"Active file authority audit could not read manifest.json: {exc}"
            _safe_log(on_log, result_hint)
    structure = str(manifest_summary.get("structure", "") or "").strip().lower()
    files_root = str(manifest_summary.get("files_root", "") or "").strip()
    expects_files_wrapper = structure in {"files_wrapper", "custom_compact_paths"} or (files_root and files_root != ".")
    wanted: dict[str, tuple[str, Path, int, str]] = {}
    for raw_path in tuple(payload_files or ()):
        local_path = Path(raw_path)
        if not local_path.is_file():
            continue
        try:
            relative_parts_for_layout = tuple(part for part in local_path.resolve().relative_to(root).parts if part)
        except ValueError:
            relative_parts_for_layout = ()
        if expects_files_wrapper and relative_parts_for_layout and relative_parts_for_layout[0].casefold() != (files_root or "files").casefold():
            result_warning = (
                f"VERIFY LOOSE MOD TARGET: package metadata expects payloads under {files_root or 'files'}/, "
                f"but found {PurePosixPath(*relative_parts_for_layout).as_posix()}."
            )
            if result_warning not in result.warnings:
                result.warnings.append(result_warning)
            result.requires_report = True
        if not expects_files_wrapper and relative_parts_for_layout and relative_parts_for_layout[0].casefold() == "files":
            result_warning = (
                "VERIFY LOOSE MOD TARGET: package metadata is game-relative but payloads are under files/. "
                "Pick the CDUMM/files-wrapper profile if the manager expects files/."
            )
            if result_warning not in result.warnings:
                result.warnings.append(result_warning)
            result.requires_report = True
        virtual_path = _loose_authority_virtual_path(root, local_path)
        if not virtual_path:
            continue
        try:
            size = local_path.stat().st_size
            digest = _sha256_file(local_path)
        except OSError:
            continue
        wanted[virtual_path.casefold()] = (virtual_path, local_path, size, digest)

    if not wanted:
        return result
    entries_by_path: dict[str, list[ArchiveEntry]] = defaultdict(list)
    if not resolved_game_root.is_dir():
        result.warnings.append(f"Active file authority audit skipped; game root not found: {resolved_game_root}")
    else:
        for pamt_path in discover_pamt_files(resolved_game_root):
            try:
                entries = parse_archive_pamt(pamt_path)
            except Exception as exc:
                _safe_log(on_log, f"Authority audit skipped unreadable PAMT {pamt_path}: {exc}")
                continue
            for entry in entries:
                key = str(entry.path or "").replace("\\", "/").strip().casefold()
                if key in wanted:
                    entries_by_path[key].append(entry)

    for key, (virtual_path, local_path, local_size, local_sha) in sorted(wanted.items()):
        row = ActiveFileAuthorityAuditRow(
            virtual_path=virtual_path,
            local_path=local_path.as_posix(),
            local_size=int(local_size),
            local_sha256=local_sha,
        )
        candidates = entries_by_path.get(key, [])
        direct_loose_path = resolved_game_root.joinpath(*PurePosixPath(virtual_path).parts)
        direct_loose_exists = direct_loose_path.is_file()
        row.duplicate_count = len(candidates) + (1 if direct_loose_exists else 0)
        if direct_loose_exists:
            try:
                row.active_source = f"loose/{virtual_path}"
                row.active_size = direct_loose_path.stat().st_size
                row.active_sha256 = _sha256_file(direct_loose_path)
            except OSError as exc:
                row.status = "active_read_failed"
                row.note = str(exc)
                result.warnings.append(f"Authority audit could not read active loose payload for {virtual_path}: {exc}")
                result.requires_report = True
                result.rows.append(row)
                continue
            if row.active_sha256 == local_sha and row.active_size == local_size:
                row.status = "match"
            else:
                row.status = "mismatch"
                row.note = "Active loose payload differs from final package; in-game test may be using stale data."
                result.mismatch_count += 1
                result.requires_report = True
                result.warnings.append(
                    f"IN-GAME TEST BLOCKED: active loose file differs from package {virtual_path} "
                    f"(active {row.active_sha256[:16]}, loose {local_sha[:16]})."
                )
            result.rows.append(row)
            continue
        active_entry = active_archive_entry_for_virtual_path(candidates) if candidates else None
        if active_entry is None:
            row.status = "loose_only"
            row.note = "No active archive entry with this virtual path was found."
            result.rows.append(row)
            continue
        row.active_source = f"{active_entry.pamt_path.parent.name}/{active_entry.pamt_path.name}"
        row.active_size = int(getattr(active_entry, "orig_size", 0) or 0)
        try:
            active_data, _decompressed, _note = read_archive_entry_data(active_entry)
            row.active_sha256 = hashlib.sha256(active_data).hexdigest()
            row.active_size = len(active_data)
        except Exception as exc:
            row.status = "active_read_failed"
            row.note = str(exc)
            result.warnings.append(f"Authority audit could not read active archive payload for {virtual_path}: {exc}")
            result.requires_report = True
            result.rows.append(row)
            continue
        if row.active_sha256 == local_sha and row.active_size == local_size:
            row.status = "match"
        elif archive_entry_is_mod_package(active_entry):
            row.status = "mismatch"
            row.note = "Active mod archive payload differs from final loose package; in-game test may be using stale data."
            result.mismatch_count += 1
            result.requires_report = True
            result.warnings.append(
                f"IN-GAME TEST BLOCKED: active {row.active_source} differs from loose {virtual_path} "
                f"(active {row.active_sha256[:16]}, loose {local_sha[:16]})."
            )
        else:
            row.status = "replaces_archive"
            row.note = "Final loose package differs from base archive; expected for replacement mods."
        result.rows.append(row)

    audit_path = (
        Path(audit_output_path).expanduser().resolve()
        if audit_output_path is not None
        else root / "cdmw_active_file_authority_audit.json"
    )
    if write_audit_file and result.requires_report:
        audit_doc = {
            "schema": "cdmw_active_file_authority_audit_v1",
            "package_root": root.as_posix(),
            "game_root": resolved_game_root.as_posix(),
            "manager_layout": manifest_summary,
            "mismatch_count": result.mismatch_count,
            "warnings": list(result.warnings),
            "in_game_visibility_notes": [
                "If this report shows the edited PAC differs but the game still shows the original, check the equipped asset variant, enabled mod-manager profile, loose path structure, game cache, paired LOD, and cloth/physics companion files.",
                "Mesh-only cloth/cloak edits may still need matching physics/PBD companion work; unchanged .pac_xml alone does not update cloth simulation.",
            ],
            "rows": [dataclasses.asdict(row) for row in result.rows],
        }
        try:
            audit_path.parent.mkdir(parents=True, exist_ok=True)
            audit_path.write_text(json.dumps(audit_doc, indent=2, sort_keys=True), encoding="utf-8")
            result.audit_path = audit_path
        except OSError as exc:
            result.warnings.append(f"Could not write active file authority audit: {exc}")
    elif write_audit_file and audit_output_path is not None and _is_active_file_authority_audit_path(audit_path):
        try:
            if audit_path.is_file():
                audit_path.unlink()
        except OSError as exc:
            result.warnings.append(f"Could not remove stale active file authority audit: {exc}")
    return result


def _refresh_changed_entries(pamt_paths: Iterable[Path], changed_paths: Iterable[str]) -> Dict[str, ArchiveEntry]:
    from cdmw.core.archive import parse_archive_pamt

    changed_lookup = {_normalize_virtual_path(path) for path in changed_paths}
    refreshed: Dict[str, ArchiveEntry] = {}
    for pamt_path in pamt_paths:
        for entry in parse_archive_pamt(pamt_path, paz_dir=pamt_path.parent):
            normalized = _normalize_virtual_path(entry.path)
            if normalized in changed_lookup:
                refreshed[normalized] = entry
    return refreshed


def patch_archive_entries(
    requests: Sequence[ArchivePatchRequest],
    *,
    on_log: Optional[Callable[[str], None]] = None,
) -> ArchivePatchResult:
    if not requests:
        raise ValueError("No archive modifications were provided.")

    package_roots = {_package_root_from_entry(request.entry).resolve() for request in requests}
    if len(package_roots) != 1:
        raise ValueError("Archive patching currently requires all modified entries to come from the same package root.")
    package_root = next(iter(package_roots))
    papgt_path = _resolve_papgt_path(requests[0].entry)

    grouped_requests: Dict[Path, List[ArchivePatchRequest]] = {}
    for request in requests:
        grouped_requests.setdefault(request.entry.pamt_path.resolve(), []).append(request)

    mutable_by_pamt = _preflight_archive_patch_requests(
        papgt_path=papgt_path,
        grouped_requests=grouped_requests,
    )

    backup_targets: List[Path] = [papgt_path]
    for pamt_path, group_requests in grouped_requests.items():
        backup_targets.append(pamt_path)
        backup_targets.extend({request.entry.paz_file.resolve() for request in group_requests})
    _safe_log(on_log, f"Creating archive patch backup for {len(requests)} entrie(s)...")
    backup_dir = _create_backup(
        sorted(set(backup_targets)),
        description=f"Patch {len(requests)} archive entrie(s)",
        on_log=on_log,
    )
    _safe_log(on_log, f"Backup created: {backup_dir}")
    warnings: List[str] = []
    touched_pamt_paths: List[Path] = []
    changed_paths = [request.entry.path for request in requests]

    try:
        papgt_raw = bytearray(papgt_path.read_bytes())

        for pamt_path, group_requests in grouped_requests.items():
            mutable = mutable_by_pamt[pamt_path]
            touched_paz_indices: set[int] = set()
            group_name = pamt_path.parent.name
            _safe_log(on_log, f"Updating {group_name}/{pamt_path.name} ({len(group_requests)} entrie(s))...")

            for request in group_requests:
                normalized_path = _normalize_virtual_path(request.entry.path)
                mutable_record = mutable.file_records.get(normalized_path)
                if mutable_record is None:
                    raise ValueError(f"Could not locate {request.entry.path} inside {pamt_path.name}.")

                _safe_log(on_log, f"Preparing payload for {request.entry.path}...")
                processed_payload = _compress_archive_payload(request.payload_data, request.entry.compression_type)
                if request.entry.encrypted:
                    processed_payload = _crypt_archive_payload(processed_payload, request.entry.basename)

                _safe_log(
                    on_log,
                    f"Writing {request.entry.basename} to {request.entry.paz_file.name} at a safe append-only offset...",
                )
                new_offset = _write_paz_payload(request.entry, processed_payload)
                struct.pack_into("<I", mutable.raw, mutable_record.record_offset + 4, new_offset)
                struct.pack_into("<I", mutable.raw, mutable_record.record_offset + 8, len(processed_payload))
                struct.pack_into("<I", mutable.raw, mutable_record.record_offset + 12, len(request.payload_data))
                touched_paz_indices.add(int(mutable_record.paz_index))

            for paz_index in sorted(touched_paz_indices):
                paz_record = mutable.paz_records.get(paz_index)
                if paz_record is None:
                    raise ValueError(f"PAMT {pamt_path.name} is missing PAZ table entry {paz_index}.")
                paz_path = pamt_path.parent / f"{paz_index}.paz"
                if not paz_path.is_file():
                    raise FileNotFoundError(f"Could not find archive payload file {paz_path}.")
                _safe_log(on_log, f"Recalculating checksum for {paz_path.name}...")
                paz_data = paz_path.read_bytes()
                struct.pack_into("<I", mutable.raw, paz_record.entry_offset, _calculate_pa_checksum(paz_data))
                struct.pack_into("<I", mutable.raw, paz_record.entry_offset + 4, len(paz_data))

            _safe_log(on_log, f"Writing updated {pamt_path.name}...")
            pamt_crc = _calculate_pa_checksum(bytes(mutable.raw[12:]))
            struct.pack_into("<I", mutable.raw, 0, pamt_crc)
            _write_bytes_preserve_timestamps(pamt_path, bytes(mutable.raw))
            touched_pamt_paths.append(pamt_path)

            crc_offset = _papgt_crc_offset(papgt_path, group_name)
            struct.pack_into("<I", papgt_raw, crc_offset, pamt_crc)

        _safe_log(on_log, f"Writing updated {papgt_path.name}...")
        papgt_crc = _calculate_pa_checksum(bytes(papgt_raw[12:]))
        struct.pack_into("<I", papgt_raw, 4, papgt_crc)
        _write_bytes_preserve_timestamps(papgt_path, bytes(papgt_raw))

        _safe_log(on_log, "Verifying archive checksum chain...")
        _verify_crc_chain(papgt_path, touched_pamt_paths)
    except Exception:
        _safe_log(on_log, f"Patch failed. Restoring files from backup: {backup_dir}")
        _restore_backup(backup_dir, on_log=on_log)
        raise

    _safe_log(on_log, "Refreshing changed archive entries...")
    refreshed_entries = _refresh_changed_entries(touched_pamt_paths, changed_paths)
    _safe_log(on_log, f"Patch complete. Backup available at {backup_dir}")
    return ArchivePatchResult(
        backup_dir=backup_dir,
        changed_entries=refreshed_entries,
        changed_paths=changed_paths,
        warnings=warnings,
    )


def _mesh_export_basename(entry: ArchiveEntry) -> str:
    stem = PurePosixPath(str(entry.path or "").replace("\\", "/")).stem.strip()
    safe_stem = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "_", stem).strip(" ._")
    return safe_stem or "archive_mesh"


_EXPORT_MTL_VISIBLE_TEXTURE_TERMS = (
    "base",
    "basecolor",
    "base_color",
    "color",
    "colour",
    "albedo",
    "diffuse",
    "detaildiffuse",
    "diffusemask",
)
_EXPORT_MTL_SUPPORT_TEXTURE_TERMS = (
    "normal",
    "height",
    "disp",
    "displacement",
    "material",
    "rough",
    "metal",
    "spec",
    "masktexture",
    "_ma",
    "_mg",
    "_sp",
)
_EXPORT_MTL_SUPPORT_SUFFIXES = (
    "_n",
    "_normal",
    "_ma",
    "_mg",
    "_sp",
    "_h",
    "_height",
    "_disp",
    "_displacement",
)


def _normalize_export_texture_alias(value: str) -> str:
    text = str(value or "").strip().replace("\\", "/")
    if not text:
        return ""
    if "/" in text:
        text = PurePosixPath(text).stem
    return re.sub(r"[^a-z0-9]+", "", text.casefold())


def _resolved_export_texture_path(reference: ArchiveModelTextureReference) -> str:
    for value in (
        getattr(reference, "resolved_archive_path", ""),
        getattr(reference, "reference_name", ""),
    ):
        normalized = str(value or "").strip().replace("\\", "/")
        if normalized.lower().endswith(".dds"):
            return normalized
    return ""


def _export_mtl_visible_texture_priority(reference: ArchiveModelTextureReference) -> int:
    resolved_path = _resolved_export_texture_path(reference)
    if not resolved_path:
        return 0
    basename_stem = PurePosixPath(resolved_path).stem.casefold()
    combined = " ".join(
        str(value or "").strip().casefold()
        for value in (
            getattr(reference, "semantic_label", ""),
            getattr(reference, "semantic_hint", ""),
            getattr(reference, "sidecar_parameter_name", ""),
            getattr(reference, "texture_role", ""),
            getattr(reference, "reference_name", ""),
            resolved_path,
        )
    )
    has_visible_hint = any(term in combined for term in _EXPORT_MTL_VISIBLE_TEXTURE_TERMS)
    has_support_hint = any(term in combined for term in _EXPORT_MTL_SUPPORT_TEXTURE_TERMS)
    has_support_suffix = any(basename_stem.endswith(suffix) for suffix in _EXPORT_MTL_SUPPORT_SUFFIXES)
    if (has_support_hint or has_support_suffix) and not has_visible_hint:
        return 0

    priority = 20
    if "base" in combined or "basecolor" in combined or "albedo" in combined:
        priority += 50
    if "diffuse" in combined or "detaildiffuse" in combined:
        priority += 45
    if "sidecar" in str(getattr(reference, "relation_reason", "") or "").casefold():
        priority += 10
    confidence = str(getattr(reference, "relation_confidence", "") or "").casefold()
    if confidence in {"authoritative", "exact_path"}:
        priority += 10
    if not has_visible_hint and has_support_suffix:
        return 0
    return priority


def _build_export_mtl_texture_overrides(
    parsed_mesh: ParsedMesh,
    texture_references: Sequence[ArchiveModelTextureReference],
) -> Dict[str, str]:
    material_by_alias: Dict[str, str] = {}
    for submesh in parsed_mesh.submeshes:
        material_name = str(submesh.material or submesh.name or "").strip()
        if not material_name:
            continue
        for alias in (submesh.name, submesh.material, submesh.texture):
            normalized_alias = _normalize_export_texture_alias(alias)
            if normalized_alias:
                material_by_alias.setdefault(normalized_alias, material_name)

    best_by_material: Dict[str, Tuple[int, str]] = {}
    for reference in texture_references:
        priority = _export_mtl_visible_texture_priority(reference)
        if priority <= 0:
            continue
        resolved_path = _resolved_export_texture_path(reference)
        if not resolved_path:
            continue
        candidate_aliases = (
            getattr(reference, "material_name", ""),
            getattr(reference, "linked_mesh_path", ""),
            getattr(reference, "part_name", ""),
            getattr(reference, "reference_name", ""),
            resolved_path,
        )
        matched_material = ""
        for alias in candidate_aliases:
            normalized_alias = _normalize_export_texture_alias(str(alias or ""))
            if normalized_alias in material_by_alias:
                matched_material = material_by_alias[normalized_alias]
                break
        if not matched_material:
            continue
        previous = best_by_material.get(matched_material)
        if previous is None or priority > previous[0]:
            best_by_material[matched_material] = (priority, resolved_path)
    return {material: path for material, (_priority, path) in best_by_material.items()}


def _export_mtl_local_texture_reference(output_dir: Path, archive_texture_path: str) -> str:
    normalized = str(archive_texture_path or "").strip().replace("\\", "/")
    if not normalized:
        return ""
    parts = PurePosixPath(normalized).parts
    copied_candidate = output_dir / "referenced_files"
    for part in parts:
        copied_candidate /= part
    if copied_candidate.is_file():
        return PurePosixPath("referenced_files").joinpath(*parts).as_posix()
    return PurePosixPath(normalized).name


def _rewrite_export_mtl_map_kd(
    mtl_path: Path,
    texture_overrides: Mapping[str, str],
    output_dir: Path,
) -> int:
    if not texture_overrides or not mtl_path.is_file():
        return 0
    lines = mtl_path.read_text(encoding="utf-8").splitlines()
    rewritten: List[str] = []
    current_material = ""
    changed = 0
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("newmtl "):
            current_material = stripped[7:].strip()
        if current_material in texture_overrides and stripped.startswith("map_Kd "):
            texture_reference = _export_mtl_local_texture_reference(output_dir, texture_overrides[current_material])
            if texture_reference:
                replacement = f"map_Kd {texture_reference}"
                if line != replacement:
                    line = replacement
                    changed += 1
        rewritten.append(line)
    if changed:
        mtl_path.write_text("\n".join(rewritten) + "\n", encoding="utf-8")
    return changed


def _parse_archive_mesh(entry: ArchiveEntry) -> ParsedMesh:
    from cdmw.core.archive import read_archive_entry_data

    data, _decompressed, _note = read_archive_entry_data(entry)
    return parse_mesh(data, entry.path)


def _find_matching_skeleton_entry(
    entry: ArchiveEntry,
    *,
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
) -> tuple[Optional[ArchiveEntry], str, Tuple[str, ...], SkeletonResolveReport]:
    from cdmw.core.archive import read_archive_entry_data

    try:
        pac_data, _decompressed, _note = read_archive_entry_data(entry)
    except Exception:
        pac_data = b""

    def _read_candidate(candidate: ArchiveEntry) -> bytes:
        payload, _decompressed, _note = read_archive_entry_data(candidate)
        return payload

    skeleton_entry, report = resolve_skeleton_for_model(
        entry,
        (),
        archive_entries_by_normalized_path=archive_entries_by_normalized_path,
        archive_entries_by_basename=archive_entries_by_basename,
        pac_data=pac_data,
        read_entry_data=_read_candidate,
    )
    if skeleton_entry is not None:
        return skeleton_entry, "", tuple(report.attempted_paths), report
    detail = (
        report.blocking_errors[0]
        if report.blocking_errors
        else f"Could not resolve a matching PAB skeleton for {entry.path}."
    )
    if report.attempted_paths:
        preview = ", ".join(report.attempted_paths[:5])
        if len(report.attempted_paths) > 5:
            preview += " ..."
        detail += f"\nTried: {preview}"
    return None, detail, tuple(report.attempted_paths), report


def export_archive_mesh(
    entry: ArchiveEntry,
    output_dir: Path,
    export_format: str,
    *,
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    related_entries: Sequence[ArchiveEntry] = (),
    allow_missing_skeleton: bool = False,
    resolve_skeleton_for_obj: bool = True,
    on_log: Optional[Callable[[str], None]] = None,
) -> MeshExportResult:
    export_kind = export_format.strip().lower()
    if export_kind not in {"obj", "fbx"}:
        raise ValueError(f"Unsupported mesh export format: {export_format}")
    if entry.extension not in ARCHIVE_MESH_EXTENSIONS:
        raise ValueError(f"{entry.path} is not a supported mesh entry.")

    parsed_mesh = _parse_archive_mesh(entry)
    if not parsed_mesh.submeshes and not parsed_mesh.lod_levels:
        raise ValueError("No geometry could be recovered from the selected mesh.")

    output_dir.mkdir(parents=True, exist_ok=True)
    basename = _mesh_export_basename(entry)
    _safe_log(on_log, f"Exporting {entry.path} as {export_kind.upper()}...")

    output_paths: List[Path] = []
    skeleton: Optional[Skeleton] = None
    skeleton_entry: Optional[ArchiveEntry] = None
    skeleton_resolution_warning = ""
    skeleton_resolve_report: Optional[SkeletonResolveReport] = None
    copied_related_count = 0
    should_resolve_skeleton = entry.extension == ".pac" and (
        export_kind == "fbx" or bool(resolve_skeleton_for_obj)
    )
    if should_resolve_skeleton:
        skeleton_entry, skeleton_resolution_warning, _attempted_paths, skeleton_resolve_report = _find_matching_skeleton_entry(
            entry,
            archive_entries_by_normalized_path=archive_entries_by_normalized_path,
            archive_entries_by_basename=archive_entries_by_basename,
        )
    if export_kind == "obj":
        output_paths.extend(Path(path) for path in export_obj(parsed_mesh, str(output_dir), basename))
    else:
        if entry.extension == ".pac":
            if skeleton_entry is not None:
                from cdmw.core.archive import read_archive_entry_data

                try:
                    skeleton_data, _decompressed, _note = read_archive_entry_data(skeleton_entry)
                    skeleton = parse_pab(skeleton_data, skeleton_entry.path)
                    if not skeleton.bones:
                        skeleton_resolution_warning = (
                            f"Matched skeleton {skeleton_entry.path} did not contain any bones."
                        )
                        skeleton = None
                except Exception as exc:
                    skeleton_resolution_warning = (
                        f"Matched skeleton {skeleton_entry.path} could not be parsed: {exc}"
                    )
                    skeleton = None
            if skeleton is None and not allow_missing_skeleton:
                confirmation_message = (
                    f"Export {entry.path} as FBX without an armature?\n\n"
                    f"{skeleton_resolution_warning or 'No matching PAB skeleton could be resolved.'}\n\n"
                    "Choose Yes to continue with a mesh-only FBX export, or No to cancel."
                )
                return MeshExportResult(
                    output_paths=[],
                    summary_lines=[
                        f"Path: {entry.path}",
                        f"Format: {parsed_mesh.format.upper()}",
                        "FBX export is waiting for confirmation because no usable skeleton could be attached.",
                    ],
                    requires_confirmation=True,
                    confirmation_title="Export FBX Without Skeleton?",
                    confirmation_message=confirmation_message,
                )
        if skeleton is not None and skeleton.bones:
            output_paths.append(Path(export_fbx_with_skeleton(parsed_mesh, skeleton, str(output_dir), basename)))
        else:
            output_paths.append(Path(export_fbx(parsed_mesh, str(output_dir), basename)))

    if related_entries:
        related_output_root = output_dir / "referenced_files"
        copied_paths = _export_related_archive_entries(
            related_entries,
            related_output_root,
            on_log=on_log,
        )
        output_paths.extend(copied_paths)
        copied_related_count = len(copied_paths)

    manifest_target_path = next(
        (
            path for path in output_paths
            if path.suffix.lower() in {".obj", ".fbx"}
        ),
        None,
    )
    if manifest_target_path is not None:
        try:
            from cdmw.core.archive import build_archive_preview_result

            preview_result = build_archive_preview_result(
                None,
                entry,
                (),
                texture_entries_by_normalized_path=(
                    dict(archive_entries_by_normalized_path) if archive_entries_by_normalized_path is not None else None
                ),
                texture_entries_by_basename=(
                    dict(archive_entries_by_basename) if archive_entries_by_basename is not None else None
                ),
            )
            model_texture_references = tuple(getattr(preview_result, "model_texture_references", ()) or ())
            paired_lod_target = ""
            if entry.extension == ".pam" and archive_entries_by_normalized_path is not None:
                paired_candidates = archive_entries_by_normalized_path.get(
                    str(PurePosixPath(entry.path).with_suffix(".pamlod")).replace("\\", "/").strip().lower(),
                    (),
                )
                if paired_candidates:
                    paired_lod_target = paired_candidates[0].path
            companion_path = ""
            if manifest_target_path.suffix.lower() == ".obj":
                companion_candidate = manifest_target_path.with_suffix(".mtl")
                if companion_candidate.is_file():
                    companion_path = str(companion_candidate)
                    rewritten_mtl_rows = _rewrite_export_mtl_map_kd(
                        companion_candidate,
                        _build_export_mtl_texture_overrides(parsed_mesh, model_texture_references),
                        output_dir,
                    )
                    if rewritten_mtl_rows:
                        _safe_log(
                            on_log,
                            f"Updated {rewritten_mtl_rows:,} OBJ material texture binding(s) from resolved archive sidecar evidence.",
                        )
            selected_companion_files: List[str] = []
            seen_selected_companion_files: set[str] = set()
            sidecar_hashes: Dict[str, str] = {}
            for related_entry in related_entries:
                if not isinstance(related_entry, ArchiveEntry):
                    continue
                normalized_related_path = related_entry.path.replace("\\", "/").strip()
                normalized_related_key = normalized_related_path.lower()
                if normalized_related_path and normalized_related_key not in seen_selected_companion_files:
                    seen_selected_companion_files.add(normalized_related_key)
                    selected_companion_files.append(normalized_related_path)
                related_extension = related_entry.extension.lower()
                related_basename = PurePosixPath(normalized_related_path).name.lower()
                if related_extension in {".xml", ".pami", ".json"} or related_basename.endswith("_xml"):
                    copied_sidecar_path = (output_dir / "referenced_files").joinpath(
                        *PurePosixPath(normalized_related_path).parts
                    )
                    if copied_sidecar_path.is_file():
                        sidecar_hashes[normalized_related_path] = _sha256_file(copied_sidecar_path)
            family_graph_payload = {}
            if getattr(preview_result, "asset_family_graph", None) is not None:
                family_graph = preview_result.asset_family_graph
                family_graph_payload = {
                    "root_path": family_graph.root_path,
                    "family_key": family_graph.family_key,
                    "members": list(family_graph.members),
                    "grouped_paths": {
                        key: list(value)
                        for key, value in getattr(family_graph, "grouped_paths", {}).items()
                    },
                    "relations": [
                        {
                            "source_path": relation.source_path,
                            "target_path": relation.target_path,
                            "relation_kind": relation.relation_kind,
                            "confidence": relation.confidence,
                            "role_label": relation.role_label,
                            "reason": relation.reason,
                            "semantic_label": relation.semantic_label,
                            "semantic_hint": relation.semantic_hint,
                            "sidecar_parameter_name": relation.sidecar_parameter_name,
                            "material_name": relation.material_name,
                            "package_label": relation.package_label,
                        }
                        for relation in getattr(family_graph, "relations", ())
                    ],
                }
            texture_binding_rows = [
                {
                    "reference_name": reference.reference_name,
                    "resolved_archive_path": reference.resolved_archive_path,
                    "semantic_label": reference.semantic_label,
                    "semantic_hint": reference.semantic_hint,
                    "sidecar_parameter_name": reference.sidecar_parameter_name,
                    "material_name": reference.material_name,
                    "relation_group": reference.relation_group,
                }
                for reference in model_texture_references
                if str(getattr(reference, "relation_group", "") or "").strip() == "Textures"
            ]
            skeleton_resolver_payload = (
                dataclasses.asdict(skeleton_resolve_report)
                if skeleton_resolve_report is not None
                else {}
            )
            skin_binding_payload = (
                build_skin_binding_map(
                    skeleton,
                    (),
                    source_path=skeleton_entry.path if skeleton_entry is not None else entry.path,
                    strict=True,
                ).to_dict()
                if skeleton is not None and getattr(skeleton, "bones", None)
                else {}
            )
            manifest_path = write_roundtrip_manifest(
                parsed_mesh,
                manifest_target_path,
                companion_path=companion_path,
                extra_payload={
                    "source_archive_path": entry.path,
                    "source_archive_format": entry.extension.lstrip(".").lower(),
                    "export_format": manifest_target_path.suffix.lstrip(".").lower(),
                    "selected_companion_files": selected_companion_files,
                    "family_graph": family_graph_payload,
                    "texture_bindings": texture_binding_rows,
                    "texture_semantics": texture_binding_rows,
                    "sidecar_hashes": sidecar_hashes,
                    "paired_pamlod_target": paired_lod_target,
                    "skeleton_identity": skeleton_entry.path if skeleton_entry is not None else "",
                    "skeleton_resolver": skeleton_resolver_payload,
                    "skin_binding_map": skin_binding_payload,
                },
            )
            if manifest_path not in output_paths:
                output_paths.append(manifest_path)
        except Exception as exc:
            _safe_log(on_log, f"Warning: could not write round-trip manifest for {entry.path}: {exc}")

    summary_lines = [
        f"Path: {entry.path}",
        f"Format: {parsed_mesh.format.upper()}",
        f"Submeshes: {len(parsed_mesh.submeshes):,}",
        f"Vertices: {parsed_mesh.total_vertices:,}",
        f"Faces: {parsed_mesh.total_faces:,}",
    ]
    if copied_related_count:
        summary_lines.append(f"Referenced files copied: {copied_related_count:,}")
    if skeleton_entry is not None and skeleton is not None and skeleton.bones:
        summary_lines.append(f"Skeleton: {skeleton_entry.path}")
        summary_lines.append(f"Skeleton bones: {len(skeleton.bones):,}")
        if skeleton_resolve_report is not None:
            summary_lines.append(
                f"Skeleton confidence: {skeleton_resolve_report.confidence}"
                + (f" ({skeleton_resolve_report.reason})" if skeleton_resolve_report.reason else "")
            )
    elif export_kind == "fbx" and entry.extension == ".pac":
        summary_lines.append("Skeleton: mesh-only export")
        if skeleton_resolution_warning:
            summary_lines.append(f"Skeleton fallback reason: {skeleton_resolution_warning}")
    return MeshExportResult(output_paths=output_paths, summary_lines=summary_lines)


def _preview_meshes_from_submeshes(submeshes: Sequence[SubMesh]) -> List[ModelPreviewMesh]:
    preview_meshes: List[ModelPreviewMesh] = []
    for submesh_index, submesh in enumerate(submeshes):
        if not submesh.vertices or not submesh.faces:
            continue
        indices: List[int] = []
        for face in submesh.faces:
            indices.extend(int(index) for index in face[:3])
        preview_mesh = ModelPreviewMesh(
            material_name=str(submesh.material or submesh.name or ""),
            texture_name=str(submesh.texture or ""),
            positions=[tuple(vertex) for vertex in submesh.vertices],
            texture_coordinates=[tuple(uv) for uv in submesh.uvs[: len(submesh.vertices)]],
            normals=[tuple(normal) for normal in submesh.normals[: len(submesh.vertices)]],
            indices=indices,
            source_submesh_index=submesh_index,
            source_vertex_indices=list(range(len(submesh.vertices))),
        )
        preview_color = tuple(getattr(submesh, "preview_color", ()) or ())
        if len(preview_color) >= 3:
            preview_mesh.preview_color = tuple(float(component) for component in preview_color[:3])
        preview_texture_path = str(getattr(submesh, "preview_texture_path", "") or "").strip()
        if preview_texture_path:
            preview_mesh.preview_texture_path = preview_texture_path
            preview_mesh.preview_texture_image = None
        preview_texture_tint = tuple(getattr(submesh, "preview_texture_tint", ()) or ())
        if len(preview_texture_tint) >= 3:
            preview_mesh.preview_texture_tint = tuple(float(component) for component in preview_texture_tint[:3])
        preview_texture_uv_scale = tuple(getattr(submesh, "preview_texture_uv_scale", ()) or ())
        if len(preview_texture_uv_scale) >= 2:
            preview_mesh.preview_texture_uv_scale = tuple(float(component) for component in preview_texture_uv_scale[:2])
        preview_texture_brightness = getattr(submesh, "preview_texture_brightness", None)
        if preview_texture_brightness is not None:
            try:
                preview_mesh.preview_texture_brightness = float(preview_texture_brightness)
            except (TypeError, ValueError, OverflowError):
                pass
        preview_native_material_overrides = getattr(submesh, "preview_native_material_overrides", None)
        if isinstance(preview_native_material_overrides, dict):
            preview_mesh.preview_native_material_overrides = dict(preview_native_material_overrides)
        preview_mesh.preview_alpha_mode = str(getattr(submesh, "preview_alpha_mode", "") or "").strip()
        preview_mesh.preview_double_sided = bool(getattr(submesh, "preview_double_sided", False))
        preview_normal_texture_path = str(getattr(submesh, "preview_normal_texture_path", "") or "").strip()
        if preview_normal_texture_path:
            preview_mesh.preview_normal_texture_path = preview_normal_texture_path
            preview_mesh.preview_normal_texture_name = str(
                getattr(submesh, "preview_normal_texture_name", "") or Path(preview_normal_texture_path).name
            )
            preview_mesh.preview_normal_texture_strength = float(
                getattr(submesh, "preview_normal_texture_strength", 0.75) or 0.75
            )
        preview_material_texture_path = str(getattr(submesh, "preview_material_texture_path", "") or "").strip()
        if preview_material_texture_path:
            preview_mesh.preview_material_texture_path = preview_material_texture_path
            preview_mesh.preview_material_texture_name = str(
                getattr(submesh, "preview_material_texture_name", "") or Path(preview_material_texture_path).name
            )
            preview_mesh.preview_material_texture_type = str(getattr(submesh, "preview_material_texture_type", "") or "").strip()
            preview_mesh.preview_material_texture_subtype = str(
                getattr(submesh, "preview_material_texture_subtype", "") or ""
            ).strip()
            preview_mesh.preview_material_texture_packed_channels = tuple(
                str(channel or "").strip()
                for channel in (getattr(submesh, "preview_material_texture_packed_channels", ()) or ())
                if str(channel or "").strip()
            )
        preview_height_texture_path = str(getattr(submesh, "preview_height_texture_path", "") or "").strip()
        if preview_height_texture_path:
            preview_mesh.preview_height_texture_path = preview_height_texture_path
            preview_mesh.preview_height_texture_name = str(
                getattr(submesh, "preview_height_texture_name", "") or Path(preview_height_texture_path).name
            )
        preview_material_texture_inputs = tuple(getattr(submesh, "preview_material_texture_inputs", ()) or ())
        if preview_material_texture_inputs:
            preview_mesh.preview_material_texture_inputs = preview_material_texture_inputs
            if any(
                "emissive" in str(getattr(item, "shader_family", "") or "").lower()
                or str(getattr(item, "slot_kind", "") or "").lower() == "emissive"
                for item in preview_material_texture_inputs
            ):
                preview_mesh.preview_sidecar_shader_family = "SkinnedMeshEmissive_Ver2"
        preview_meshes.append(preview_mesh)
    return preview_meshes


def parsed_mesh_to_preview_model(parsed_mesh: ParsedMesh) -> ModelPreviewData:
    if parsed_mesh.format == "pamlod" and parsed_mesh.lod_levels:
        source_submeshes = parsed_mesh.lod_levels[0]
        preview_model = _build_model_preview(parsed_mesh.path, "pamlod", _preview_meshes_from_submeshes(source_submeshes), "lod mesh")
        preview_model.lod_index = 0
        preview_model.lod_count = len(parsed_mesh.lod_levels)
        preview_model.summary = _build_lod_summary(
            parsed_mesh.path,
            displayed_lod_index=0,
            recovered_lod_count=len(parsed_mesh.lod_levels),
            vertex_count=preview_model.vertex_count,
            face_count=preview_model.face_count,
        )
        return preview_model

    source_submeshes = parsed_mesh.submeshes
    label = "submesh" if parsed_mesh.format != "pac" else "mesh"
    preview_model = _build_model_preview(parsed_mesh.path, parsed_mesh.format, _preview_meshes_from_submeshes(source_submeshes), label)
    if scene_import_normalizes_texture_v(parsed_mesh.format, parsed_mesh.path):
        for mesh in getattr(preview_model, "meshes", ()) or ():
            if getattr(mesh, "preview_texture_flip_vertical", None) is None:
                mesh.preview_texture_flip_vertical = False
    return preview_model


def attach_scene_preview_textures(
    preview_model: object,
    scene_result: SceneImportResult,
    scene_path: str | Path,
) -> int:
    if not isinstance(preview_model, ModelPreviewData):
        return 0
    source_path = Path(scene_path).expanduser()
    try:
        source_path = source_path.resolve()
    except OSError:
        source_path = source_path.absolute()

    texture_paths: List[Path] = []
    for candidate in tuple(scene_result.discovered_texture_files or ()) + tuple(scene_result.extracted_embedded_files or ()):
        if isinstance(candidate, Path) and candidate.is_file():
            texture_paths.append(candidate.resolve())
    for mesh in getattr(preview_model, "meshes", []) or []:
        for attr_name in (
            "preview_texture_path",
            "preview_normal_texture_path",
            "preview_material_texture_path",
            "preview_height_texture_path",
        ):
            candidate_text = str(getattr(mesh, attr_name, "") or "").strip()
            if not candidate_text:
                continue
            candidate = Path(candidate_text)
            if candidate.is_file():
                texture_paths.append(candidate.resolve())
    if not texture_paths:
        for root in (source_path.parent, source_path.parent / "textures", source_path.parent.parent / "textures"):
            if not root.is_dir():
                continue
            try:
                for candidate in root.iterdir():
                    if candidate.is_file() and candidate.suffix.lower() in SCENE_TEXTURE_SOURCE_EXTENSIONS:
                        texture_paths.append(candidate.resolve())
            except OSError:
                continue
    texture_paths = list(dict.fromkeys(texture_paths))
    by_key: Dict[str, Path] = {}
    for texture_path in texture_paths:
        by_key[str(texture_path).replace("\\", "/").lower()] = texture_path
        by_key[texture_path.as_posix().lower()] = texture_path
        by_key[texture_path.name.lower()] = texture_path
        by_key[texture_path.stem.lower()] = texture_path

    def compact(value: object) -> str:
        return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

    def slot_kind(path: Path) -> str:
        stem = compact(path.stem)
        if any(token in stem for token in ("emissive", "emission", "glow", "illumination", "illum")):
            return "emissive"
        if any(token in stem for token in ("normalmap", "normalgl", "normaldx", "normal", "nrm", "bump")):
            return "normal"
        if any(token in stem for token in ("heightmap", "height", "displacement", "disp", "depth")):
            return "height"
        if any(token in stem for token in ("basecolor", "basecolour", "albedo", "diffuse", "diffusemap", "colormap")):
            return "base"
        if any(
            token in stem
            for token in (
                "metallicroughness",
                "roughnessmetallic",
                "occlusionroughnessmetallic",
                "roughness",
                "metallic",
                "metalness",
                "ambientocclusion",
                "occlusion",
                "specular",
                "glossiness",
                "gloss",
                "opacity",
                "alpha",
                "orm",
                "rma",
                "mra",
                "arm",
                "mask",
            )
        ):
            return "material"
        return "base"

    def material_subtype(path: Path) -> str:
        stem = compact(path.stem)
        if "occlusionroughnessmetallic" in stem or "orm" in stem:
            return "orm"
        if "metallicroughness" in stem or "metalrough" in stem or "metallicrough" in stem:
            return "metallic_roughness"
        if "roughnessmetallic" in stem or "rma" in stem:
            return "rma"
        if "metallic" in stem or "metalness" in stem:
            return "metallic"
        if "roughness" in stem:
            return "roughness"
        if "occlusion" in stem or stem.endswith("ao"):
            return "ao"
        if "specular" in stem:
            return "specular"
        return "packed"

    def material_channels(subtype: str) -> Tuple[str, ...]:
        if subtype == "specular":
            return ("specular", "glossiness")
        if subtype == "metallic_roughness":
            return ("roughness", "metallic")
        if subtype == "orm":
            return ("ao", "roughness", "metallic")
        if subtype == "rma":
            return ("roughness", "metallic", "ao")
        return ()

    def texture_group_key(path: Path) -> str:
        stem = compact(path.stem)
        for token in (
            "metallicroughness",
            "roughnessmetallic",
            "occlusionroughnessmetallic",
            "basecolor",
            "basecolour",
            "diffuse",
            "albedo",
            "normalmap",
            "normalgl",
            "normaldx",
            "normal",
            "nrm",
            "bump",
            "roughness",
            "metallic",
            "metalness",
            "ambientocclusion",
            "occlusion",
            "specular",
            "glossiness",
            "gloss",
            "heightmap",
            "height",
            "displacement",
            "disp",
            "depth",
            "emissive",
            "emission",
            "glow",
            "illumination",
            "illum",
            "opacity",
            "alpha",
            "orm",
            "rma",
            "mra",
            "arm",
            "mask",
            "color",
            "colour",
            "base",
        ):
            stem = stem.replace(token, "")
        return stem or compact(path.stem)

    grouped: Dict[str, Dict[str, Path]] = defaultdict(dict)
    for texture_path in texture_paths:
        grouped[texture_group_key(texture_path)].setdefault(slot_kind(texture_path), texture_path)

    def resolve_texture(value: object) -> Optional[Path]:
        text = str(value or "").strip().replace("\\", "/")
        if not text:
            return None
        direct = Path(text)
        if direct.is_file():
            return direct.resolve()
        local = source_path.parent.joinpath(*PurePosixPath(text).parts)
        if local.is_file():
            return local.resolve()
        return by_key.get(text.lower()) or by_key.get(Path(text).name.lower()) or by_key.get(Path(text).stem.lower())

    def assign_base(mesh: ModelPreviewMesh, path: Path) -> int:
        path_text = str(path)
        mesh.preview_texture_path = path_text
        mesh.preview_texture_image = None
        mesh.preview_base_texture_default_path = path_text
        mesh.preview_base_texture_default_name = path.name
        return 1

    def assign_normal(mesh: ModelPreviewMesh, path: Path) -> int:
        path_text = str(path)
        mesh.preview_normal_texture_path = path_text
        mesh.preview_normal_texture_name = path.name
        mesh.preview_normal_texture_strength = float(getattr(mesh, "preview_normal_texture_strength", 0.0) or 0.75)
        mesh.preview_normal_texture_default_path = path_text
        mesh.preview_normal_texture_default_name = path.name
        mesh.preview_normal_texture_default_strength = mesh.preview_normal_texture_strength
        return 1

    def assign_material(mesh: ModelPreviewMesh, path: Path) -> int:
        path_text = str(path)
        subtype = material_subtype(path)
        mesh.preview_material_texture_path = path_text
        mesh.preview_material_texture_name = path.name
        mesh.preview_material_texture_type = subtype if subtype in {"ao", "specular", "roughness", "metallic"} else "material"
        mesh.preview_material_texture_subtype = subtype
        mesh.preview_material_texture_packed_channels = material_channels(subtype)
        mesh.preview_material_texture_default_path = path_text
        mesh.preview_material_texture_default_name = path.name
        mesh.preview_material_texture_default_type = mesh.preview_material_texture_type
        mesh.preview_material_texture_default_subtype = mesh.preview_material_texture_subtype
        mesh.preview_material_texture_default_packed_channels = mesh.preview_material_texture_packed_channels
        return 1

    def assign_material_input(
        mesh: ModelPreviewMesh,
        *,
        slot_kind: str,
        path: Path,
        semantic_type: str,
        semantic_subtype: str,
        packed_channels: Sequence[str] = (),
        shader_family: str = "",
        parameters: Sequence[PreviewMaterialParameterInput] = (),
    ) -> int:
        existing = list(getattr(mesh, "preview_material_texture_inputs", ()) or ())
        path_text = str(path)
        normalized_path_text = path_text.replace("\\", "/").lower()
        if any(
            str(getattr(item, "slot_kind", "") or "").lower() == slot_kind
            and (
                str(getattr(item, "texture_name", "") or "").lower() == path.name.lower()
                or str(
                    getattr(item, "preview_texture_path", "")
                    or getattr(item, "source_texture_path", "")
                    or ""
                ).replace("\\", "/").lower()
                == normalized_path_text
            )
            for item in existing
        ):
            return 0
        parameter_name = {
            "base": "_baseColorTexture",
            "normal": "_normalTexture",
            "material": "_metallicRoughnessTexture",
            "ao": "_occlusionTexture",
            "emissive": "_emissiveIntensityTexture",
            "height": "_heightTexture",
        }.get(slot_kind, "")
        existing.append(
            PreviewMaterialTextureInput(
                slot_kind=slot_kind,
                parameter_name=parameter_name,
                source_texture_path=path_text,
                source_dds_path=path_text if path.suffix.lower() == ".dds" else "",
                texture_name=path.name,
                preview_texture_path=path_text,
                semantic_type=semantic_type,
                semantic_subtype=semantic_subtype,
                packed_channels=tuple(str(channel) for channel in packed_channels if str(channel)),
                material_name=str(getattr(mesh, "material_name", "") or "").strip(),
                shader_family=shader_family,
                confidence="scene",
                visualized=True,
                material_parameters=tuple(parameters),
            )
        )
        mesh.preview_material_texture_inputs = tuple(existing)
        if slot_kind == "emissive":
            mesh.preview_sidecar_shader_family = "SkinnedMeshEmissive_Ver2"
        return 1

    def assign_emissive(mesh: ModelPreviewMesh, path: Path) -> int:
        return assign_material_input(
            mesh,
            slot_kind="emissive",
            path=path,
            semantic_type="emissive",
            semantic_subtype="emissive",
            shader_family="SkinnedMeshEmissive_Ver2",
            parameters=(
                PreviewMaterialParameterInput(
                    parameter_kind="float",
                    parameter_name="_emissiveIntensity",
                    value="1.000000",
                    numeric_value=1.0,
                ),
            ),
        )

    def assign_height(mesh: ModelPreviewMesh, path: Path) -> int:
        path_text = str(path)
        mesh.preview_height_texture_path = path_text
        mesh.preview_height_texture_name = path.name
        mesh.preview_height_texture_default_path = path_text
        mesh.preview_height_texture_default_name = path.name
        return 1

    meshes = [mesh for mesh in getattr(preview_model, "meshes", []) or [] if isinstance(mesh, ModelPreviewMesh)]
    base_candidates = [path for path in texture_paths if slot_kind(path) == "base"]
    single_mesh_base = base_candidates[0] if len(meshes) == 1 and len(base_candidates) == 1 else None
    resolved_count = 0
    for mesh in meshes:
        resolved_paths: Dict[str, Path] = {}
        for slot_name, attr_name in (
            ("base", "preview_texture_path"),
            ("normal", "preview_normal_texture_path"),
            ("material", "preview_material_texture_path"),
            ("height", "preview_height_texture_path"),
        ):
            existing = resolve_texture(getattr(mesh, attr_name, ""))
            if existing is not None:
                resolved_paths[slot_name] = existing
        named_texture = resolve_texture(getattr(mesh, "texture_name", ""))
        if named_texture is not None:
            named_kind = slot_kind(named_texture)
            if named_kind == "base":
                resolved_paths.setdefault("base", named_texture)
            elif named_kind == "normal":
                resolved_paths.setdefault("normal", named_texture)
            elif named_kind == "height":
                resolved_paths.setdefault("height", named_texture)
            else:
                resolved_paths.setdefault("material", named_texture)
        for item in tuple(getattr(mesh, "preview_material_texture_inputs", ()) or ()):
            slot_name = str(getattr(item, "slot_kind", "") or "").strip().lower()
            if slot_name not in {"base", "normal", "material", "ao", "emissive", "height"}:
                continue
            existing = resolve_texture(
                str(getattr(item, "preview_texture_path", "") or "")
                or str(getattr(item, "source_texture_path", "") or "")
                or str(getattr(item, "texture_name", "") or "")
            )
            if existing is not None:
                resolved_paths.setdefault(slot_name, existing)

        sibling_group: Mapping[str, Path] = {}
        group_source = resolved_paths.get("base") or resolved_paths.get("material") or resolved_paths.get("normal") or resolved_paths.get("height")
        if group_source is not None:
            sibling_group = grouped.get(texture_group_key(group_source), {})
        material_key = compact(getattr(mesh, "material_name", ""))
        if not resolved_paths.get("base") and material_key:
            for group_key, group in grouped.items():
                base_path = group.get("base")
                if base_path is None:
                    continue
                compact_group_key = compact(group_key)
                if compact_group_key and (compact_group_key in material_key or material_key in compact_group_key):
                    resolved_paths["base"] = base_path
                    sibling_group = group
                    break
        if not resolved_paths.get("base") and sibling_group.get("base") is not None:
            group_key = compact(texture_group_key(group_source)) if group_source is not None else ""
            if not material_key or (group_key and (group_key in material_key or material_key in group_key)):
                resolved_paths["base"] = sibling_group["base"]
        if not resolved_paths.get("base") and single_mesh_base is not None:
            resolved_paths["base"] = single_mesh_base

        if resolved_paths.get("base") is not None:
            resolved_count += assign_base(mesh, resolved_paths["base"])
        if sibling_group:
            resolved_paths.setdefault("normal", sibling_group.get("normal"))
            resolved_paths.setdefault("material", sibling_group.get("material"))
            resolved_paths.setdefault("emissive", sibling_group.get("emissive"))
            resolved_paths.setdefault("height", sibling_group.get("height"))
        if resolved_paths.get("normal") is not None:
            resolved_count += assign_normal(mesh, resolved_paths["normal"])
        if resolved_paths.get("material") is not None:
            resolved_count += assign_material(mesh, resolved_paths["material"])
            subtype = material_subtype(resolved_paths["material"])
            resolved_count += assign_material_input(
                mesh,
                slot_kind="material",
                path=resolved_paths["material"],
                semantic_type="material",
                semantic_subtype=subtype,
                packed_channels=material_channels(subtype),
            )
        if resolved_paths.get("ao") is not None:
            resolved_count += assign_material_input(
                mesh,
                slot_kind="ao",
                path=resolved_paths["ao"],
                semantic_type="ao",
                semantic_subtype="ao",
                packed_channels=("ao",),
            )
        if resolved_paths.get("emissive") is not None:
            resolved_count += assign_emissive(mesh, resolved_paths["emissive"])
        if resolved_paths.get("height") is not None:
            resolved_count += assign_height(mesh, resolved_paths["height"])
    return resolved_count


def _restore_rebuilt_mesh_texture_identity(
    source_mesh: ParsedMesh,
    rebuilt_mesh: ParsedMesh,
) -> int:
    if not source_mesh.submeshes or not rebuilt_mesh.submeshes:
        return 0

    def _normalize_identity(value: str) -> str:
        return str(value or "").strip().lower()

    source_by_name: Dict[str, SubMesh] = {}
    duplicate_names: set[str] = set()
    for submesh in source_mesh.submeshes:
        normalized_name = _normalize_identity(submesh.name)
        if not normalized_name:
            continue
        if normalized_name in source_by_name:
            duplicate_names.add(normalized_name)
            continue
        source_by_name[normalized_name] = submesh
    for duplicate_name in duplicate_names:
        source_by_name.pop(duplicate_name, None)

    restored_count = 0
    for index, rebuilt_submesh in enumerate(rebuilt_mesh.submeshes):
        source_submesh: Optional[SubMesh] = None
        normalized_name = _normalize_identity(rebuilt_submesh.name)
        if normalized_name:
            source_submesh = source_by_name.get(normalized_name)
        if source_submesh is None and index < len(source_mesh.submeshes):
            source_submesh = source_mesh.submeshes[index]
        if source_submesh is None:
            continue

        source_texture = str(getattr(source_submesh, "texture", "") or "").strip()
        if source_texture and str(getattr(rebuilt_submesh, "texture", "") or "").strip() != source_texture:
            rebuilt_submesh.texture = source_texture
            restored_count += 1
        if not str(getattr(rebuilt_submesh, "material", "") or "").strip():
            rebuilt_submesh.material = str(getattr(source_submesh, "material", "") or "").strip()
        if not str(getattr(rebuilt_submesh, "name", "") or "").strip():
            rebuilt_submesh.name = str(getattr(source_submesh, "name", "") or "").strip()
    return restored_count


def build_mesh_preview_from_bytes(data: bytes, virtual_path: str) -> Tuple[ModelPreviewData, ParsedMesh]:
    parsed_mesh = parse_mesh(data, virtual_path)
    preview_model = parsed_mesh_to_preview_model(parsed_mesh)
    return preview_model, parsed_mesh


def _build_selected_sidecar_texture_bindings(
    supplemental_files: Sequence[Path],
) -> Tuple[
    Tuple[object, ...],
    Tuple[str, ...],
    Dict[str, Tuple[str, ...]],
    Dict[str, Tuple[str, ...]],
]:
    from collections import defaultdict

    from cdmw.core.archive import _ArchiveModelSidecarTextureBinding
    from cdmw.core.upscale_profiles import normalize_texture_reference_for_sidecar_lookup, parse_texture_sidecar_bindings

    bindings: List[object] = []
    sidecar_paths: List[str] = []
    seen_binding_keys: set[Tuple[str, str, str]] = set()
    sidecar_texts_by_normalized_path: Dict[str, List[str]] = defaultdict(list)
    sidecar_texts_by_basename: Dict[str, List[str]] = defaultdict(list)

    def append_unique_text(target: Dict[str, List[str]], key: str, text: str) -> None:
        normalized_key = str(key or "").strip()
        normalized_text = str(text or "")
        if not normalized_key or not normalized_text.strip():
            return
        bucket = target[normalized_key]
        if normalized_text not in bucket:
            bucket.append(normalized_text)

    def read_sidecar_text(path: Path) -> str:
        data = path.read_bytes()
        for encoding in ("utf-8-sig", "utf-16", "utf-8", "cp1252"):
            try:
                return data.decode(encoding).replace("\ufeff", "")
            except UnicodeError:
                continue
        return data.decode("utf-8", errors="replace").replace("\ufeff", "")

    for supplemental_path in supplemental_files:
        if supplemental_path.suffix.lower() not in MESH_IMPORT_SIDECAR_EXTENSIONS:
            continue
        resolved_path = supplemental_path.expanduser().resolve()
        if not resolved_path.is_file():
            continue
        try:
            text = read_sidecar_text(resolved_path)
        except Exception:
            continue
        parsed_bindings = parse_texture_sidecar_bindings(text, sidecar_path=resolved_path.name)
        if not parsed_bindings:
            continue
        sidecar_paths.append(resolved_path.name)
        for binding in parsed_bindings:
            texture_role = binding.texture_role
            visualization_state = binding.visualization_state
            try:
                from cdmw.modding.asset_replacement import classify_texture_binding

                classification = classify_texture_binding(binding.parameter_name, binding.texture_path)
                texture_role = classification.slot_label or classification.slot_kind
                visualization_state = classification.visual_state
            except Exception:
                pass
            normalized_texture_path = normalize_texture_reference_for_sidecar_lookup(binding.texture_path)
            key = (
                normalized_texture_path,
                str(binding.submesh_name or "").strip().lower(),
                str(binding.parameter_name or "").strip().lower(),
            )
            if normalized_texture_path:
                append_unique_text(sidecar_texts_by_normalized_path, normalized_texture_path, text)
                basename = PurePosixPath(normalized_texture_path).name
                if basename:
                    append_unique_text(sidecar_texts_by_basename, basename, text)
            if key in seen_binding_keys:
                continue
            seen_binding_keys.add(key)
            bindings.append(
                _ArchiveModelSidecarTextureBinding(
                    texture_path=binding.texture_path,
                    parameter_name=binding.parameter_name,
                    submesh_name=binding.submesh_name,
                    sidecar_path=resolved_path.name,
                    sidecar_kind=binding.sidecar_kind,
                    linked_mesh_path=binding.linked_mesh_path,
                    part_name=binding.part_name,
                    material_name=binding.material_name,
                    shader_family=binding.shader_family,
                    texture_role=texture_role,
                    visualization_state=visualization_state,
                    resolved_texture_exists=binding.resolved_texture_exists,
                    srgb_mode=str(getattr(binding, "srgb_mode", "") or ""),
                    parameter_declared_by=str(getattr(binding, "parameter_declared_by", "") or ""),
                    material_output_quality=str(getattr(binding, "material_output_quality", "") or ""),
                    layer_role=str(getattr(binding, "layer_role", "") or ""),
                    layer_channel=str(getattr(binding, "layer_channel", "") or ""),
                    blend_flags=tuple(
                        str(value)
                        for value in tuple(getattr(binding, "blend_flags", ()) or ())
                        if str(value)
                    ),
                )
            )
    return (
        tuple(bindings),
        tuple(sidecar_paths),
        {key: tuple(values) for key, values in sidecar_texts_by_normalized_path.items()},
        {key: tuple(values) for key, values in sidecar_texts_by_basename.items()},
    )


def _build_mesh_import_supplemental_file_specs(
    entry: ArchiveEntry,
    supplemental_files: Sequence[Path],
    texture_references: Sequence[ArchiveModelTextureReference],
    *,
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
) -> Tuple[MeshImportSupplementalFileSpec, ...]:
    if not supplemental_files:
        return ()

    reference_candidates_by_basename: Dict[str, List[str]] = {}
    for reference in texture_references:
        resolved_archive_path = str(getattr(reference, "resolved_archive_path", "") or "").strip()
        reference_name = str(getattr(reference, "reference_name", "") or "").strip()
        target_path = resolved_archive_path or reference_name
        if not target_path:
            continue
        basename = PurePosixPath(target_path.replace("\\", "/")).name.lower()
        if not basename:
            continue
        bucket = reference_candidates_by_basename.setdefault(basename, [])
        if target_path not in bucket:
            bucket.append(target_path)

    related_entries: Sequence[ArchiveEntry] = ()
    if archive_entries_by_basename is not None:
        from cdmw.core.archive import _find_archive_model_related_entries

        related_entries = _find_archive_model_related_entries(entry, dict(archive_entries_by_basename))
    related_entries_by_extension: Dict[str, List[ArchiveEntry]] = {}
    for related_entry in related_entries:
        related_entries_by_extension.setdefault(related_entry.extension.lower(), []).append(related_entry)

    specs: List[MeshImportSupplementalFileSpec] = []
    for supplemental_path in supplemental_files:
        resolved_source = supplemental_path.expanduser().resolve()
        if not resolved_source.is_file():
            continue
        extension = resolved_source.suffix.lower()
        if extension in SCENE_TEXTURE_SOURCE_EXTENSIONS - {".dds"}:
            continue
        preferred_paths: List[str] = []
        if extension == ".dds":
            preferred_paths.extend(reference_candidates_by_basename.get(resolved_source.name.lower(), ()))
            preferred_paths.extend(_mesh_import_loose_texture_preferred_paths(resolved_source))
        elif extension in MESH_IMPORT_SIDECAR_EXTENSIONS:
            preferred_paths.extend(
                _mesh_import_sidecar_preferred_paths(entry, resolved_source, related_entries_by_extension)
            )
        elif extension in MESH_IMPORT_COMPANION_EXTENSIONS:
            preferred_paths.extend(_mesh_import_candidate_virtual_paths(resolved_source))
        target_entry, target_path = _resolve_supplemental_target_entry(
            resolved_source,
            archive_entries_by_normalized_path=archive_entries_by_normalized_path,
            archive_entries_by_basename=archive_entries_by_basename,
            preferred_paths=preferred_paths,
        )
        if extension == ".dds" and target_entry is None and not preferred_paths:
            continue
        kind = (
            "texture"
            if extension == ".dds"
            else "sidecar"
            if extension in MESH_IMPORT_SIDECAR_EXTENSIONS
            else "companion"
            if extension in MESH_IMPORT_COMPANION_EXTENSIONS
            else "file"
        )
        specs.append(
            MeshImportSupplementalFileSpec(
                source_path=resolved_source,
                target_path=target_path or (target_entry.path if isinstance(target_entry, ArchiveEntry) else ""),
                kind=kind,
                target_entry=target_entry if isinstance(target_entry, ArchiveEntry) else None,
                used_for_preview=kind in {"texture", "sidecar", "companion"},
            )
        )
    return tuple(specs)


def _find_first_archive_entry_by_virtual_path(
    virtual_path: str,
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]],
) -> Optional[ArchiveEntry]:
    if archive_entries_by_normalized_path is None:
        return None
    candidates = archive_entries_by_normalized_path.get(_normalize_virtual_path(virtual_path), ())
    return candidates[0] if candidates else None


def _collect_original_mesh_sidecar_texts(
    entry: ArchiveEntry,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]],
) -> Tuple[Tuple[ArchiveEntry, str], ...]:
    if archive_entries_by_basename is None:
        return ()
    from cdmw.core.archive import (
        _find_archive_model_sidecar_entries,
        read_archive_entry_data,
        try_decode_text_like_archive_data,
    )

    sidecars: List[Tuple[ArchiveEntry, str]] = []
    for sidecar_entry in _find_archive_model_sidecar_entries(entry, dict(archive_entries_by_basename)):
        try:
            sidecar_data, _decompressed, _note = read_archive_entry_data(sidecar_entry)
        except Exception:
            continue
        sidecar_text = try_decode_text_like_archive_data(sidecar_data)
        if sidecar_text:
            sidecars.append((sidecar_entry, sidecar_text))
    return tuple(sidecars)


def _source_owned_target_names_from_sidecars(
    original_sidecars: Sequence[Tuple[ArchiveEntry, str]],
) -> Tuple[str, ...]:
    """Return game-runtime submesh wrapper names in original _subMeshResources order."""
    for _sidecar_entry, sidecar_text in tuple(original_sidecars or ()):
        text = str(sidecar_text or "")
        if "_subMeshResources" not in text or "SkinnedMeshMaterialWrapper" not in text:
            continue
        vector_match = re.search(
            r'<Vector\b[^>]*\bName="_subMeshResources"[^>]*>(?P<body>.*?)</Vector>\s*</SkinnedMeshProperty>',
            text,
            flags=re.IGNORECASE | re.DOTALL,
        )
        body = vector_match.group("body") if vector_match is not None else text
        names: List[str] = []
        for match in re.finditer(
            r'<SkinnedMeshMaterialWrapper\b(?P<attrs>[^>]*)>',
            body,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            attrs = match.group("attrs") or ""
            name_match = re.search(
                r'\b(?:_subMeshName|subMeshName|SubMeshName)="([^"]+)"',
                attrs,
                flags=re.IGNORECASE,
            )
            name = str(name_match.group(1) if name_match else "").strip()
            if name:
                names.append(name)
        if names:
            return tuple(names)
    return ()


def _mesh_import_normalize_runtime_stem_candidate(value: str) -> str:
    candidate = str(value or "").replace("\\", "/").strip().strip('"').strip("'").lower()
    if not candidate:
        return ""
    candidate = PurePosixPath(candidate).name
    for suffix in _MESH_IMPORT_TEXTURE_SUFFIXES:
        if candidate.endswith(suffix):
            candidate = candidate[: -len(suffix)]
            break
    for suffix in _MESH_IMPORT_SHORT_TEXTURE_SUFFIXES:
        if candidate.endswith(suffix) and len(candidate) > len(suffix):
            candidate = candidate[: -len(suffix)]
            break
    candidate = re.sub(r"[^a-z0-9_]+", "_", candidate).strip("_")
    if not candidate.startswith("cd_") or len(candidate) < 8:
        return ""
    return candidate


def _mesh_import_runtime_stem_candidates_from_sidecars(
    original_sidecars: Sequence[Tuple[ArchiveEntry, str]],
) -> Tuple[str, ...]:
    stems: List[str] = []
    seen: set[str] = set()
    for _sidecar_entry, sidecar_text in tuple(original_sidecars or ()):
        text = str(sidecar_text or "").replace("\\", "/")
        if not text:
            continue
        for pattern in (
            r'\b(?:_subMeshName|subMeshName|SubMeshName)="([^"]+)"',
            r'\b_path="([^"]+)"',
            r'\bvalue="([^"]+)"',
        ):
            for match in re.finditer(pattern, text, flags=re.IGNORECASE):
                stem = _mesh_import_normalize_runtime_stem_candidate(match.group(1))
                if stem and stem not in seen:
                    stems.append(stem)
                    seen.add(stem)
    return tuple(stems)


def _mesh_import_runtime_mesh_paths_from_sidecars(
    original_sidecars: Sequence[Tuple[ArchiveEntry, str]],
) -> Tuple[str, ...]:
    paths: List[str] = []
    seen: set[str] = set()
    extension_pattern = "|".join(re.escape(ext.lstrip(".")) for ext in sorted(_MESH_IMPORT_RUNTIME_MESH_EXTENSIONS))
    path_pattern = re.compile(
        rf"character/model/[^\s\"'<>]+?\.(?:{extension_pattern})\b",
        flags=re.IGNORECASE,
    )
    for _sidecar_entry, sidecar_text in tuple(original_sidecars or ()):
        text = str(sidecar_text or "")
        if not text:
            continue
        for match in path_pattern.finditer(text):
            path = match.group(0).replace("\\", "/").strip().strip('"').strip("'")
            key = path.lower()
            if key and key not in seen:
                paths.append(path)
                seen.add(key)
    return tuple(paths)


def _mesh_import_runtime_stem_candidates_from_mesh(mesh: ParsedMesh) -> Tuple[str, ...]:
    stems: List[str] = []
    seen: set[str] = set()
    for submesh in tuple(getattr(mesh, "submeshes", ()) or ()):
        for raw_value in (
            getattr(submesh, "name", ""),
            getattr(submesh, "material", ""),
            getattr(submesh, "texture", ""),
        ):
            stem = _mesh_import_normalize_runtime_stem_candidate(str(raw_value or ""))
            if stem and stem not in seen:
                stems.append(stem)
                seen.add(stem)
    return tuple(stems)


def _mesh_import_runtime_sibling_mesh_candidates(
    entry: ArchiveEntry,
    mesh: ParsedMesh,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]],
    original_sidecars: Sequence[Tuple[ArchiveEntry, str]] = (),
) -> Tuple[ArchiveEntry, ...]:
    if archive_entries_by_basename is None:
        return ()
    source_path = str(getattr(entry, "path", "") or "").replace("\\", "/").strip().lower()
    source_extension = str(getattr(entry, "extension", "") or "").strip().lower()
    if source_extension not in _MESH_IMPORT_RUNTIME_MESH_EXTENSIONS:
        return ()
    # Submesh names and DDS stems often describe shared material families, not
    # runtime mesh identity. Only explicit model mesh paths from sidecars are
    # strong enough to warn that the selected PAC may not be the runtime target.
    runtime_paths = _mesh_import_runtime_mesh_paths_from_sidecars(original_sidecars)
    if not runtime_paths:
        return ()
    candidates: List[ArchiveEntry] = []
    seen_paths: set[str] = set()
    for runtime_path in runtime_paths:
        runtime_key = str(runtime_path or "").replace("\\", "/").strip().lower()
        basename = PurePosixPath(runtime_key).name
        if not basename:
            continue
        basename_candidates = list(archive_entries_by_basename.get(basename, ()) or ())
        if basename != basename.lower():
            basename_candidates.extend(archive_entries_by_basename.get(basename.lower(), ()) or ())
        for candidate in tuple(basename_candidates):
            candidate_path = str(getattr(candidate, "path", "") or "").replace("\\", "/").strip()
            candidate_key = candidate_path.lower()
            if not candidate_key or candidate_key == source_path or candidate_key in seen_paths:
                continue
            if candidate_key != runtime_key:
                continue
            if str(getattr(candidate, "extension", "") or "").strip().lower() not in _MESH_IMPORT_RUNTIME_MESH_EXTENSIONS:
                continue
            if "character/model/" not in candidate_key:
                continue
            candidates.append(candidate)
            seen_paths.add(candidate_key)

    def _score(candidate: ArchiveEntry) -> Tuple[int, int, str]:
        path = str(getattr(candidate, "path", "") or "").replace("\\", "/").lower()
        score = 0
        if "/1_pc/" in path:
            score += 80
        if "/armor/" in path:
            score += 30
        if "/2_mon/" in source_path and "/2_mon/" not in path:
            score += 20
        if "/modelproperty/" not in path and "character/model/" in path:
            score += 5
        return (score, -len(path), path)

    candidates.sort(key=_score, reverse=True)
    return tuple(candidates[:12])


def mesh_import_runtime_sibling_mesh_candidates(
    entry: ArchiveEntry,
    mesh: ParsedMesh,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]],
    original_sidecars: Sequence[Tuple[ArchiveEntry, str]] = (),
) -> Tuple[ArchiveEntry, ...]:
    """Return likely runtime mesh targets for display/preview clone sources."""

    return _mesh_import_runtime_sibling_mesh_candidates(
        entry,
        mesh,
        archive_entries_by_basename,
        original_sidecars,
    )


def _mesh_import_runtime_sibling_warning_lines(
    entry: ArchiveEntry,
    mesh: ParsedMesh,
    archive_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]],
    original_sidecars: Sequence[Tuple[ArchiveEntry, str]] = (),
) -> Tuple[str, ...]:
    candidates = _mesh_import_runtime_sibling_mesh_candidates(
        entry,
        mesh,
        archive_entries_by_basename,
        original_sidecars,
    )
    if not candidates:
        return ()
    source_path = str(getattr(entry, "path", "") or "").replace("\\", "/").strip().lower()
    has_player_candidate = any("/1_pc/" in str(getattr(candidate, "path", "") or "").replace("\\", "/").lower() for candidate in candidates)
    if "/2_mon/" not in source_path and not has_player_candidate:
        return ()
    lines = [
        "Runtime target warning: this selected mesh appears to be a display/monster clone that references player equipment mesh names. "
        "Editing/exporting only this PAC can look correct in preview but leave the equipped in-game model unchanged."
        if "/2_mon/" in source_path and has_player_candidate
        else "Runtime target warning: related runtime mesh candidates with the same material/submesh family were found. "
        "If in-game output does not change, edit/export the runtime mesh path instead of only this preview source.",
        "Likely runtime mesh candidate(s):",
    ]
    for candidate in candidates[:6]:
        lines.append(f"  {candidate.path}")
    if len(candidates) > 6:
        lines.append(f"  ... {len(candidates) - 6:,} more candidate(s)")
    return tuple(lines)


def _decode_text_payload(data: bytes) -> str:
    for encoding in ("utf-8-sig", "utf-16", "utf-8", "cp1252"):
        try:
            return bytes(data or b"").decode(encoding).replace("\ufeff", "")
        except UnicodeError:
            continue
    return bytes(data or b"").decode("utf-8", errors="replace").replace("\ufeff", "")


def _summarize_crimson_companion_supplemental_files(supplemental_files: Sequence[Path]) -> Tuple[str, ...]:
    companion_files = [
        path
        for path in tuple(supplemental_files or ())
        if isinstance(path, Path) and path.suffix.lower() in (MESH_IMPORT_COMPANION_EXTENSIONS | {".pami"})
    ]
    if not companion_files:
        return ()
    try:
        from cdmw.core.crimson_formats import (
            complete_swap_file_policy,
            decode_meshinfo,
            decode_paa_metabin,
            decode_prefab,
            parse_pami_material_instances,
        )
    except Exception:
        return ()
    try:
        from cdmw.rendering.material_channels import parse_crimson_material_definition_text
    except Exception:
        parse_crimson_material_definition_text = None  # type: ignore[assignment]

    lines: List[str] = ["Crimson companion metadata:"]
    for path in companion_files[:12]:
        extension = path.suffix.lower()
        policy = complete_swap_file_policy(extension)
        try:
            data = path.read_bytes()
        except OSError as exc:
            lines.append(f"  {path.name}: unreadable ({exc})")
            continue
        if extension == ".prefab":
            decoded = decode_prefab(data)
            roles = Counter(reference.role for reference in decoded.references)
            role_text = _summarize_compact([f"{role}={count}" for role, count in sorted(roles.items())]) or "no resource refs"
            lines.append(
                f"  {path.name}: prefab refs {role_text}; patchable={decoded.patchable_reference_count}; policy={policy}"
            )
        elif extension == ".meshinfo":
            decoded = decode_meshinfo(data)
            roles = Counter(reference.role for reference in decoded.references)
            role_text = _summarize_compact([f"{role}={count}" for role, count in sorted(roles.items())]) or "no visible refs"
            lines.append(f"  {path.name}: meshinfo refs {role_text}; policy={decoded.material_policy}")
        elif extension == ".paa_metabin":
            decoded = decode_paa_metabin(data)
            declared = decoded.declared_type or "AnimationMetaData"
            lines.append(f"  {path.name}: {declared}; policy={decoded.material_policy}")
        elif extension == ".pami":
            instances = parse_pami_material_instances(_decode_text_payload(data))
            texture_count = sum(len(instance.texture_parameters) for instance in instances)
            lines.append(
                f"  {path.name}: pami material instances={len(instances)}, texture params={texture_count}; policy={policy}"
            )
        elif extension == ".material" and parse_crimson_material_definition_text is not None:
            try:
                definition = parse_crimson_material_definition_text(_decode_text_payload(data), source_path=str(path))
                lines.append(
                    f"  {path.name}: material technique={definition.technique or '-'}, params={len(definition.parameters)}, groups={len(definition.parameter_groups)}; policy={policy}"
                )
            except Exception as exc:
                lines.append(f"  {path.name}: material definition parse failed ({exc}); policy={policy}")
        else:
            lines.append(f"  {path.name}: policy={policy}")
    if len(companion_files) > 12:
        lines.append(f"  ... {len(companion_files) - 12:,} more companion file(s)")
    return tuple(lines)


def _mesh_texture_original_source_path(texture_entry: object) -> Path:
    from cdmw.core.archive import ensure_archive_preview_source

    if not isinstance(texture_entry, ArchiveEntry):
        raise ValueError("Original texture archive entry is unavailable.")
    source_path, _note = ensure_archive_preview_source(texture_entry)
    return source_path


def _mesh_texture_original_bytes(texture_entry: object) -> bytes:
    from cdmw.core.archive import read_archive_entry_data

    if not isinstance(texture_entry, ArchiveEntry):
        raise ValueError("Original texture archive entry is unavailable.")
    data, _decompressed, _note = read_archive_entry_data(texture_entry)
    return data


def _texture_replacement_payloads_to_specs(
    payloads: Sequence[TextureReplacementPayload],
    *,
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]],
) -> Tuple[MeshImportSupplementalFileSpec, ...]:
    specs: List[MeshImportSupplementalFileSpec] = []
    for payload in payloads:
        target_entry = _find_first_archive_entry_by_virtual_path(
            payload.target_path,
            archive_entries_by_normalized_path,
        )
        specs.append(
            MeshImportSupplementalFileSpec(
                source_path=payload.source_path,
                target_path=payload.target_path,
                kind=payload.kind,
                target_entry=target_entry,
                used_for_preview=True,
                payload_data=payload.payload_data,
                note=payload.note,
            )
        )
    return tuple(specs)


def _generated_texture_preview_file(payload: TextureReplacementPayload) -> Path:
    digest = hashlib.sha1(payload.payload_data).hexdigest()[:16]
    target_name = PurePosixPath(str(payload.target_path or "").replace("\\", "/")).name
    if not target_name:
        target_name = payload.source_path.with_suffix(".dds").name
    if not target_name.lower().endswith(".dds"):
        target_name = f"{Path(target_name).stem}.dds"
    output_dir = app_temp_cache_path("static_mesh_texture_previews")
    output_dir.mkdir(parents=True, exist_ok=True)
    output_path = output_dir / f"{Path(target_name).stem}_{digest}.dds"
    if not output_path.is_file():
        output_path.write_bytes(payload.payload_data)
        request_app_temp_cache_prune()
    return output_path


def _apply_generated_static_texture_previews(
    preview_model: ModelPreviewData,
    *,
    generated_payloads: Sequence[TextureReplacementPayload],
    texture_replacement_report: object,
    texconv_path: Optional[Path],
) -> int:
    if not getattr(preview_model, "meshes", None):
        return 0
    texture_payloads_by_target = {
        str(payload.target_path or "").replace("\\", "/").strip().lower(): payload
        for payload in generated_payloads
        if payload.kind == "texture_generated" and payload.payload_data
    }
    if not texture_payloads_by_target:
        return 0

    from cdmw.core.archive import _resolve_model_texture_semantic_details
    from cdmw.core.pipeline import ensure_dds_display_preview_png, parse_dds

    resolved_texconv_path = texconv_path.expanduser().resolve() if texconv_path is not None and texconv_path.expanduser().is_file() else None
    preview_cache: Dict[str, str] = {}

    def _preview_path_for_payload(payload: TextureReplacementPayload) -> str:
        dds_path = _generated_texture_preview_file(payload)
        cache_key = dds_path.as_posix().lower()
        cached = preview_cache.get(cache_key, "")
        if cached:
            return cached
        dds_info = None
        try:
            dds_info = parse_dds(dds_path)
        except Exception:
            dds_info = None
        preview_path = ensure_dds_display_preview_png(resolved_texconv_path, dds_path, dds_info=dds_info)
        preview_cache[cache_key] = preview_path
        return preview_path

    def _tokens(value: str) -> set[str]:
        stop_words = {"cd", "phm", "pc", "texture", "textures", "dds", "png", "normal", "base", "color", "roughness", "metallic"}
        tokens: set[str] = set()
        for raw_token in re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).split():
            token = re.sub(r"\d+$", "", raw_token.strip())
            if len(token) > 1 and token not in stop_words and not token.isdigit():
                tokens.add(token)
        return tokens

    def _mesh_match_score(mesh: ModelPreviewMesh, material_name: str, texture_path: str) -> float:
        mesh_material = str(getattr(mesh, "material_name", "") or "")
        mesh_name = str(getattr(mesh, "name", "") or "")
        material_key = str(material_name or "").strip().lower()
        mesh_material_key = mesh_material.strip().lower()
        if material_key and mesh_material_key == material_key:
            return 100.0
        query_tokens = _tokens(f"{material_name} {texture_path}")
        mesh_tokens = _tokens(f"{mesh_material} {mesh_name}")
        if not query_tokens or not mesh_tokens:
            return 0.0
        overlap = query_tokens & mesh_tokens
        score = float(len(overlap) * 12)
        for token in overlap:
            score += min(6.0, len(token) * 0.75)
        for query_token in query_tokens:
            for mesh_token in mesh_tokens:
                if len(query_token) >= 4 and len(mesh_token) >= 4 and (query_token in mesh_token or mesh_token in query_token):
                    score += 3.0
        return score

    def _candidate_meshes(material_name: str, texture_path: str) -> List[ModelPreviewMesh]:
        scored = [
            (_mesh_match_score(mesh, material_name, texture_path), mesh)
            for mesh in preview_model.meshes
        ]
        best_score = max((score for score, _mesh in scored), default=0.0)
        if best_score > 0.0:
            return [mesh for score, mesh in scored if score == best_score]
        return list(preview_model.meshes) if len(preview_model.meshes) == 1 else []

    assigned_count = 0
    slot_mappings = list(getattr(texture_replacement_report, "slot_mappings", ()) or ())
    source_material_by_target: Dict[str, str] = {}
    base_targets: set[str] = set()
    for mapping in slot_mappings:
        target_path = str(getattr(mapping, "output_texture_path", "") or "").replace("\\", "/").strip().lower()
        payload = texture_payloads_by_target.get(target_path)
        if payload is None:
            continue
        target_material_name = str(getattr(mapping, "target_material_name", "") or "")
        source_material_name = str(getattr(mapping, "source_material_name", "") or "")
        if target_material_name and source_material_name:
            source_material_by_target.setdefault(target_material_name.strip().lower(), source_material_name)
        try:
            preview_path = _preview_path_for_payload(payload)
        except Exception:
            continue
        slot_kind = str(getattr(mapping, "slot_kind", "") or "").strip().lower()
        if slot_kind == "base" and target_material_name:
            base_targets.add(target_material_name.strip().lower())
        source_name = getattr(getattr(mapping, "source_path", None), "name", "") or PurePosixPath(payload.target_path).name
        for mesh in _candidate_meshes(
            target_material_name,
            str(getattr(mapping, "target_texture_path", "") or ""),
        ):
            if slot_kind == "base":
                mesh.preview_texture_path = preview_path
                mesh.texture_name = source_name
                mesh.preview_texture_flip_vertical = False
                assigned_count += 1
            elif slot_kind == "normal":
                mesh.preview_normal_texture_path = preview_path
                mesh.preview_normal_texture_name = source_name
                mesh.preview_normal_texture_strength = 0.75
                assigned_count += 1
            elif slot_kind == "height":
                mesh.preview_height_texture_path = preview_path
                mesh.preview_height_texture_name = source_name
                assigned_count += 1
            elif slot_kind in {"material", "material_mask", "detail_mask"}:
                semantic_type, semantic_subtype, _confidence, packed_channels = _resolve_model_texture_semantic_details(source_name)
                mesh.preview_material_texture_path = preview_path
                mesh.preview_material_texture_name = source_name
                mesh.preview_material_texture_type = semantic_type
                mesh.preview_material_texture_subtype = semantic_subtype
                mesh.preview_material_texture_packed_channels = tuple(packed_channels)
                assigned_count += 1

    # PAC-driven sidecar generation binds by the rebuilt draw-section names.
    # If the first pass did not find a fuzzy match for a renamed/merged section,
    # assign by token overlap without requiring a texture-path match so the
    # preview follows the same material routing that will be packaged.
    for mapping in slot_mappings:
        target_material_name = str(getattr(mapping, "target_material_name", "") or "")
        target_path = str(getattr(mapping, "output_texture_path", "") or "").replace("\\", "/").strip().lower()
        payload = texture_payloads_by_target.get(target_path)
        if payload is None:
            continue
        try:
            preview_path = _preview_path_for_payload(payload)
        except Exception:
            continue
        slot_kind = str(getattr(mapping, "slot_kind", "") or "").strip().lower()
        source_name = getattr(getattr(mapping, "source_path", None), "name", "") or PurePosixPath(payload.target_path).name
        target_tokens = _tokens(target_material_name)
        for mesh in preview_model.meshes:
            mesh_tokens = _tokens(f"{getattr(mesh, 'material_name', '')} {getattr(mesh, 'name', '')}")
            if target_tokens and mesh_tokens and not (target_tokens & mesh_tokens):
                continue
            if slot_kind == "base" and not str(getattr(mesh, "preview_texture_path", "") or "").strip():
                mesh.preview_texture_path = preview_path
                mesh.texture_name = source_name
                mesh.preview_texture_flip_vertical = False
                assigned_count += 1
            elif slot_kind == "normal" and not str(getattr(mesh, "preview_normal_texture_path", "") or "").strip():
                mesh.preview_normal_texture_path = preview_path
                mesh.preview_normal_texture_name = source_name
                mesh.preview_normal_texture_strength = 0.75
                assigned_count += 1
            elif slot_kind == "height" and not str(getattr(mesh, "preview_height_texture_path", "") or "").strip():
                mesh.preview_height_texture_path = preview_path
                mesh.preview_height_texture_name = source_name
                assigned_count += 1
            elif slot_kind in {"material", "material_mask", "detail_mask"} and not str(getattr(mesh, "preview_material_texture_path", "") or "").strip():
                semantic_type, semantic_subtype, _confidence, packed_channels = _resolve_model_texture_semantic_details(source_name)
                mesh.preview_material_texture_path = preview_path
                mesh.preview_material_texture_name = source_name
                mesh.preview_material_texture_type = semantic_type
                mesh.preview_material_texture_subtype = semantic_subtype
                mesh.preview_material_texture_packed_channels = tuple(packed_channels)
                assigned_count += 1
    texture_sets_by_source = {
        str(getattr(texture_set, "material_name", "") or "").strip().lower(): texture_set
        for texture_set in (getattr(texture_replacement_report, "texture_sets", ()) or ())
    }
    for target_material_key, source_material_name in source_material_by_target.items():
        if target_material_key in base_targets:
            continue
        texture_set = texture_sets_by_source.get(str(source_material_name or "").strip().lower())
        base_slot = getattr(texture_set, "slots", {}).get("base") if texture_set is not None else None
        source_path = getattr(base_slot, "source_path", None)
        if not isinstance(source_path, Path) or not source_path.is_file():
            continue
        for mesh in _candidate_meshes(target_material_key, ""):
            mesh.preview_texture_path = source_path.as_posix()
            mesh.texture_name = source_path.name
            mesh.preview_texture_flip_vertical = False
            assigned_count += 1
    return assigned_count


def build_mesh_import_preview(
    entry: ArchiveEntry,
    obj_path: Path,
    *,
    import_mode: str = "roundtrip",
    static_replacement_options: Optional[StaticMeshReplacementOptions] = None,
    scene_import_result: Optional[SceneImportResult] = None,
    source_display_label: str = "",
    archive_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    texconv_path: Optional[Path] = None,
    texture_entries_by_normalized_path: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    texture_entries_by_basename: Optional[Mapping[str, Sequence[ArchiveEntry]]] = None,
    visible_texture_mode: str = "mesh_base_first",
    supplemental_files: Sequence[Path] = (),
) -> MeshImportPreviewResult:
    from cdmw.core.archive import (
        _attach_model_sidecar_texture_preview_paths,
        _attach_model_support_texture_preview_paths,
        _attach_model_texture_preview_paths,
        _extract_archive_model_sidecar_texture_references,
        _normalize_model_visible_texture_mode,
        build_archive_model_texture_references,
        read_archive_entry_data,
    )

    if scene_import_result is None:
        scene_import_result = import_scene_mesh_with_report(obj_path)
    imported_mesh = scene_import_result.mesh
    imported_mesh.path = entry.path
    imported_mesh.format = entry.extension.lstrip(".").lower()
    manifest_payload = (
        _load_obj_roundtrip_sidecar(str(obj_path))
        if obj_path.suffix.lower() == ".obj" and obj_path.expanduser().is_file()
        else None
    )
    original_baseline = read_archive_entry_baseline_data(entry, read_entry_data=read_archive_entry_data)
    original_data = original_baseline.data
    original_mesh = parse_mesh(original_data, entry.path)
    original_sidecars_for_static: Tuple[Tuple[ArchiveEntry, str], ...] = ()
    if texture_entries_by_basename is not None:
        original_sidecars_for_static = _collect_original_mesh_sidecar_texts(entry, texture_entries_by_basename)
    normalized_import_mode = str(import_mode or "roundtrip").strip().lower()
    static_mappings = []
    enable_missing_base_color_parameters = False
    effective_static_source_mesh = imported_mesh
    if normalized_import_mode in {"static", "static_replacement", "static-mesh-replacement"}:
        base_static_options = static_replacement_options or StaticMeshReplacementOptions()
        effective_static_source_mesh = effective_static_replacement_source_mesh(
            original_mesh,
            imported_mesh,
            base_static_options,
        )
        enable_missing_base_color_parameters = bool(
            getattr(base_static_options, "enable_missing_base_color_parameters", False)
        )
        static_mappings = base_static_options.submesh_mappings or suggest_static_submesh_mappings(
            original_mesh,
            effective_static_source_mesh,
        )
        if not base_static_options.submesh_mappings:
            base_static_options = dataclasses.replace(base_static_options, submesh_mappings=static_mappings)
        if bool(getattr(base_static_options, "complete_external_swap", False)):
            source_owned_target_names = _source_owned_target_names_from_sidecars(original_sidecars_for_static)
            if source_owned_target_names:
                base_static_options = dataclasses.replace(
                    base_static_options,
                    source_owned_target_names=list(source_owned_target_names),
                )
        rebuilt_data, static_report = build_static_mesh_replacement(
            original_data,
            original_mesh,
            imported_mesh,
            base_static_options,
        )
        normalized_import_mode = "static_replacement"
    else:
        if obj_path.suffix.lower() != ".obj":
            raise ValueError("Round-trip edit import only supports OBJ. Use Mesh Replacement for DAE, GLB, or glTF imports.")
        static_report = None
        normalized_import_mode = "roundtrip"
        rebuilt_data = build_mesh(imported_mesh, original_data)
    parsed_mesh = parse_mesh(rebuilt_data, entry.path)
    restored_texture_identity_count = _restore_rebuilt_mesh_texture_identity(imported_mesh, parsed_mesh)
    preview_model = parsed_mesh_to_preview_model(parsed_mesh)

    summary_lines = [
        f"Preview rebuilt mesh for {entry.path}",
        f"Import mode: {'Mesh replacement' if normalized_import_mode == 'static_replacement' else 'Round-trip edit'}",
        f"Vertices: {parsed_mesh.total_vertices:,}",
        f"Faces: {parsed_mesh.total_faces:,}",
        f"Submeshes: {len(parsed_mesh.submeshes):,}",
        f"Rebuilt size: {len(rebuilt_data):,} bytes",
    ]
    if source_display_label.strip():
        summary_lines.append(f"Replacement source: {source_display_label.strip()}")
    if original_baseline.message:
        summary_lines.append(f"Original mesh donor: {original_baseline.message}")
    if scene_import_result.diagnostics:
        summary_lines.append("Scene import notes:")
        summary_lines.extend(f"  {line}" for line in scene_import_result.diagnostics)
    if static_report is not None:
        summary_lines.append(
            "Static replacement analysis: "
            f"original {static_report.original_submesh_count} submesh(es), "
            f"replacement {static_report.replacement_submesh_count} source submesh(es)."
        )
        if static_report.mapping_summary:
            summary_lines.append("Static replacement mapping:")
            summary_lines.extend(f"  {line}" for line in static_report.mapping_summary)
        if static_report.warnings:
            summary_lines.append("Static replacement warnings:")
            summary_lines.extend(f"  {line}" for line in static_report.warnings)
        if static_report.alignment_summary:
            summary_lines.append("Static replacement alignment:")
            summary_lines.extend(f"  {line}" for line in static_report.alignment_summary)
    if restored_texture_identity_count > 0:
        summary_lines.append(
            f"Restored {restored_texture_identity_count:,} imported submesh texture identifier(s) onto rebuilt preview metadata."
        )
    resolved_supplemental_files = tuple(
        path.expanduser().resolve()
        for path in supplemental_files
        if isinstance(path, Path) and path.expanduser().resolve().is_file()
    )
    if normalized_import_mode == "static_replacement":
        auto_scene_supplemental_files = tuple(
            path
            for path in tuple(scene_import_result.discovered_texture_files)
            + tuple(scene_import_result.extracted_embedded_files)
            + tuple(getattr(scene_import_result, "discovered_supplemental_files", ()) or ())
            + (
                tuple(discover_scene_texture_files(obj_path, imported_mesh))
                if obj_path.expanduser().is_file()
                else ()
            )
            if path.is_file()
        )
        if auto_scene_supplemental_files:
            seen_supplemental = {str(path).lower() for path in resolved_supplemental_files}
            appended = [path for path in auto_scene_supplemental_files if str(path).lower() not in seen_supplemental]
            if appended:
                resolved_supplemental_files = tuple(resolved_supplemental_files) + tuple(appended)
                summary_lines.append(
                    f"Auto-discovered {len(appended):,} supplemental texture/sidecar file(s) next to the imported mesh."
                )
    if resolved_supplemental_files:
        summary_lines.append(f"Selected supplemental files: {len(resolved_supplemental_files):,}")
        summary_lines.extend(_summarize_crimson_companion_supplemental_files(resolved_supplemental_files))
    sidecar_texture_references: Tuple[object, ...] = ()
    sidecar_reference_paths: Tuple[str, ...] = ()
    sidecar_texts_by_normalized_path: Dict[str, Tuple[str, ...]] = {}
    sidecar_texts_by_basename: Dict[str, Tuple[str, ...]] = {}
    original_archive_sidecar_texture_references: Tuple[object, ...] = ()
    original_archive_sidecar_reference_paths: Tuple[str, ...] = ()
    selected_sidecar_texture_references: Tuple[object, ...] = ()
    selected_sidecar_reference_paths: Tuple[str, ...] = ()
    selected_sidecar_texts_by_normalized_path: Dict[str, Tuple[str, ...]] = {}
    selected_sidecar_texts_by_basename: Dict[str, Tuple[str, ...]] = {}
    normalized_visible_texture_mode = _normalize_model_visible_texture_mode(visible_texture_mode)
    if resolved_supplemental_files:
        (
            selected_sidecar_texture_references,
            selected_sidecar_reference_paths,
            selected_sidecar_texts_by_normalized_path,
            selected_sidecar_texts_by_basename,
        ) = _build_selected_sidecar_texture_bindings(resolved_supplemental_files)
        if selected_sidecar_texture_references:
            summary_lines.append(
                f"Using {len(selected_sidecar_texture_references):,} texture binding(s) from selected local sidecar file(s): {', '.join(selected_sidecar_reference_paths[:3])}"
                + (" ..." if len(selected_sidecar_reference_paths) > 3 else "")
            )
    if texture_entries_by_basename is not None:
        (
            original_archive_sidecar_texture_references,
            original_archive_sidecar_reference_paths,
            sidecar_texts_by_normalized_path,
            sidecar_texts_by_basename,
        ) = _extract_archive_model_sidecar_texture_references(
            entry,
            archive_entries_by_basename=(
                dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
            ),
        )
        if original_archive_sidecar_texture_references and not selected_sidecar_texture_references:
            sidecar_suffix = (
                f" from {', '.join(original_archive_sidecar_reference_paths[:2])}"
                if original_archive_sidecar_reference_paths
                else ""
            )
            if len(original_archive_sidecar_reference_paths) > 2:
                sidecar_suffix += " ..."
            summary_lines.append(
                f"Companion material sidecar data contributed {len(original_archive_sidecar_texture_references):,} texture binding(s){sidecar_suffix}."
            )
            summary_lines.append(
                "Loose mesh mods may still need the matching companion .xml sidecar when custom material or texture remaps are involved."
            )
    if original_archive_sidecar_texture_references:
        sidecar_texture_references = original_archive_sidecar_texture_references
        sidecar_reference_paths = original_archive_sidecar_reference_paths
    if selected_sidecar_texture_references:
        sidecar_texture_references = selected_sidecar_texture_references
        sidecar_reference_paths = selected_sidecar_reference_paths
        sidecar_texts_by_normalized_path = selected_sidecar_texts_by_normalized_path
        sidecar_texts_by_basename = selected_sidecar_texts_by_basename
    summary_lines.extend(
        _mesh_import_runtime_sibling_warning_lines(
            entry,
            parsed_mesh,
            texture_entries_by_basename,
            original_sidecars_for_static,
        )
    )
    texture_references: Tuple[ArchiveModelTextureReference, ...] = ()
    if texconv_path is not None:
        if sidecar_texture_references:
            summary_lines.extend(
                _attach_model_sidecar_texture_preview_paths(
                    texconv_path,
                    entry,
                    preview_model,
                    parsed_mesh=parsed_mesh,
                    sidecar_texture_bindings=sidecar_texture_references,
                    visible_texture_mode=normalized_visible_texture_mode,
                    texture_entries_by_normalized_path=(
                        dict(texture_entries_by_normalized_path) if texture_entries_by_normalized_path is not None else None
                    ),
                    texture_entries_by_basename=(
                        dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
                    ),
                    sidecar_texts_by_normalized_path=sidecar_texts_by_normalized_path,
                    sidecar_texts_by_basename=sidecar_texts_by_basename,
                )
            )
        summary_lines.extend(
            _attach_model_texture_preview_paths(
                texconv_path,
                entry,
                preview_model,
                texture_entries_by_normalized_path=(
                    dict(texture_entries_by_normalized_path) if texture_entries_by_normalized_path is not None else None
                ),
                texture_entries_by_basename=(
                    dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
                ),
                sidecar_texts_by_normalized_path=sidecar_texts_by_normalized_path,
                sidecar_texts_by_basename=sidecar_texts_by_basename,
            )
        )
        if sidecar_texture_references and normalized_visible_texture_mode == "mesh_base_first":
            summary_lines.extend(
                _attach_model_sidecar_texture_preview_paths(
                    texconv_path,
                    entry,
                    preview_model,
                    parsed_mesh=parsed_mesh,
                    sidecar_texture_bindings=sidecar_texture_references,
                    visible_texture_mode="layer_aware_visible",
                    texture_entries_by_normalized_path=(
                        dict(texture_entries_by_normalized_path) if texture_entries_by_normalized_path is not None else None
                    ),
                    texture_entries_by_basename=(
                        dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
                    ),
                    sidecar_texts_by_normalized_path=sidecar_texts_by_normalized_path,
                    sidecar_texts_by_basename=sidecar_texts_by_basename,
                    fallback_only=True,
                )
            )
            summary_lines.extend(
                _attach_model_texture_preview_paths(
                    texconv_path,
                    entry,
                    preview_model,
                    texture_entries_by_normalized_path=(
                        dict(texture_entries_by_normalized_path) if texture_entries_by_normalized_path is not None else None
                    ),
                    texture_entries_by_basename=(
                        dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
                    ),
                    sidecar_texts_by_normalized_path=sidecar_texts_by_normalized_path,
                    sidecar_texts_by_basename=sidecar_texts_by_basename,
                    override_existing_base=True,
                    prefer_material_name_for_base=True,
                )
            )
        summary_lines.extend(
            _attach_model_support_texture_preview_paths(
                texconv_path,
                entry,
                preview_model,
                parsed_mesh=parsed_mesh,
                sidecar_texture_bindings=sidecar_texture_references,
                texture_entries_by_normalized_path=(
                    dict(texture_entries_by_normalized_path) if texture_entries_by_normalized_path is not None else None
                ),
                texture_entries_by_basename=(
                    dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
                ),
                sidecar_texts_by_normalized_path=sidecar_texts_by_normalized_path,
                sidecar_texts_by_basename=sidecar_texts_by_basename,
            )
        )
        if resolved_supplemental_files:
            supplemental_dds_by_normalized_path, supplemental_dds_by_basename = _build_mesh_import_local_dds_lookup(
                resolved_supplemental_files
            )
            if selected_sidecar_texture_references:
                summary_lines.extend(
                    _apply_mesh_import_local_sidecar_texture_overrides(
                        preview_model,
                        parsed_mesh,
                        selected_sidecar_texture_references,
                        supplemental_dds_by_normalized_path,
                        supplemental_dds_by_basename,
                        texconv_path=texconv_path,
                    )
                )
                summary_lines.extend(
                    _apply_mesh_import_local_support_texture_overrides(
                        preview_model,
                        parsed_mesh,
                        selected_sidecar_texture_references,
                        supplemental_dds_by_normalized_path,
                        supplemental_dds_by_basename,
                        texconv_path=texconv_path,
                    )
                )
            summary_lines.extend(
                _apply_mesh_import_local_texture_overrides(
                    preview_model,
                    supplemental_dds_by_normalized_path,
                    supplemental_dds_by_basename,
                    texconv_path=texconv_path,
                )
            )
    texture_references = tuple(
        build_archive_model_texture_references(
            entry,
            preview_model,
            parsed_mesh=parsed_mesh,
            sidecar_texture_references=sidecar_texture_references,
            texture_entries_by_normalized_path=(
                dict(texture_entries_by_normalized_path) if texture_entries_by_normalized_path is not None else None
            ),
            texture_entries_by_basename=(
                dict(texture_entries_by_basename) if texture_entries_by_basename is not None else None
            ),
            sidecar_texts_by_normalized_path=sidecar_texts_by_normalized_path,
            sidecar_texts_by_basename=sidecar_texts_by_basename,
        )
    )
    supplemental_file_specs = _build_mesh_import_supplemental_file_specs(
        entry,
        resolved_supplemental_files,
        texture_references,
        archive_entries_by_normalized_path=archive_entries_by_normalized_path,
        archive_entries_by_basename=texture_entries_by_basename,
    )
    texture_slot_overrides = tuple(getattr(static_replacement_options, "texture_slot_overrides", ()) or ())
    source_material_texture_overrides = tuple(
        getattr(static_replacement_options, "source_material_texture_overrides", ()) or ()
    )
    donor_material_plans = tuple(getattr(static_replacement_options, "donor_material_plans", ()) or ())
    prune_removed_target_texture_parameters = bool(
        getattr(static_replacement_options, "prune_removed_target_texture_parameters", False)
    )
    prune_unmapped_original_texture_parameters = bool(
        getattr(static_replacement_options, "prune_unmapped_original_texture_parameters", False)
    )
    complete_external_material_reset = bool(
        getattr(static_replacement_options, "complete_external_material_reset", False)
    )
    complete_swap_material_profile = str(
        getattr(
            static_replacement_options,
            "complete_swap_material_profile",
            "source_graph_strict" if complete_external_material_reset else "arm_standard",
        )
        or ("source_graph_strict" if complete_external_material_reset else "arm_standard")
    )
    try:
        complete_swap_global_gloss_reduction = max(
            -100.0,
            min(100.0, float(getattr(static_replacement_options, "global_gloss_reduction", 0.0) or 0.0)),
        )
    except (TypeError, ValueError, OverflowError):
        complete_swap_global_gloss_reduction = 0.0
    try:
        complete_swap_edge_relief_strength = max(
            0.0,
            min(100.0, float(getattr(static_replacement_options, "edge_relief_strength", 0.0) or 0.0)),
        )
    except (TypeError, ValueError, OverflowError):
        complete_swap_edge_relief_strength = 0.0
    complete_swap_edge_relief_source = str(
        getattr(static_replacement_options, "edge_relief_source", "hybrid") or "hybrid"
    )
    try:
        complete_swap_accent_glow_strength = max(
            0.0,
            min(100.0, float(getattr(static_replacement_options, "accent_glow_strength", 0.0) or 0.0)),
        )
    except (TypeError, ValueError, OverflowError):
        complete_swap_accent_glow_strength = 0.0
    try:
        complete_swap_auto_brightness_balance = max(
            0.0,
            min(100.0, float(getattr(static_replacement_options, "auto_brightness_balance", 0.0) or 0.0)),
        )
    except (TypeError, ValueError, OverflowError):
        complete_swap_auto_brightness_balance = 0.0
    try:
        complete_swap_dark_detail_lift = max(
            0.0,
            min(100.0, float(getattr(static_replacement_options, "dark_detail_lift", 0.0) or 0.0)),
        )
    except (TypeError, ValueError, OverflowError):
        complete_swap_dark_detail_lift = 0.0
    try:
        complete_swap_tone_contrast = max(
            -100.0,
            min(100.0, float(getattr(static_replacement_options, "tone_contrast", 0.0) or 0.0)),
        )
    except (TypeError, ValueError, OverflowError):
        complete_swap_tone_contrast = 0.0
    if (
        normalized_import_mode == "static_replacement"
        and bool(getattr(static_replacement_options, "neutralize_inherited_material_layers", False))
    ):
        summary_lines.append(
            "Source-color faithful material mode: enabled; generated material sidecars will neutralize inherited tint/grime/detail/color-blend layers on rebuilt draw sections."
        )
    if normalized_import_mode == "static_replacement" and complete_external_material_reset:
        summary_lines.append(
            "Complete external swap material reset: enabled; generated material sidecars will reset inherited target shader response on rebuilt draw sections."
        )
        summary_lines.append(
            f"Complete swap material profile: {complete_swap_material_profile}; source PBR maps/factors will be translated into CD runtime support masks."
        )
        if complete_swap_global_gloss_reduction < 0.0:
            summary_lines.append(
                "Global gloss boost requested: "
                f"{abs(complete_swap_global_gloss_reduction):.0f}%; generated source roughness will be lowered "
                "and compatible shine/scalar response increased."
            )
        elif complete_swap_global_gloss_reduction > 0.0:
            summary_lines.append(
                "Global gloss reduction requested: "
                f"{complete_swap_global_gloss_reduction:.0f}%; CD gloss/smoothness, metallic/spec, and shine response will be reduced."
            )
        if complete_swap_edge_relief_strength > 0.0:
            summary_lines.append(
                "Edge relief requested: "
                f"{complete_swap_edge_relief_strength:.0f}% via {complete_swap_edge_relief_source.replace('_', ' ')} support."
            )
        if complete_swap_accent_glow_strength > 0.0:
            summary_lines.append(
                "Accent glow requested: "
                f"{complete_swap_accent_glow_strength:.0f}%; accent/emissive source parts will receive emissive shader parameters."
            )
        if complete_swap_dark_detail_lift > 0.0:
            summary_lines.append(
                "Source brightness requested: "
                f"{complete_swap_dark_detail_lift:.0f}%; source base DDS shadows and midtones will be lifted."
            )
        if complete_swap_auto_brightness_balance > 0.0:
            summary_lines.append(
                "Auto brightness balance requested: "
                f"{complete_swap_auto_brightness_balance:.0f}%; source base DDS exposure will be nudged toward a stable midrange."
            )
        if abs(complete_swap_tone_contrast) > 0.0:
            summary_lines.append(
                "Tone contrast requested: "
                f"{complete_swap_tone_contrast:+.0f}%; generated source base DDS tone curve will be adjusted."
            )
    if (
        normalized_import_mode == "static_replacement"
        and (
            resolved_supplemental_files
            or texture_slot_overrides
            or source_material_texture_overrides
            or donor_material_plans
            or prune_removed_target_texture_parameters
            or prune_unmapped_original_texture_parameters
        )
    ):
        original_sidecars = original_sidecars_for_static or _collect_original_mesh_sidecar_texts(entry, texture_entries_by_basename)
        texture_source_files = tuple(
            path for path in resolved_supplemental_files if path.suffix.lower() in SCENE_TEXTURE_SOURCE_EXTENSIONS
        )
        if (
            texture_source_files
            or texture_slot_overrides
            or source_material_texture_overrides
            or donor_material_plans
            or prune_removed_target_texture_parameters
            or prune_unmapped_original_texture_parameters
        ):
            try:
                generated_payloads, texture_replacement_report = build_texture_replacement_payloads(
                    obj_mesh=effective_static_source_mesh,
                    rebuilt_mesh=parsed_mesh,
                    texture_files=texture_source_files,
                    original_texture_refs=texture_references,
                    original_sidecars=original_sidecars,
                    submesh_mappings=static_mappings,
                    texconv_path=texconv_path,
                    read_original_texture_bytes=_mesh_texture_original_bytes,
                    original_texture_source_path=_mesh_texture_original_source_path,
                    enable_missing_base_color_parameters=enable_missing_base_color_parameters,
                    texture_slot_overrides=texture_slot_overrides,
                    source_material_texture_overrides=source_material_texture_overrides,
                    source_part_adjustments=tuple(
                        getattr(static_replacement_options, "source_part_adjustments", ()) or ()
                    ),
                    donor_material_plans=donor_material_plans,
                    texture_output_size_mode=str(
                        getattr(static_replacement_options, "texture_output_size_mode", "source") or "source"
                    ),
                    pac_driven_sidecar=bool(
                        getattr(static_replacement_options, "rebuild_material_sidecar", True)
                    ),
                    neutralize_inherited_material_layers=bool(
                        getattr(static_replacement_options, "neutralize_inherited_material_layers", False)
                    ),
                    complete_external_material_reset=complete_external_material_reset,
                    complete_swap_material_profile=complete_swap_material_profile,
                    complete_swap_global_gloss_reduction=complete_swap_global_gloss_reduction,
                    complete_swap_edge_relief_strength=complete_swap_edge_relief_strength,
                    complete_swap_edge_relief_source=complete_swap_edge_relief_source,
                    complete_swap_accent_glow_strength=complete_swap_accent_glow_strength,
                    complete_swap_auto_brightness_balance=complete_swap_auto_brightness_balance,
                    complete_swap_dark_detail_lift=complete_swap_dark_detail_lift,
                    complete_swap_tone_contrast=complete_swap_tone_contrast,
                    removed_target_material_names=tuple(
                        str(getattr(original_mesh.submeshes[int(index)], "material", "") or getattr(original_mesh.submeshes[int(index)], "name", "") or f"target {int(index)}")
                        for index in tuple(getattr(static_replacement_options, "removed_target_submesh_indices", ()) or ())
                        if str(index).strip().lstrip("-").isdigit()
                        and 0 <= int(index) < len(getattr(original_mesh, "submeshes", ()) or ())
                    ),
                    prune_removed_target_texture_parameters=prune_removed_target_texture_parameters,
                    prune_unmapped_original_texture_parameters=prune_unmapped_original_texture_parameters,
                    output_draw_sections=tuple(getattr(static_report, "output_draw_sections", ()) or ()),
                    pac_xml_corpus_root=str(getattr(static_replacement_options, "pac_xml_corpus_root", "") or ""),
                    pac_xml_profile_cache_path=str(getattr(static_replacement_options, "pac_xml_profile_cache_path", "") or ""),
                )
            except Exception as exc:
                generated_payloads = []
                texture_replacement_report = None
                summary_lines.append(f"Static texture replacement failed: {exc}")
            if texture_replacement_report is not None:
                material_profile_name = str(getattr(texture_replacement_report, "material_profile_name", "") or "").strip()
                probe_variants = tuple(getattr(texture_replacement_report, "material_probe_variants", ()) or ())
                if material_profile_name:
                    summary_lines.append(f"Complete swap material profile active: {material_profile_name}")
                    if probe_variants:
                        summary_lines.append(
                            "Complete swap calibration profiles available: "
                            + ", ".join(str(getattr(variant, "material_profile_name", "") or "") for variant in probe_variants[:5])
                        )
                material_routes = tuple(getattr(texture_replacement_report, "material_routes", ()) or ())
                if material_routes:
                    summary_lines.append("Static source material routing:")
                    for route in material_routes[:16]:
                        roles = ", ".join(tuple(getattr(route, "detected_roles", ()) or ())) or "-"
                        source_material = str(getattr(route, "source_material_name", "") or "-")
                        summary_lines.append(
                            "  "
                            f"{getattr(route, 'target_material_name', '')} <- {source_material} "
                            f"[{getattr(route, 'status', 'Unknown')}; {roles}]"
                        )
                    if len(material_routes) > 16:
                        summary_lines.append(f"  ... {len(material_routes) - 16:,} more routing row(s)")
                if texture_replacement_report.slot_mappings:
                    summary_lines.append("Static texture replacement mapping:")
                    summary_lines.extend(
                        "  "
                        f"{mapping.source_material_name} {mapping.slot_kind} "
                        f"({mapping.source_path.name}) -> {mapping.output_texture_path}"
                        for mapping in texture_replacement_report.slot_mappings[:16]
                    )
                    if len(texture_replacement_report.slot_mappings) > 16:
                        summary_lines.append(
                            f"  ... {len(texture_replacement_report.slot_mappings) - 16:,} more texture mapping(s)"
                        )
                if texture_replacement_report.warnings:
                    summary_lines.append("Static texture replacement warnings:")
                    summary_lines.extend(f"  {warning}" for warning in texture_replacement_report.warnings)
                if texture_replacement_report.errors:
                    summary_lines.append("Static texture replacement errors:")
                    summary_lines.extend(f"  {error}" for error in texture_replacement_report.errors)
                if (
                    not texture_replacement_report.slot_mappings
                    and not texture_replacement_report.warnings
                    and not texture_replacement_report.errors
                ):
                    summary_lines.append(
                        "Static texture replacement found no matching original texture bindings for the selected PNG/DDS files."
                    )
            if generated_payloads:
                preview_assignment_count = _apply_generated_static_texture_previews(
                    preview_model,
                    generated_payloads=generated_payloads,
                    texture_replacement_report=texture_replacement_report,
                    texconv_path=texconv_path,
                )
                if preview_assignment_count > 0:
                    summary_lines.append(
                        f"Applied {preview_assignment_count:,} generated static texture preview slot(s) from PNG/DDS replacements."
                    )
                elif texconv_path is None:
                    summary_lines.append(
                        "Generated static texture payloads were not shown in preview because the DirectXTex/native preview backend did not produce usable previews."
                    )
                generated_specs = _texture_replacement_payloads_to_specs(
                    generated_payloads,
                    archive_entries_by_normalized_path=archive_entries_by_normalized_path,
                )
                supplemental_file_specs = tuple(supplemental_file_specs) + generated_specs
                generated_texture_count = sum(1 for payload in generated_payloads if payload.kind == "texture_generated")
                generated_sidecar_count = sum(1 for payload in generated_payloads if payload.kind == "sidecar_generated")
                summary_lines.append(
                    f"Generated static replacement payloads: {generated_texture_count:,} texture(s), {generated_sidecar_count:,} sidecar(s)."
                )
            if generated_payloads and not original_sidecars:
                summary_lines.append(
                    "Generated replacement texture payloads without a patched material sidecar because no original sidecar text was available."
                )
    if supplemental_file_specs:
        mapped_count = sum(1 for spec in supplemental_file_specs if spec.target_path)
        unmapped_count = len(supplemental_file_specs) - mapped_count
        summary_lines.append(f"Supplemental files mapped to package/archive targets: {mapped_count:,}")
        if unmapped_count > 0:
            summary_lines.append(
                f"{unmapped_count:,} supplemental file(s) could not be mapped to a known game-relative target automatically."
            )

    paired_lod_data: Optional[bytes] = None
    paired_lod_path = ""
    if (
        normalized_import_mode in {"roundtrip", "static_replacement"}
        and entry.extension == ".pam"
        and archive_entries_by_normalized_path is not None
    ):
        paired_path = f"{Path(entry.path).with_suffix('.pamlod').as_posix()}"
        paired_candidates = archive_entries_by_normalized_path.get(_normalize_virtual_path(paired_path), ())
        if paired_candidates:
            paired_entry = paired_candidates[0]
            paired_baseline = read_archive_entry_baseline_data(paired_entry, read_entry_data=read_archive_entry_data)
            paired_original = paired_baseline.data
            paired_source_mesh = parsed_mesh if normalized_import_mode == "static_replacement" else imported_mesh
            try:
                paired_mesh = transfer_pam_edit_to_pamlod_mesh(
                    paired_source_mesh,
                    original_data,
                    paired_original,
                    paired_entry.path,
                )
                paired_lod_data = build_mesh(paired_mesh, paired_original)
                paired_lod_path = paired_entry.path
                summary_lines.append(f"Paired PAMLOD rebuild prepared: {paired_entry.path}")
                if paired_baseline.message:
                    summary_lines.append(f"Paired LOD donor: {paired_baseline.message}")
            except Exception as exc:
                summary_lines.append(f"Paired PAMLOD rebuild could not be prepared: {exc}")

    import_diffs, import_issues, auto_fix_result, validation_summary_lines = _build_mesh_import_validation(
        entry,
        original_mesh,
        parsed_mesh,
        import_mode=normalized_import_mode,
        texture_references=texture_references,
        supplemental_file_specs=supplemental_file_specs,
        original_sidecar_bindings=original_archive_sidecar_texture_references,
        selected_sidecar_bindings=selected_sidecar_texture_references,
        paired_lod_path=paired_lod_path,
        manifest_payload=manifest_payload,
    )
    summary_lines.extend(validation_summary_lines)

    return MeshImportPreviewResult(
        rebuilt_data=rebuilt_data,
        parsed_mesh=parsed_mesh,
        preview_model=preview_model,
        summary_lines=summary_lines,
        import_mode=normalized_import_mode,
        texture_references=texture_references,
        supplemental_file_specs=supplemental_file_specs,
        paired_lod_data=paired_lod_data,
        paired_lod_path=paired_lod_path,
        import_diffs=import_diffs,
        import_issues=import_issues,
        auto_fix_result=auto_fix_result,
        roundtrip_manifest=manifest_payload if isinstance(manifest_payload, dict) else None,
        source_owned_output_draw_sections=tuple(getattr(static_report, "output_draw_sections", ()) or ()),
    )


def _ffmpeg_candidates() -> List[Path]:
    candidates: List[Path] = []
    env_path = shutil.which("ffmpeg")
    if env_path:
        candidates.append(Path(env_path))
    runtime_roots = [Path.cwd()]
    meipass = getattr(__import__("sys"), "_MEIPASS", "")
    if meipass:
        runtime_roots.append(Path(meipass))
    runtime_roots.append(Path(__file__).resolve().parents[2])
    for root in runtime_roots:
        for relative in ("ffmpeg/ffmpeg.exe", ".tools/ffmpeg/ffmpeg.exe", "ffmpeg.exe"):
            path = root / relative
            if path.is_file():
                candidates.append(path)
    seen: set[str] = set()
    unique: List[Path] = []
    for candidate in candidates:
        key = str(candidate.resolve())
        if key in seen:
            continue
        seen.add(key)
        unique.append(candidate)
    return unique


def _run_hidden_process(command: Sequence[str], *, timeout: int = 120) -> subprocess.CompletedProcess[str]:
    popen_kwargs: Dict[str, object] = {
        "capture_output": True,
        "text": True,
        "timeout": timeout,
    }
    popen_kwargs.update(hidden_subprocess_kwargs())
    return subprocess.run(list(command), **popen_kwargs)


def _convert_audio_to_wav(source_path: Path, output_path: Path) -> Path:
    if source_path.suffix.lower() == ".wav":
        shutil.copy2(source_path, output_path)
        return output_path

    ffmpeg_path = next(iter(_ffmpeg_candidates()), None)
    if ffmpeg_path is None:
        raise ValueError("ffmpeg.exe is required to convert this audio stream to WAV.")
    result = _run_hidden_process(
        [str(ffmpeg_path), "-y", "-i", str(source_path), "-ar", "48000", "-ac", "1", "-sample_fmt", "s16", str(output_path)],
        timeout=180,
    )
    if result.returncode != 0 or not output_path.is_file():
        raise ValueError(result.stderr.strip() or "ffmpeg could not convert the selected audio stream.")
    return output_path


def _decode_with_vgmstream(source_path: Path, output_path: Path) -> Path:
    from cdmw.core.archive import _resolve_vgmstream_cli_path

    cli_path = _resolve_vgmstream_cli_path()
    if cli_path is None:
        raise ValueError("Bundled vgmstream decoder is not available in this build.")
    result = _run_hidden_process([str(cli_path), "-o", str(output_path), str(source_path)], timeout=180)
    if result.returncode != 0 or not output_path.is_file():
        raise ValueError(result.stderr.strip() or "vgmstream-cli could not decode this Wwise stream.")
    return output_path


def export_archive_audio_as_wav(entry: ArchiveEntry, output_path: Path) -> Path:
    from cdmw.core.archive import ensure_archive_preview_source

    output_path = output_path.expanduser().resolve()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    source_path, _note = ensure_archive_preview_source(entry)
    extension = entry.extension.lower()
    if extension in {".wem", ".bnk"}:
        return _decode_with_vgmstream(source_path, output_path)
    return _convert_audio_to_wav(source_path, output_path)


@dataclass(slots=True, frozen=True)
class _WavFormatInfo:
    audio_format: int
    channels: int
    sample_rate: int
    bits_per_sample: int


def _iter_riff_chunks(data: bytes, *, max_chunks: int = 64) -> List[Tuple[bytes, int, int]]:
    chunks: List[Tuple[bytes, int, int]] = []
    if len(data) < 12 or data[:4] != b"RIFF" or data[8:12] != b"WAVE":
        return chunks
    offset = 12
    while offset + 8 <= len(data) and len(chunks) < max_chunks:
        chunk_id = data[offset : offset + 4]
        chunk_size = struct.unpack_from("<I", data, offset + 4)[0]
        data_offset = offset + 8
        if data_offset > len(data):
            break
        chunks.append((chunk_id, chunk_size, data_offset))
        next_offset = data_offset + chunk_size
        if next_offset <= offset:
            break
        offset = next_offset + (chunk_size % 2)
    return chunks


def _read_wav_format_info_from_bytes(data: bytes) -> Optional[_WavFormatInfo]:
    for chunk_id, chunk_size, chunk_offset in _iter_riff_chunks(data):
        if chunk_id != b"fmt " or chunk_size < 16 or chunk_offset + 16 > len(data):
            continue
        try:
            audio_format, channels, sample_rate, _byte_rate, _block_align, bits_per_sample = struct.unpack_from(
                "<HHIIHH",
                data,
                chunk_offset,
            )
        except struct.error:
            return None
        return _WavFormatInfo(
            audio_format=int(audio_format),
            channels=int(channels),
            sample_rate=int(sample_rate),
            bits_per_sample=int(bits_per_sample),
        )
    return None


def _read_wav_format_info(audio_path: Path, *, header_limit: int = 262_144) -> Optional[_WavFormatInfo]:
    try:
        with audio_path.open("rb") as handle:
            header = handle.read(max(64, int(header_limit)))
    except OSError:
        return None
    return _read_wav_format_info_from_bytes(header)


def _normalize_audio_input(audio_path: Path, *, sample_rate: int, channels: int) -> Path:
    if audio_path.suffix.lower() == ".wav":
        wav_info = _read_wav_format_info(audio_path)
        if (
            wav_info is not None
            and wav_info.audio_format == 1
            and wav_info.sample_rate == int(sample_rate)
            and wav_info.channels == int(channels)
            and wav_info.bits_per_sample == 16
        ):
            return audio_path
    temp_root = Path(tempfile.gettempdir()) / APP_NAME / "audio_patch"
    temp_root.mkdir(parents=True, exist_ok=True)
    output_path = temp_root / f"{audio_path.stem}_{sample_rate}hz_{channels}ch.wav"
    ffmpeg_path = next(iter(_ffmpeg_candidates()), None)
    if ffmpeg_path is None:
        raise ValueError("ffmpeg.exe is required to normalize replacement audio for patching.")
    result = _run_hidden_process(
        [str(ffmpeg_path), "-y", "-i", str(audio_path), "-ar", str(sample_rate), "-ac", str(channels), "-sample_fmt", "s16", str(output_path)],
        timeout=180,
    )
    if result.returncode != 0 or not output_path.is_file():
        raise ValueError(result.stderr.strip() or "ffmpeg could not normalize the selected replacement audio.")
    return output_path


def _build_pcm_wem(wav_data: bytes, sample_rate: int, channels: int) -> bytes:
    pcm_data = b""
    if wav_data[:4] == b"RIFF" and wav_data[8:12] == b"WAVE":
        cursor = 12
        while cursor + 8 <= len(wav_data):
            chunk_id = wav_data[cursor : cursor + 4]
            chunk_size = struct.unpack_from("<I", wav_data, cursor + 4)[0]
            if chunk_id == b"data":
                pcm_data = wav_data[cursor + 8 : cursor + 8 + chunk_size]
                break
            cursor += 8 + chunk_size
    else:
        pcm_data = wav_data

    if not pcm_data:
        return wav_data

    bits_per_sample = 16
    byte_rate = sample_rate * channels * (bits_per_sample // 8)
    block_align = channels * (bits_per_sample // 8)
    fmt_chunk = struct.pack(
        "<4sIHHIIHH",
        b"fmt ",
        16,
        1,
        channels,
        sample_rate,
        byte_rate,
        block_align,
        bits_per_sample,
    )
    data_chunk = b"data" + struct.pack("<I", len(pcm_data)) + pcm_data
    riff_size = 4 + len(fmt_chunk) + len(data_chunk)
    return b"RIFF" + struct.pack("<I", riff_size) + b"WAVE" + fmt_chunk + data_chunk


def build_archive_audio_patch_payload(entry: ArchiveEntry, replacement_audio_path: Path) -> bytes:
    from cdmw.core.archive import read_archive_entry_data

    normalized_path = replacement_audio_path.expanduser().resolve()
    if not normalized_path.is_file():
        raise FileNotFoundError(f"Audio replacement file was not found: {normalized_path}")

    if entry.extension == ".wav":
        return normalized_path.read_bytes()

    if entry.extension != ".wem":
        raise ValueError(f"Archive audio patching currently supports .wav and .wem targets only, not {entry.extension}.")

    original_data, _decompressed, _note = read_archive_entry_data(entry)
    sample_rate = 48000
    channels = 1
    original_wav_info = _read_wav_format_info_from_bytes(original_data)
    if original_wav_info is not None:
        channels = max(1, int(original_wav_info.channels))
        sample_rate = max(1, int(original_wav_info.sample_rate))
    normalized_wav = _normalize_audio_input(normalized_path, sample_rate=sample_rate, channels=channels)
    return _build_pcm_wem(normalized_wav.read_bytes(), sample_rate, channels)


def build_pab_preview(data: bytes, virtual_path: str) -> SkeletonPreviewResult:
    skeleton = parse_pab(data, virtual_path)
    lines = [f"PAB skeleton preview for {virtual_path}"]
    parser_mode = str(getattr(skeleton, "parser_mode", "") or "fixed")
    tail_data = bytes(getattr(skeleton, "tail_data", b"") or b"")
    parse_warning = str(getattr(skeleton, "parse_warning", "") or "").strip()
    detail_lines = [
        f"Declared bones: {int(getattr(skeleton, 'bone_count', len(skeleton.bones)) or 0):,}",
        f"Parsed bones: {len(skeleton.bones):,}",
        f"Parser mode: {parser_mode}",
        f"Tail data: {len(tail_data):,} bytes",
    ]
    if parse_warning:
        detail_lines.append(parse_warning)
    if not skeleton.bones:
        lines.append("No bones were recovered.")
        return SkeletonPreviewResult(preview_text="\n".join(lines), detail_lines=detail_lines)

    root_bones = [bone for bone in skeleton.bones if bone.parent_index < 0]
    named_bones = [bone for bone in skeleton.bones if str(bone.name or "").strip()]
    child_map: Dict[int, List[int]] = {}
    for bone in skeleton.bones:
        child_map.setdefault(int(bone.parent_index), []).append(int(bone.index))

    def _depth(index: int) -> int:
        children = child_map.get(index, [])
        if not children:
            return 1
        return 1 + max(_depth(child_index) for child_index in children)

    max_depth = max((_depth(root.index) for root in root_bones), default=0)
    positions = [
        tuple(float(component) for component in bone.position)
        for bone in skeleton.bones
        if len(tuple(bone.position)) >= 3
    ]
    detail_lines.append(f"Root bones: {len(root_bones):,}")
    detail_lines.append(f"Named bones: {len(named_bones):,}")
    detail_lines.append(f"Max hierarchy depth: {max_depth}")
    if positions:
        min_x = min(position[0] for position in positions)
        min_y = min(position[1] for position in positions)
        min_z = min(position[2] for position in positions)
        max_x = max(position[0] for position in positions)
        max_y = max(position[1] for position in positions)
        max_z = max(position[2] for position in positions)
        detail_lines.append(
            "Bone position bounds: "
            f"min=({min_x:.3f}, {min_y:.3f}, {min_z:.3f}) "
            f"max=({max_x:.3f}, {max_y:.3f}, {max_z:.3f})"
        )
    lines.extend(
        [
            "",
            "Summary:",
            f"- Declared bones: {int(getattr(skeleton, 'bone_count', len(skeleton.bones)) or 0):,}",
            f"- Bones: {len(skeleton.bones):,}",
            f"- Root bones: {len(root_bones):,}",
            f"- Named bones: {len(named_bones):,}",
            f"- Max hierarchy depth: {max_depth}",
            f"- Parser mode: {parser_mode}",
            f"- Tail data: {len(tail_data):,} bytes",
        ]
    )
    if parse_warning:
        lines.append(f"- Warning: {parse_warning}")
    if root_bones:
        lines.append("- Root names: " + ", ".join((bone.name or "<unnamed>") for bone in root_bones[:8]))
        if len(root_bones) > 8:
            lines[-1] += " ..."
    lines.append("")
    lines.append("Bone hierarchy:")
    for bone in skeleton.bones[:128]:
        parent_text = "root" if bone.parent_index < 0 else f"parent {bone.parent_index}"
        position_text = ""
        if len(tuple(bone.position)) >= 3:
            position_text = f" pos=({bone.position[0]:.3f}, {bone.position[1]:.3f}, {bone.position[2]:.3f})"
        lines.append(f"[{bone.index:03d}] {bone.name or '<unnamed>'} ({parent_text}){position_text}")
    if len(skeleton.bones) > 128:
        lines.append("")
        lines.append("Preview truncated to the first 128 bones.")
    return SkeletonPreviewResult(preview_text="\n".join(lines), detail_lines=detail_lines)


