def _hkx_sdk_version_label(version: str) -> str:
    if len(version) == 8 and version.isdigit():
        year = int(version[:4])
        major = int(version[4:6])
        patch = int(version[6:8])
        if 1999 <= year <= 2100:
            return f"{year}.{major}.{patch}"
    return version


def _extract_hkx_printable_strings(data: bytes) -> List[str]:
    printable = []
    current = bytearray()
    for value in data[:_HKX_PRINTABLE_SCAN_LIMIT]:
        if 32 <= value <= 126:
            current.append(value)
            continue
        if len(current) >= 4:
            printable.append(current.decode("ascii", errors="ignore"))
            if len(printable) >= _HKX_PRINTABLE_STRING_LIMIT:
                break
        current.clear()
    if len(current) >= 4 and len(printable) < _HKX_PRINTABLE_STRING_LIMIT:
        printable.append(current.decode("ascii", errors="ignore"))
    return printable


def _extract_hkx_type_names(printable: Sequence[str]) -> List[str]:
    names: set[str] = set()
    for text in printable:
        for match in _HKX_TYPE_NAME_RE.finditer(text):
            names.add(match.group(0))
    return sorted(names)


def _detect_hkx_tag_sections(data: bytes) -> List[str]:
    return [section for section in _HKX_KNOWN_TAG_SECTIONS if section.encode("ascii") in data[:_HKX_PRINTABLE_SCAN_LIMIT]]


def _detect_hkx_sdk_version(data: bytes, printable: Sequence[str]) -> str:
    match = re.search(rb"SDKV([0-9]{8})", data[:4096])
    if match:
        return match.group(1).decode("ascii", errors="ignore")
    for text in printable[:16]:
        match_text = re.search(r"SDKV([0-9]{8})", text)
        if match_text:
            return match_text.group(1)
    return ""


def _detect_hkx_declared_size(data: bytes) -> Optional[int]:
    if len(data) < 4:
        return None
    declared_size = int.from_bytes(data[:4], "big", signed=False)
    if declared_size == len(data):
        return declared_size
    return None


def _decode_hkx_length_word(raw_length_word: int) -> Tuple[int, int]:
    return raw_length_word & 0x0FFFFFFF, raw_length_word & 0xF0000000


def _find_hkx_tag_items(data: bytes) -> List[HkxTagItem]:
    items: List[HkxTagItem] = []
    tag0_offset = data[:64].find(b"TAG0")
    if tag0_offset >= 0:
        items.append(HkxTagItem(name="TAG0", offset=tag0_offset))

    seen: set[Tuple[str, int]] = set()
    for marker in _HKX_TAG_ITEM_MARKERS:
        marker_bytes = marker.encode("ascii")
        start = 0
        while True:
            offset = data.find(marker_bytes, start)
            if offset < 0:
                break
            start = offset + 1
            if offset < 4:
                continue
            raw_length_word = int.from_bytes(data[offset - 4 : offset], "big", signed=False)
            declared_length, length_flags = _decode_hkx_length_word(raw_length_word)
            if declared_length <= 0:
                continue
            marker_end = offset + declared_length
            word_end = offset - 4 + declared_length
            if marker_end > len(data) + 4 and word_end > len(data):
                continue
            if (marker, offset) in seen:
                continue
            seen.add((marker, offset))
            items.append(
                HkxTagItem(
                    name=marker,
                    offset=offset,
                    length_word_offset=offset - 4,
                    raw_length_word=raw_length_word,
                    declared_length=declared_length,
                    length_flags=length_flags,
                    marker_end_offset=marker_end,
                    word_end_offset=word_end,
                )
            )
    return sorted(items, key=lambda item: item.offset)


def _hkx_tag_item_by_name(items: Sequence[HkxTagItem], name: str) -> Optional[HkxTagItem]:
    return next((item for item in items if item.name == name), None)


def _hkx_next_tag_item(items: Sequence[HkxTagItem], item: HkxTagItem) -> Optional[HkxTagItem]:
    later_items = [candidate for candidate in items if candidate.offset > item.offset]
    return later_items[0] if later_items else None


def _extract_hkx_tst1_type_names(data: bytes, items: Sequence[HkxTagItem]) -> List[str]:
    tst1 = _hkx_tag_item_by_name(items, "TST1")
    if tst1 is None:
        return []
    next_item = _hkx_next_tag_item(items, tst1)
    end_candidates = []
    if tst1.marker_end_offset is not None:
        end_candidates.append(tst1.marker_end_offset)
    if next_item is not None and next_item.length_word_offset is not None:
        end_candidates.append(next_item.length_word_offset)
    elif next_item is not None:
        end_candidates.append(next_item.offset)
    end = min((candidate for candidate in end_candidates if candidate > tst1.offset), default=len(data))
    blob = data[tst1.offset + 4 : max(tst1.offset + 4, min(end, len(data)))]
    names: List[str] = []
    for raw_name in blob.split(b"\0"):
        if not raw_name or raw_name == b"\xff":
            continue
        name = raw_name.decode("ascii", errors="ignore").strip()
        if name and name != "\xff":
            names.append(name)
    return names


def _read_hkx_var_uint(payload: bytes, offset: int) -> Tuple[int, int]:
    if offset >= len(payload):
        raise ValueError("Unexpected end of Havok packed integer stream.")
    byte_1 = payload[offset]
    offset += 1
    if byte_1 & 0b10000000 == 0:
        return byte_1 & 0b01111111, offset
    if byte_1 == 0b11000011:
        if offset + 2 > len(payload):
            raise ValueError("Truncated Havok packed integer.")
        return (payload[offset] << 8) | payload[offset + 1], offset + 2
    marker = byte_1 >> 3
    if 0b00010000 <= marker < 0b00011000:
        if offset >= len(payload):
            raise ValueError("Truncated Havok packed integer.")
        return 0b00111111_11111111 & ((byte_1 << 8) | payload[offset]), offset + 1
    if 0b00011000 <= marker < 0b00011100:
        if offset + 2 > len(payload):
            raise ValueError("Truncated Havok packed integer.")
        return 0b00011111_11111111_11111111 & (
            (byte_1 << 16) | (payload[offset] << 8) | payload[offset + 1]
        ), offset + 2
    if marker == 0b00011100:
        if offset + 3 > len(payload):
            raise ValueError("Truncated Havok packed integer.")
        return int.from_bytes(bytes((byte_1,)) + payload[offset : offset + 3], "little") & 0x07FFFFFF, offset + 3
    if marker == 0b00011101:
        if offset + 4 > len(payload):
            raise ValueError("Truncated Havok packed integer.")
        return (
            0b00000111_11111111_11111111_11111111_11111111
            & (
                (byte_1 << 32)
                | (payload[offset] << 24)
                | (payload[offset + 1] << 16)
                | (payload[offset + 2] << 8)
                | payload[offset + 3]
            ),
            offset + 4,
        )
    if marker == 0b00011110:
        if offset + 7 > len(payload):
            raise ValueError("Truncated Havok packed integer.")
        return int.from_bytes(bytes((byte_1,)) + payload[offset : offset + 7], "little") & 0x07FFFFFFFFFFFFFF, offset + 7
    raise ValueError(f"Unrecognized Havok packed integer marker byte 0x{byte_1:02X}.")


def _parse_hkx_tna1_type_infos(
    data: bytes,
    items: Sequence[HkxTagItem],
    string_table_names: Sequence[str],
) -> Tuple[Optional[int], List[HkxTypeInfo], List[str]]:
    tna1 = _hkx_tag_item_by_name(items, "TNA1")
    if tna1 is None or tna1.offset + 4 >= len(data):
        return None, [], []
    if tna1.word_end_offset is not None and tna1.word_end_offset <= len(data):
        payload_end = tna1.word_end_offset
    elif tna1.marker_end_offset is not None and tna1.marker_end_offset <= len(data):
        payload_end = tna1.marker_end_offset
    else:
        next_item = _hkx_next_tag_item(items, tna1)
        payload_end = next_item.length_word_offset if next_item and next_item.length_word_offset else len(data)
    payload = data[tna1.offset + 4 : max(tna1.offset + 4, min(payload_end, len(data)))]
    if not payload:
        return None, [], []
    warnings: List[str] = []
    try:
        declared_count, cursor = _read_hkx_var_uint(payload, 0)
    except ValueError as exc:
        return None, [], [f"Could not decode TNA1 type count: {exc}"]
    type_infos: List[HkxTypeInfo] = []
    for index in range(1, declared_count):
        try:
            name_index, cursor = _read_hkx_var_uint(payload, cursor)
            template_count, cursor = _read_hkx_var_uint(payload, cursor)
            name = string_table_names[name_index] if name_index < len(string_table_names) else f"type-string[{name_index}]"
            template_parameters: List[Tuple[str, int]] = []
            for _ in range(template_count):
                template_name_index, cursor = _read_hkx_var_uint(payload, cursor)
                template_value, cursor = _read_hkx_var_uint(payload, cursor)
                template_name = (
                    string_table_names[template_name_index]
                    if template_name_index < len(string_table_names)
                    else f"template-string[{template_name_index}]"
                )
                template_parameters.append((template_name, template_value))
        except ValueError as exc:
            warnings.append(f"Could not fully decode TNA1 type {index}: {exc}")
            break
        type_infos.append(HkxTypeInfo(index=index, name=name, template_parameters=template_parameters))
    if cursor < len(payload) and any(value != 0 for value in payload[cursor:]):
        warnings.append(f"TNA1 has {len(payload) - cursor:,} undecoded non-zero trailing byte(s).")
    return declared_count, type_infos, warnings


def _extract_hkx_declared_type_name_count(data: bytes, items: Sequence[HkxTagItem]) -> Optional[int]:
    tna1 = _hkx_tag_item_by_name(items, "TNA1")
    if tna1 is None or tna1.offset + 4 >= len(data):
        return None
    return int(data[tna1.offset + 4])


def _detect_hkx_data_payload_offset(items: Sequence[HkxTagItem]) -> Optional[int]:
    data_item = _hkx_tag_item_by_name(items, "DATA")
    if data_item is None:
        return None
    return data_item.offset + 4


def _parse_hkx_item_records(
    data: bytes,
    items: Sequence[HkxTagItem],
    type_names_by_index: Mapping[int, str],
) -> List[HkxItemRecord]:
    item = _hkx_tag_item_by_name(items, "ITEM")
    if item is None:
        return []
    data_payload_offset = _detect_hkx_data_payload_offset(items)
    record_start = item.offset + 16
    if item.word_end_offset is not None and item.word_end_offset <= len(data):
        record_end = item.word_end_offset
    elif item.marker_end_offset is not None and item.marker_end_offset <= len(data):
        record_end = item.marker_end_offset
    else:
        record_end = len(data)
    if record_start >= record_end:
        return []
    usable_length = record_end - record_start
    records: List[HkxItemRecord] = []
    for index in range(usable_length // 12):
        offset = record_start + index * 12
        raw_type_flags = int.from_bytes(data[offset : offset + 4], "little", signed=False)
        data_offset = int.from_bytes(data[offset + 4 : offset + 8], "little", signed=False)
        count = int.from_bytes(data[offset + 8 : offset + 12], "little", signed=False)
        type_index = raw_type_flags & 0x0FFFFFFF
        flags = raw_type_flags & 0xF0000000
        type_name = type_names_by_index.get(type_index, "")
        records.append(
            HkxItemRecord(
                index=index,
                raw_type_flags=raw_type_flags,
                type_index=type_index,
                flags=flags,
                data_offset=data_offset,
                absolute_data_offset=(data_payload_offset + data_offset if data_payload_offset is not None else None),
                count=count,
                type_name=type_name,
            )
        )
    return records


def _format_hkx_float_bounds(values: Sequence[Sequence[float]], axes: int) -> str:
    labels = ("x", "y", "z", "w")
    parts = []
    for axis in range(min(axes, len(labels))):
        axis_values = [float(value[axis]) for value in values if len(value) > axis]
        if not axis_values:
            continue
        parts.append(f"{labels[axis]}=({min(axis_values):.6g}..{max(axis_values):.6g})")
    return ", ".join(parts)


def _format_hkx_vector(values: Sequence[float]) -> str:
    return "(" + ", ".join(f"{float(value):.6g}" for value in values) + ")"


def _summarize_hkx_float_vectors(
    data: bytes,
    start: int,
    count: int,
    components: int,
    stride: int,
) -> Tuple[List[Tuple[float, ...]], str]:
    values: List[Tuple[float, ...]] = []
    format_string = "<" + ("f" * components)
    size = struct.calcsize(format_string)
    for index in range(count):
        offset = start + index * stride
        if offset + size > len(data):
            break
        values.append(tuple(float(value) for value in struct.unpack_from(format_string, data, offset)))
    return values, _format_hkx_float_bounds(values, components)


def _decode_hkx_convex_face_vertex_indices(face_records: bytes, index_bytes: bytes, face_count: int) -> List[Tuple[int, ...]]:
    face_vertex_indices: List[Tuple[int, ...]] = []
    for index in range(face_count):
        offset = index * 4
        if offset + 4 > len(face_records):
            break
        index_start = int.from_bytes(face_records[offset : offset + 2], "little", signed=False)
        vertex_count = face_records[offset + 2]
        if vertex_count == 0 or vertex_count > 64:
            continue
        index_end = index_start + vertex_count
        if index_end > len(index_bytes):
            continue
        face_vertex_indices.append(tuple(int(value) for value in index_bytes[index_start:index_end]))
    return face_vertex_indices


def _read_hkx_float_vector_payload(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    record: Optional[HkxItemRecord],
    components: int,
    stride: int,
) -> List[Tuple[float, ...]]:
    if record is None or record.count <= 0:
        return []
    span = spans.get(record.index)
    if span is None:
        return []
    start, end = span
    if end - start < record.count * stride:
        return []
    values, _bounds = _summarize_hkx_float_vectors(data, start, record.count, components, stride)
    return values


def _hkx_payload_slice(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    record: Optional[HkxItemRecord],
    max_length: Optional[int] = None,
) -> bytes:
    if record is None:
        return b""
    span = spans.get(record.index)
    if span is None:
        return b""
    start, end = span
    if max_length is not None:
        end = min(end, start + max_length)
    return data[start:end]


def _build_hkx_hull_geometry_hint(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    records: Sequence[HkxItemRecord],
    *,
    shape_type: str,
    shape_record: Optional[HkxItemRecord],
) -> Optional[HkxCollisionGeometryHint]:
    hint = HkxCollisionGeometryHint(
        shape_type=shape_type,
        shape_record_index=(shape_record.index if shape_record is not None else None),
    )
    vertex_record = next((record for record in records if record.type_name == "hkFloat3"), None)
    plane_record = next((record for record in records if record.type_name == "hkVector4"), None)
    face_record = next((record for record in records if record.type_name == "hknpConvexHull::Face"), None)
    index_record = next((record for record in records if record.type_name == "hkUint8"), None)
    edge_records = [record for record in records if record.type_name == "hknpConvexHull::Edge"]

    vertices = _read_hkx_float_vector_payload(data, spans, vertex_record, 3, 12)
    if vertex_record is not None and vertices:
        hint.vertex_record_index = vertex_record.index
        hint.vertex_count = vertex_record.count
        hint.bounds_min = (
            min(value[0] for value in vertices),
            min(value[1] for value in vertices),
            min(value[2] for value in vertices),
        )
        hint.bounds_max = (
            max(value[0] for value in vertices),
            max(value[1] for value in vertices),
            max(value[2] for value in vertices),
        )
    if plane_record is not None:
        hint.plane_record_index = plane_record.index
        hint.plane_count = plane_record.count
    if face_record is not None:
        hint.face_record_index = face_record.index
        hint.face_count = face_record.count
    if index_record is not None:
        hint.face_index_record_index = index_record.index
        hint.face_index_count = index_record.count
    if edge_records:
        hint.edge_record_indices = [record.index for record in edge_records]
        hint.edge_pair_count = sum(max(0, record.count) for record in edge_records)
    face_payload = _hkx_payload_slice(data, spans, face_record, face_record.count * 4 if face_record else None)
    index_payload = _hkx_payload_slice(data, spans, index_record, index_record.count if index_record else None)
    if face_record is not None and face_payload and index_payload:
        hint.face_vertex_indices = _decode_hkx_convex_face_vertex_indices(face_payload, index_payload, face_record.count)
    if not any((hint.vertex_count, hint.plane_count, hint.face_count, hint.face_index_count, hint.edge_pair_count)):
        return None
    return hint


def _assign_hkx_mass_property_records(
    hints: Sequence[HkxCollisionGeometryHint],
    records: Sequence[HkxItemRecord],
) -> None:
    mass_records = [record for record in records if record.type_name == "hknpShapeMassProperties"]
    editable_shape_hints = [
        hint
        for hint in hints
        if hint.shape_type in {"hknpConvexShape", "hknpBoxShape", "hknpSphereShape", "hknpShape"}
    ]
    for hint, record in zip(editable_shape_hints, mass_records):
        hint.mass_record_index = record.index


def _hkx_item_record_spans(
    data: bytes,
    items: Sequence[HkxTagItem],
    records: Sequence[HkxItemRecord],
) -> Dict[int, Tuple[int, int]]:
    data_item = _hkx_tag_item_by_name(items, "DATA")
    if data_item is None or not records:
        return {}
    data_end = data_item.word_end_offset if data_item.word_end_offset is not None else data_item.marker_end_offset
    if data_end is None or data_end > len(data):
        data_end = len(data)
    absolute_offsets = sorted({
        int(record.absolute_data_offset)
        for record in records
        if record.absolute_data_offset is not None and 0 <= int(record.absolute_data_offset) < data_end
    })
    spans: Dict[int, Tuple[int, int]] = {}
    for record in records:
        if record.absolute_data_offset is None or record.absolute_data_offset >= data_end:
            continue
        start = int(record.absolute_data_offset)
        next_offset_index = bisect.bisect_right(absolute_offsets, start)
        end = absolute_offsets[next_offset_index] if next_offset_index < len(absolute_offsets) else data_end
        if end <= start:
            continue
        spans[record.index] = (start, end)
    return spans


def _hkx_hex(value: int, width: int = 0) -> str:
    return f"0x{int(value) & ((1 << 64) - 1):0{width}X}" if width else f"0x{int(value):X}"


def _hkx_record_offset_indexes(
    records: Sequence[HkxItemRecord],
) -> Tuple[Dict[int, Tuple[HkxItemRecord, ...]], Dict[int, Tuple[HkxItemRecord, ...]]]:
    data_offsets: Dict[int, List[HkxItemRecord]] = defaultdict(list)
    absolute_offsets: Dict[int, List[HkxItemRecord]] = defaultdict(list)
    for record in records:
        data_offset = int(record.data_offset)
        if data_offset > 0:
            data_offsets[data_offset].append(record)
        if record.absolute_data_offset is not None:
            absolute_offset = int(record.absolute_data_offset)
            if absolute_offset > 0:
                absolute_offsets[absolute_offset].append(record)
    return (
        {offset: tuple(offset_records) for offset, offset_records in data_offsets.items()},
        {offset: tuple(offset_records) for offset, offset_records in absolute_offsets.items()},
    )


def _hkx_offset_index_target(
    lookup: Mapping[int, Tuple[HkxItemRecord, ...]],
    value: int,
    current_record: HkxItemRecord,
) -> Optional[HkxItemRecord]:
    candidates = lookup.get(value)
    if not candidates:
        return None
    for target in reversed(candidates):
        if target.index != current_record.index:
            return target
    return None


def _summarize_hkx_possible_record_links(
    payload: bytes,
    records: Sequence[HkxItemRecord],
    current_record: HkxItemRecord,
    *,
    limit: int = 6,
    offset_indexes: Optional[Tuple[Dict[int, Tuple[HkxItemRecord, ...]], Dict[int, Tuple[HkxItemRecord, ...]]]] = None,
) -> List[str]:
    data_offsets, absolute_offsets = offset_indexes or _hkx_record_offset_indexes(records)
    matches: List[str] = []
    seen: set[Tuple[str, int, int]] = set()
    for offset in range(0, max(0, len(payload) - 3), 4):
        value32 = struct.unpack_from("<I", payload, offset)[0]
        for label, lookup in (("data", data_offsets), ("absolute", absolute_offsets)):
            target = _hkx_offset_index_target(lookup, value32, current_record)
            if target is None:
                continue
            key = (label, offset, target.index)
            if key in seen:
                continue
            seen.add(key)
            matches.append(
                f"+0x{offset:X} {label}-offset {_hkx_hex(value32)} -> "
                f"record[{target.index}] {target.type_name or f'type[{target.type_index}]'}"
            )
            if len(matches) >= limit:
                return matches
    return matches


def _hkx_possible_record_link_documents(
    payload: bytes,
    records: Sequence[HkxItemRecord],
    current_record: HkxItemRecord,
    *,
    limit: int = 64,
    offset_indexes: Optional[Tuple[Dict[int, Tuple[HkxItemRecord, ...]], Dict[int, Tuple[HkxItemRecord, ...]]]] = None,
) -> List[Dict[str, object]]:
    data_offsets, absolute_offsets = offset_indexes or _hkx_record_offset_indexes(records)
    links: List[Dict[str, object]] = []
    seen: set[Tuple[str, int, int]] = set()
    for offset in range(0, max(0, len(payload) - 3), 4):
        value32 = struct.unpack_from("<I", payload, offset)[0]
        for kind, lookup in (("data_offset", data_offsets), ("absolute_offset", absolute_offsets)):
            target = _hkx_offset_index_target(lookup, value32, current_record)
            if target is None:
                continue
            key = (kind, offset, target.index)
            if key in seen:
                continue
            seen.add(key)
            reference_category = _hkx_havok_reference_category(
                source_type_name=current_record.type_name,
                target_type_name=target.type_name,
                offset=offset,
            )
            confidence = _hkx_havok_reference_confidence(
                source_type_name=current_record.type_name,
                reference_kind=kind,
                reference_category=reference_category,
            )
            links.append(
                {
                    "offset": offset,
                    "hex_offset": f"0x{offset:X}",
                    "reference_kind": kind,
                    "reference_category": reference_category,
                    "raw_value": value32,
                    "raw_value_hex": _hkx_hex(value32),
                    "target_record_index": target.index,
                    "target_type_index": target.type_index,
                    "target_type_name": target.type_name,
                    "confidence": confidence,
                    "description": (
                        "A 32-bit word in this payload matches another ITEM record offset. This is a useful "
                        "reference candidate, but the exact Havok 2024.2 pointer/reference encoding is not confirmed."
                    ),
                }
            )
            if len(links) >= limit:
                return links
    return links


def _summarize_hkx_u32_words(payload: bytes, *, limit: int = 8) -> str:
    word_count = min(limit, len(payload) // 4)
    if word_count <= 0:
        return ""
    words = [struct.unpack_from("<I", payload, index * 4)[0] for index in range(word_count)]
    return "u32 words: " + " ".join(_hkx_hex(word, 8) for word in words)


def _summarize_hkx_float_rows(payload: bytes, *, row_count: int, components: int = 4) -> List[Tuple[float, ...]]:
    rows: List[Tuple[float, ...]] = []
    fmt = "<" + ("f" * components)
    stride = struct.calcsize(fmt)
    for index in range(row_count):
        offset = index * stride
        if offset + stride > len(payload):
            break
        row = tuple(float(value) for value in struct.unpack_from(fmt, payload, offset))
        if all(math.isfinite(value) for value in row):
            rows.append(row)
    return rows


def _summarize_hkx_object_payload(
    payload: bytes,
    records: Sequence[HkxItemRecord],
    record: HkxItemRecord,
    *,
    offset_indexes: Optional[Tuple[Dict[int, Tuple[HkxItemRecord, ...]], Dict[int, Tuple[HkxItemRecord, ...]]]] = None,
) -> List[str]:
    lines: List[str] = []
    type_name = record.type_name
    if not payload:
        return lines
    if type_name.startswith("hkArray") and len(payload) >= 16:
        ref_value = struct.unpack_from("<Q", payload, 0)[0]
        size_value = struct.unpack_from("<I", payload, 8)[0]
        capacity_value = struct.unpack_from("<I", payload, 12)[0]
        lines.append(
            "array-like header (unverified): "
            f"ref/data={_hkx_hex(ref_value)}, size={size_value:,}, capacity/flags={_hkx_hex(capacity_value, 8)}"
        )
    elif type_name.startswith("hkRefPtr") and len(payload) >= 8:
        ref_value = struct.unpack_from("<Q", payload, 0)[0]
        lines.append(f"ref-like payload (unverified): target/ref={_hkx_hex(ref_value)}")
    elif type_name == "hknpShapeMassProperties" and len(payload) >= 64:
        rows = _summarize_hkx_float_rows(payload[:64], row_count=4, components=4)
        if rows:
            lines.append(
                "mass-property float rows (unverified): "
                + "; ".join(
                    "(" + ", ".join(f"{component:.6g}" for component in row) + ")" for row in rows
                )
            )
    elif type_name == "hkCompressedMassProperties" and len(payload) >= 16:
        words = _hkx_first_u32_words(payload[: min(len(payload), 32)], min(8, len(payload) // 4))
        if words:
            lines.append(
                "compressed mass-property words (read-only): "
                + " ".join(_hkx_hex(int(word), 8) for word in words if isinstance(word, int))
            )
    elif type_name == "hkPackedVector3" and record.count > 0 and len(payload) >= 4:
        stride = max(4, len(payload) // max(1, int(record.count)))
        samples: List[str] = []
        for item_index in range(min(int(record.count), 6)):
            offset = item_index * stride
            if offset + 4 > len(payload):
                break
            samples.append("(" + ", ".join(str(int(value)) for value in payload[offset:offset + 4]) + ")")
        if samples:
            lines.append(
                f"packed vector3 rows (read-only): stride={stride}, samples="
                + "; ".join(samples)
            )
    elif type_name in _HKX_SCALAR_ARRAY_TYPES:
        scalar_values = _hkx_scalar_array_values(payload, record, limit=16)
        if scalar_values:
            values = scalar_values["values"]
            lines.append(
                f"{scalar_values['data_type']} scalar values (read-only): "
                f"count={scalar_values['decoded_value_count']}, sample={values}"
            )
    elif type_name in _HKX_ENUM_RECORD_TYPES:
        enum_values = _hkx_enum_record_values(payload, record, limit=16)
        if enum_values:
            lines.append(
                f"enum/flags values (read-only): width={enum_values['storage_byte_width']} byte(s), "
                f"count={enum_values['decoded_value_count']}, sample={enum_values['values']}"
            )
    elif type_name in {
        "hknpConvexShape",
        "hknpCompoundShape",
        "hknpShapeInstance",
        "hknpShapeProperties::Entry",
        "hkFreeListArrayElement<tVALUE_TYPE=7>",
        "hkcdSimdTreeNamespace::Node",
    } or type_name.startswith("hknp"):
        word_summary = _summarize_hkx_u32_words(payload)
        if word_summary:
            lines.append(f"object words (unverified layout): {word_summary}")
    link_matches = _summarize_hkx_possible_record_links(payload, records, record, offset_indexes=offset_indexes)
    if link_matches:
        lines.append("possible record/data references: " + "; ".join(link_matches))
    return lines


def _summarize_hkx_item_payloads(
    data: bytes,
    items: Sequence[HkxTagItem],
    records: Sequence[HkxItemRecord],
) -> List[HkxItemPayloadSummary]:
    spans = _hkx_item_record_spans(data, items, records)
    offset_indexes = _hkx_record_offset_indexes(records)
    summaries: List[HkxItemPayloadSummary] = []
    for record in records:
        span = spans.get(record.index)
        if span is None:
            continue
        start, end = span
        byte_length = end - start
        inferred_stride = byte_length / record.count if record.count else None
        lines: List[str] = []
        type_name = record.type_name
        if type_name == "hkFloat3" and record.count > 0 and byte_length >= record.count * 12:
            values, bounds = _summarize_hkx_float_vectors(data, start, record.count, 3, 12)
            if bounds:
                lines.append(f"bounds: {bounds}")
            if values:
                sample = "; ".join(
                    "(" + ", ".join(f"{component:.6g}" for component in value[:3]) + ")" for value in values[:4]
                )
                lines.append(f"sample: {sample}")
        elif type_name == "hkVector4" and record.count > 0 and byte_length >= record.count * 16:
            values, bounds = _summarize_hkx_float_vectors(data, start, record.count, 4, 16)
            if bounds:
                lines.append(f"bounds: {bounds}")
            if values:
                sample = "; ".join(
                    "(" + ", ".join(f"{component:.6g}" for component in value[:4]) + ")" for value in values[:4]
                )
                lines.append(f"sample: {sample}")
        elif type_name == "hkUint8" and record.count > 0:
            payload = data[start : min(start + record.count, len(data))]
            if payload:
                lines.append(f"values: min={min(payload)}, max={max(payload)}, unique={len(set(payload))}")
                lines.append("sample: " + " ".join(str(value) for value in payload[:32]))
        elif type_name == "hknpConvexHull::Edge" and record.count > 0 and byte_length >= record.count * 4:
            pairs: List[Tuple[int, int]] = []
            for index in range(record.count):
                offset = start + index * 4
                if offset + 4 > len(data):
                    break
                pairs.append(struct.unpack_from("<HH", data, offset))
            if pairs:
                max_index = max(max(pair) for pair in pairs)
                lines.append(f"uint16 pairs: {len(pairs):,}, max-index={max_index}")
                lines.append("sample: " + "; ".join(f"({a}, {b})" for a, b in pairs[:8]))
        elif type_name == "hknpConvexHull::Face" and record.count > 0 and byte_length >= record.count * 4:
            faces = [tuple(data[start + index * 4 : start + index * 4 + 4]) for index in range(record.count)]
            if faces:
                lines.append(
                    "face records: "
                    + "; ".join(
                        f"(index-start={face[0] | (face[1] << 8)}, vertex-count={face[2]}, meta={face[3]})"
                        for face in faces[:8]
                    )
                )
        object_lines = _summarize_hkx_object_payload(data[start:end], records, record, offset_indexes=offset_indexes)
        if object_lines:
            lines.extend(object_lines)
        elif record.count == 1 and byte_length in {8, 16, 32, 64, 128, 184}:
            lines.append("single object payload")
        if lines:
            summaries.append(
                HkxItemPayloadSummary(
                    record_index=record.index,
                    type_name=type_name,
                    byte_length=byte_length,
                    inferred_stride=inferred_stride,
                    lines=lines,
                )
            )
    return summaries


def _infer_hkx_collision_geometry_hints(
    data: bytes,
    items: Sequence[HkxTagItem],
    records: Sequence[HkxItemRecord],
) -> List[HkxCollisionGeometryHint]:
    if not any(record.type_name.startswith("hknp") for record in records):
        return []
    spans = _hkx_item_record_spans(data, items, records)
    hints: List[HkxCollisionGeometryHint] = []

    convex_shape_records = [record for record in records if record.type_name == "hknpConvexShape"]
    property_indices = [
        index for index, record in enumerate(records) if record.type_name == "hknpShapeProperties::Entry"
    ]
    for group_index, start_index in enumerate(property_indices):
        next_start = property_indices[group_index + 1] if group_index + 1 < len(property_indices) else len(records)
        group_records = records[start_index:next_start]
        hint = _build_hkx_hull_geometry_hint(
            data,
            spans,
            group_records,
            shape_type="hknpConvexShape",
            shape_record=(
                convex_shape_records[group_index] if group_index < len(convex_shape_records) else None
            ),
        )
        if hint is not None:
            hints.append(hint)

    for index, record in enumerate(records):
        if record.type_name != "hknpBoxShape":
            continue
        next_shape_index = next(
            (
                candidate_index
                for candidate_index, candidate in enumerate(records[index + 1 :], start=index + 1)
                if candidate.type_name in {"hknpBoxShape", "hknpConvexShape", "hknpSphereShape", "hknpCapsuleShape"}
            ),
            len(records),
        )
        hint = _build_hkx_hull_geometry_hint(
            data,
            spans,
            records[index + 1 : next_shape_index],
            shape_type="hknpBoxShape",
            shape_record=record,
        )
        if hint is not None:
            hints.append(hint)

    for index, record in enumerate(records):
        if record.type_name != "hknpSphereShape":
            continue
        span = spans.get(record.index)
        if span is None:
            continue
        start, end = span
        payload = data[start:end]
        radius: Optional[float] = None
        if len(payload) >= 0x6C:
            candidate_radius = struct.unpack_from("<f", payload, 0x68)[0]
            if 0.0 < candidate_radius < 1_000_000.0:
                radius = float(candidate_radius)
        center_record = next(
            (
                candidate
                for candidate in records[index + 1 :]
                if candidate.type_name == "hkFloat3" and candidate.count == 1
            ),
            None,
        )
        center_values = _read_hkx_float_vector_payload(data, spans, center_record, 3, 12)
        center = center_values[0] if center_values else None
        hint = HkxCollisionGeometryHint(
            shape_type="hknpSphereShape",
            shape_record_index=record.index,
            vertex_record_index=(center_record.index if center_record is not None else None),
            radius=radius,
        )
        if center is not None and radius is not None:
            hint.bounds_min = (center[0] - radius, center[1] - radius, center[2] - radius)
            hint.bounds_max = (center[0] + radius, center[1] + radius, center[2] + radius)
        if radius is not None or center is not None:
            hints.append(hint)

    for index, record in enumerate(records):
        if record.type_name != "hknpCapsuleShape":
            continue
        span = spans.get(record.index)
        if span is None:
            continue
        start, end = span
        payload = data[start:end]
        radius: Optional[float] = None
        if len(payload) >= 0x6C:
            candidate_radius = struct.unpack_from("<f", payload, 0x68)[0]
            if 0.0 < candidate_radius < 1_000_000.0:
                radius = float(candidate_radius)
        endpoint_record = next(
            (
                candidate
                for candidate in records[index + 1 :]
                if candidate.type_name == "hkFloat3" and candidate.count == 2
            ),
            None,
        )
        endpoints = _read_hkx_float_vector_payload(data, spans, endpoint_record, 3, 12)
        hint = HkxCollisionGeometryHint(
            shape_type="hknpCapsuleShape",
            shape_record_index=record.index,
            vertex_record_index=(endpoint_record.index if endpoint_record is not None else None),
            vertex_count=(2 if len(endpoints) >= 2 else 0),
            radius=radius,
        )
        if len(endpoints) >= 2:
            start_point, end_point = endpoints[0], endpoints[1]
            dx = end_point[0] - start_point[0]
            dy = end_point[1] - start_point[1]
            dz = end_point[2] - start_point[2]
            hint.capsule_length = math.sqrt(dx * dx + dy * dy + dz * dz)
            pad = radius or 0.0
            hint.bounds_min = (
                min(start_point[0], end_point[0]) - pad,
                min(start_point[1], end_point[1]) - pad,
                min(start_point[2], end_point[2]) - pad,
            )
            hint.bounds_max = (
                max(start_point[0], end_point[0]) + pad,
                max(start_point[1], end_point[1]) + pad,
                max(start_point[2], end_point[2]) + pad,
            )
        if radius is not None or endpoints:
            hints.append(hint)

    for record in records:
        if record.type_name != "hknpMeshShape":
            continue
        hint = HkxCollisionGeometryHint(
            shape_type="hknpMeshShape",
            shape_record_index=record.index,
            mesh_section_count=sum(
                max(0, candidate.count)
                for candidate in records
                if candidate.type_name == "hknpMeshShape::GeometrySection"
            ),
            mesh_primitive_count=sum(
                max(0, candidate.count)
                for candidate in records
                if candidate.type_name == "hknpMeshShape::GeometrySection::Primitive"
            ),
            mesh_aabb_node_count=sum(
                max(0, candidate.count)
                for candidate in records
                if candidate.type_name == "hknpAabb8TreeNode"
            ),
            mesh_shape_tag_count=sum(
                max(0, candidate.count)
                for candidate in records
                if candidate.type_name == "hknpMeshShape::ShapeTagTableEntry"
            ),
            mesh_data_byte_count=sum(
                max(0, candidate.count) for candidate in records if candidate.type_name == "hkUint8"
            ),
        )
        if any(
            (
                hint.mesh_section_count,
                hint.mesh_primitive_count,
                hint.mesh_aabb_node_count,
                hint.mesh_shape_tag_count,
                hint.mesh_data_byte_count,
            )
        ):
            hints.append(hint)

    if hints:
        _assign_hkx_mass_property_records(hints, records)
        return hints

    fallback_hint = _build_hkx_hull_geometry_hint(
        data,
        spans,
        records,
        shape_type="hknpShape",
        shape_record=None,
    )
    fallback_hints = [fallback_hint] if fallback_hint is not None else []
    _assign_hkx_mass_property_records(fallback_hints, records)
    return fallback_hints


def parse_hkx_tagfile_summary(data: bytes) -> HkxTagfileSummary:
    printable = _extract_hkx_printable_strings(data)
    native_parts = _hkx_native_summary_parts(data)
    native_object_records: List[Dict[str, object]] = []
    native_physics_tuning_groups: List[Dict[str, object]] = []
    native_tagfile_reference_fixups: Dict[str, object] = {}
    native_fixup_semantics_report: Dict[str, object] = {}
    native_model_graph: Dict[str, object] = {}
    native_hard_internal_evidence: Dict[str, object] = {}
    native_real_hkclass_metadata: Dict[str, object] = {}
    native_real_hkclass_metadata_v2: Dict[str, object] = {}
    native_fixup_semantics_v2: Dict[str, object] = {}
    native_semantic_model_v1: Dict[str, object] = {}
    native_semantic_writer_gate_v1: Dict[str, object] = {}
    native_edit_candidate_map_v1: Dict[str, object] = {}
    native_hkx_edit_gate_v1: Dict[str, object] = {}
    native_class_decoder_evidence_v2: Dict[str, object] = {}
    native_decoder_evidence_v2: Dict[str, object] = {}
    native_modding_readiness: Dict[str, object] = {}
    native_no_edit_binary_writer: Dict[str, object] = {}
    if native_parts is not None:
        (
            tag_items,
            string_table_names,
            type_infos,
            declared_type_name_count,
            type_names,
            item_records,
            type_warnings,
            native_object_records,
            native_physics_tuning_groups,
            native_tagfile_reference_fixups,
            native_fixup_semantics_report,
            native_model_graph,
            native_hard_internal_evidence,
            native_real_hkclass_metadata,
            native_real_hkclass_metadata_v2,
            native_fixup_semantics_v2,
            native_semantic_model_v1,
            native_semantic_writer_gate_v1,
            native_edit_candidate_map_v1,
            native_hkx_edit_gate_v1,
            native_class_decoder_evidence_v2,
            native_decoder_evidence_v2,
            native_modding_readiness,
            native_no_edit_binary_writer,
        ) = native_parts
        if not type_names:
            type_names = [type_info.display_name for type_info in type_infos] or string_table_names or _extract_hkx_type_names(printable)
    else:
        tag_items = _find_hkx_tag_items(data)
        string_table_names = _extract_hkx_tst1_type_names(data, tag_items)
        declared_type_name_count, type_infos, type_warnings = _parse_hkx_tna1_type_infos(data, tag_items, string_table_names)
        tna_type_names = [type_info.display_name for type_info in type_infos]
        fallback_type_names = _extract_hkx_type_names(printable)
        type_names = tna_type_names or string_table_names or fallback_type_names
        type_names_by_index = {type_info.index: type_info.display_name for type_info in type_infos}
        if not type_names_by_index:
            type_names_by_index = {index: name for index, name in enumerate(type_names)}
        item_records = _parse_hkx_item_records(data, tag_items, type_names_by_index)
    declared_size = int.from_bytes(data[:4], "big", signed=False) if len(data) >= 4 else None
    sdk_version = _detect_hkx_sdk_version(data, printable)
    item_payload_summaries = _summarize_hkx_item_payloads(data, tag_items, item_records)
    collision_geometry_hints = _infer_hkx_collision_geometry_hints(data, tag_items, item_records)
    warnings: List[str] = []
    warnings.extend(type_warnings)
    if declared_size is not None and declared_size != len(data):
        warnings.append(f"Declared size {declared_size:,} does not match payload size {len(data):,}.")
    return HkxTagfileSummary(
        declared_size=declared_size,
        size_matches=declared_size == len(data) if declared_size is not None else False,
        sdk_version=sdk_version,
        tag0_offset=data[:64].find(b"TAG0"),
        tag_items=tag_items,
        type_names=type_names,
        string_table_names=string_table_names,
        type_infos=type_infos,
        declared_type_name_count=declared_type_name_count,
        item_records=item_records,
        item_payload_summaries=item_payload_summaries,
        collision_geometry_hints=collision_geometry_hints,
        native_object_records=native_object_records,
        native_physics_tuning_groups=native_physics_tuning_groups,
        native_tagfile_reference_fixups=native_tagfile_reference_fixups,
        native_fixup_semantics_report=native_fixup_semantics_report,
        native_model_graph=native_model_graph,
        native_hard_internal_evidence=native_hard_internal_evidence,
        native_real_hkclass_metadata=native_real_hkclass_metadata,
        native_real_hkclass_metadata_v2=native_real_hkclass_metadata_v2,
        native_fixup_semantics_v2=native_fixup_semantics_v2,
        native_semantic_model_v1=native_semantic_model_v1,
        native_semantic_writer_gate_v1=native_semantic_writer_gate_v1,
        native_edit_candidate_map_v1=native_edit_candidate_map_v1,
        native_hkx_edit_gate_v1=native_hkx_edit_gate_v1,
        native_class_decoder_evidence_v2=native_class_decoder_evidence_v2,
        native_decoder_evidence_v2=native_decoder_evidence_v2,
        native_modding_readiness=native_modding_readiness,
        native_no_edit_binary_writer=native_no_edit_binary_writer,
        warnings=warnings,
    )


def _hkx_record_by_index(records: Sequence[HkxItemRecord], record_index: Optional[int]) -> Optional[HkxItemRecord]:
    if record_index is None:
        return None
    return next((record for record in records if record.index == record_index), None)


def _hkx_native_summary_parts(
    data: bytes,
) -> Optional[
    Tuple[
        List[HkxTagItem],
        List[str],
        List[HkxTypeInfo],
        Optional[int],
        List[str],
        List[HkxItemRecord],
        List[str],
        List[Dict[str, object]],
        List[Dict[str, object]],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
        Dict[str, object],
    ]
]:
    try:
        from cdmw.core.hkx_native import parse_hkx_summary_with_rust
    except Exception:
        return None
    native = parse_hkx_summary_with_rust(data)
    if not isinstance(native, Mapping):
        return None
    try:
        tag_items = [
            HkxTagItem(
                name=str(item.get("name") or ""),
                offset=int(item.get("offset")),
                length_word_offset=(int(item["length_word_offset"]) if item.get("length_word_offset") is not None else None),
                raw_length_word=(int(item["raw_length_word"]) if item.get("raw_length_word") is not None else None),
                declared_length=(int(item["declared_length"]) if item.get("declared_length") is not None else None),
                length_flags=(int(item["length_flags"]) if item.get("length_flags") is not None else None),
                marker_end_offset=(int(item["marker_end_offset"]) if item.get("marker_end_offset") is not None else None),
                word_end_offset=(int(item["word_end_offset"]) if item.get("word_end_offset") is not None else None),
            )
            for item in native.get("tag_items", [])
            if isinstance(item, Mapping) and item.get("offset") is not None
        ]
        type_infos = [
            HkxTypeInfo(
                index=int(item.get("index")),
                name=str(item.get("name") or ""),
                template_parameters=[
                    (str(parameter.get("name") or ""), int(parameter.get("value") or 0))
                    for parameter in item.get("template_parameters", [])
                    if isinstance(parameter, Mapping)
                ],
            )
            for item in native.get("type_infos", [])
            if isinstance(item, Mapping) and item.get("index") is not None
        ]
        item_records = [
            HkxItemRecord(
                index=int(item.get("index")),
                raw_type_flags=int(item.get("raw_type_flags") or 0),
                type_index=int(item.get("type_index") or 0),
                flags=int(item.get("flags") or 0),
                data_offset=int(item.get("data_offset") or 0),
                absolute_data_offset=(int(item["absolute_data_offset"]) if item.get("absolute_data_offset") is not None else None),
                count=int(item.get("count") or 0),
                type_name=str(item.get("type_name") or ""),
            )
            for item in native.get("item_records", [])
            if isinstance(item, Mapping) and item.get("index") is not None
        ]
        string_table_names = [str(name) for name in native.get("string_table_names", []) if str(name)]
        type_names = [str(name) for name in native.get("type_names", []) if str(name)]
        warnings = [str(warning) for warning in native.get("warnings", []) if str(warning)]
        native_object_records = [
            dict(item)
            for item in native.get("object_records", [])
            if isinstance(item, Mapping)
        ]
        native_physics_tuning_groups = [
            dict(item)
            for item in native.get("physics_tuning_groups", [])
            if isinstance(item, Mapping)
        ]
        native_tagfile_reference_fixups = (
            dict(native.get("tagfile_reference_fixups") or {})
            if isinstance(native.get("tagfile_reference_fixups"), Mapping)
            else {}
        )
        native_fixup_semantics_report = (
            dict(native.get("fixup_semantics_report") or {})
            if isinstance(native.get("fixup_semantics_report"), Mapping)
            else {}
        )
        native_model_graph = (
            dict(native.get("native_model_graph") or {})
            if isinstance(native.get("native_model_graph"), Mapping)
            else {}
        )
        native_hard_internal_evidence = (
            dict(native.get("hard_internal_evidence") or {})
            if isinstance(native.get("hard_internal_evidence"), Mapping)
            else {}
        )
        native_real_hkclass_metadata = (
            dict(native.get("real_hkclass_metadata") or {})
            if isinstance(native.get("real_hkclass_metadata"), Mapping)
            else {}
        )
        native_real_hkclass_metadata_v2 = (
            dict(native.get("real_hkclass_metadata_v2") or {})
            if isinstance(native.get("real_hkclass_metadata_v2"), Mapping)
            else {}
        )
        native_fixup_semantics_v2 = (
            dict(native.get("fixup_semantics_v2") or {})
            if isinstance(native.get("fixup_semantics_v2"), Mapping)
            else {}
        )
        native_semantic_model_v1 = (
            dict(native.get("semantic_model_v1") or {})
            if isinstance(native.get("semantic_model_v1"), Mapping)
            else {}
        )
        native_semantic_writer_gate_v1 = (
            dict(native.get("semantic_writer_gate_v1") or {})
            if isinstance(native.get("semantic_writer_gate_v1"), Mapping)
            else {}
        )
        native_edit_candidate_map_v1 = (
            dict(native.get("edit_candidate_map_v1") or {})
            if isinstance(native.get("edit_candidate_map_v1"), Mapping)
            else {}
        )
        native_hkx_edit_gate_v1 = (
            dict(native.get("hkx_edit_gate_v1") or {})
            if isinstance(native.get("hkx_edit_gate_v1"), Mapping)
            else {}
        )
        native_class_decoder_evidence_v2 = (
            dict(native.get("class_decoder_evidence_v2") or {})
            if isinstance(native.get("class_decoder_evidence_v2"), Mapping)
            else {}
        )
        native_decoder_evidence_v2 = (
            dict(native.get("decoder_evidence_v2") or {})
            if isinstance(native.get("decoder_evidence_v2"), Mapping)
            else {}
        )
        native_modding_readiness = (
            dict(native.get("modding_readiness") or {})
            if isinstance(native.get("modding_readiness"), Mapping)
            else {}
        )
        native_no_edit_binary_writer = (
            dict(native.get("no_edit_binary_writer") or {})
            if isinstance(native.get("no_edit_binary_writer"), Mapping)
            else {}
        )
        declared_type_name_count = (
            int(native["declared_type_name_count"])
            if native.get("declared_type_name_count") is not None
            else None
        )
    except (TypeError, ValueError):
        return None
    if not tag_items:
        return None
    return (
        tag_items,
        string_table_names,
        type_infos,
        declared_type_name_count,
        type_names,
        item_records,
        warnings,
        native_object_records,
        native_physics_tuning_groups,
        native_tagfile_reference_fixups,
        native_fixup_semantics_report,
        native_model_graph,
        native_hard_internal_evidence,
        native_real_hkclass_metadata,
        native_real_hkclass_metadata_v2,
        native_fixup_semantics_v2,
        native_semantic_model_v1,
        native_semantic_writer_gate_v1,
        native_edit_candidate_map_v1,
        native_hkx_edit_gate_v1,
        native_class_decoder_evidence_v2,
        native_decoder_evidence_v2,
        native_modding_readiness,
        native_no_edit_binary_writer,
    )


def _hkx_json_number_vector(values: Sequence[float]) -> List[float]:
    return [float(value) for value in values]


