def _hkx_export_float_vectors_for_record(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    record: Optional[HkxItemRecord],
    components: int,
    stride: int,
) -> List[List[float]]:
    return [_hkx_json_number_vector(value) for value in _read_hkx_float_vector_payload(data, spans, record, components, stride)]


def _hkx_export_mass_property_rows_for_record(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    record: Optional[HkxItemRecord],
) -> List[List[float]]:
    if record is None or record.type_name != "hknpShapeMassProperties":
        return []
    span = spans.get(record.index)
    if span is None:
        return []
    start, end = span
    if end - start < 64:
        return []
    rows = _summarize_hkx_float_rows(data[start : start + 64], row_count=4, components=4)
    return [_hkx_json_number_vector(row) for row in rows] if len(rows) == 4 else []


def _hkx_export_box_shape_summary_for_record(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    record: Optional[HkxItemRecord],
) -> Optional[Dict[str, object]]:
    if record is None or record.type_name != "hknpBoxShape":
        return None
    span = spans.get(record.index)
    if span is None:
        return None
    start, end = span
    payload = data[start:end]
    if len(payload) < 0xC0:
        return None
    rows: List[List[float]] = []
    for row_index in range(4):
        row_offset = 0x80 + row_index * 16
        row = [float(value) for value in struct.unpack_from("<ffff", payload, row_offset)]
        if not all(math.isfinite(component) for component in row):
            return None
        rows.append(row)
    half_extents = [abs(rows[0][3]), abs(rows[1][3]), abs(rows[2][3])]
    center = rows[3][:3]
    margin: Optional[float] = None
    radius_factor: Optional[float] = None
    if len(payload) >= 0x6C:
        candidate_margin = struct.unpack_from("<f", payload, 0x68)[0]
        if math.isfinite(candidate_margin):
            margin = float(candidate_margin)
    if len(payload) >= 0x70:
        candidate_factor = struct.unpack_from("<f", payload, 0x6C)[0]
        if math.isfinite(candidate_factor):
            radius_factor = float(candidate_factor)
    bounds_min = [float(center[index] - half_extents[index]) for index in range(3)]
    bounds_max = [float(center[index] + half_extents[index]) for index in range(3)]
    offset_count_pairs: Dict[str, Dict[str, int]] = {}
    for field_name, offset in (
        ("vertices", 0x38),
        ("planes", 0x40),
        ("faces", 0x48),
        ("face_indices", 0x50),
        ("edge_table_a", 0x58),
        ("edge_table_b", 0x60),
    ):
        if offset + 8 <= len(payload):
            offset_count_pairs[field_name] = {
                "offset": int(struct.unpack_from("<I", payload, offset)[0]),
                "count": int(struct.unpack_from("<I", payload, offset + 4)[0]),
            }
    return {
        "status": "read_only_schema_recovery",
        "confidence": "experimental",
        "warning": (
            "hknpBoxShape local frame/extents are inferred from repeated Crimson Desert samples. "
            "They are shown for browsing/preview and are not safe to edit yet."
        ),
        "local_frame_rows": rows,
        "center": _hkx_json_number_vector(center),
        "half_extents": _hkx_json_number_vector(half_extents),
        "bounds_min": _hkx_json_number_vector(bounds_min),
        "bounds_max": _hkx_json_number_vector(bounds_max),
        "convex_radius_or_collision_margin": margin,
        "aabb_or_radius_factor": radius_factor,
        "offset_count_pairs": offset_count_pairs,
    }


def _hkx_shape_payload_float_description(type_name: str, offset: int) -> str:
    if type_name == "hknpConvexShape" and offset in {0x68, 0x6C}:
        return (
            "Unverified hknpConvexShape float slot observed across Crimson Desert samples. "
            "The importer can patch this fixed offset, but the exact Havok field name is not recovered yet."
        )
    return (
        f"Unverified {type_name or 'hknp shape'} float slot. "
        "Patch only if you are intentionally experimenting with this fixed payload offset."
    )


def _hkx_export_shape_payload_float_slots_for_record(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    record: Optional[HkxItemRecord],
) -> List[Dict[str, object]]:
    if record is None or not record.type_name.startswith("hknp"):
        return []
    span = spans.get(record.index)
    if span is None:
        return []
    start, end = span
    payload = data[start:end]
    slots: List[Dict[str, object]] = []
    for offset in range(0, len(payload) - 3, 4):
        value = struct.unpack_from("<f", payload, offset)[0]
        if not math.isfinite(value):
            continue
        if abs(value) < 1e-6 or abs(value) > 1_000_000.0:
            continue
        slots.append(
            {
                "offset": offset,
                "hex_offset": f"0x{offset:X}",
                "value": float(value),
                "description": _hkx_shape_payload_float_description(record.type_name, offset),
            }
        )
    return slots


def _hkx_export_hull_topology_document(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    hint: HkxCollisionGeometryHint,
    records: Sequence[HkxItemRecord],
) -> Optional[Dict[str, object]]:
    face_record = _hkx_record_by_index(records, hint.face_record_index)
    index_record = _hkx_record_by_index(records, hint.face_index_record_index)
    edge_records = [
        record
        for record_index in hint.edge_record_indices
        for record in [_hkx_record_by_index(records, record_index)]
        if record is not None
    ]
    topology: Dict[str, object] = {
        "status": "experimental_topology_edit",
        "warning": (
            "Topology edits are fixed-size only. Keep face record count, index byte count, edge pair counts, "
            "and all referenced vertex indices within the existing vertex count."
        ),
        "descriptions": {
            "face_records": (
                "Convex hull face table. index_start points into face_indices; vertex_count tells how many "
                "indices belong to the face; meta is an unverified Havok byte."
            ),
            "face_indices": "Byte index buffer used by face_records. Values normally reference existing vertex rows.",
            "edge_tables": "uint16 pair tables used by Havok hull support/edge data. Exact field meaning is unverified.",
            "face_vertex_loops": "Decoded read-only convenience view combining face_records and face_indices.",
        },
    }
    records_map: Dict[str, object] = {}
    if face_record is not None:
        face_payload = _hkx_payload_slice(data, spans, face_record, face_record.count * 4)
        face_values = _hkx_advanced_editable_values_document(face_payload, face_record)
        if isinstance(face_values, Mapping) and face_values.get("kind") == "face_records":
            topology["face_records"] = face_values.get("records", [])
            records_map["face_records"] = int(face_record.index)
    if index_record is not None:
        index_payload = _hkx_payload_slice(data, spans, index_record, index_record.count)
        index_values = _hkx_advanced_editable_values_document(index_payload, index_record)
        if isinstance(index_values, Mapping) and index_values.get("kind") == "byte_values":
            topology["face_indices"] = index_values.get("values", [])
            records_map["face_indices"] = int(index_record.index)
    if edge_records:
        edge_tables: List[Dict[str, object]] = []
        for edge_record in edge_records:
            edge_payload = _hkx_payload_slice(data, spans, edge_record, edge_record.count * 4)
            edge_values = _hkx_advanced_editable_values_document(edge_payload, edge_record)
            if isinstance(edge_values, Mapping) and edge_values.get("kind") == "uint16_pairs":
                edge_tables.append(
                    {
                        "record_index": int(edge_record.index),
                        "pair_count": int(edge_record.count),
                        "pairs": edge_values.get("pairs", []),
                    }
                )
        if edge_tables:
            topology["edge_tables"] = edge_tables
            records_map["edge_tables"] = [int(record.index) for record in edge_records]
    if hint.face_vertex_indices:
        topology["face_vertex_loops"] = [list(face) for face in hint.face_vertex_indices]
        topology["face_vertex_loops_read_only"] = True
    if records_map:
        topology["records"] = records_map
    return topology if any(key in topology for key in ("face_records", "face_indices", "edge_tables")) else None


def _hkx_mesh_payload_digest(payload: bytes) -> Dict[str, object]:
    return {
        "sha1": hashlib.sha1(payload).hexdigest(),
        "sample_hex": _hkx_payload_hex(payload[:64]),
        "sample_byte_count": min(len(payload), 64),
    }


def _hkx_mesh_record_base(record: HkxItemRecord, payload: bytes, role: str) -> Dict[str, object]:
    stride = len(payload) // record.count if record.count and len(payload) % record.count == 0 else None
    return {
        "record_index": int(record.index),
        "type_name": record.type_name,
        "role": role,
        "count": int(record.count),
        "data_offset": int(record.data_offset),
        "absolute_data_offset": int(record.absolute_data_offset) if record.absolute_data_offset is not None else None,
        "byte_length": len(payload),
        "stride": stride,
        "status": "read_only_schema_recovery",
        "confidence": "experimental",
        "raw_preservation": _hkx_mesh_payload_digest(payload),
    }


def _hkx_first_u32_words(payload: bytes, count: int) -> List[int]:
    return [struct.unpack_from("<I", payload, offset * 4)[0] for offset in range(min(count, len(payload) // 4))]


def _hkx_scalar_array_values(payload: bytes, record: HkxItemRecord, *, limit: int = 512) -> Optional[Dict[str, object]]:
    spec = _HKX_SCALAR_ARRAY_TYPES.get(record.type_name)
    if spec is None or record.count <= 0:
        return None
    _field_name, data_type, fmt, byte_width, _description = spec
    max_count = min(int(record.count), len(payload) // byte_width)
    if max_count <= 0:
        return None
    values: List[object] = []
    for index in range(min(max_count, limit)):
        raw_value = struct.unpack_from(fmt, payload, index * byte_width)[0]
        if data_type == "float32[]":
            values.append(float(raw_value))
        elif data_type == "bool[]":
            values.append(bool(raw_value))
        else:
            values.append(int(raw_value))
    return {
        "values": values,
        "value_count": int(record.count),
        "decoded_value_count": max_count,
        "truncated": max(0, max_count - len(values)),
        "data_type": data_type,
        "byte_width": byte_width,
    }


def _hkx_enum_record_values(payload: bytes, record: HkxItemRecord, *, limit: int = 256) -> Optional[Dict[str, object]]:
    if record.type_name not in _HKX_ENUM_RECORD_TYPES or record.count <= 0 or not payload:
        return None
    count = max(1, int(record.count))
    stride = len(payload) // count if len(payload) % count == 0 else None
    byte_width = 4
    if stride in (1, 2, 4, 8):
        byte_width = int(stride)
    elif len(payload) >= count * 4:
        byte_width = 4
    elif len(payload) >= count * 2:
        byte_width = 2
    else:
        byte_width = 1
    fmt = {1: "B", 2: "<H", 4: "<I", 8: "<Q"}[byte_width]
    decoded_count = min(int(record.count), len(payload) // byte_width)
    values = [
        int(struct.unpack_from(fmt, payload, index * byte_width)[0])
        for index in range(min(decoded_count, limit))
    ]
    return {
        "values": values,
        "value_count": int(record.count),
        "decoded_value_count": decoded_count,
        "truncated": max(0, decoded_count - len(values)),
        "storage_byte_width": byte_width,
        "description": _HKX_ENUM_RECORD_TYPES[record.type_name],
    }


def _hkx_u32_pair_rows(payload: bytes, *, limit_bytes: int = 192) -> List[Dict[str, object]]:
    rows: List[Dict[str, object]] = []
    for offset in range(0, min(len(payload), limit_bytes), 8):
        if offset + 8 > len(payload):
            break
        low, high = struct.unpack_from("<II", payload, offset)
        if low == 0 and high == 0:
            continue
        rows.append(
            {
                "offset": offset,
                "hex_offset": f"0x{offset:X}",
                "a": int(low),
                "b": int(high),
                "as_u64": int(struct.unpack_from("<Q", payload, offset)[0]),
            }
        )
    return rows


def _hkx_finite_float_slots(payload: bytes, *, limit_bytes: int = 192, limit: int = 32) -> List[Dict[str, object]]:
    values: List[Dict[str, object]] = []
    for offset in range(0, min(len(payload), limit_bytes) - 3, 4):
        value = struct.unpack_from("<f", payload, offset)[0]
        if not math.isfinite(value) or abs(value) < 1e-8 or abs(value) > 1_000_000.0:
            continue
        values.append({"offset": offset, "hex_offset": f"0x{offset:X}", "value": float(value)})
        if len(values) >= limit:
            break
    return values


def _hkx_finite_float_slots_in_range(payload: bytes, start: int, length: int, *, limit: int = 8) -> List[Dict[str, object]]:
    slots: List[Dict[str, object]] = []
    end = min(len(payload), start + length)
    for offset in range(start, max(start, end - 3), 4):
        value = struct.unpack_from("<f", payload, offset)[0]
        if not math.isfinite(value) or abs(value) < 1e-8 or abs(value) > 1_000_000.0:
            continue
        slots.append(
            {
                "offset": offset,
                "hex_offset": f"0x{offset:X}",
                "value": float(value),
                "description": "Finite float candidate inside a read-only mesh-shape record.",
            }
        )
        if len(slots) >= limit:
            break
    return slots


def _hkx_mesh_geometry_section_candidate_fields(payload: bytes) -> Dict[str, object]:
    words = _hkx_first_u32_words(payload, 16)
    if len(words) < 8:
        return {}
    signed_words = [struct.unpack_from("<i", payload, index * 4)[0] for index in range(min(16, len(payload) // 4))]
    fields: List[Dict[str, object]] = [
        {
            "name": "aabb_tree_relative_offset",
            "offset": 0,
            "value": words[0],
            "description": "Candidate byte offset from the geometry-section area to hknpAabb8TreeNode data.",
        },
        {
            "name": "aabb_tree_node_count",
            "offset": 4,
            "value": words[1],
            "description": "Candidate count of quantized AABB tree nodes referenced by this section.",
        },
        {
            "name": "primitive_relative_offset",
            "offset": 8,
            "value": words[2],
            "description": "Candidate byte offset to packed primitive/index tuples for this section.",
        },
        {
            "name": "primitive_count",
            "offset": 12,
            "value": words[3],
            "description": "Candidate primitive tuple count for this section.",
        },
        {
            "name": "mesh_byte_buffer_relative_offset",
            "offset": 16,
            "value": words[4],
            "description": "Candidate byte offset to a mesh byte/index buffer used by this section.",
        },
        {
            "name": "mesh_byte_buffer_size",
            "offset": 20,
            "value": words[5],
            "description": "Candidate byte length for the first mesh byte/index buffer.",
        },
        {
            "name": "secondary_buffer_relative_offset",
            "offset": 24,
            "value": words[6],
            "description": "Candidate byte offset to a secondary mesh buffer or range table.",
        },
        {
            "name": "secondary_buffer_count_or_size",
            "offset": 28,
            "value": words[7],
            "description": "Candidate count or byte length for the secondary mesh buffer.",
        },
    ]
    if len(words) >= 12:
        fields.extend(
            [
                {
                    "name": "unknown_word_08",
                    "offset": 32,
                    "value": signed_words[8] if len(signed_words) > 8 else words[8],
                    "description": "Unconfirmed signed section field, possibly a range, quantization, or tree/link value.",
                },
                {
                    "name": "unknown_word_09",
                    "offset": 36,
                    "value": signed_words[9] if len(signed_words) > 9 else words[9],
                    "description": "Unconfirmed signed section field, possibly a range, quantization, or tree/link value.",
                },
                {
                    "name": "unknown_word_10",
                    "offset": 40,
                    "value": signed_words[10] if len(signed_words) > 10 else words[10],
                    "description": "Unconfirmed signed section field, possibly a range, quantization, or tree/link value.",
                },
            ]
        )
    if len(payload) >= 56:
        fields.extend(
            [
                {
                    "name": "quantization_or_scale_x",
                    "offset": 44,
                    "value": struct.unpack_from("<f", payload, 44)[0],
                    "description": "Candidate float scale/quantization field for mesh bounds or AABB decoding.",
                },
                {
                    "name": "quantization_or_scale_y",
                    "offset": 48,
                    "value": struct.unpack_from("<f", payload, 48)[0],
                    "description": "Candidate float scale/quantization field for mesh bounds or AABB decoding.",
                },
                {
                    "name": "quantization_or_scale_z",
                    "offset": 52,
                    "value": struct.unpack_from("<f", payload, 52)[0],
                    "description": "Candidate float scale/quantization field for mesh bounds or AABB decoding.",
                },
            ]
        )
    return {
        "status": "read_only_candidate_layout",
        "confidence": "strong inference" if words[1] > 0 and words[3] > 0 else "experimental",
        "fields": fields,
        "description": (
            "First-pass hknpMeshShape::GeometrySection layout. Offset/count pairs line up with real "
            "Crimson Desert mesh-shape records, but edits remain disabled until all referenced buffers "
            "and tree data can be rebuilt."
        ),
    }


def _hkx_mesh_record_index_at_data_offset(records: Sequence[HkxItemRecord], data_offset: int, type_name: str) -> Optional[int]:
    for record in records:
        if int(record.data_offset) == int(data_offset) and record.type_name == type_name:
            return int(record.index)
    return None


def _hkx_mesh_enrich_geometry_section_layout_targets(
    layout: Dict[str, object],
    records: Sequence[HkxItemRecord],
    section_data_offset: int,
) -> None:
    fields = layout.get("fields")
    if not isinstance(fields, list):
        return
    target_specs = {
        "aabb_tree_relative_offset": ("hknpAabb8TreeNode", 0, "Exact target record for quantized AABB tree nodes."),
        "primitive_relative_offset": (
            "hknpMeshShape::GeometrySection::Primitive",
            8,
            "Target primitive tuple record. Crimson Desert samples point 8 bytes before the ITEM payload.",
        ),
        "mesh_byte_buffer_relative_offset": (
            "hkUint8",
            16,
            "Target mesh byte/index buffer. Crimson Desert samples point 16 bytes before the ITEM payload.",
        ),
        "secondary_buffer_relative_offset": (
            "hkUint8",
            24,
            "Target secondary mesh byte/range buffer. Crimson Desert samples point 24 bytes before the ITEM payload.",
        ),
    }
    for field in fields:
        if not isinstance(field, dict):
            continue
        spec = target_specs.get(str(field.get("name") or ""))
        value = field.get("value")
        if spec is None or not isinstance(value, int):
            continue
        target_type, bias, description = spec
        target_offset = int(section_data_offset) + int(value) + int(bias)
        field["target_type_name"] = target_type
        field["target_data_offset"] = target_offset
        field["target_bias"] = bias
        field["target_record_index"] = _hkx_mesh_record_index_at_data_offset(records, target_offset, target_type)
        field["target_resolution"] = "resolved" if field["target_record_index"] is not None else "unresolved"
        field["target_description"] = description


def _hkx_mesh_primitive_tuple_rows(payload: bytes, count: int) -> Tuple[List[Dict[str, object]], Dict[str, object], int]:
    usable_count = min(max(0, int(count)), len(payload) // 4, 512)
    rows: List[Dict[str, object]] = []
    all_indices: List[int] = []
    triangle_candidate_count = 0
    quad_candidate_count = 0
    degenerate_candidate_count = 0
    for index in range(usable_count):
        base = index * 4
        raw_bytes = list(payload[base : base + 4])
        raw = struct.unpack_from("<I", payload, base)[0]
        non_sentinel = [value for value in raw_bytes if value != 0xFF]
        unique_non_sentinel = set(non_sentinel)
        if len(non_sentinel) == 3:
            triangle_candidate_count += 1
        elif len(non_sentinel) == 4:
            quad_candidate_count += 1
        if len(unique_non_sentinel) < len(non_sentinel):
            degenerate_candidate_count += 1
        all_indices.extend(non_sentinel)
        rows.append(
            {
                "index": index,
                "packed_u32": raw,
                "hex": f"0x{raw:08X}",
                "low_u16": raw & 0xFFFF,
                "high_u16": (raw >> 16) & 0xFFFF,
                "byte_indices": raw_bytes,
                "candidate_vertex_indices": non_sentinel,
                "candidate_kind": "triangle" if len(non_sentinel) == 3 else "quad" if len(non_sentinel) == 4 else "unknown",
                "description": (
                    "Read-only primitive tuple. The four bytes behave like compact vertex/primitive indices "
                    "in sampled Crimson Desert mesh HKX files; 0xFF is treated as a possible triangle sentinel."
                ),
            }
        )
    analysis = {
        "status": "read_only_bitfield_analysis",
        "topology_candidate_status": "read_only_tuple_index_analysis",
        "packed_word_count": len(rows),
        "tuple_stride_bytes": 4,
        "candidate_index_min": min(all_indices) if all_indices else None,
        "candidate_index_max": max(all_indices) if all_indices else None,
        "candidate_index_unique_count": len(set(all_indices)),
        "candidate_triangle_count": triangle_candidate_count,
        "candidate_quad_count": quad_candidate_count,
        "candidate_degenerate_count": degenerate_candidate_count,
        "candidate_index_range": [min(all_indices), max(all_indices)] if all_indices else [],
        "description": (
            "Primitive rows are exposed as four-byte index tuples for comparison. This improves readability, "
            "but topology edits are still blocked because primitive material/shape-key fields and companion "
            "AABB/tree rebuild rules are not fully decoded."
        ),
    }
    padding_length = len(payload) - usable_count * 4
    return rows, analysis, padding_length


def _hkx_mesh_aabb8_node_rows(payload: bytes, record_count: int) -> Tuple[List[Dict[str, object]], Dict[str, object], int]:
    candidate_stride = 32 if len(payload) >= 32 else None
    if candidate_stride is None:
        return [], {"status": "not_enough_data"}, 0
    usable_count = min(len(payload) // candidate_stride, max(0, int(record_count)), 256)
    nodes: List[Dict[str, object]] = []
    for index in range(usable_count):
        base = index * candidate_stride
        row_payload = payload[base : base + candidate_stride]
        min_bytes = list(row_payload[0:4])
        max_bytes = list(row_payload[4:8])
        nodes.append(
            {
                "index": index,
                "candidate_min_bytes": min_bytes,
                "candidate_max_bytes": max_bytes,
                "child_or_primitive_bytes": list(row_payload[8:16]),
                "u16_words_sample": [
                    struct.unpack_from("<H", row_payload, offset * 2)[0]
                    for offset in range(min(8, len(row_payload) // 2))
                ],
                "u32_words_sample": _hkx_first_u32_words(row_payload, 4),
                "raw_hex": _hkx_payload_hex(row_payload),
                "description": (
                    "Read-only 32-byte candidate hknpAabb8TreeNode. Bytes appear to contain quantized bounds "
                    "and child/primitive links, but the exact layout is still being recovered."
                ),
            }
        )
    analysis = {
        "status": "read_only_aabb8_candidate_analysis",
        "candidate_stride_bytes": candidate_stride,
        "candidate_node_count": usable_count,
        "declared_record_count": int(record_count),
        "payload_byte_length": len(payload),
        "unparsed_tail_bytes": max(0, len(payload) - usable_count * candidate_stride),
        "count_matches_declared": usable_count == int(record_count),
        "description": (
            "AABB tree data is segmented into 32-byte candidate nodes for inspection. Count mismatches are "
            "reported because Havok may include padding or compact tree metadata outside the recovered node rows."
        ),
    }
    return nodes, analysis, int(analysis["unparsed_tail_bytes"])


def _hkx_export_mesh_shape_details_document(
    data: bytes,
    spans: Mapping[int, Tuple[int, int]],
    records: Sequence[HkxItemRecord],
    shape_record: Optional[HkxItemRecord],
) -> Optional[Dict[str, object]]:
    mesh_records = [record for record in records if record.type_name == "hknpMeshShape"]
    section_records = [record for record in records if record.type_name == "hknpMeshShape::GeometrySection"]
    primitive_records = [record for record in records if record.type_name == "hknpMeshShape::GeometrySection::Primitive"]
    aabb_records = [record for record in records if record.type_name == "hknpAabb8TreeNode"]
    shape_tag_records = [record for record in records if record.type_name == "hknpMeshShape::ShapeTagTableEntry"]
    byte_records = [record for record in records if record.type_name == "hkUint8"]
    if not any((mesh_records, section_records, primitive_records, aabb_records, shape_tag_records, byte_records)):
        return None

    details: Dict[str, object] = {
        "status": "read_only_schema_recovery",
        "warning": (
            "Mesh-shape topology is exported for inspection only. Primitive words, geometry-section fields, "
            "AABB nodes, and byte buffers are preserved exactly. Only topology-preserving primitive tuple winding "
            "edits are supported until the Havok 2024.2 mesh schema is recovered enough for full rebuilds."
        ),
        "descriptions": {
            "mesh_shape_records": "hknpMeshShape object payloads with raw bytes and candidate fixed fields.",
            "geometry_sections": "hknpMeshShape::GeometrySection records. Rows are usually fixed-size section descriptors.",
            "primitive_buffers": "hknpMeshShape::GeometrySection::Primitive packed primitive words. Triangle/quad encoding is not confirmed.",
            "aabb_tree_nodes": "hknpAabb8TreeNode acceleration-structure records. Values are likely quantized bounds/tree links.",
            "shape_tag_table": "hknpMeshShape::ShapeTagTableEntry rows, likely primitive/shape-tag ranges.",
            "mesh_byte_buffers": "hkUint8 byte buffers associated with mesh-shape data in files that contain hknpMeshShape.",
        },
        "records": {},
    }
    records_map: Dict[str, object] = {}

    mesh_shape_rows: List[Dict[str, object]] = []
    for record in mesh_records:
        payload = _hkx_payload_slice(data, spans, record)
        if not payload:
            continue
        row = _hkx_mesh_record_base(record, payload, "mesh_shape_object")
        row["u32_words_sample"] = _hkx_first_u32_words(payload, 24)
        row["finite_float_slots"] = _hkx_finite_float_slots_in_range(payload, 0, min(len(payload), 160), limit=16)
        if shape_record is not None and record.index == shape_record.index:
            row["selected_by_geometry_hint"] = True
        mesh_shape_rows.append(row)
    if mesh_shape_rows:
        details["mesh_shape_records"] = mesh_shape_rows
        records_map["mesh_shape_records"] = [row["record_index"] for row in mesh_shape_rows]

    section_rows: List[Dict[str, object]] = []
    for record in section_records:
        payload = _hkx_payload_slice(data, spans, record)
        if not payload:
            continue
        section_doc = _hkx_mesh_record_base(record, payload, "geometry_section_table")
        stride = section_doc.get("stride")
        rows: List[Dict[str, object]] = []
        if isinstance(stride, int) and stride >= 4:
            for index in range(min(record.count, 64)):
                base = index * stride
                row_payload = payload[base : base + stride]
                candidate_layout = _hkx_mesh_geometry_section_candidate_fields(row_payload)
                if candidate_layout:
                    _hkx_mesh_enrich_geometry_section_layout_targets(
                        candidate_layout,
                        records,
                        int(record.data_offset) + base,
                    )
                rows.append(
                    {
                        "index": index,
                        "u32_words_sample": _hkx_first_u32_words(row_payload, min(8, max(1, stride // 4))),
                        "finite_float_slots": _hkx_finite_float_slots_in_range(payload, base, stride, limit=8),
                        "raw_hex": _hkx_payload_hex(row_payload[:64]),
                        "candidate_layout": candidate_layout,
                    }
                )
        if record.count == 1 and payload and "candidate_layout" not in section_doc:
            candidate_layout = _hkx_mesh_geometry_section_candidate_fields(payload)
            if candidate_layout:
                _hkx_mesh_enrich_geometry_section_layout_targets(candidate_layout, records, int(record.data_offset))
            section_doc["candidate_layout"] = candidate_layout
        section_doc["rows"] = rows
        section_doc["truncated_rows"] = max(0, int(record.count) - len(rows))
        section_rows.append(section_doc)
    if section_rows:
        details["geometry_sections"] = section_rows
        records_map["geometry_sections"] = [row["record_index"] for row in section_rows]

    primitive_rows: List[Dict[str, object]] = []
    primitive_analysis_rows: List[Dict[str, object]] = []
    for record in primitive_records:
        payload = _hkx_payload_slice(data, spans, record)
        if not payload:
            continue
        primitive_doc = _hkx_mesh_record_base(record, payload, "primitive_packed_words")
        values, analysis, padding_length = _hkx_mesh_primitive_tuple_rows(payload, int(record.count))
        primitive_doc["primitive_words"] = values
        primitive_doc["truncated_primitives"] = max(0, int(record.count) - len(values))
        primitive_doc["padding_or_tail_bytes"] = padding_length
        primitive_doc["description"] = (
            "Packed mesh primitive descriptors exposed as four-byte tuple candidates. The exact topology/material "
            "layout is not confirmed, so these are read-only."
        )
        low_values = [int(value["low_u16"]) for value in values if isinstance(value.get("low_u16"), int)]
        high_values = [int(value["high_u16"]) for value in values if isinstance(value.get("high_u16"), int)]
        analysis["low_u16_min"] = min(low_values) if low_values else None
        analysis["low_u16_max"] = max(low_values) if low_values else None
        analysis["low_u16_unique_count"] = len(set(low_values))
        analysis["high_u16_min"] = min(high_values) if high_values else None
        analysis["high_u16_max"] = max(high_values) if high_values else None
        analysis["high_u16_unique_count"] = len(set(high_values))
        primitive_doc["analysis"] = analysis
        primitive_analysis_rows.append(
            {
                "record_index": record.index,
                "count": len(values),
                "low_u16_unique_count": len(set(low_values)),
                "high_u16_unique_count": len(set(high_values)),
                "candidate_index_range": analysis.get("candidate_index_range") or [],
                "candidate_index_unique_count": analysis.get("candidate_index_unique_count"),
                "candidate_triangle_count": analysis.get("candidate_triangle_count"),
                "candidate_quad_count": analysis.get("candidate_quad_count"),
                "candidate_degenerate_count": analysis.get("candidate_degenerate_count"),
                "topology_candidate_status": analysis.get("topology_candidate_status"),
            }
        )
        primitive_rows.append(primitive_doc)
    if primitive_rows:
        details["primitive_buffers"] = primitive_rows
        records_map["primitive_buffers"] = [row["record_index"] for row in primitive_rows]

    aabb_rows: List[Dict[str, object]] = []
    for record in aabb_records:
        payload = _hkx_payload_slice(data, spans, record)
        if not payload:
            continue
        aabb_doc = _hkx_mesh_record_base(record, payload, "aabb8_tree_nodes")
        stride = aabb_doc.get("stride")
        nodes: List[Dict[str, object]] = []
        if isinstance(stride, int) and stride >= 8:
            for index in range(min(int(record.count), 64)):
                base = index * stride
                row_payload = payload[base : base + stride]
                nodes.append(
                    {
                        "index": index,
                        "u16_words_sample": [
                            struct.unpack_from("<H", row_payload, offset * 2)[0]
                            for offset in range(min(8, len(row_payload) // 2))
                        ],
                        "u32_words_sample": _hkx_first_u32_words(row_payload, min(4, max(1, stride // 4))),
                        "raw_hex": _hkx_payload_hex(row_payload[:64]),
                    }
                )
        if not nodes:
            nodes, analysis, _tail_bytes = _hkx_mesh_aabb8_node_rows(payload, int(record.count))
            aabb_doc["analysis"] = analysis
            aabb_doc["candidate_stride"] = analysis.get("candidate_stride_bytes")
        else:
            aabb_doc["analysis"] = {
                "status": "read_only_aabb8_stride_from_record_count",
                "candidate_stride_bytes": stride,
                "candidate_node_count": len(nodes),
                "declared_record_count": int(record.count),
                "payload_byte_length": len(payload),
            }
        aabb_doc["nodes"] = nodes
        aabb_doc["truncated_nodes"] = max(0, int(record.count) - len(nodes))
        aabb_rows.append(aabb_doc)
    if aabb_rows:
        details["aabb_tree_nodes"] = aabb_rows
        records_map["aabb_tree_nodes"] = [row["record_index"] for row in aabb_rows]

    shape_tag_rows: List[Dict[str, object]] = []
    for record in shape_tag_records:
        payload = _hkx_payload_slice(data, spans, record)
        if not payload:
            continue
        tag_doc = _hkx_mesh_record_base(record, payload, "shape_tag_table")
        stride = tag_doc.get("stride")
        rows = []
        if isinstance(stride, int) and stride >= 4:
            for index in range(min(int(record.count), 128)):
                base = index * stride
                row_payload = payload[base : base + stride]
                rows.append(
                    {
                        "index": index,
                        "u32_words": _hkx_first_u32_words(row_payload, min(4, max(1, stride // 4))),
                        "raw_hex": _hkx_payload_hex(row_payload[:32]),
                    }
                )
        tag_doc["entries"] = rows
        tag_doc["truncated_entries"] = max(0, int(record.count) - len(rows))
        shape_tag_rows.append(tag_doc)
    if shape_tag_rows:
        details["shape_tag_table"] = shape_tag_rows
        records_map["shape_tag_table"] = [row["record_index"] for row in shape_tag_rows]

    byte_buffer_rows: List[Dict[str, object]] = []
    for record in byte_records[:32]:
        payload = _hkx_payload_slice(data, spans, record, min(max(0, int(record.count)), 4096))
        if not payload:
            continue
        byte_doc = _hkx_mesh_record_base(record, payload, "mesh_related_byte_buffer")
        byte_doc["unique_value_count"] = len(set(payload))
        byte_doc["values_sample"] = list(payload[:128])
        byte_doc["truncated_values"] = max(0, int(record.count) - len(byte_doc["values_sample"]))
        byte_buffer_rows.append(byte_doc)
    if byte_buffer_rows:
        details["mesh_byte_buffers"] = byte_buffer_rows
        records_map["mesh_byte_buffers"] = [row["record_index"] for row in byte_buffer_rows]

    if records_map:
        details["records"] = records_map
    details["editability"] = {
        "editable": False,
        "status": "blocked_until_mesh_schema_recovered",
        "supported_safe_operations": [
            "primitive tuple winding/order edits where each primitive keeps the exact same vertex-index set",
        ],
        "blocked_operations": [
            "changing primitive count",
            "changing triangle/quad topology",
            "editing primitive tuple vertex sets",
            "changing AABB tree nodes",
            "changing mesh byte-buffer lengths",
            "changing shape-tag ranges",
        ],
        "safe_current_behavior": (
            "export/browser plus no-edit byte preservation; primitive tuple winding edits are applied only when "
            "each tuple keeps the same indices and sentinel count"
        ),
        "next_decoder_targets": [
            "geometry section header fields",
            "primitive packed bit layout",
            "shape tag range semantics",
            "AABB tree node quantization",
            "byte-buffer role mapping",
        ],
    }
    if primitive_analysis_rows:
        details["primitive_analysis_summary"] = primitive_analysis_rows
    return details


def _hkx_schema_observation_document(summary: HkxTagfileSummary) -> Dict[str, object]:
    records_by_index = {record.index: record for record in summary.item_records}
    payload_summaries: List[Dict[str, object]] = []
    for payload_summary in summary.item_payload_summaries:
        record = records_by_index.get(payload_summary.record_index)
        payload_summaries.append(
            {
                "record_index": payload_summary.record_index,
                "type_index": record.type_index if record is not None else None,
                "type_name": payload_summary.type_name,
                "count": record.count if record is not None else None,
                "data_offset": record.data_offset if record is not None else None,
                "byte_length": payload_summary.byte_length,
                "inferred_stride": payload_summary.inferred_stride,
                "lines": list(payload_summary.lines),
            }
        )
    return {
        "status": "read_only_research",
        "description": (
            "Decoded and inferred tagfile structure. These values are exported for schema recovery and comparison "
            "against multiple HKX files; the importer ignores this section."
        ),
        "type_table": [
            {
                "index": type_info.index,
                "name": type_info.name,
                "display_name": type_info.display_name,
                "template_parameters": [
                    {"name": name, "value": value}
                    for name, value in type_info.template_parameters
                ],
            }
            for type_info in summary.type_infos
        ],
        "record_payload_summaries": payload_summaries,
    }


def _hkx_record_role_description(type_name: str) -> str:
    if type_name == "hkFloat3":
        return "Array of three-float vectors. In decoded convex shapes this is usually local-space vertex positions."
    if type_name == "hkVector4":
        return "Array of four-float vectors. In decoded convex shapes this is usually hull plane equations."
    if type_name == "hknpConvexHull::Face":
        return "Convex-hull face table. Each record stores an index-buffer start, vertex count, and metadata byte."
    if type_name == "hkUint8":
        return "Byte array. In decoded convex hulls this is usually the face vertex index buffer."
    if type_name in _HKX_SCALAR_ARRAY_TYPES:
        return _HKX_SCALAR_ARRAY_TYPES[type_name][4]
    if type_name in _HKX_ENUM_RECORD_TYPES:
        return _HKX_ENUM_RECORD_TYPES[type_name] + " Exported read-only until the owning object schema is confirmed."
    if type_name == "hknpConvexHull::Edge":
        return "Convex-hull edge/support table. The exact 2024.2 field meaning is still unverified."
    if type_name == "hknpConvexShape":
        return "Fixed-size convex shape object. It references hull data arrays and contains unverified shape settings."
    if type_name == "hknpShapeMassProperties":
        return "Shape mass-property payload. Exported as four unverified float4 rows for fixed-size edits."
    if type_name == "hkCompressedMassProperties":
        return "Compressed mass-property payload. Exported as read-only packed words and finite-float candidates until the exact Havok 2024.2 schema is recovered."
    if type_name == "hkPackedVector3":
        return "Packed vector array. Exported as read-only quantized byte/word rows; edit support requires recovering the packing scale and owning field."
    if type_name == "hknpShapeProperties::Entry":
        return "Shape property entry. Likely stores material/filter/property metadata; exact fields are not recovered yet."
    if type_name == "hknpCompoundShape":
        return "Compound shape object. It groups child shape instances and tree/free-list data."
    if type_name == "hknpShapeInstance":
        return "Child shape instance payload. It likely links a child shape with transform/filter metadata."
    if type_name == "hknpRagdollData":
        return "Ragdoll container data. It groups physics bodies, constraints, skeleton mapping, and runtime ragdoll metadata."
    if type_name == "hkRootLevelContainer":
        return "Root Havok object container. It usually points to named variants that identify the primary scene/system object."
    if type_name == "hkRootLevelContainer::NamedVariant":
        return "Root named variant entry. It likely links a name, class name, and root object reference."
    if type_name == "hkRefVariant":
        return "Variant reference wrapper. Usually stores a reference to an arbitrary Havok object plus type/context metadata."
    if type_name == "hkStringPtr":
        return "Havok string pointer/reference. Usually references a char record or string data."
    if type_name == "hkMemoryResourceContainer":
        return "Memory/resource container. Exported read-only as reference/count pairs; structural resource edits are not supported."
    if type_name == "hknpPhysicsSceneData":
        return "Physics scene data container. It likely groups one or more hknp physics systems and scene-level metadata."
    if type_name == "hknpPhysicsSystemData":
        return "Physics system container. It likely groups materials, motion properties, bodies, constraints, and shape references."
    if type_name == "hknpPhysicsSystemData::ExtendedBodyCinfo":
        return "Physics body construction info. Likely stores body transform, motion/material references, mass-like values, and flags."
    if type_name == "hknpConstraintCinfo":
        return "Constraint construction info. Likely links two bodies with one constraint-data record."
    if type_name == "hknpConstraintData":
        return "Base/variant constraint data record. Concrete constraint layouts may be referenced from nearby records."
    if type_name == "hknpRagdollConstraintData":
        return "Ragdoll joint constraint data. Likely contains joint frames, angular limits, tau/damping-like values, and motors."
    if type_name == "hknpLimitedHingeConstraintData":
        return "Limited hinge joint data. Likely contains hinge frames, angular limits, and motor/damping-like values."
    if type_name == "hknpWheelConstraintData":
        return "Wheel constraint data. Corpus samples show vehicle/wagon files use this heavily; exported read-only as joint-frame and tuning float candidates."
    if type_name == "hknpFixedConstraintData":
        return "Fixed constraint data. Likely stores locked body frames and strength/tau-like tuning; exported read-only until exact fields are confirmed."
    if type_name == "hknpBreakableConstraintData":
        return "Breakable constraint data. Likely stores constraint frames plus break threshold/strength metadata; exported read-only until safe edit rules are known."
    if type_name == "hknpPositionConstraintMotor":
        return "Constraint motor data. Float slots include very likely min/max force and strength/damping-like values."
    if type_name == "hknpSharedMotionProperties":
        return "Shared body motion settings. Likely contains damping, gravity/factor, solver, velocity, and motion tuning values."
    if type_name == "hknpRefDragProperties":
        return "Reference drag-properties payload. Likely stores damping/drag-related tuning for body motion."
    if type_name == "hknpRefMassDistribution":
        return "Reference mass-distribution payload. Likely stores mass/inertia distribution tuning for body motion."
    if type_name == "hknpCylinderShape":
        return "Cylinder collision shape. Corpus vehicle samples use these for wheel/axle-like collision; exported read-only as radius/axis candidates."
    if type_name in {"hknpAabb8TreeNode", "hknpMeshShape::GeometrySection", "hknpMeshShape::GeometrySection::Primitive", "hknpMeshShape::ShapeTagTableEntry"}:
        return "Mesh-shape acceleration/table payload. Rows are separated for schema recovery; topology and AABB rebuilds are not supported yet."
    if type_name == "hkcdSimdTreeNamespace::Node":
        return "Spatial tree node payload used by compound/mesh acceleration structures."
    if type_name == "hkMatrix4":
        return "Read-only 4x4 matrix rows. Commonly used by hkx scene/mesh metadata; editing is disabled until owner semantics are recovered."
    if type_name.startswith("hkx"):
        return "Havok scene/mesh/animation metadata payload. Exported read-only as structured samples for browsing and schema recovery."
    if type_name.startswith("hkArray"):
        return "Havok array-like header. Values may include data references, size, capacity, and flags."
    if type_name.startswith("hkRefPtr"):
        return "Havok reference pointer-like payload. Values may point to another object record."
    if type_name.startswith("hknp"):
        return "Modern Havok Physics object payload. Field layout is partially recovered only."
    return "Decoded ITEM payload. Type-specific Havok 2024.2 field names are not recovered yet."


def _hkx_payload_hex(payload: bytes) -> str:
    return payload.hex(" ")


def _hkx_decode_char_payload_text(payload: bytes, count: int) -> str:
    sample = payload[: max(0, min(len(payload), int(count) if count > 0 else len(payload)))]
    if b"\0" in sample:
        sample = sample.split(b"\0", 1)[0]
    try:
        text = sample.decode("utf-8", errors="replace").strip()
    except Exception:
        text = ""
    if not text:
        return ""
    printable_count = sum(1 for char in text if char.isprintable())
    if printable_count < max(1, len(text) * 3 // 4):
        return ""
    return text


def _hkx_parse_payload_hex(value: object, *, name: str) -> bytes:
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a hex string.")
    compact = re.sub(r"[^0-9A-Fa-f]", "", value)
    if len(compact) % 2:
        raise ValueError(f"{name} must contain an even number of hex digits.")
    try:
        return bytes.fromhex(compact)
    except ValueError as exc:
        raise ValueError(f"{name} contains invalid hex.") from exc


def _hkx_record_status_from_payload(payload_info: Mapping[str, object]) -> Tuple[str, str]:
    type_name = str(payload_info.get("type_name") or "")
    editable_values = payload_info.get("editable_values")
    interpretation = payload_info.get("interpretation")
    layout = payload_info.get("layout")
    if isinstance(editable_values, Mapping):
        kind = str(editable_values.get("kind") or "")
        if kind in {"float3_rows", "float4_rows", "face_records", "byte_values", "uint16_pairs"}:
            return "editable", "strong inference"
        if kind == "fixed_float_slots":
            return "editable", "experimental"
        return "editable", "experimental"
    if type_name in {
        "hkFloat3",
        "hkVector4",
        "hknpConvexHull::Face",
        "hkUint8",
        "hknpConvexHull::Edge",
    }:
        return "decoded", "strong inference"
    if type_name.startswith("hkArray") or type_name.startswith("hkRefPtr"):
        return "partially_decoded", "experimental"
    if isinstance(interpretation, Mapping):
        decoded_keys = set(interpretation) - {"role", "field_status", "u32_words_sample", "possible_internal_links"}
        if decoded_keys:
            return "partially_decoded", "experimental"
    if isinstance(layout, Mapping):
        fields = layout.get("fields")
        if isinstance(fields, list) and fields:
            if any(isinstance(field, Mapping) and field.get("editable") is True for field in fields):
                return "editable", "experimental"
            if any(isinstance(field, Mapping) and str(field.get("confidence") or "") != "raw" for field in fields):
                return "partially_decoded", "experimental"
    return "raw_preserved", "raw"


def _hkx_missing_decoder_requirements_for_type(type_name: str) -> Tuple[str, str, List[str]]:
    normalized = str(type_name or "")
    if normalized.startswith("hkArray"):
        return (
            "array_owner_context",
            "Array header is readable, but the owning Havok member still decides the real element type.",
            [
                "owner-field array mapping",
                "element template/class metadata",
                "fixup-backed data pointer semantics",
                "rebuild-safe count/capacity rules",
            ],
        )
    if normalized.startswith("hkRefPtr") or normalized.startswith("hkRelPtr"):
        return (
            "reference_pointer_context",
            "Reference storage is readable, but exact Havok reference semantics still need fixup-backed class context.",
            [
                "PTCH/fixup-backed target classification",
                "null/data/string/type reference distinction",
                "target class member metadata",
            ],
        )
    if normalized.startswith("hkFreeListArrayElement"):
        return (
            "free_list_entry_context",
            "Free-list entry storage is isolated, but owner semantics and mutation rules are not recovered.",
            [
                "owning array/member metadata",
                "entry lifetime/free-list flags",
                "safe fixed-size write rules",
            ],
        )
    if normalized in {"hknpTriangleShape", "hknpLodShape"}:
        return (
            "shape_internals",
            "Shape payload is identified, but exact child/triangle/LOD member layout is not fully decoded.",
            [
                "shape-specific hkClass member metadata",
                "child shape/material/tag references",
                "triangle or LOD payload field mapping",
                "safe fixed-size write rules",
            ],
        )
    mesh_shape_types = {
        "hknpMeshShape",
        "hknpMeshShape::GeometrySection",
        "hknpMeshShape::GeometrySection::Primitive",
        "hknpMeshShape::ShapeTagTableEntry",
        "hknpAabb8TreeNode",
        "hkcdStaticMeshTree::Section",
        "hknpLegacyCompressedMeshShape",
        "hknpLegacyCompressedMeshShape::MeshData",
    }
    if normalized in mesh_shape_types:
        return (
            "mesh_shape_internals",
            "Mesh-shape rows are separated for browsing, but the topology/tree payload is not fully decoded.",
            [
                "mesh primitive bit layout",
                "AABB tree node encoding",
                "shape tag range/table semantics",
                "mesh byte-buffer ownership",
            ],
        )
    if normalized in {"hknpShapeMassProperties", "hkCompressedMassProperties"}:
        return (
            "compressed_mass_properties",
            "Mass/inertia values are preserved and sampled, but packed Havok mass-property semantics are incomplete.",
            [
                "compressed mass scale/basis decoding",
                "inertia tensor field mapping",
                "owner shape/body semantics",
            ],
        )
    if normalized in {"hknpMaterial", "hknpShapeProperties::Entry"}:
        return (
            "material_property_entries",
            "Material/property payloads are browsable, but flags and property table ownership are still inferred.",
            [
                "material member metadata",
                "property key/value semantics",
                "free-list/property entry ownership",
            ],
        )
    if normalized in {
        "hknpPhysicsSystemData",
        "hknpPhysicsSystemData::ExtendedBodyCinfo",
        "hknpConstraintCinfo",
        "hknpConstraintData",
        "hknpBallAndSocketConstraintData",
        "hknpHingeConstraintData",
        "hknpRagdollConstraintData",
        "hknpLimitedHingeConstraintData",
        "hknpWheelConstraintData",
        "hknpFixedConstraintData",
        "hknpBreakableConstraintData",
        "hknpSharedMotionProperties",
        "hknpPositionConstraintMotor",
        "hknpVelocityConstraintMotor",
    }:
        return (
            "physics_class_members",
            "Physics class payload has useful recovered values, but real hkClass member metadata is still synthetic.",
            [
                "real member type codes/flags/offsets",
                "base class and enum references",
                "owner-array type mapping",
                "template/default/version/signature metadata",
            ],
        )
    if normalized in {"hkRootLevelContainer", "hkRootLevelContainer::NamedVariant", "hkRefVariant"}:
        return (
            "root_container_semantics",
            "Root/container records are recognized, but full NamedVariant semantics are still being recovered.",
            [
                "name string reference",
                "class string/type reference",
                "variant object reference",
                "nested scene/system/ragdoll/animation root ordering",
            ],
        )
    if normalized.startswith(("hka", "hkx")) or "Animation" in normalized or "Skeleton" in normalized:
        return (
            "skeleton_animation_containers",
            "Animation/skeleton metadata is browsable, but container tables are not fully mapped.",
            [
                "skeleton/animation owner arrays",
                "clip/track table semantics",
                "string/path reference ownership",
                "safe no-edit rebuild proof",
            ],
        )
    if normalized.startswith("hknp"):
        return (
            "havok_physics_member_layout",
            "Modern Havok Physics object payload is partially recovered but not fully mapped to hkClass members.",
            [
                "real hkClass member metadata",
                "field names/types/offsets",
                "reference and array owner context",
            ],
        )
    return (
        "unknown_havok_member_layout",
        "Payload bytes are preserved, but the class/member layout is not recovered enough for named Havok XML.",
        [
            "real hkClass metadata",
            "field names/types/offsets",
            "reference/array semantics",
        ],
    )


def _hkx_decode_state_from_payload(payload_info: Mapping[str, object], status: str, confidence: str) -> Dict[str, object]:
    type_name = str(payload_info.get("type_name") or "")
    if status == "editable":
        return {
            "status_label": "Patchable value",
            "decode_category": "fixed_size_patchable_value",
            "status_reason": "A fixed-size value location is mapped and can be patched without changing HKX structure.",
            "missing_requirements": [
                "byte-identical native no-edit writer before Havok XML import",
                "real hkClass metadata for official Havok member naming",
            ],
        }
    if status == "decoded":
        return {
            "status_label": "Decoded value rows",
            "decode_category": "decoded_value_table",
            "status_reason": "The payload is decoded into stable row values for browsing/export.",
            "missing_requirements": [
                "owner hkClass metadata for exact official member names",
                "native no-edit writer before import beyond CDMW fixed-size patches",
            ],
        }
    if status == "partially_decoded":
        category, reason, missing = _hkx_missing_decoder_requirements_for_type(type_name)
        return {
            "status_label": "Readable, not fully mapped",
            "decode_category": category,
            "status_reason": reason,
            "missing_requirements": missing,
        }
    category, reason, missing = _hkx_missing_decoder_requirements_for_type(type_name)
    raw_reason = "No stable structured decode is available yet; bytes are preserved for safe roundtrip/export."
    if confidence and str(confidence).lower() != "raw":
        raw_reason = reason
    return {
        "status_label": "Raw preserved",
        "decode_category": category,
        "status_reason": raw_reason,
        "missing_requirements": missing,
    }


def _hkx_converter_record_document(payload_info: Mapping[str, object]) -> Dict[str, object]:
    status, confidence = _hkx_record_status_from_payload(payload_info)
    decode_state = _hkx_decode_state_from_payload(payload_info, status, confidence)
    interpretation = payload_info.get("interpretation")
    decoded_fields: Dict[str, object] = {}
    references: List[object] = []
    if isinstance(interpretation, Mapping):
        for key, value in interpretation.items():
            if key in {"role", "field_status", "u32_words_sample", "possible_internal_links", "possible_record_references"}:
                continue
            decoded_fields[str(key)] = value
        link_documents = interpretation.get("possible_record_references")
        if isinstance(link_documents, list):
            references = [dict(link) for link in link_documents if isinstance(link, Mapping)]
        links = interpretation.get("possible_internal_links")
        if isinstance(links, list):
            if references:
                decoded_fields["legacy_reference_summary"] = [str(link) for link in links]
            else:
                references = [str(link) for link in links]
    layout = payload_info.get("layout")
    if isinstance(layout, Mapping):
        layout_fields = layout.get("fields")
        if isinstance(layout_fields, list):
            decoded_fields["layout_field_count"] = len(layout_fields)
        layout_references = layout.get("references")
        if isinstance(layout_references, list):
            seen_reference_keys = {
                (
                    reference.get("offset"),
                    reference.get("target_record_index"),
                    reference.get("reference_kind"),
                )
                for reference in references
                if isinstance(reference, Mapping)
            }
            for reference in layout_references:
                if not isinstance(reference, Mapping):
                    continue
                reference_key = (
                    reference.get("offset"),
                    reference.get("target_record_index"),
                    reference.get("reference_kind"),
                )
                if reference_key in seen_reference_keys:
                    continue
                seen_reference_keys.add(reference_key)
                references.append(dict(reference))
    return {
        "record_index": payload_info.get("record_index"),
        "type_index": payload_info.get("type_index"),
        "type_name": payload_info.get("type_name"),
        "count": payload_info.get("count"),
        "data_offset": payload_info.get("data_offset"),
        "absolute_data_offset": payload_info.get("absolute_data_offset"),
        "byte_length": payload_info.get("byte_length"),
        "status": status,
        "confidence": confidence,
        **decode_state,
        "description": payload_info.get("description", ""),
        "decoded_fields": decoded_fields,
        "references": references,
        "layout": payload_info.get("layout"),
        "raw_ranges": payload_info.get("raw_ranges"),
        "editable_values": payload_info.get("editable_values"),
    }


def _hkx_editable_value_count(value: object) -> int:
    if not isinstance(value, Mapping):
        return 0
    kind = str(value.get("kind") or "")
    if kind in {"float3_rows", "float4_rows"}:
        rows = value.get("rows")
        if isinstance(rows, list):
            return sum(len(row) for row in rows if isinstance(row, list))
    if kind == "face_records":
        records = value.get("records")
        if isinstance(records, list):
            return len(records) * 3
    if kind == "byte_values":
        values = value.get("values")
        return len(values) if isinstance(values, list) else 0
    if kind == "uint16_pairs":
        pairs = value.get("pairs")
        if isinstance(pairs, list):
            return len(pairs) * 2
    if kind == "fixed_float_slots":
        items = value.get("items")
        if not isinstance(items, list):
            return 0
        return sum(
            len(item.get("float_slots", []))
            for item in items
            if isinstance(item, Mapping) and isinstance(item.get("float_slots"), list)
        )
    return 0


def _hkx_compatibility_status_from_counts(
    *,
    sdk_version: str,
    item_record_count: int,
    payload_record_count: int,
    size_matches: bool,
    editable_target_count: int,
    preview_linked_target_count: int,
) -> str:
    if sdk_version != "20240200" or item_record_count <= 0:
        return "unsupported"
    if not size_matches or payload_record_count <= 0:
        return "inspectable"
    if preview_linked_target_count > 0 and editable_target_count > 0:
        return "preview_linked"
    if editable_target_count > 0:
        return "value_editable"
    if payload_record_count >= item_record_count:
        return "roundtrip_safe"
    return "inspectable"


def _hkx_is_known_generic_container_type(type_name: str) -> bool:
    return (
        type_name.startswith("hkArray")
        or type_name.startswith("hkRefPtr")
        or type_name.startswith("hkFreeListArrayElement")
    )


def _hkx_converter_report_document(
    data: bytes,
    summary: HkxTagfileSummary,
    advanced_payloads: Sequence[Mapping[str, object]],
) -> Dict[str, object]:
    record_status_counts: Counter[str] = Counter()
    type_coverage: Dict[str, Dict[str, object]] = {}
    editable_record_count = 0
    decoded_or_partial_count = 0
    decoded_field_count = 0
    editable_slot_count = 0
    raw_preserved_byte_count = 0
    typed_layout_byte_count = 0
    candidate_layout_byte_count = 0
    unresolved_layout_byte_count = 0
    reference_candidate_count = 0
    records: List[Dict[str, object]] = []
    payloads_by_record = {
        int(payload.get("record_index")): payload
        for payload in advanced_payloads
        if isinstance(payload.get("record_index"), int)
    }
    for record in summary.item_records:
        payload_info = payloads_by_record.get(record.index)
        if payload_info is None:
            status, confidence = "raw_preserved", "raw"
            byte_length = None
            decode_state = _hkx_decode_state_from_payload({"type_name": record.type_name}, status, confidence)
        else:
            status, confidence = _hkx_record_status_from_payload(payload_info)
            byte_length = payload_info.get("byte_length")
            decode_state = _hkx_decode_state_from_payload(payload_info, status, confidence)
        try:
            record_byte_length = int(byte_length) if byte_length is not None else 0
        except (TypeError, ValueError, OverflowError):
            record_byte_length = 0
        decoded_fields = payload_info.get("decoded_fields") if isinstance(payload_info, Mapping) else None
        if not isinstance(decoded_fields, (Mapping, list)) and isinstance(payload_info, Mapping):
            interpretation = payload_info.get("interpretation")
            if isinstance(interpretation, Mapping):
                decoded_fields = {
                    str(key): value
                    for key, value in interpretation.items()
                    if key not in {"role", "field_status", "u32_words_sample", "possible_internal_links", "possible_record_references"}
                }
        references = payload_info.get("references") if isinstance(payload_info, Mapping) else None
        if not isinstance(references, list) and isinstance(payload_info, Mapping):
            payload_layout = payload_info.get("layout")
            layout_references = payload_layout.get("references") if isinstance(payload_layout, Mapping) else None
            references = layout_references if isinstance(layout_references, list) else None
        editable_values = payload_info.get("editable_values") if isinstance(payload_info, Mapping) else None
        layout = payload_info.get("layout") if isinstance(payload_info, Mapping) else None
        byte_coverage = layout.get("byte_coverage") if isinstance(layout, Mapping) else None
        typed_bytes = int(byte_coverage.get("typed_byte_count") or 0) if isinstance(byte_coverage, Mapping) else 0
        candidate_bytes = int(byte_coverage.get("candidate_byte_count") or 0) if isinstance(byte_coverage, Mapping) else 0
        unresolved_bytes = (
            int(byte_coverage.get("unresolved_byte_count") or 0)
            if isinstance(byte_coverage, Mapping)
            else record_byte_length
        )
        decoded_field_len = (
            len(decoded_fields)
            if isinstance(decoded_fields, Mapping)
            else len(decoded_fields) if isinstance(decoded_fields, list) else 0
        )
        reference_len = len(references) if isinstance(references, list) else 0
        editable_len = _hkx_editable_value_count(editable_values)
        decoded_field_count += decoded_field_len
        reference_candidate_count += reference_len
        editable_slot_count += editable_len
        typed_layout_byte_count += typed_bytes
        candidate_layout_byte_count += candidate_bytes
        unresolved_layout_byte_count += unresolved_bytes
        if status == "raw_preserved":
            raw_preserved_byte_count += record_byte_length
        coverage = type_coverage.setdefault(
            record.type_name,
            {
                "type_name": record.type_name,
                "record_count": 0,
                "byte_length": 0,
                "decoded_field_count": 0,
                "editable_slot_count": 0,
                "reference_candidate_count": 0,
                "raw_preserved_byte_count": 0,
                "typed_layout_byte_count": 0,
                "candidate_layout_byte_count": 0,
                "unresolved_layout_byte_count": 0,
                "status_counts": Counter(),
            },
        )
        coverage["record_count"] = int(coverage["record_count"]) + 1
        coverage["byte_length"] = int(coverage["byte_length"]) + record_byte_length
        coverage["decoded_field_count"] = int(coverage["decoded_field_count"]) + decoded_field_len
        coverage["editable_slot_count"] = int(coverage["editable_slot_count"]) + editable_len
        coverage["reference_candidate_count"] = int(coverage["reference_candidate_count"]) + reference_len
        coverage["typed_layout_byte_count"] = int(coverage["typed_layout_byte_count"]) + typed_bytes
        coverage["candidate_layout_byte_count"] = int(coverage["candidate_layout_byte_count"]) + candidate_bytes
        coverage["unresolved_layout_byte_count"] = int(coverage["unresolved_layout_byte_count"]) + unresolved_bytes
        if status == "raw_preserved":
            coverage["raw_preserved_byte_count"] = int(coverage["raw_preserved_byte_count"]) + record_byte_length
        coverage_status_counts = coverage["status_counts"]
        if isinstance(coverage_status_counts, Counter):
            coverage_status_counts[status] += 1
        record_status_counts[status] += 1
        if status == "editable":
            editable_record_count += 1
            decoded_or_partial_count += 1
        elif status in {"decoded", "partially_decoded"}:
            decoded_or_partial_count += 1
        records.append(
            {
                "record_index": record.index,
                "type_index": record.type_index,
                "type_name": record.type_name,
                "count": record.count,
                "data_offset": record.data_offset,
                "absolute_data_offset": record.absolute_data_offset,
                "byte_length": byte_length,
                "status": status,
                "confidence": confidence,
                "byte_coverage": dict(byte_coverage) if isinstance(byte_coverage, Mapping) else {},
                "coverage_basis": str(layout.get("coverage_basis") or "") if isinstance(layout, Mapping) else "",
                **decode_state,
            }
        )
    total_records = len(summary.item_records)
    decoded_coverage = float(decoded_or_partial_count / total_records) if total_records else 0.0
    payload_record_coverage = float(len(payloads_by_record) / total_records) if total_records else 0.0
    cdmw_status = _hkx_compatibility_status_from_counts(
        sdk_version=summary.sdk_version,
        item_record_count=total_records,
        payload_record_count=len(payloads_by_record),
        size_matches=summary.size_matches,
        editable_target_count=editable_slot_count,
        preview_linked_target_count=0,
    )
    type_coverage_rows: List[Dict[str, object]] = []
    for row in type_coverage.values():
        status_counter = row.get("status_counts")
        row_copy = dict(row)
        row_copy["status_counts"] = dict(sorted(status_counter.items())) if isinstance(status_counter, Counter) else {}
        type_coverage_rows.append(row_copy)
    type_coverage_rows.sort(key=lambda row: (-int(row.get("byte_length") or 0), str(row.get("type_name") or "")))
    coverage_by_type_name = {str(row.get("type_name") or ""): row for row in type_coverage_rows}
    schema_target_coverage: List[Dict[str, object]] = []
    for type_name in _HKX_COMPATIBILITY_TARGET_TYPES:
        row = coverage_by_type_name.get(type_name)
        status_counts = row.get("status_counts") if isinstance(row, Mapping) else None
        record_count = int(row.get("record_count") or 0) if isinstance(row, Mapping) else 0
        editable_slots = int(row.get("editable_slot_count") or 0) if isinstance(row, Mapping) else 0
        raw_bytes = int(row.get("raw_preserved_byte_count") or 0) if isinstance(row, Mapping) else 0
        decoded_fields_for_type = int(row.get("decoded_field_count") or 0) if isinstance(row, Mapping) else 0
        typed_bytes = int(row.get("typed_layout_byte_count") or 0) if isinstance(row, Mapping) else 0
        candidate_bytes = int(row.get("candidate_layout_byte_count") or 0) if isinstance(row, Mapping) else 0
        unresolved_bytes = int(row.get("unresolved_layout_byte_count") or 0) if isinstance(row, Mapping) else 0
        schema_target_coverage.append(
            {
                "type_name": type_name,
                "present": record_count > 0,
                "record_count": record_count,
                "byte_length": int(row.get("byte_length") or 0) if isinstance(row, Mapping) else 0,
                "decoded_field_count": decoded_fields_for_type,
                "editable_slot_count": editable_slots,
                "raw_preserved_byte_count": raw_bytes,
                "typed_layout_byte_count": typed_bytes,
                "candidate_layout_byte_count": candidate_bytes,
                "unresolved_layout_byte_count": unresolved_bytes,
                "status_counts": dict(status_counts) if isinstance(status_counts, Mapping) else {},
                "coverage_status": (
                    "value_editable"
                    if editable_slots > 0
                    or type_name == "hknpShapeMassProperties"
                    or (isinstance(status_counts, Mapping) and int(status_counts.get("editable") or 0) > 0)
                    else "decoded"
                    if decoded_fields_for_type > 0 or (isinstance(status_counts, Mapping) and any(str(key) in {"decoded", "partially_decoded"} for key in status_counts))
                    else "raw_preserved"
                    if raw_bytes > 0
                    else "not_present"
                ),
            }
        )
    unresolved_rows: List[Tuple[Dict[str, object], int, str]] = []
    target_type_set = set(_HKX_COMPATIBILITY_TARGET_TYPES)
    for row in type_coverage_rows:
        type_name = str(row.get("type_name") or "")
        status_counts = row.get("status_counts")
        raw_bytes = int(row.get("raw_preserved_byte_count") or 0)
        byte_length = int(row.get("byte_length") or 0)
        editable_slots = int(row.get("editable_slot_count") or 0)
        if raw_bytes > 0:
            unresolved_rows.append((row, raw_bytes, "raw_preserved"))
        elif (
            type_name not in target_type_set
            and not _hkx_is_known_generic_container_type(type_name)
            and editable_slots <= 0
            and isinstance(status_counts, Mapping)
            and int(status_counts.get("partially_decoded") or 0) > 0
        ):
            unresolved_rows.append((row, byte_length, "partial_unknown_schema"))
    unresolved_rows.sort(key=lambda item: (-item[1], str(item[0].get("type_name") or "")))
    failed_unknown_rows: List[Dict[str, object]] = []
    total_unresolved_bytes = sum(byte_count for _row, byte_count, _reason in unresolved_rows)
    for rank, (row, unresolved_bytes, reason) in enumerate(unresolved_rows, start=1):
        type_name = str(row.get("type_name") or "")
        category, status_reason, missing_requirements = _hkx_missing_decoder_requirements_for_type(type_name)
        failed_unknown_rows.append(
            {
                "priority_rank": rank,
                "type_name": row.get("type_name"),
                "record_count": row.get("record_count"),
                "raw_preserved_byte_count": row.get("raw_preserved_byte_count"),
                "unresolved_byte_count": unresolved_bytes,
                "unresolved_reason": reason,
                "raw_preserved_byte_share": float(unresolved_bytes / total_unresolved_bytes) if total_unresolved_bytes else 0.0,
                "decode_category": category,
                "status_reason": status_reason,
                "missing_requirements": missing_requirements,
                "suggested_next_decoder_step": missing_requirements[0] if missing_requirements else "recover real hkClass metadata",
            }
        )
    return {
        "name": "Crimson Desert HKX converter report",
        "status": cdmw_status,
        "cdmw_hkx_compatibility_status": cdmw_status,
        "converter_format": "cdmw_crimson_desert_hkx_converter_v1",
        "sdk_version": summary.sdk_version,
        "sdk_label": _hkx_sdk_version_label(summary.sdk_version),
        "payload_size": len(data),
        "declared_size": summary.declared_size,
        "size_matches": summary.size_matches,
        "sections": [
            {
                "name": item.name,
                "offset": item.offset,
                "declared_length": item.declared_length,
                "flags": item.length_flags,
                "data_end": item.word_end_offset,
            }
            for item in summary.tag_items
        ],
        "type_count": len(summary.type_infos or summary.type_names),
        "item_record_count": total_records,
        "payload_record_count": len(payloads_by_record),
        "editable_record_count": editable_record_count,
        "decoded_or_partial_record_count": decoded_or_partial_count,
        "decoded_coverage": decoded_coverage,
        "payload_record_coverage": payload_record_coverage,
        "decoded_field_count": decoded_field_count,
        "editable_slot_count": editable_slot_count,
        "raw_preserved_byte_count": raw_preserved_byte_count,
        "typed_layout_byte_count": typed_layout_byte_count,
        "candidate_layout_byte_count": candidate_layout_byte_count,
        "unresolved_layout_byte_count": unresolved_layout_byte_count,
        "reference_candidate_count": reference_candidate_count,
        "record_status_counts": dict(sorted(record_status_counts.items())),
        "decode_coverage_by_type": type_coverage_rows,
        "schema_target_coverage": schema_target_coverage,
        "failed_or_unknown_schema_areas": failed_unknown_rows,
        "warnings": list(summary.warnings),
        "confidence": "strong inference" if summary.sdk_version == "20240200" and total_records else "experimental",
        "records": records,
    }


def _hkx_decode_gap_friendly_label(category: str, status: str) -> str:
    category_key = str(category or "").strip()
    if category_key == "mesh_shape_internals":
        return "Readable, missing mesh primitive layout"
    if category_key == "physics_class_members":
        return "Readable, missing real hkClass members"
    if category_key == "shape_internals":
        return "Readable, missing shape internals"
    if category_key == "material_property_entries":
        return "Readable, missing material/property names"
    if category_key == "compressed_mass_properties":
        return "Readable, missing compressed mass rules"
    if category_key == "array_owner_context":
        return "Readable, missing array owner type"
    if category_key == "reference_pointer_context":
        return "Readable, missing reference semantics"
    if category_key == "root_container_semantics":
        return "Readable, missing root container semantics"
    if category_key == "skeleton_animation_containers":
        return "Readable, missing skeleton/animation tables"
    if "raw" in str(status or "").casefold():
        return "Raw preserved, decoder needed"
    return "Readable, not fully mapped"


def _hkx_decode_gap_summary_document(
    converter_report: Mapping[str, object],
    decoder_evidence_v2: Optional[Mapping[str, object]] = None,
) -> Dict[str, object]:
    coverage_rows = converter_report.get("decode_coverage_by_type")
    if not isinstance(coverage_rows, list):
        coverage_rows = []
    gaps: List[Dict[str, object]] = []
    total_unresolved_bytes = 0
    total_partial_records = 0
    total_raw_records = 0
    for row in coverage_rows:
        if not isinstance(row, Mapping):
            continue
        type_name = str(row.get("type_name") or "")
        if not type_name:
            continue
        status_counts = row.get("status_counts")
        if not isinstance(status_counts, Mapping):
            status_counts = {}
        partial_records = int(status_counts.get("partially_decoded") or 0)
        raw_records = int(status_counts.get("raw_preserved") or status_counts.get("raw") or 0)
        editable_slots = int(row.get("editable_slot_count") or 0)
        raw_bytes = int(row.get("raw_preserved_byte_count") or 0)
        unresolved_bytes = int(row.get("unresolved_layout_byte_count") or 0)
        candidate_bytes = int(row.get("candidate_layout_byte_count") or 0)
        typed_bytes = int(row.get("typed_layout_byte_count") or 0)
        byte_length = int(row.get("byte_length") or 0)
        if raw_records <= 0 and partial_records <= 0:
            continue
        if editable_slots > 0 and unresolved_bytes <= 0 and raw_bytes <= 0:
            continue
        category, status_reason, missing_requirements = _hkx_missing_decoder_requirements_for_type(type_name)
        evidence_row: Optional[Mapping[str, object]] = None
        evidence_class_rows = (
            decoder_evidence_v2.get("class_statuses")
            if isinstance(decoder_evidence_v2, Mapping)
            else None
        )
        if isinstance(evidence_class_rows, list):
            found_evidence_row = next(
                (
                    item
                    for item in evidence_class_rows
                    if isinstance(item, Mapping) and str(item.get("type_name") or "") == type_name
                ),
                None,
            )
            if isinstance(found_evidence_row, Mapping):
                evidence_row = found_evidence_row
                evidence_missing = evidence_row.get("missing_requirements")
                if isinstance(evidence_missing, list) and evidence_missing:
                    missing_requirements = [str(value) for value in evidence_missing if str(value).strip()]
        unresolved_volume = raw_bytes or unresolved_bytes or max(0, byte_length - typed_bytes)
        if unresolved_volume <= 0 and partial_records > 0:
            unresolved_volume = candidate_bytes or byte_length
        gap_status = "raw_preserved" if raw_records and not partial_records else "partially_decoded" if partial_records and not raw_records else "mixed"
        total_unresolved_bytes += max(0, unresolved_volume)
        total_partial_records += partial_records
        total_raw_records += raw_records
        gaps.append(
            {
                "type_name": type_name,
                "record_count": int(row.get("record_count") or 0),
                "partial_record_count": partial_records,
                "raw_preserved_record_count": raw_records,
                "byte_length": byte_length,
                "typed_layout_byte_count": typed_bytes,
                "candidate_layout_byte_count": candidate_bytes,
                "unresolved_byte_count": unresolved_volume,
                "decoded_field_count": int(row.get("decoded_field_count") or 0),
                "editable_slot_count": editable_slots,
                "reference_candidate_count": int(row.get("reference_candidate_count") or 0),
                "decode_category": category,
                "status": gap_status,
                "friendly_status_label": (
                    str(evidence_row.get("friendly_status"))
                    if evidence_row is not None and evidence_row.get("friendly_status")
                    else _hkx_decode_gap_friendly_label(category, gap_status)
                ),
                "what_this_means": status_reason,
                "what_is_missing": "; ".join(str(value) for value in missing_requirements if str(value).strip()),
                "missing_requirements": missing_requirements,
                "suggested_next_decoder_step": missing_requirements[0] if missing_requirements else "recover real hkClass metadata",
                "safe_edit_policy": "read_only" if editable_slots <= 0 else "fixed_size_patch_only",
                "priority_score": unresolved_volume + candidate_bytes + partial_records * 256 + raw_records * 512,
            }
        )
    gaps.sort(
        key=lambda gap: (
            -int(gap.get("priority_score") or 0),
            -int(gap.get("unresolved_byte_count") or 0),
            str(gap.get("type_name") or ""),
        )
    )
    for rank, gap in enumerate(gaps, start=1):
        gap["priority_rank"] = rank
        gap["unresolved_byte_share"] = (
            float(int(gap.get("unresolved_byte_count") or 0) / total_unresolved_bytes)
            if total_unresolved_bytes
            else 0.0
        )
    return {
        "format": "cdmw_hkx_decode_gap_summary_v1",
        "status": "has_decode_gaps" if gaps else "no_ranked_decode_gaps",
        "description": (
            "Ranked read-only evidence for HKX classes that are readable but not fully decoded. "
            "This is used to explain partially decoded rows in the editor; it does not enable new imports."
        ),
        "gap_count": len(gaps),
        "partial_record_count": total_partial_records,
        "raw_preserved_record_count": total_raw_records,
        "total_unresolved_byte_count": total_unresolved_bytes,
        "gaps": gaps[:128],
        "truncated_gap_count": max(0, len(gaps) - 128),
    }


def _hkx_tag_sections_document(summary: HkxTagfileSummary) -> List[Dict[str, object]]:
    return [
        {
            "name": item.name,
            "offset": item.offset,
            "length_word_offset": item.length_word_offset,
            "raw_length_word": item.raw_length_word,
            "declared_length": item.declared_length,
            "length_flags": item.length_flags,
            "data_end": item.word_end_offset,
        }
        for item in summary.tag_items
    ]


def _hkx_tag_item_payload(data: bytes, items: Sequence[HkxTagItem], name: str) -> bytes:
    item = _hkx_tag_item_by_name(items, name)
    if item is None or item.offset + 4 > len(data):
        return b""
    if item.word_end_offset is not None and item.word_end_offset <= len(data):
        payload_end = item.word_end_offset
    elif item.marker_end_offset is not None and item.marker_end_offset <= len(data):
        payload_end = item.marker_end_offset
    else:
        next_item = _hkx_next_tag_item(items, item)
        payload_end = next_item.length_word_offset if next_item and next_item.length_word_offset else len(data)
    payload_start = item.offset + 4
    return data[payload_start : max(payload_start, min(payload_end, len(data)))]


def _hkx_tagfile_fixup_reference_category(target_type_name: str, *, section_name: str, match_kind: str) -> str:
    target = str(target_type_name or "")
    if match_kind == "null":
        return "null_reference"
    if match_kind == "type_index":
        return "type_reference"
    if match_kind == "string_table_index":
        if target.startswith(("hk", "hknp", "hka", "hkx", "hkcd")) or "::" in target:
            return "type_class_reference"
        return "string_reference"
    if target == "char":
        return "string_reference"
    if target.startswith("hkArray") or target in _HKX_SCALAR_ARRAY_TYPES:
        return "array_data_reference"
    if section_name == "INDX":
        return "object_reference"
    return "data_reference_candidate"


def _hkx_tagfile_fixup_word_match(
    value: int,
    *,
    section_name: str,
    record_by_data_offset: Mapping[int, HkxItemRecord],
    record_by_absolute_offset: Mapping[int, HkxItemRecord],
    type_name_by_index: Mapping[int, str],
    string_table_names: Sequence[str],
) -> Dict[str, object]:
    if value == 0:
        return {
            "match_kind": "null",
            "reference_category": "null_reference",
            "confidence": "strong inference",
            "description": "Zero word in a tagfile fixup/reference-like section; treated as a null reference candidate.",
        }
    target_record = record_by_data_offset.get(value)
    if target_record is not None:
        return {
            "match_kind": "data_offset",
            "reference_category": _hkx_tagfile_fixup_reference_category(
                target_record.type_name,
                section_name=section_name,
                match_kind="data_offset",
            ),
            "target_record_index": target_record.index,
            "target_type_index": target_record.type_index,
            "target_type_name": target_record.type_name,
            "target_data_offset": target_record.data_offset,
            "confidence": "experimental",
            "description": "INDX/section word matches an ITEM DATA-relative offset. Exact Havok fixup semantics are still being recovered.",
        }
    target_record = record_by_absolute_offset.get(value)
    if target_record is not None:
        return {
            "match_kind": "absolute_offset",
            "reference_category": _hkx_tagfile_fixup_reference_category(
                target_record.type_name,
                section_name=section_name,
                match_kind="absolute_offset",
            ),
            "target_record_index": target_record.index,
            "target_type_index": target_record.type_index,
            "target_type_name": target_record.type_name,
            "target_absolute_offset": target_record.absolute_data_offset,
            "confidence": "experimental",
            "description": "INDX/section word matches an absolute ITEM payload offset. Exact Havok fixup semantics are still being recovered.",
        }
    if value in type_name_by_index:
        type_name = str(type_name_by_index.get(value) or "")
        return {
            "match_kind": "type_index",
            "reference_category": _hkx_tagfile_fixup_reference_category(
                type_name,
                section_name=section_name,
                match_kind="type_index",
            ),
            "target_type_index": value,
            "target_type_name": type_name,
            "confidence": "experimental",
            "description": "INDX/section word matches a recovered TNA1 type index.",
        }
    if 0 <= value < len(string_table_names):
        string_value = str(string_table_names[value])
        return {
            "match_kind": "string_table_index",
            "reference_category": _hkx_tagfile_fixup_reference_category(
                string_value,
                section_name=section_name,
                match_kind="string_table_index",
            ),
            "target_string_index": value,
            "target_string": string_value,
            "confidence": "experimental",
            "description": "INDX/section word matches a recovered TST1 string-table index.",
        }
    return {
        "match_kind": "unresolved_word",
        "reference_category": "unresolved_fixup_word",
        "confidence": "raw",
        "description": "No recovered ITEM, type, or string-table target matched this fixup word.",
    }


def _hkx_tagfile_nested_item_word_match(
    word_index: int,
    offset: int,
    value: int,
    *,
    section_item: HkxTagItem,
    item_item: HkxTagItem,
    records: Sequence[HkxItemRecord],
) -> Optional[Dict[str, object]]:
    word_absolute_offset = int(section_item.offset) + 4 + int(offset)
    if item_item.length_word_offset is not None and int(item_item.length_word_offset) == word_absolute_offset:
        return {
            "match_kind": "item_length_word",
            "reference_category": "item_table_metadata",
            "confidence": "confirmed",
            "description": "INDX contains the nested ITEM section length word.",
        }
    if word_absolute_offset == int(item_item.offset):
        return {
            "match_kind": "item_marker",
            "reference_category": "item_table_metadata",
            "target_type_name": "ITEM",
            "confidence": "confirmed",
            "description": "INDX contains the nested ITEM marker.",
        }
    if int(item_item.offset) < word_absolute_offset < int(item_item.offset) + 16:
        return {
            "match_kind": "item_header_word",
            "reference_category": "item_table_metadata",
            "confidence": "confirmed",
            "description": "Header/padding word before nested ITEM records.",
        }
    record_start = int(item_item.offset) + 16
    item_end = (
        int(item_item.word_end_offset)
        if item_item.word_end_offset is not None
        else int(item_item.marker_end_offset)
        if item_item.marker_end_offset is not None
        else record_start
    )
    if word_absolute_offset < record_start or word_absolute_offset + 4 > item_end:
        return None
    relative = word_absolute_offset - record_start
    record_slot = relative // 12
    if record_slot < 0 or record_slot >= len(records):
        return None
    record = records[record_slot]
    role = relative % 12
    if role == 0:
        return {
            "match_kind": "item_type_flags",
            "reference_category": "type_reference",
            "target_record_index": record.index,
            "target_type_index": record.type_index,
            "target_type_name": record.type_name,
            "confidence": "confirmed" if int(value) == int(record.raw_type_flags) else "experimental",
            "description": "Nested ITEM descriptor raw type/flags word. Low bits are the recovered TNA1 type index; high bits are ITEM flags.",
        }
    if role == 4:
        return {
            "match_kind": "item_data_offset",
            "reference_category": "item_data_offset",
            "target_record_index": record.index,
            "target_type_index": record.type_index,
            "target_type_name": record.type_name,
            "target_data_offset": record.data_offset,
            "target_absolute_offset": record.absolute_data_offset,
            "confidence": "confirmed" if int(value) == int(record.data_offset) else "experimental",
            "description": "Nested ITEM descriptor DATA-relative object payload offset.",
        }
    if role == 8:
        return {
            "match_kind": "item_count",
            "reference_category": "item_count",
            "target_record_index": record.index,
            "target_type_index": record.type_index,
            "target_type_name": record.type_name,
            "confidence": "confirmed" if int(value) == int(record.count) else "experimental",
            "description": "Nested ITEM descriptor element count.",
        }
    return None


def _hkx_decode_ptch_patch_site(
    data: bytes,
    patch_site_index: int,
    ptch_word_index: int,
    patch_site_offset: int,
    *,
    section_item: HkxTagItem,
    ptch_item: HkxTagItem,
    records: Sequence[HkxItemRecord],
) -> Dict[str, object]:
    word_absolute_offset = int(ptch_item.offset) + 4 + int(ptch_word_index) * 4
    section_payload_start = int(section_item.offset) + 4
    section_word_offset = word_absolute_offset - section_payload_start
    owner_record = max(
        (record for record in records if int(record.data_offset) <= int(patch_site_offset)),
        key=lambda record: int(record.data_offset),
        default=None,
    )
    owner_local_offset: Optional[int] = None
    patch_value: Optional[int] = None
    if owner_record is not None:
        owner_local_offset = int(patch_site_offset) - int(owner_record.data_offset)
        if owner_record.absolute_data_offset is not None:
            absolute = int(owner_record.absolute_data_offset) + owner_local_offset
            if 0 <= absolute and absolute + 8 <= len(data):
                patch_value = struct.unpack_from("<Q", data, absolute)[0]
    target_record: Optional[HkxItemRecord] = None
    if patch_value is not None and 0 <= patch_value < len(records):
        target_record = records[int(patch_value)]
    if patch_value == 0:
        target_status = "null"
        reference_category = "null_reference"
        confidence = "strong inference"
    elif target_record is not None:
        target_status = "object"
        reference_category = _hkx_tagfile_fixup_reference_category(
            target_record.type_name,
            section_name="INDX",
            match_kind="data_offset",
        )
        confidence = "strong inference"
    else:
        target_status = "unresolved"
        reference_category = "patch_offset_candidate"
        confidence = "experimental"
    row: Dict[str, object] = {
        "index": int(patch_site_index),
        "ptch_word_index": int(ptch_word_index),
        "section_word_index": section_word_offset // 4 if section_word_offset >= 0 else None,
        "section_word_offset": section_word_offset if section_word_offset >= 0 else None,
        "patch_site_offset": int(patch_site_offset),
        "patch_site_hex_offset": _hkx_hex(int(patch_site_offset)),
        "owner_record_index": owner_record.index if owner_record is not None else None,
        "owner_type_index": owner_record.type_index if owner_record is not None else None,
        "owner_type_name": owner_record.type_name if owner_record is not None else None,
        "owner_local_offset": owner_local_offset,
        "patch_value": patch_value,
        "target_status": target_status,
        "reference_category": reference_category,
        "target_record_index": target_record.index if target_record is not None else None,
        "target_type_index": target_record.type_index if target_record is not None else None,
        "target_type_name": target_record.type_name if target_record is not None else None,
        "target_data_offset": target_record.data_offset if target_record is not None else None,
        "target_absolute_offset": target_record.absolute_data_offset if target_record is not None else None,
        "confidence": confidence,
    }
    return {key: value for key, value in row.items() if value is not None}


def _hkx_decode_nested_ptch_table(
    data: bytes,
    *,
    section_item: HkxTagItem,
    ptch_item: HkxTagItem,
    records: Sequence[HkxItemRecord],
) -> Optional[Dict[str, object]]:
    ptch_end = (
        int(ptch_item.word_end_offset)
        if ptch_item.word_end_offset is not None
        else int(ptch_item.marker_end_offset)
        if ptch_item.marker_end_offset is not None
        else int(ptch_item.offset) + 4
    )
    payload_offset = int(ptch_item.offset) + 4
    if payload_offset + 20 > len(data) or payload_offset > ptch_end:
        return None
    payload_byte_length = max(0, ptch_end - payload_offset)
    word_count = payload_byte_length // 4
    if word_count < 5:
        return None
    ptch_words = [
        struct.unpack_from("<I", data, payload_offset + word_offset)[0]
        for word_offset in range(0, word_count * 4, 4)
        if payload_offset + word_offset + 4 <= len(data)
    ]
    if len(ptch_words) < 5 or tuple(ptch_words[:4]) != (1, 1, 0, 2):
        return None
    patch_site_count = int(ptch_words[4])
    if patch_site_count > max(0, len(ptch_words) - 5):
        return None
    patch_sites = [
        _hkx_decode_ptch_patch_site(
            data,
            patch_site_index,
            5 + patch_site_index,
            int(ptch_words[5 + patch_site_index]),
            section_item=section_item,
            ptch_item=ptch_item,
            records=records,
        )
        for patch_site_index in range(patch_site_count)
    ]
    resolved_patch_site_count = sum(1 for site in patch_sites if site.get("target_status") == "object")
    null_patch_site_count = sum(1 for site in patch_sites if site.get("target_status") == "null")
    unresolved_patch_site_count = sum(1 for site in patch_sites if site.get("target_status") == "unresolved")
    return {
        "offset": int(ptch_item.offset),
        "hex_offset": _hkx_hex(int(ptch_item.offset)),
        "payload_offset": payload_offset,
        "payload_hex_offset": _hkx_hex(payload_offset),
        "payload_byte_length": payload_byte_length,
        "word_count": word_count,
        "header": [1, 1, 0, 2],
        "patch_site_count": patch_site_count,
        "resolved_patch_site_count": resolved_patch_site_count,
        "null_patch_site_count": null_patch_site_count,
        "unresolved_patch_site_count": unresolved_patch_site_count,
        "confidence": "strong inference" if unresolved_patch_site_count == 0 else "experimental",
        "patch_sites": patch_sites,
    }


def _hkx_tagfile_nested_ptch_word_match(
    data: bytes,
    word_index: int,
    offset: int,
    value: int,
    *,
    section_item: HkxTagItem,
    ptch_item: HkxTagItem,
    ptch_payload: bytes,
    records: Sequence[HkxItemRecord],
    record_by_data_offset: Mapping[int, HkxItemRecord],
    record_by_absolute_offset: Mapping[int, HkxItemRecord],
    type_name_by_index: Mapping[int, str],
    string_table_names: Sequence[str],
) -> Optional[Dict[str, object]]:
    word_absolute_offset = int(section_item.offset) + 4 + int(offset)
    if ptch_item.length_word_offset is not None and int(ptch_item.length_word_offset) == word_absolute_offset:
        return {
            "match_kind": "ptch_length_word",
            "reference_category": "ptch_table_metadata",
            "confidence": "confirmed",
            "description": "INDX contains the nested PTCH section length word.",
        }
    if word_absolute_offset == int(ptch_item.offset):
        return {
            "match_kind": "ptch_marker",
            "reference_category": "ptch_table_metadata",
            "target_type_name": "PTCH",
            "confidence": "confirmed",
            "description": "INDX contains the nested PTCH marker.",
        }
    ptch_end = (
        int(ptch_item.word_end_offset)
        if ptch_item.word_end_offset is not None
        else int(ptch_item.marker_end_offset)
        if ptch_item.marker_end_offset is not None
        else int(ptch_item.offset) + 4
    )
    if word_absolute_offset < int(ptch_item.offset) + 4 or word_absolute_offset + 4 > ptch_end:
        return None
    ptch_payload_start = int(ptch_item.offset) + 4
    ptch_word_offset = word_absolute_offset - ptch_payload_start
    if ptch_word_offset < 0 or ptch_word_offset % 4:
        return None
    ptch_word_index = ptch_word_offset // 4
    ptch_words = [
        struct.unpack_from("<I", ptch_payload, word_offset)[0]
        for word_offset in range(0, (len(ptch_payload) // 4) * 4, 4)
    ]
    if len(ptch_words) >= 5 and tuple(ptch_words[:4]) == (1, 1, 0, 2) and int(ptch_words[4]) <= max(0, len(ptch_words) - 5):
        if ptch_word_index < 4:
            return {
                "match_kind": "ptch_header_word",
                "reference_category": "ptch_table_metadata",
                "confidence": "confirmed",
                "description": "Nested PTCH fixed header word. Corpus samples use [1, 1, 0, 2] before the patch-site count.",
            }
        if ptch_word_index == 4:
            return {
                "match_kind": "ptch_patch_site_count",
                "reference_category": "ptch_table_metadata",
                "patch_site_count": int(value),
                "confidence": "confirmed",
                "description": "Number of DATA-relative patch-site offsets following the PTCH header.",
            }
        patch_site_count = int(ptch_words[4])
        if 5 <= ptch_word_index < 5 + patch_site_count:
            site = _hkx_decode_ptch_patch_site(
                data,
                ptch_word_index - 5,
                ptch_word_index,
                int(value),
                section_item=section_item,
                ptch_item=ptch_item,
                records=records,
            )
            target_status = str(site.get("target_status") or "unresolved")
            row: Dict[str, object] = {
                **site,
                "match_kind": (
                    "ptch_object_patch_offset"
                    if target_status == "object"
                    else "ptch_null_patch_offset"
                    if target_status == "null"
                    else "ptch_patch_site_offset"
                ),
                "description": (
                    "Nested PTCH object-reference patch site. The PTCH word is a DATA-relative offset; "
                    "the slot value is interpreted as a target ITEM record index when it is in range."
                ),
            }
            return {key: value for key, value in row.items() if value is not None}
    match = _hkx_tagfile_fixup_word_match(
        int(value),
        section_name="PTCH",
        record_by_data_offset=record_by_data_offset,
        record_by_absolute_offset=record_by_absolute_offset,
        type_name_by_index=type_name_by_index,
        string_table_names=string_table_names,
    )
    match_kind = str(match.get("match_kind") or "unresolved_word")
    match["match_kind"] = {
        "null": "ptch_null",
        "data_offset": "ptch_data_offset",
        "absolute_offset": "ptch_absolute_offset",
        "type_index": "ptch_type_index",
        "string_table_index": "ptch_string_table_index",
        "unresolved_word": "ptch_payload_word",
    }.get(match_kind, f"ptch_{match_kind}")
    if str(match.get("reference_category") or "") == "unresolved_fixup_word":
        match["reference_category"] = "patch_offset_candidate"
        match["confidence"] = "experimental"
        match["description"] = (
            "Nested PTCH payload word that did not match a recovered ITEM/type/string target. "
            "Kept as a patch/fixup offset candidate until PTCH tuple semantics are fully mapped."
        )
    return match


def _hkx_tagfile_reference_fixups_document(
    data: bytes,
    summary: HkxTagfileSummary,
    *,
    word_limit_per_section: int = 256,
    varuint_limit_per_section: int = 128,
) -> Dict[str, object]:
    record_by_data_offset = {
        int(record.data_offset): record
        for record in summary.item_records
        if int(record.data_offset) > 0
    }
    record_by_absolute_offset = {
        int(record.absolute_data_offset): record
        for record in summary.item_records
        if record.absolute_data_offset is not None and int(record.absolute_data_offset) > 0
    }
    type_name_by_index = {int(type_info.index): type_info.display_name for type_info in summary.type_infos}
    if not type_name_by_index:
        type_name_by_index = {index: name for index, name in enumerate(summary.type_names)}
    section_rows: List[Dict[str, object]] = []
    total_match_counts: Counter[str] = Counter()
    total_reference_category_counts: Counter[str] = Counter()
    total_ptch_table_count = 0
    total_ptch_patch_site_count = 0
    total_ptch_resolved_patch_site_count = 0
    total_ptch_null_patch_site_count = 0
    total_ptch_unresolved_patch_site_count = 0
    for section_name in ("INDX", "TPAD"):
        section_item = _hkx_tag_item_by_name(summary.tag_items, section_name)
        if section_item is None:
            continue
        payload = _hkx_tag_item_payload(data, summary.tag_items, section_name)
        section_payload_start = int(section_item.offset) + 4
        section_payload_end = section_payload_start + len(payload)
        nested_item = _hkx_tag_item_by_name(summary.tag_items, "ITEM")
        if nested_item is not None:
            nested_length_offset = int(nested_item.length_word_offset) if nested_item.length_word_offset is not None else None
            nested_marker_offset = int(nested_item.offset)
            if not (
                (nested_length_offset is not None and section_payload_start <= nested_length_offset < section_payload_end)
                or section_payload_start <= nested_marker_offset < section_payload_end
            ):
                nested_item = None
        nested_ptch = _hkx_tag_item_by_name(summary.tag_items, "PTCH")
        ptch_payload = b""
        if nested_ptch is not None:
            nested_length_offset = int(nested_ptch.length_word_offset) if nested_ptch.length_word_offset is not None else None
            nested_marker_offset = int(nested_ptch.offset)
            if not (
                (nested_length_offset is not None and section_payload_start <= nested_length_offset < section_payload_end)
                or section_payload_start <= nested_marker_offset < section_payload_end
            ):
                nested_ptch = None
            else:
                ptch_payload = _hkx_tag_item_payload(data, summary.tag_items, "PTCH")
        ptch_tables: List[Dict[str, object]] = []
        if nested_ptch is not None:
            ptch_table = _hkx_decode_nested_ptch_table(
                data,
                section_item=section_item,
                ptch_item=nested_ptch,
                records=summary.item_records,
            )
            if ptch_table is not None:
                ptch_tables.append(ptch_table)
                total_ptch_table_count += 1
                total_ptch_patch_site_count += int(ptch_table.get("patch_site_count") or 0)
                total_ptch_resolved_patch_site_count += int(ptch_table.get("resolved_patch_site_count") or 0)
                total_ptch_null_patch_site_count += int(ptch_table.get("null_patch_site_count") or 0)
                total_ptch_unresolved_patch_site_count += int(ptch_table.get("unresolved_patch_site_count") or 0)
        words: List[Dict[str, object]] = []
        word_counts: Counter[str] = Counter()
        for word_index in range(min(len(payload) // 4, word_limit_per_section)):
            offset = word_index * 4
            value = struct.unpack_from("<I", payload, offset)[0]
            match = (
                _hkx_tagfile_nested_item_word_match(
                    word_index,
                    offset,
                    int(value),
                    section_item=section_item,
                    item_item=nested_item,
                    records=summary.item_records,
                )
                if nested_item is not None
                else None
            )
            if match is None and nested_ptch is not None:
                match = _hkx_tagfile_nested_ptch_word_match(
                    data,
                    word_index,
                    offset,
                    int(value),
                    section_item=section_item,
                    ptch_item=nested_ptch,
                    ptch_payload=ptch_payload,
                    records=summary.item_records,
                    record_by_data_offset=record_by_data_offset,
                    record_by_absolute_offset=record_by_absolute_offset,
                    type_name_by_index=type_name_by_index,
                    string_table_names=summary.string_table_names,
                )
            if match is None:
                match = _hkx_tagfile_fixup_word_match(
                    int(value),
                    section_name=section_name,
                    record_by_data_offset=record_by_data_offset,
                    record_by_absolute_offset=record_by_absolute_offset,
                    type_name_by_index=type_name_by_index,
                    string_table_names=summary.string_table_names,
                )
            match_kind = str(match.get("match_kind") or "unresolved_word")
            word_counts[match_kind] += 1
            total_match_counts[match_kind] += 1
            reference_category = str(match.get("reference_category") or "")
            if reference_category:
                total_reference_category_counts[reference_category] += 1
            words.append(
                {
                    "index": word_index,
                    "offset": offset,
                    "hex_offset": f"0x{offset:X}",
                    "value": int(value),
                    "value_hex": _hkx_hex(int(value)),
                    **match,
                }
            )
        reference_category_counts = Counter(str(word.get("reference_category") or "") for word in words if str(word.get("reference_category") or ""))
        resolved_references = [
            {
                "section": section_name,
                "offset": word.get("offset"),
                "hex_offset": word.get("hex_offset"),
                "value": word.get("value"),
                "match_kind": word.get("match_kind"),
                "reference_category": word.get("reference_category"),
                "target_record_index": word.get("target_record_index"),
                "target_type_name": word.get("target_type_name"),
                "target_type_index": word.get("target_type_index"),
                "target_string": word.get("target_string"),
                "owner_record_index": word.get("owner_record_index"),
                "owner_type_index": word.get("owner_type_index"),
                "owner_type_name": word.get("owner_type_name"),
                "owner_local_offset": word.get("owner_local_offset"),
                "patch_value": word.get("patch_value"),
                "target_status": word.get("target_status"),
                "confidence": word.get("confidence"),
            }
            for word in words
            if isinstance(word, Mapping)
            and str(word.get("match_kind") or "") not in {"unresolved_word"}
            and str(word.get("reference_category") or "") not in {"item_table_metadata", "item_count", "ptch_table_metadata", "patch_offset_candidate"}
        ][:128]
        varuint_values: List[Dict[str, object]] = []
        cursor = 0
        varuint_status = "not_decoded" if not payload else "decoded_sample"
        while payload and cursor < len(payload) and len(varuint_values) < varuint_limit_per_section:
            start = cursor
            try:
                value, cursor = _read_hkx_var_uint(payload, cursor)
            except ValueError as exc:
                varuint_status = f"stopped: {exc}"
                break
            match = _hkx_tagfile_fixup_word_match(
                int(value),
                section_name=section_name,
                record_by_data_offset=record_by_data_offset,
                record_by_absolute_offset=record_by_absolute_offset,
                type_name_by_index=type_name_by_index,
                string_table_names=summary.string_table_names,
            )
            varuint_values.append(
                {
                    "index": len(varuint_values),
                    "offset": start,
                    "hex_offset": f"0x{start:X}",
                    "byte_length": cursor - start,
                    "value": int(value),
                    "value_hex": _hkx_hex(int(value)),
                    **match,
                }
            )
        section_rows.append(
            {
                "name": section_name,
                "offset": section_item.offset,
                "payload_byte_length": len(payload),
                "word_count": len(payload) // 4,
                "shown_word_count": len(words),
                "truncated_word_count": max(0, (len(payload) // 4) - len(words)),
                "match_kind_counts": dict(sorted(word_counts.items())),
                "reference_category_counts": dict(sorted(reference_category_counts.items())),
                "record_offset_match_count": (
                    int(word_counts.get("data_offset") or 0)
                    + int(word_counts.get("absolute_offset") or 0)
                    + int(word_counts.get("item_data_offset") or 0)
                ),
                "null_word_count": int(word_counts.get("null") or 0),
                "type_index_match_count": int(word_counts.get("type_index") or 0) + int(word_counts.get("item_type_flags") or 0),
                "string_table_index_match_count": int(word_counts.get("string_table_index") or 0),
                "ptch_tables": ptch_tables,
                "varuint_status": varuint_status,
                "varuint_values": varuint_values,
                "resolved_references": resolved_references,
                "words": words,
            }
        )
    return {
        "format": "cdmw_hkx_tagfile_reference_fixups_v1",
        "status": "experimental_observation",
        "imported": False,
        "description": (
            "Read-only scan of tagfile reference/fixup-like sections. INDX semantics are not treated as editable yet; "
            "words are classified when they belong to nested ITEM descriptors, nested PTCH payloads, recovered ITEM offsets, TNA1 type indexes, strings, or nulls."
        ),
        "ptch_table_count": total_ptch_table_count,
        "ptch_patch_site_count": total_ptch_patch_site_count,
        "ptch_resolved_patch_site_count": total_ptch_resolved_patch_site_count,
        "ptch_null_patch_site_count": total_ptch_null_patch_site_count,
        "ptch_unresolved_patch_site_count": total_ptch_unresolved_patch_site_count,
        "match_kind_counts": dict(sorted(total_match_counts.items())),
        "reference_category_counts": dict(sorted(total_reference_category_counts.items())),
        "section_count": len(section_rows),
        "sections": section_rows,
    }


def _hkx_fixup_semantics_report_document(tagfile_reference_fixups: Mapping[str, object]) -> Dict[str, object]:
    sections = tagfile_reference_fixups.get("sections") if isinstance(tagfile_reference_fixups, Mapping) else None
    section_rows = sections if isinstance(sections, list) else []
    tuple_shape_counts: Counter[str] = Counter()
    payload_match_kind_counts: Counter[str] = Counter()
    reference_category_counts: Counter[str] = Counter()
    target_status_counts: Counter[str] = Counter()
    varuint_status_counts: Counter[str] = Counter()
    remaining_cases: Counter[str] = Counter()
    remaining_descriptions: Dict[str, str] = {}
    section_summaries: List[Dict[str, object]] = []

    def _add_case(case: str, count: int, description: str) -> None:
        if count <= 0:
            return
        remaining_cases[case] += int(count)
        remaining_descriptions.setdefault(case, description)

    expected_tuple_shapes = {"1,1,0,2"}
    known_ptch_word_kinds = {
        "ptch_length_word",
        "ptch_marker",
        "ptch_header_word",
        "ptch_patch_site_count",
        "ptch_object_patch_offset",
        "ptch_null_patch_offset",
    }
    for section in section_rows:
        if not isinstance(section, Mapping):
            continue
        section_name = str(section.get("name") or "")
        section_match_counts = section.get("match_kind_counts")
        section_ref_counts = section.get("reference_category_counts")
        if isinstance(section_match_counts, Mapping):
            for kind, raw_count in section_match_counts.items():
                try:
                    count = int(raw_count)
                except (TypeError, ValueError, OverflowError):
                    continue
                kind_text = str(kind or "")
                if kind_text.startswith("ptch_"):
                    payload_match_kind_counts[kind_text] += count
                    if kind_text not in known_ptch_word_kinds:
                        _add_case(
                            f"ptch_match_kind:{kind_text}",
                            count,
                            "PTCH payload word matched a non-header/non-object shape that still needs corpus proof.",
                        )
        if isinstance(section_ref_counts, Mapping):
            for category, raw_count in section_ref_counts.items():
                try:
                    count = int(raw_count)
                except (TypeError, ValueError, OverflowError):
                    continue
                category_text = str(category or "")
                if not category_text:
                    continue
                reference_category_counts[category_text] += count
                if category_text in {
                    "data_reference_candidate",
                    "string_reference",
                    "type_reference",
                    "type_class_reference",
                    "patch_offset_candidate",
                    "unresolved_fixup_word",
                }:
                    _add_case(
                        f"reference_category:{category_text}",
                        count,
                        "Observed reference category is not yet promoted into a full Havok fixup semantic.",
                    )
        varuint_status = str(section.get("varuint_status") or "")
        if varuint_status:
            varuint_status_counts[varuint_status] += 1
            if varuint_status not in {"decoded_sample", "not_decoded"}:
                _add_case(
                    f"varuint_status:{varuint_status}",
                    1,
                    "Varuint probe did not cleanly decode through the sampled section payload.",
                )
        ptch_tables = section.get("ptch_tables")
        table_count = 0
        patch_site_count = 0
        resolved_site_count = 0
        unresolved_site_count = 0
        if isinstance(ptch_tables, list):
            for table in ptch_tables:
                if not isinstance(table, Mapping):
                    continue
                table_count += 1
                header = table.get("header")
                if isinstance(header, list):
                    shape = ",".join(str(value) for value in header)
                    tuple_shape_counts[shape] += 1
                    if shape not in expected_tuple_shapes:
                        _add_case(
                            f"ptch_tuple_shape:{shape}",
                            1,
                            "PTCH table header shape differs from the currently verified object/null patch tuple.",
                        )
                try:
                    patch_site_count += int(table.get("patch_site_count") or 0)
                    resolved_site_count += int(table.get("resolved_patch_site_count") or 0) + int(table.get("null_patch_site_count") or 0)
                    unresolved_site_count += int(table.get("unresolved_patch_site_count") or 0)
                except (TypeError, ValueError, OverflowError):
                    pass
                patch_sites = table.get("patch_sites")
                if not isinstance(patch_sites, list):
                    continue
                for site in patch_sites:
                    if not isinstance(site, Mapping):
                        continue
                    target_status = str(site.get("target_status") or "unresolved")
                    target_status_counts[target_status] += 1
                    reference_category = str(site.get("reference_category") or "")
                    if reference_category:
                        reference_category_counts[reference_category] += 1
                    if target_status == "unresolved":
                        _add_case(
                            "unresolved_ptch_patch_site",
                            1,
                            "PTCH patch-site offset was found but its patched slot value was not resolved to null or an ITEM record.",
                        )
                    elif target_status not in {"object", "null"}:
                        _add_case(
                            f"non_object_ptch_patch_site:{target_status}",
                            1,
                            "PTCH patch site resolved to a target status that is not yet modeled as object/null.",
                        )
                    if reference_category and reference_category not in {"object_reference", "null_reference"}:
                        _add_case(
                            f"patch_site_reference_category:{reference_category}",
                            1,
                            "PTCH patch site carries a non-object/null reference category that needs dedicated semantics.",
                        )
        section_summaries.append(
            {
                "name": section_name,
                "payload_byte_length": section.get("payload_byte_length"),
                "word_count": section.get("word_count"),
                "ptch_table_count": table_count,
                "ptch_patch_site_count": patch_site_count,
                "ptch_patch_site_resolved_count": resolved_site_count,
                "ptch_patch_site_unresolved_count": unresolved_site_count,
                "varuint_status": varuint_status,
                "match_kind_counts": dict(section_match_counts) if isinstance(section_match_counts, Mapping) else {},
                "reference_category_counts": dict(section_ref_counts) if isinstance(section_ref_counts, Mapping) else {},
            }
        )
    remaining_case_rows = [
        {
            "priority_rank": index + 1,
            "case": case,
            "count": count,
            "description": remaining_descriptions.get(case, ""),
        }
        for index, (case, count) in enumerate(
            sorted(remaining_cases.items(), key=lambda item: (-int(item[1]), str(item[0])))
        )
    ]
    return {
        "format": "cdmw_hkx_fixup_semantics_report_v1",
        "status": "experimental_observation",
        "imported": False,
        "description": (
            "Read-only PTCH/INDX semantics tracker. It separates verified object/null PTCH patch sites from "
            "remaining tuple shapes and data/string/type-style candidates that still need corpus proof."
        ),
        "ptch_table_count": int(tagfile_reference_fixups.get("ptch_table_count") or 0)
        if isinstance(tagfile_reference_fixups, Mapping)
        else 0,
        "ptch_patch_site_count": int(tagfile_reference_fixups.get("ptch_patch_site_count") or 0)
        if isinstance(tagfile_reference_fixups, Mapping)
        else 0,
        "ptch_object_patch_site_count": int(tagfile_reference_fixups.get("ptch_resolved_patch_site_count") or 0)
        if isinstance(tagfile_reference_fixups, Mapping)
        else 0,
        "ptch_null_patch_site_count": int(tagfile_reference_fixups.get("ptch_null_patch_site_count") or 0)
        if isinstance(tagfile_reference_fixups, Mapping)
        else 0,
        "ptch_unresolved_patch_site_count": int(tagfile_reference_fixups.get("ptch_unresolved_patch_site_count") or 0)
        if isinstance(tagfile_reference_fixups, Mapping)
        else 0,
        "ptch_tuple_shape_counts": dict(sorted(tuple_shape_counts.items())),
        "ptch_payload_match_kind_counts": dict(sorted(payload_match_kind_counts.items())),
        "ptch_reference_category_counts": dict(sorted(reference_category_counts.items())),
        "ptch_target_status_counts": dict(sorted(target_status_counts.items())),
        "varuint_status_counts": dict(sorted(varuint_status_counts.items())),
        "ptch_remaining_case_priorities": remaining_case_rows,
        "section_summaries": section_summaries,
    }


def _hkx_type_registry_document(summary: HkxTagfileSummary) -> Dict[str, object]:
    type_infos = [
        {
            "index": type_info.index,
            "name": type_info.name,
            "display_name": type_info.display_name,
            "template_parameters": [
                {"name": name, "value": value}
                for name, value in type_info.template_parameters
            ],
        }
        for type_info in summary.type_infos
    ]
    return {
        "declared_type_name_count": summary.declared_type_name_count,
        "type_infos": type_infos,
        "string_table_names": list(summary.string_table_names),
        "type_names": list(summary.type_names),
    }


def _hkx_havok_schema_base_name(type_name: str) -> str:
    if type_name.startswith("hkArray"):
        return "hkArray"
    if type_name.startswith("hkRefPtr"):
        return "hkRefPtr"
    return type_name


def _hkx_havok_member_rows_for_type(type_name: str) -> List[Dict[str, object]]:
    rows = _HKX_HAVOK_MEMBER_SCHEMA.get(type_name)
    if rows is None:
        rows = _HKX_HAVOK_MEMBER_SCHEMA.get(_hkx_havok_schema_base_name(type_name), ())
    return [_hkx_havok_enrich_member_row(row) for row in rows]


def _hkx_havok_member_by_source_name(type_name: str, field_name: str) -> Optional[Dict[str, object]]:
    for member in _hkx_havok_member_rows_for_type(type_name):
        source_names = member.get("source_names")
        if isinstance(source_names, tuple) and field_name in source_names:
            return member
        if isinstance(source_names, list) and field_name in source_names:
            return member
    return None


def _hkx_havok_template_arguments(type_text: str) -> List[str]:
    text = str(type_text or "").strip()
    start = text.find("<")
    end = text.rfind(">")
    if start < 0 or end <= start:
        return []
    inner = text[start + 1 : end]
    args: List[str] = []
    depth = 0
    current: List[str] = []
    for char in inner:
        if char == "<":
            depth += 1
            current.append(char)
        elif char == ">":
            depth = max(0, depth - 1)
            current.append(char)
        elif char == "," and depth == 0:
            arg = "".join(current).strip()
            if arg:
                args.append(arg)
            current = []
        else:
            current.append(char)
    arg = "".join(current).strip()
    if arg:
        args.append(arg)
    return args


def _hkx_havok_member_type_metadata(member: Mapping[str, object]) -> Dict[str, object]:
    data_type = str(member.get("type") or "")
    reference_status = str(member.get("reference_status") or "none")
    array_status = str(member.get("array_status") or "none")
    template_args = _hkx_havok_template_arguments(data_type)
    element_type = template_args[0] if template_args and data_type.startswith("hkArray<") else ""
    pointer_type = ""
    if data_type.startswith("hkRefPtr<") and template_args:
        pointer_type = template_args[0]
    elif data_type in {"hkStringPtr", "char*", "char[]"}:
        pointer_type = "char"
    elif data_type.endswith("*"):
        pointer_type = data_type[:-1].strip()
    is_array = data_type.startswith("hkArray<") or data_type.endswith("[]") or array_status in {
        "hkArray",
        "row_list",
        "scalar_list",
        "string_data",
        "fixed_rows",
    }
    is_pointer = bool(pointer_type) or data_type.startswith("hkRefPtr<") or data_type in {"hkRefVariant", "hkStringPtr"}
    scalar_map = {
        "hkReal": "TYPE_REAL",
        "float": "TYPE_REAL",
        "int": "TYPE_INT32",
        "hkInt16": "TYPE_INT16",
        "hkUint8": "TYPE_UINT8",
        "hkUint32": "TYPE_UINT32",
        "unsigned int": "TYPE_UINT32",
        "unsigned short": "TYPE_UINT16",
        "unsigned char": "TYPE_UINT8",
        "char": "TYPE_CHAR",
        "char*": "TYPE_CSTRING",
        "char[]": "TYPE_CSTRING",
    }
    if is_array:
        member_type = "TYPE_ARRAY"
    elif data_type.startswith("hkRefPtr<"):
        member_type = "TYPE_POINTER"
    elif data_type in {"hkRefVariant", "void*"}:
        member_type = "TYPE_POINTER"
    elif data_type in {"hkStringPtr", "char*"}:
        member_type = "TYPE_CSTRING"
    elif data_type.endswith("::Enum") or data_type.endswith("FlagsEnum"):
        member_type = "TYPE_ENUM"
    else:
        member_type = scalar_map.get(data_type, "TYPE_STRUCT")
    class_ref = (element_type or pointer_type) if member_type in {"TYPE_ARRAY", "TYPE_POINTER", "TYPE_STRUCT"} else ""
    return {
        "member_type": member_type,
        "subtype": element_type or pointer_type or "",
        "class_ref": class_ref,
        "template_arguments": template_args,
        "is_array": is_array,
        "is_pointer": is_pointer,
        "is_enum": member_type == "TYPE_ENUM",
        "flags": str(member.get("flags") or "FLAGS_NONE"),
        "storage": (
            "hkArray"
            if data_type.startswith("hkArray<")
            else "hkRefPtr"
            if data_type.startswith("hkRefPtr<")
            else "reference"
            if reference_status not in {"", "none"}
            else "value"
        ),
    }


def _hkx_havok_enrich_member_row(member: Mapping[str, object]) -> Dict[str, object]:
    row = dict(member)
    for key, value in _hkx_havok_member_type_metadata(row).items():
        row.setdefault(key, value)
    row.setdefault("flags", "FLAGS_NONE")
    row.setdefault("cdmw_recovered", False)
    return row


def _hkx_havok_reference_category(
    *,
    source_type_name: str,
    target_type_name: str = "",
    offset: Optional[int] = None,
    field_name: str = "",
) -> str:
    source = _hkx_havok_schema_base_name(str(source_type_name or ""))
    target = str(target_type_name or "")
    name = str(field_name or "")
    name_lower = name.lower()
    if target == "char":
        if "class" in name_lower or (source == "hkRootLevelContainer::NamedVariant" and offset == 8):
            return "type_class_reference"
        return "string_reference"
    if "class_name" in name_lower or "classname" in name_lower:
        return "type_class_reference"
    if "name_reference" in name_lower or source == "hkStringPtr":
        return "string_reference"
    if source == "hkArray" or "array" in name_lower or "data_reference" in name_lower:
        return "array_data_reference"
    if source in {"hkRefPtr", "hkRefVariant"}:
        return "object_reference"
    if source == "hkRootLevelContainer::NamedVariant" and offset == 16:
        return "object_reference"
    if (
        "object_reference" in name_lower
        or "shape_reference" in name_lower
        or "constraint_data_reference" in name_lower
        or "body_" in name_lower
        or name_lower.endswith("_reference_pair")
    ):
        return "object_reference"
    if target:
        return "object_reference"
    return "record_reference_candidate"


def _hkx_havok_reference_confidence(
    *,
    source_type_name: str,
    reference_kind: str,
    reference_category: str,
) -> str:
    source = _hkx_havok_schema_base_name(str(source_type_name or ""))
    if reference_kind == "data_offset" and reference_category in {
        "array_data_reference",
        "object_reference",
        "string_reference",
        "type_class_reference",
    }:
        if source in {
            "hkArray",
            "hkRefPtr",
            "hkRefVariant",
            "hkStringPtr",
            "hkRootLevelContainer",
            "hkRootLevelContainer::NamedVariant",
        }:
            return "strong inference"
    return "experimental"


def _hkx_havok_param_name_for_field(type_name: str, field: Mapping[str, object]) -> str:
    field_name = str(field.get("name") or "")
    member = _hkx_havok_member_by_source_name(type_name, field_name)
    if isinstance(member, Mapping):
        return str(member.get("name") or field_name)
    if field_name.startswith("finite_float_") or field_name.startswith("u32_") or "candidate" in field_name:
        return f"cdmwRecovered_{field_name}"
    return field_name


def _hkx_havok_data_type_for_field(type_name: str, field: Mapping[str, object]) -> str:
    member = _hkx_havok_member_by_source_name(type_name, str(field.get("name") or ""))
    if isinstance(member, Mapping) and str(member.get("type") or ""):
        return str(member["type"])
    return str(field.get("data_type") or "unknown")


def _hkx_havok_array_status_for_field(type_name: str, field: Mapping[str, object]) -> str:
    member = _hkx_havok_member_by_source_name(type_name, str(field.get("name") or ""))
    if isinstance(member, Mapping):
        return str(member.get("array_status") or "none")
    data_type = str(field.get("data_type") or "")
    if "[]" in data_type or "array" in data_type.lower():
        return "array_like"
    return "none"


def _hkx_havok_reference_status_for_field(type_name: str, field: Mapping[str, object]) -> str:
    member = _hkx_havok_member_by_source_name(type_name, str(field.get("name") or ""))
    if isinstance(member, Mapping):
        return str(member.get("reference_status") or "none")
    data_type = str(field.get("data_type") or "").lower()
    if "reference" in data_type:
        return _hkx_havok_reference_category(
            source_type_name=type_name,
            field_name=str(field.get("name") or ""),
            offset=field.get("offset") if isinstance(field.get("offset"), int) else None,
        )
    return "none"


def _hkx_havok_confidence_for_field(type_name: str, field: Mapping[str, object]) -> str:
    member = _hkx_havok_member_by_source_name(type_name, str(field.get("name") or ""))
    if isinstance(member, Mapping) and str(member.get("confidence") or ""):
        return str(member["confidence"])
    return str(field.get("confidence") or "experimental")


def _hkx_havok_synthetic_member_rows(
    type_name: str,
    observed_fields: Sequence[Mapping[str, object]],
) -> List[Dict[str, object]]:
    rows = _hkx_havok_member_rows_for_type(type_name)
    seen_names = {str(row.get("name") or "") for row in rows}
    for field in observed_fields:
        if not isinstance(field, Mapping):
            continue
        source_name = str(field.get("name") or "")
        member_name = _hkx_havok_param_name_for_field(type_name, field)
        if not member_name or member_name in seen_names:
            continue
        seen_names.add(member_name)
        rows.append(
            {
                "source_names": (source_name,),
                "name": member_name,
                "type": _hkx_havok_data_type_for_field(type_name, field),
                "offset": field.get("offset"),
                "array_status": _hkx_havok_array_status_for_field(type_name, field),
                "reference_status": _hkx_havok_reference_status_for_field(type_name, field),
                "confidence": _hkx_havok_confidence_for_field(type_name, field),
                "cdmw_recovered": True,
            }
        )
    return [_hkx_havok_enrich_member_row(row) for row in rows]


def _hkx_havok_xml_param_text(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return f"{value:.9g}"
    if isinstance(value, str):
        return value
    if isinstance(value, (list, tuple)):
        if all(isinstance(item, (int, float, bool, str)) for item in value):
            return " ".join(_hkx_havok_xml_param_text(item) for item in value)
        rows: List[str] = []
        for item in value:
            if isinstance(item, (list, tuple)) and all(isinstance(component, (int, float, bool, str)) for component in item):
                rows.append(" ".join(_hkx_havok_xml_param_text(component) for component in item))
            else:
                rows.append(json.dumps(item, sort_keys=True))
        return "\n".join(rows)
    return json.dumps(value, sort_keys=True)


def _hkx_havok_xml_reference_target(reference: Mapping[str, object]) -> str:
    target_record_index = reference.get("target_record_index")
    if isinstance(target_record_index, int):
        return f"#record{target_record_index}"
    if isinstance(target_record_index, str) and target_record_index.strip().lstrip("-").isdigit():
        return f"#record{int(target_record_index)}"
    return ""


def _hkx_ptch_reference_documents_by_owner_offset(
    tagfile_reference_fixups: Optional[Mapping[str, object]],
) -> Dict[int, Dict[int, Dict[str, object]]]:
    if not isinstance(tagfile_reference_fixups, Mapping):
        return {}
    refs_by_owner: Dict[int, Dict[int, Dict[str, object]]] = defaultdict(dict)
    sections = tagfile_reference_fixups.get("sections")
    if not isinstance(sections, list):
        return {}
    for section in sections:
        if not isinstance(section, Mapping):
            continue
        section_name = str(section.get("name") or "")
        ptch_tables = section.get("ptch_tables")
        if not isinstance(ptch_tables, list):
            continue
        for table_index, table in enumerate(ptch_tables):
            if not isinstance(table, Mapping):
                continue
            patch_sites = table.get("patch_sites")
            if not isinstance(patch_sites, list):
                continue
            for site in patch_sites:
                if not isinstance(site, Mapping):
                    continue
                owner_record_index = site.get("owner_record_index")
                owner_local_offset = site.get("owner_local_offset")
                if not isinstance(owner_record_index, int) or not isinstance(owner_local_offset, int):
                    continue
                target_status = str(site.get("target_status") or "unresolved")
                target = _hkx_havok_xml_reference_target(site)
                reference_category = str(site.get("reference_category") or "")
                if target_status == "null":
                    reference_category = "null_reference"
                elif not target:
                    reference_category = reference_category or "patch_offset_candidate"
                reference = {
                    "offset": owner_local_offset,
                    "hex_offset": f"0x{owner_local_offset:X}",
                    "reference_kind": (
                        "ptch_object_patch"
                        if target_status == "object"
                        else "ptch_null_patch"
                        if target_status == "null"
                        else "ptch_patch_site"
                    ),
                    "reference_category": reference_category,
                    "raw_value": site.get("patch_value"),
                    "raw_value_hex": _hkx_hex(int(site.get("patch_value"))) if isinstance(site.get("patch_value"), int) else "",
                    "target": target,
                    "target_record_index": site.get("target_record_index"),
                    "target_type_index": site.get("target_type_index"),
                    "target_type_name": str(site.get("target_type_name") or ""),
                    "target_status": target_status,
                    "confidence": str(site.get("confidence") or "strong inference"),
                    "source": "PTCH",
                    "fixup_source": "PTCH",
                    "fixup_backed": True,
                    "section": section_name,
                    "ptch_table_index": table_index,
                    "ptch_word_index": site.get("ptch_word_index"),
                    "ptch_patch_site_index": site.get("index"),
                    "ptch_patch_site_offset": site.get("patch_site_offset"),
                    "ptch_patch_site_hex_offset": str(site.get("patch_site_hex_offset") or ""),
                    "description": (
                        "PTCH-backed reference patch site. The PTCH word identifies this owner-local slot, and "
                        "the patched slot value is interpreted as a target ITEM record index or null."
                    ),
                }
                refs_by_owner[owner_record_index][owner_local_offset] = {
                    key: value for key, value in reference.items() if value not in (None, "")
                }
    return refs_by_owner


def _hkx_havok_xml_record_strings(objects: Sequence[Mapping[str, object]]) -> Dict[int, str]:
    strings: Dict[int, str] = {}
    for object_info in objects:
        if not isinstance(object_info, Mapping) or str(object_info.get("type_name") or "") != "char":
            continue
        record_index = object_info.get("record_index")
        if not isinstance(record_index, int):
            continue
        decoded_fields = object_info.get("decoded_fields")
        if isinstance(decoded_fields, Mapping):
            decoded_string = decoded_fields.get("decoded_string")
            if isinstance(decoded_string, Mapping) and isinstance(decoded_string.get("value"), str):
                strings[record_index] = str(decoded_string["value"])
                continue
        layout = object_info.get("layout")
        layout_fields = layout.get("fields") if isinstance(layout, Mapping) else None
        if isinstance(layout_fields, list):
            for field in layout_fields:
                if (
                    isinstance(field, Mapping)
                    and str(field.get("name") or "") == "ascii_or_utf8_text"
                    and isinstance(field.get("value"), str)
                ):
                    strings[record_index] = str(field["value"])
                    break
    return strings


def _hkx_havok_xml_reference_record_index(reference: Optional[Mapping[str, object]]) -> Optional[int]:
    if not isinstance(reference, Mapping):
        return None
    target_record_index = reference.get("target_record_index")
    if isinstance(target_record_index, int):
        return target_record_index
    if isinstance(target_record_index, str) and target_record_index.strip().lstrip("-").isdigit():
        return int(target_record_index)
    return None


def _hkx_havok_xml_pair_low_count(field: Mapping[str, object]) -> Tuple[Optional[int], Optional[int]]:
    value = field.get("value")
    if isinstance(value, int):
        return int(value & 0xFFFFFFFF), None
    if not isinstance(value, Mapping):
        return None, None
    low_value = None
    for key in ("data_or_reference", "data_or_offset", "low_u32", "a", "raw_value"):
        candidate = value.get(key)
        if isinstance(candidate, int):
            low_value = int(candidate)
            break
    if low_value is None and isinstance(value.get("raw_u64"), int):
        low_value = int(value["raw_u64"]) & 0xFFFFFFFF
    count_value = None
    for key in ("count_or_flags", "row_count", "value_count", "record_count", "pair_count", "decoded_value_count", "b", "high_u32"):
        candidate = value.get(key)
        if isinstance(candidate, int):
            count_value = int(candidate)
            break
    return low_value, count_value


def _hkx_havok_xml_numelements_for_field(type_name: str, field: Mapping[str, object]) -> Optional[int]:
    member = _hkx_havok_member_by_source_name(type_name, str(field.get("name") or ""))
    array_status = str(member.get("array_status") or "") if isinstance(member, Mapping) else _hkx_havok_array_status_for_field(type_name, field)
    data_type = str(member.get("type") or field.get("data_type") or "") if isinstance(member, Mapping) else str(field.get("data_type") or "")
    value = field.get("value")
    if isinstance(value, Mapping):
        for key in ("count_or_flags", "row_count", "value_count", "record_count", "pair_count", "decoded_value_count"):
            candidate = value.get(key)
            if isinstance(candidate, int) and 0 <= candidate <= 10_000_000:
                return int(candidate)
    if isinstance(value, list):
        return len(value)
    if array_status in {"hkArray", "row_list", "scalar_list", "array_like", "string_data"} or "[]" in data_type or data_type.startswith("hkArray<"):
        _low, count = _hkx_havok_xml_pair_low_count(field)
        if isinstance(count, int) and 0 <= count <= 10_000_000:
            return int(count)
    return None


def _hkx_havok_xml_array_element_type(data_type: str) -> str:
    text = str(data_type or "").strip()
    if text.startswith("hkArray<") and text.endswith(">"):
        text = text[len("hkArray<") : -1].strip()
    while text.startswith("hkRefPtr<") and text.endswith(">"):
        text = text[len("hkRefPtr<") : -1].strip()
    return text


def _hkx_havok_xml_type_matches_expected(record_type_name: str, expected_type_name: str) -> bool:
    record_type = str(record_type_name or "")
    raw_expected = str(expected_type_name or "")
    if raw_expected.startswith("hkRefPtr<") and record_type.startswith("hkRefPtr<"):
        return True
    expected = _hkx_havok_xml_array_element_type(raw_expected)
    if not expected or expected in {"void", "void*", "hkReferencedObject*", "hkRefVariant"}:
        return True
    if record_type == expected:
        return True
    if expected == "hknpShape" and record_type.startswith("hknp") and record_type.endswith("Shape"):
        return True
    return False


def _hkx_havok_xml_target_record_for_offset(value: Optional[int], summary: HkxTagfileSummary) -> Optional[HkxItemRecord]:
    if not isinstance(value, int) or value <= 0:
        return None
    for record in summary.item_records:
        if int(record.data_offset) == value:
            return record
    for record in summary.item_records:
        if record.absolute_data_offset is not None and int(record.absolute_data_offset) == value:
            return record
    return None


def _hkx_havok_xml_apply_sibling_array_counts(fields: Sequence[MutableMapping[str, object]]) -> None:
    by_name = {str(field.get("hkparam_name") or field.get("name") or ""): field for field in fields if isinstance(field, MutableMapping)}
    for name, field in list(by_name.items()):
        if not name.endswith("Size"):
            continue
        value = field.get("value")
        if not isinstance(value, int) or value < 0:
            continue
        owner_name = name[: -len("Size")]
        owner = by_name.get(owner_name)
        if isinstance(owner, MutableMapping) and str(owner.get("array_status") or "") in {"hkArray", "array_like"}:
            owner.setdefault("numelements", int(value))
    data_field = by_name.get("data")
    size_field = by_name.get("size")
    if isinstance(data_field, MutableMapping) and isinstance(size_field, Mapping) and isinstance(size_field.get("value"), int):
        data_field.setdefault("numelements", int(size_field["value"]))


def _hkx_havok_xml_enrich_reference_field(
    field: MutableMapping[str, object],
    *,
    source_type_name: str,
    source_field: Mapping[str, object],
    summary: HkxTagfileSummary,
    char_strings_by_record: Mapping[int, str],
    existing_reference: Optional[Mapping[str, object]],
) -> None:
    numelements = _hkx_havok_xml_numelements_for_field(source_type_name, source_field)
    if numelements is not None:
        field["numelements"] = int(numelements)

    reference_category = str(field.get("reference_category") or field.get("reference_status") or "")
    low_value, count_value = _hkx_havok_xml_pair_low_count(source_field)
    if (
        low_value == 0
        and (count_value in {None, 0})
        and reference_category in {"object_reference", "string_reference", "type_class_reference", "array_data_reference"}
    ):
        field["hkparam_text"] = "null"
        field["value"] = None
        field["reference_target"] = ""
        field["reference_kind"] = "null"
        field["reference_category"] = "null_reference"
        field["reference_status"] = "null_reference"
        field["reference_target_type"] = ""
        field["confidence"] = "strong inference"
        if str(field.get("array_status") or "") == "hkArray":
            field["numelements"] = 0
        field["description"] = (
            str(field.get("description") or "")
            + " Zero reference payload is emitted as null in the Havok XML parity view."
        ).strip()
        return
    target_record_index = _hkx_havok_xml_reference_record_index(existing_reference)
    if target_record_index is not None and reference_category in {"string_reference", "type_class_reference"}:
        target_text = char_strings_by_record.get(target_record_index)
        if target_text:
            field["hkparam_text"] = target_text
            field["value"] = target_text
            field["reference_target"] = f"#record{target_record_index}"
            field["reference_status"] = reference_category
            field["confidence"] = "strong inference"
            field["description"] = (
                str(field.get("description") or "")
                + " Resolved referenced char record to text for Havok XML browsing; string edits remain ignored by CDMW import."
            ).strip()

    array_status = str(field.get("array_status") or "")
    data_type = str(field.get("type") or "")
    if array_status != "hkArray" and not data_type.startswith("hkArray<"):
        return
    target_record = _hkx_havok_xml_target_record_for_offset(low_value, summary)
    if target_record is None:
        return
    expected_type = _hkx_havok_xml_array_element_type(data_type)
    confidence = "strong inference" if _hkx_havok_xml_type_matches_expected(target_record.type_name, expected_type) else "experimental"
    target = f"#record{target_record.index}"
    field["hkparam_text"] = target
    field["value"] = target
    field["reference_target"] = target
    field["reference_kind"] = "owner_array_field"
    field["reference_category"] = "array_data_reference"
    field["reference_status"] = "array_data_reference"
    field["reference_target_type"] = target_record.type_name
    field["confidence"] = confidence
    if isinstance(count_value, int) and 0 <= count_value <= 10_000_000:
        field["numelements"] = int(count_value)
    field["description"] = (
        f"Owner-field array resolution linked {source_type_name}.{field.get('hkparam_name') or field.get('name')} "
        "to a recovered ITEM record. Array count changes remain blocked by CDMW import."
    )


def _hkx_havok_xml_array_value_fields(object_info: Mapping[str, object]) -> List[Dict[str, object]]:
    type_name = str(object_info.get("type_name") or "")
    decoded_fields = object_info.get("decoded_fields")
    if not isinstance(decoded_fields, Mapping):
        return []
    fields: List[Dict[str, object]] = []
    if type_name == "hkFloat3" and isinstance(decoded_fields.get("float3_rows"), list):
        rows = decoded_fields["float3_rows"]
        fields.append(
            {
                "name": "values",
                "type": "hkArray<hkFloat3>",
                "offset": 0,
                "hex_offset": "0x0",
                "size": object_info.get("byte_length"),
                "value": rows,
                "hkparam_name": "values",
                "hkparam_text": _hkx_havok_xml_param_text(rows),
                "numelements": len(rows),
                "reference_target": "",
                "reference_kind": "",
                "reference_category": "",
                "reference_target_type": "",
                "array_status": "row_list",
                "reference_status": "none",
                "editable": False,
                "confidence": "strong inference",
                "description": "Havok-style row list for decoded hkFloat3 array data. Row count changes remain blocked by CDMW import.",
            }
        )
    elif type_name == "hkVector4" and isinstance(decoded_fields.get("float4_rows"), list):
        rows = decoded_fields["float4_rows"]
        fields.append(
            {
                "name": "values",
                "type": "hkArray<hkVector4>",
                "offset": 0,
                "hex_offset": "0x0",
                "size": object_info.get("byte_length"),
                "value": rows,
                "hkparam_name": "values",
                "hkparam_text": _hkx_havok_xml_param_text(rows),
                "numelements": len(rows),
                "reference_target": "",
                "reference_kind": "",
                "reference_category": "",
                "reference_target_type": "",
                "array_status": "row_list",
                "reference_status": "none",
                "editable": False,
                "confidence": "strong inference",
                "description": "Havok-style row list for decoded hkVector4 array data. Row count changes remain blocked by CDMW import.",
            }
        )
    elif type_name in _HKX_SCALAR_ARRAY_TYPES:
        scalar_values = decoded_fields.get("scalar_values")
        values = scalar_values.get("values") if isinstance(scalar_values, Mapping) else None
        if isinstance(values, list):
            member_type = _HKX_SCALAR_ARRAY_TYPES[type_name][1].replace("[]", "")
            fields.append(
                {
                    "name": "values",
                    "type": f"hkArray<{member_type}>",
                    "offset": 0,
                    "hex_offset": "0x0",
                    "size": object_info.get("byte_length"),
                    "value": values,
                    "hkparam_name": "values",
                    "hkparam_text": _hkx_havok_xml_param_text(values),
                    "numelements": len(values),
                    "reference_target": "",
                    "reference_kind": "",
                    "reference_category": "",
                    "reference_target_type": "",
                    "array_status": "scalar_list",
                    "reference_status": "none",
                    "editable": False,
                    "confidence": "strong inference",
                    "description": "Havok-style scalar list for decoded array data. Count changes remain blocked by CDMW import.",
                }
            )
    elif type_name == "char" and isinstance(decoded_fields.get("decoded_string"), Mapping):
        string_value = decoded_fields["decoded_string"].get("value")
        if isinstance(string_value, str):
            fields.append(
                {
                    "name": "string",
                    "type": "char[]",
                    "offset": 0,
                    "hex_offset": "0x0",
                    "size": object_info.get("byte_length"),
                    "value": string_value,
                    "hkparam_name": "string",
                    "hkparam_text": string_value,
                    "numelements": len(string_value),
                    "reference_target": "",
                    "reference_kind": "",
                    "reference_category": "",
                    "reference_target_type": "",
                    "array_status": "string_data",
                    "reference_status": "none",
                    "editable": False,
                    "confidence": "confirmed",
                    "description": "Decoded string data. String length edits remain blocked because they would change record size and references.",
                }
            )
    return fields


def _hkx_havok_xml_root_recovery(hkobjects: Sequence[Mapping[str, object]]) -> Dict[str, object]:
    by_id = {str(obj.get("id") or ""): obj for obj in hkobjects if isinstance(obj, Mapping)}
    named_variants = _hkx_havok_xml_named_variants(hkobjects)
    preferred_classes = (
        "hkRootLevelContainer",
        "hknpPhysicsSceneData",
        "hknpPhysicsSystemData",
        "hknpRagdollData",
        "hkaAnimationContainer",
    )
    for class_name in preferred_classes:
        for obj in hkobjects:
            if not isinstance(obj, Mapping) or str(obj.get("class") or "") != class_name:
                continue
            return {
                "toplevelobject": str(obj.get("id") or ""),
                "class": class_name,
                "method": "preferred_root_class",
                "confidence": "strong inference" if class_name == "hkRootLevelContainer" else "experimental",
                "description": "Root selected from known Havok root/container classes instead of record order.",
                "named_variant_count": len(named_variants),
                "named_variants": named_variants,
            }
    for obj in hkobjects:
        if not isinstance(obj, Mapping) or str(obj.get("class") or "") != "hkRootLevelContainer::NamedVariant":
            continue
        fields = obj.get("fields")
        if not isinstance(fields, list):
            continue
        for field in fields:
            if not isinstance(field, Mapping) or str(field.get("hkparam_name") or "") != "variant":
                continue
            target = str(field.get("reference_target") or "")
            target_obj = by_id.get(target)
            if isinstance(target_obj, Mapping):
                return {
                    "toplevelobject": target,
                    "class": str(target_obj.get("class") or ""),
                    "method": "named_variant_object_reference",
                    "confidence": str(field.get("confidence") or "experimental"),
                    "description": "Root selected from hkRootLevelContainer::NamedVariant.variant reference.",
                    "named_variant_count": len(named_variants),
                    "named_variants": named_variants,
                }
    fallback = str(hkobjects[0].get("id") or "") if hkobjects and isinstance(hkobjects[0], Mapping) else ""
    return {
        "toplevelobject": fallback,
        "class": str(hkobjects[0].get("class") or "") if hkobjects and isinstance(hkobjects[0], Mapping) else "",
        "method": "first_record_fallback",
        "confidence": "raw" if fallback else "none",
        "description": "No known root class or named-variant root reference was recovered; using first exported record.",
        "named_variant_count": len(named_variants),
        "named_variants": named_variants,
    }


def _hkx_havok_xml_named_variants(hkobjects: Sequence[Mapping[str, object]]) -> List[Dict[str, object]]:
    by_id = {str(obj.get("id") or ""): obj for obj in hkobjects if isinstance(obj, Mapping)}
    variants: List[Dict[str, object]] = []
    for obj in hkobjects:
        if not isinstance(obj, Mapping) or str(obj.get("class") or "") != "hkRootLevelContainer::NamedVariant":
            continue
        fields = obj.get("fields")
        if not isinstance(fields, list):
            continue
        by_name = {
            str(field.get("hkparam_name") or field.get("name") or ""): field
            for field in fields
            if isinstance(field, Mapping)
        }
        target = str(by_name.get("variant", {}).get("reference_target") or "")
        target_obj = by_id.get(target)
        variants.append(
            {
                "record": str(obj.get("id") or ""),
                "name": str(by_name.get("name", {}).get("hkparam_text") or ""),
                "className": str(by_name.get("className", {}).get("hkparam_text") or ""),
                "class_reference_target": str(by_name.get("className", {}).get("reference_target") or ""),
                "variant": target,
                "variant_class": str(target_obj.get("class") or "") if isinstance(target_obj, Mapping) else "",
                "confidence": str(by_name.get("variant", {}).get("confidence") or obj.get("confidence") or "experimental"),
            }
        )
    return variants


def _hkx_havok_class_metadata(
    type_info: HkxTypeInfo,
    members: Sequence[Mapping[str, object]],
    observed_fields: Sequence[Mapping[str, object]],
) -> Dict[str, object]:
    max_member_end = 0
    for field in observed_fields:
        if not isinstance(field, Mapping):
            continue
        offset = field.get("offset")
        size = field.get("size")
        if isinstance(offset, int) and isinstance(size, int) and offset >= 0 and size >= 0:
            max_member_end = max(max_member_end, offset + size)
    for member in members:
        offset = member.get("offset")
        if isinstance(offset, int) and offset >= 0:
            max_member_end = max(max_member_end, offset)
    signature_seed = f"{type_info.display_name}|{len(members)}|{max_member_end}".encode("utf-8", errors="ignore")
    signature = int.from_bytes(hashlib.sha1(signature_seed).digest()[:4], "little")
    confidence_counts = Counter(str(member.get("confidence") or "experimental") for member in members if isinstance(member, Mapping))
    return {
        "parent": "",
        "object_size": max_member_end or None,
        "version": 0,
        "flags": "FLAGS_NONE",
        "signature": f"0x{signature:08X}",
        "member_count": len(members),
        "declared_member_count": len(members),
        "recovered_member_count": sum(1 for member in members if isinstance(member, Mapping) and bool(member.get("cdmw_recovered"))),
        "confidence_counts": dict(sorted(confidence_counts.items())),
        "metadata_status": "synthetic_recovered_hkClass",
        "real_hkclass_metadata_recovered": False,
        "metadata_source": "TNA1_TYPE_NAMES_PLUS_CDMW_LAYOUT_RECOVERY",
        "member_offset_confidence": "observed_layout" if members or observed_fields else "unknown",
        "unresolved_real_metadata": [
            "member_type_codes",
            "member_flags",
            "base_classes",
            "enum_refs",
            "signatures",
            "versions",
            "default_values",
            "template_refs",
        ],
    }


def _hkx_real_hkclass_metadata_by_name(summary: HkxTagfileSummary) -> Dict[str, Dict[str, object]]:
    report = summary.native_real_hkclass_metadata_v2 if isinstance(summary.native_real_hkclass_metadata_v2, Mapping) and summary.native_real_hkclass_metadata_v2 else summary.native_real_hkclass_metadata
    if not isinstance(report, Mapping):
        return {}
    classes = report.get("classes")
    if not isinstance(classes, list):
        return {}
    by_name: Dict[str, Dict[str, object]] = {}
    for row in classes:
        if not isinstance(row, Mapping):
            continue
        name = str(row.get("class_name") or row.get("name") or "")
        if name:
            by_name[name] = dict(row)
    return by_name


def _hkx_real_hkclass_member_rows(real_class: Mapping[str, object]) -> List[Dict[str, object]]:
    rows: List[Dict[str, object]] = []
    members = real_class.get("members")
    if not isinstance(members, list):
        return rows
    for member in members:
        if not isinstance(member, Mapping):
            continue
        member_type = str(member.get("type_name") or member.get("member_type_name") or "")
        subtype = str(member.get("subtype_name") or "")
        class_ref = str(member.get("class_ref_name") or "")
        enum_ref = str(member.get("enum_ref_name") or "")
        data_type = class_ref if member_type in {"TYPE_POINTER", "TYPE_ARRAY", "TYPE_STRUCT"} and class_ref else member_type
        rows.append(
            {
                "name": str(member.get("name") or ""),
                "type": data_type,
                "offset": member.get("offset"),
                "size": None,
                "array_status": "hkArray" if member_type in {"TYPE_ARRAY", "TYPE_SIMPLEARRAY", "TYPE_RELARRAY"} else "none",
                "reference_status": "object_reference"
                if member_type == "TYPE_POINTER"
                else "array_data_reference"
                if member_type in {"TYPE_ARRAY", "TYPE_SIMPLEARRAY", "TYPE_RELARRAY"}
                else "type_class_reference"
                if class_ref
                else "none",
                "member_type": member_type,
                "member_type_code": member.get("type_code") if member.get("type_code") is not None else member.get("member_type_code"),
                "subtype": subtype,
                "subtype_code": member.get("subtype_code"),
                "class_ref": class_ref,
                "class_ref_record_index": member.get("class_ref_record_index"),
                "enum_ref": enum_ref,
                "enum_ref_record_index": member.get("enum_ref_record_index"),
                "flags": str(member.get("flags_hex") or ""),
                "member_flags": member.get("flags"),
                "c_array_size": member.get("c_array_size"),
                "template_ref": str(member.get("template_ref") or ""),
                "storage": "real_hkClassMember",
                "is_array": member_type in {"TYPE_ARRAY", "TYPE_SIMPLEARRAY", "TYPE_RELARRAY"},
                "is_pointer": member_type == "TYPE_POINTER",
                "is_enum": member_type in {"TYPE_ENUM", "TYPE_FLAGS"} or bool(enum_ref),
                "confidence": str(member.get("confidence") or "strong inference"),
                "cdmw_recovered": False,
                "real_hkclass_metadata_recovered": True,
                "metadata_source": "HKCLASS_MEMBER_RECORD",
                "source_names": [],
            }
        )
    return rows


def _hkx_real_hkclass_metadata_document(real_class: Mapping[str, object], members: Sequence[Mapping[str, object]]) -> Dict[str, object]:
    recovered_requirements = (
        dict(real_class.get("recovered_requirements") or {})
        if isinstance(real_class.get("recovered_requirements"), Mapping)
        else {}
    )
    unresolved = [
        str(item)
        for item in real_class.get("unresolved_requirements", [])
        if str(item)
    ] if isinstance(real_class.get("unresolved_requirements"), list) else []
    signature_hex = str(real_class.get("signature_hex") or "")
    return {
        "parent": str(real_class.get("parent_name") or real_class.get("base_class") or ""),
        "object_size": real_class.get("object_size"),
        "version": real_class.get("version"),
        "flags": str(real_class.get("flags") if real_class.get("flags") is not None else "FLAGS_NONE"),
        "signature": signature_hex or _hkx_xml_scalar(real_class.get("signature")),
        "member_count": len(members),
        "declared_member_count": real_class.get("declared_member_count"),
        "recovered_member_count": len(members),
        "confidence_counts": {"strong inference": len(members)} if members else {},
        "metadata_status": "real_hkClass_records",
        "real_hkclass_metadata_recovered": True,
        "metadata_source": "HKCLASS_RECORDS_NATIVE",
        "member_offset_confidence": "real_hkClassMember_offsets",
        "unresolved_real_metadata": unresolved,
        "recovered_real_metadata": {
            key: bool(value)
            for key, value in recovered_requirements.items()
        },
        "record_index": real_class.get("record_index"),
        "parent_record_index": real_class.get("parent_record_index"),
        "defaults_record_index": real_class.get("defaults_record_index"),
        "attributes_record_index": real_class.get("attributes_record_index"),
        "declared_enum_count": real_class.get("declared_enum_count"),
        "members_record_index": real_class.get("members_record_index"),
        "enums_record_index": real_class.get("enums_record_index"),
    }


def _hkx_havok_xml_type_classes(
    summary: HkxTagfileSummary,
    objects: Sequence[Mapping[str, object]],
) -> List[Dict[str, object]]:
    observed_fields_by_type: Dict[str, List[Mapping[str, object]]] = defaultdict(list)
    for object_info in objects:
        if not isinstance(object_info, Mapping):
            continue
        type_name = str(object_info.get("type_name") or "")
        layout = object_info.get("layout")
        fields = layout.get("fields") if isinstance(layout, Mapping) else None
        if isinstance(fields, list):
            observed_fields_by_type[type_name].extend(field for field in fields if isinstance(field, Mapping))
    hkclasses: List[Dict[str, object]] = []
    real_hkclass_by_name = _hkx_real_hkclass_metadata_by_name(summary)
    emitted_real_names: set[str] = set()
    for type_info in summary.type_infos:
        display_name = type_info.display_name
        observed_fields = observed_fields_by_type.get(display_name, ())
        real_class = real_hkclass_by_name.get(display_name) or real_hkclass_by_name.get(type_info.name)
        if real_class is not None:
            member_rows = _hkx_real_hkclass_member_rows(real_class)
            class_metadata = _hkx_real_hkclass_metadata_document(real_class, member_rows)
            emitted_real_names.add(str(real_class.get("name") or display_name))
        else:
            member_rows = _hkx_havok_synthetic_member_rows(display_name, observed_fields)
            if not member_rows and display_name != type_info.name:
                member_rows = _hkx_havok_synthetic_member_rows(type_info.name, observed_fields)
            class_metadata = _hkx_havok_class_metadata(type_info, member_rows, observed_fields)
        hkclasses.append(
            {
                "id": f"#type{type_info.index}",
                "name": display_name,
                "base_name": type_info.name,
                "index": type_info.index,
                **class_metadata,
                "template_parameters": [
                    {"name": name, "value": value}
                    for name, value in type_info.template_parameters
                ],
                "members": member_rows,
            }
        )
    for real_name, real_class in sorted(real_hkclass_by_name.items()):
        if real_name in emitted_real_names:
            continue
        member_rows = _hkx_real_hkclass_member_rows(real_class)
        class_metadata = _hkx_real_hkclass_metadata_document(real_class, member_rows)
        hkclasses.append(
            {
                "id": f"#realtype{real_class.get('record_index')}",
                "name": real_name,
                "base_name": real_name,
                "index": real_class.get("record_index"),
                **class_metadata,
                "template_parameters": [],
                "members": member_rows,
            }
        )
    return hkclasses


