def _hkx_user_editing_guide_document(cdmw_compatibility: Mapping[str, object]) -> Dict[str, object]:
    status = str(cdmw_compatibility.get("status") or "unsupported")
    return {
        "status": status,
        "summary": (
            "Start with blue patchable rows in Structured Editor or Collision Editor. Treat grey/context rows as labels "
            "and clues. Export/import ignores descriptions, guidance, and relationship metadata."
        ),
        "confidence_legend": [
            {
                "label": "confirmed",
                "meaning": "Field is decoded or strongly validated by the converter. Still keep edits small.",
                "suggested_action": "Good first target for controlled value-only edits.",
            },
            {
                "label": "strong inference",
                "meaning": "Field behavior is inferred from repeated Crimson Desert HKX patterns and descriptor context.",
                "suggested_action": "Try small changes and compare in-game or in preview.",
            },
            {
                "label": "experimental",
                "meaning": "Field is readable, but the exact Havok meaning is still being recovered.",
                "suggested_action": "Use only on copies/mod output and change one value at a time.",
            },
            {
                "label": "raw preserved",
                "meaning": "Bytes are preserved for round-trip safety but not decoded enough for guided edits.",
                "suggested_action": "Do not edit unless you are intentionally reverse-engineering.",
            },
        ],
        "safe_first_edits": [
            "motor/constraint force or damping-like fixed float slots with low/medium edit risk",
            "sphere or capsule radius values that stay positive",
            "convex vertices/planes when preserving counts and topology",
            "mesh primitive tuple winding/order only, keeping the same four byte values per primitive",
        ],
        "avoid_until_decoded": [
            "adding/removing records, objects, shapes, vertices, faces, primitives, or arrays",
            "changing mesh primitive vertex sets, shape-tag ranges, byte-buffer lengths, or AABB tree nodes",
            "editing references, hkArray sizes/capacity, hkRefPtr targets, strings, or raw structural payloads",
            "large tuning jumps without testing one value at a time",
        ],
        "workflow": [
            "Use HKX Browser to identify bodies, shapes, constraints, motors, and related descriptor hints.",
            "Use Show in 3D Preview for mapped shapes/constraints before editing.",
            "Use Structured Editor for body/constraint/motor values and Collision Editor for shape values.",
            "Change one row, write a loose mod, test, then come back for the next row.",
        ],
    }


def _hkx_editor_group_title(group_key: str) -> str:
    return {
        "bodies": "Bodies",
        "collision_shapes": "Collision Shapes",
        "constraints": "Constraints",
        "motors": "Motors",
        "motion_damping": "Motion / Damping",
        "object_records": "Object Records",
        "raw_preserved_data": "Raw Preserved Data",
    }.get(group_key, group_key.replace("_", " ").title())


def _hkx_editor_selection_id(*parts: object) -> str:
    normalized = [
        re.sub(r"[^A-Za-z0-9_.:-]+", "_", str(part)).strip("_")
        for part in parts
        if part is not None and str(part) != ""
    ]
    return "/".join(normalized)


def _hkx_editor_add_row(
    rows_by_group: Dict[str, List[Dict[str, object]]],
    group: str,
    *,
    label: str,
    value: object = "",
    value_type: str = "",
    importable: bool = False,
    patch_path: str = "",
    editor_tab: str = "",
    record_index: object = None,
    item_index: object = None,
    offset: object = None,
    byte_offset: object = None,
    subject: str = "",
    field: str = "",
    confidence: str = "experimental",
    edit_risk: str = "",
    effect: str = "",
    explanation: str = "",
    if_increased: str = "",
    if_decreased: str = "",
    safe_edit_hint: str = "",
    value_constraints: str = "",
    source: str = "",
    viewer_selection_id: str = "",
    context_label: str = "",
    display_label: str = "",
    body_name: object = "",
    socket_name: object = "",
    fixed_socket_name: object = "",
    physics_material_name: object = "",
    shape_index: object = None,
    shape_type: object = "",
    context_source: object = "",
    context_confidence: object = "",
    identity_path: object = "",
) -> None:
    row: Dict[str, object] = {
        "id": _hkx_editor_selection_id(group, record_index, item_index, offset, field or label, len(rows_by_group[group])),
        "group": group,
        "label": label,
        "display_label": display_label or label,
        "subject": subject,
        "field": field or label,
        "value": value,
        "original_value": value,
        "value_type": value_type,
        "importable": bool(importable),
        "patch_path": patch_path,
        "editor_tab": editor_tab,
        "confidence": confidence,
        "edit_risk": edit_risk,
        "effect": effect,
        "explanation": explanation,
        "if_increased": if_increased,
        "if_decreased": if_decreased,
        "safe_edit_hint": safe_edit_hint,
        "value_constraints": value_constraints,
        "source": source,
        "viewer_selection_id": viewer_selection_id,
    }
    for key, row_value in (
        ("record_index", record_index),
        ("item_index", item_index),
        ("offset", offset),
        ("hex_offset", f"0x{int(offset):X}" if isinstance(offset, int) else None),
        ("absolute_byte_offset", byte_offset),
        ("hex_absolute_byte_offset", f"0x{int(byte_offset):X}" if isinstance(byte_offset, int) else None),
        ("context_label", context_label),
        ("body_name", body_name),
        ("socket_name", socket_name),
        ("fixed_socket_name", fixed_socket_name),
        ("physics_material_name", physics_material_name),
        ("shape_index", shape_index),
        ("shape_type", shape_type),
        ("context_source", context_source),
        ("context_confidence", context_confidence),
        ("identity_path", identity_path),
    ):
        if row_value not in (None, ""):
            row[key] = row_value
    rows_by_group[group].append(row)


def _hkx_editor_model_document(
    shapes: Sequence[Mapping[str, object]],
    physics_tuning: Optional[Mapping[str, object]],
    physics_body_summary: Optional[Mapping[str, object]],
    physics_constraint_summary: Optional[Mapping[str, object]],
    editable_field_catalog: Optional[Mapping[str, object]],
    byte_patch_map: Optional[Mapping[str, object]],
    objects: Sequence[Mapping[str, object]],
    advanced_payloads: Sequence[Mapping[str, object]],
) -> Dict[str, object]:
    group_order = [
        "bodies",
        "collision_shapes",
        "constraints",
        "motors",
        "motion_damping",
        "object_records",
        "raw_preserved_data",
    ]
    rows_by_group: Dict[str, List[Dict[str, object]]] = {group: [] for group in group_order}
    patch_entries_by_shape_field: Dict[Tuple[str, str], Mapping[str, object]] = {}
    if isinstance(byte_patch_map, Mapping):
        for entry in byte_patch_map.get("entries", []) if isinstance(byte_patch_map.get("entries"), list) else []:
            if isinstance(entry, Mapping):
                entry_path = str(entry.get("path") or "")
                shape_field_match = re.match(r"^shapes\[(\d+)\]\.([A-Za-z_][A-Za-z0-9_]*)", entry_path)
                if shape_field_match:
                    patch_entries_by_shape_field.setdefault((shape_field_match.group(1), shape_field_match.group(2)), entry)
    shape_index_by_record_index = {
        int(shape.get("shape_record_index")): int(shape.get("index"))
        for shape in shapes
        if isinstance(shape, Mapping)
        and isinstance(shape.get("shape_record_index"), int)
        and isinstance(shape.get("index"), int)
    }
    body_record_shape_links: Dict[int, int] = {}
    for object_info in objects:
        if not isinstance(object_info, Mapping):
            continue
        if str(object_info.get("type_name") or "") != "hknpPhysicsSystemData::ExtendedBodyCinfo":
            continue
        record_index = object_info.get("record_index")
        references = object_info.get("references")
        if not isinstance(record_index, int) or not isinstance(references, list):
            continue
        for reference in references:
            if not isinstance(reference, Mapping):
                continue
            target_record_index = reference.get("target_record_index")
            if isinstance(target_record_index, int) and target_record_index in shape_index_by_record_index:
                body_record_shape_links[int(record_index)] = shape_index_by_record_index[target_record_index]
                break

    body_context_by_shape_index: Dict[str, Dict[str, object]] = {}
    if isinstance(physics_body_summary, Mapping):
        for body in physics_body_summary.get("bodies", []) if isinstance(physics_body_summary.get("bodies"), list) else []:
            if not isinstance(body, Mapping):
                continue
            shape_index = body.get("shape_index")
            if shape_index in (None, ""):
                continue
            primary_context: Mapping[str, object] = {}
            descriptor_contexts = body.get("descriptor_contexts")
            if isinstance(descriptor_contexts, list):
                primary_context = next((context for context in descriptor_contexts if isinstance(context, Mapping)), {})
            body_context_by_shape_index[str(shape_index)] = {
                "body_name": body.get("body_name") or primary_context.get("body_name"),
                "socket_name": body.get("socket_name") or primary_context.get("socket_name"),
                "fixed_socket_name": body.get("fixed_socket_name") or primary_context.get("fixed_socket_name"),
                "physics_material_name": body.get("physics_material_name") or primary_context.get("physics_material_name"),
                "shape_index": shape_index,
                "shape_type": body.get("shape_type"),
                "context_source": primary_context.get("descriptor_path") or "physics_body_summary",
                "context_confidence": body.get("confidence") or primary_context.get("confidence") or "experimental",
            }

    def _context_label(context: Mapping[str, object], fallback: object = "") -> str:
        for key in ("body_name", "socket_name", "fixed_socket_name", "physics_material_name"):
            value = str(context.get(key) or "").strip()
            if value:
                return value
        return str(fallback or "").strip()

    def _context_identity_path(context: Mapping[str, object], field_name: object = "") -> str:
        parts = []
        for label, key in (
            ("body", "body_name"),
            ("socket", "socket_name"),
            ("fixed_socket", "fixed_socket_name"),
            ("material", "physics_material_name"),
        ):
            value = str(context.get(key) or "").strip()
            if value:
                parts.append(f"{label}:{value}")
        shape_index = context.get("shape_index")
        if shape_index not in (None, ""):
            parts.append(f"shape/{shape_index}")
        if field_name not in (None, "") and str(field_name).strip():
            parts.append(str(field_name).strip())
        return " -> ".join(parts)

    def _context_kwargs_for_shape(shape_index: object, field_name: object = "", fallback_label: object = "") -> Dict[str, object]:
        if shape_index in (None, ""):
            return {}
        context = body_context_by_shape_index.get(str(shape_index))
        if not isinstance(context, Mapping):
            fallback = str(fallback_label or "").strip()
            return {
                "shape_index": shape_index,
                "context_label": fallback,
                "display_label": f"{fallback}: {field_name}" if fallback and field_name else fallback or str(field_name or ""),
                "identity_path": f"shape/{shape_index} -> {field_name}".strip(" ->") if field_name else f"shape/{shape_index}",
            }
        label = _context_label(context, fallback_label)
        result = dict(context)
        result["context_label"] = label
        result["display_label"] = f"{label}: {field_name}" if label and field_name else label or str(fallback_label or "")
        result["identity_path"] = _context_identity_path(context, field_name)
        return result

    if isinstance(physics_body_summary, Mapping):
        for body in physics_body_summary.get("bodies", []) if isinstance(physics_body_summary.get("bodies"), list) else []:
            if not isinstance(body, Mapping):
                continue
            body_name = str(body.get("body_name") or f"shape {body.get('shape_index') or ''}").strip()
            shape_type = str(body.get("shape_type") or "")
            capsule = body.get("capsule")
            value = ""
            if isinstance(capsule, Mapping):
                radius = capsule.get("radius")
                length = capsule.get("length")
                value = "; ".join(
                    part
                    for part in (
                        f"radius={_hkx_xml_scalar(radius)}" if radius is not None else "",
                        f"length={_hkx_xml_scalar(length)}" if length is not None else "",
                    )
                    if part
                )
            _hkx_editor_add_row(
                rows_by_group,
                "bodies",
                label=body_name or "body",
                subject=shape_type,
                value=value,
                value_type="summary",
                confidence=str(body.get("confidence") or "experimental"),
                effect=str(body.get("simulation_role") or "body context"),
                explanation=str(body.get("description") or "Decoded body/shape context for identifying editable physics values."),
                source="physics_body_summary",
                viewer_selection_id=_hkx_editor_selection_id("shape", body.get("shape_index")),
                **_context_kwargs_for_shape(body.get("shape_index"), "body summary", body_name or "body"),
            )

    for shape in shapes:
        if not isinstance(shape, Mapping):
            continue
        shape_index = shape.get("index")
        shape_type = str(shape.get("shape_type") or "hknpShape")
        subject = _hkx_editable_shape_subject(shape)
        summary_parts = [shape_type]
        for key, label in (("center", "center"), ("extent", "extent")):
            value = shape.get(key)
            if isinstance(value, list) and len(value) == 3:
                summary_parts.append(f"{label}={_hkx_compact_vector(value)}")
        shape_record_index = shape.get("shape_record_index")
        if shape_record_index is not None:
            summary_parts.append(f"record={shape_record_index}")
        read_only_reason = str(shape.get("read_only_reason") or "")
        _hkx_editor_add_row(
            rows_by_group,
            "collision_shapes",
            label=f"{subject}: summary" if subject else f"shape {shape_index}: summary",
            subject=subject or shape_type,
            field="summary",
            value="; ".join(summary_parts),
            value_type="decoded shape summary",
            importable=False,
            editor_tab="Overview",
            record_index=shape_record_index,
            confidence="strong inference"
            if shape_type in {"hknpConvexShape", "hknpBoxShape", "hknpSphereShape", "hknpCapsuleShape"}
            else "experimental",
            edit_risk="not editable",
            effect="collision volume / preview target",
            explanation=(
                read_only_reason
                or "Decoded collision shape summary. This row is for browsing, filtering, and 3D preview selection; edit supported child values where available."
            ),
            safe_edit_hint="Read-only summary row. Use editable child rows or XML fixed-size fields where available.",
            source="collision_shapes",
            viewer_selection_id=_hkx_editor_selection_id("shape", shape_index),
            **_context_kwargs_for_shape(shape_index, "summary", subject or shape_type),
        )
        for field_name in shape.get("editable_fields", []) if isinstance(shape.get("editable_fields"), list) else []:
            field_name = str(field_name or "")
            if not field_name:
                continue
            value_summary = _hkx_editable_shape_field_value_summary(shape, field_name)
            patch_path = ""
            if field_name in {"sphere_radius", "capsule_radius"}:
                patch_path = f"shapes[{shape_index}].{field_name}"
            elif field_name in {"vertices", "planes", "capsule_endpoints"}:
                patch_path = f"shapes[{shape_index}].{field_name}[0]"
            patch_entry = patch_entries_by_shape_field.get((str(shape_index), field_name))
            semantics = _hkx_editable_catalog_semantics(
                {
                    "category": "collision_shape",
                    "name": field_name,
                    "description": _hkx_editable_shape_field_description(shape, field_name),
                }
            )
            _hkx_editor_add_row(
                rows_by_group,
                "collision_shapes",
                label=f"{subject}: {field_name}" if subject else f"shape {shape_index}: {field_name}",
                subject=subject or shape_type,
                field=field_name,
                value=value_summary,
                value_type="number/vector/table",
                importable=True,
                patch_path=patch_path or f"shapes[{shape_index}].{field_name}",
                editor_tab="Collision Editor",
                record_index=(patch_entry or {}).get("record_index") if isinstance(patch_entry, Mapping) else None,
                byte_offset=(patch_entry or {}).get("absolute_data_offset") if isinstance(patch_entry, Mapping) else None,
                confidence="strong inference" if field_name in {"vertices", "planes", "capsule_radius", "capsule_endpoints", "sphere_radius", "sphere_center"} else "experimental",
                edit_risk=str(semantics.get("edit_risk") or ""),
                effect=str(semantics.get("effect") or "collision volume"),
                explanation=_hkx_editable_shape_field_description(shape, field_name),
                safe_edit_hint=str(semantics.get("edit_guidance") or ""),
                value_constraints=str(semantics.get("value_constraints") or ""),
                source="shapes",
                viewer_selection_id=_hkx_editor_selection_id("shape", shape_index),
                **_context_kwargs_for_shape(shape_index, field_name, subject or shape_type),
            )
        mesh_details = shape.get("mesh_details")
        if isinstance(mesh_details, Mapping):
            editability = mesh_details.get("editability")
            if isinstance(editability, Mapping):
                blocked_operations = editability.get("blocked_operations")
                blocked_summary = ", ".join(str(item) for item in blocked_operations[:4]) if isinstance(blocked_operations, list) else ""
                _hkx_editor_add_row(
                    rows_by_group,
                    "collision_shapes",
                    label=f"{subject}: mesh editability",
                    subject=subject or shape_type,
                    field="mesh_editability",
                    value=str(editability.get("status") or "blocked"),
                    value_type="read-only safety gate",
                    importable=False,
                    editor_tab="Collision Editor",
                    record_index=shape_record_index,
                    confidence="confirmed",
                    edit_risk="not editable",
                    effect="mesh-shape topology safety",
                    explanation=(
                        "Mesh-shape topology editing is disabled until geometry sections, packed primitive words, "
                        "AABB nodes, and shape-tag ranges are decoded well enough to rebuild them safely."
                    ),
                    safe_edit_hint=str(editability.get("safe_current_behavior") or "") + (f"; blocked: {blocked_summary}" if blocked_summary else ""),
                    value_constraints="read-only; no primitive, AABB, shape-tag, or byte-buffer length changes",
                    source="mesh_details",
                    viewer_selection_id=_hkx_editor_selection_id("shape", shape_index),
                    **_context_kwargs_for_shape(shape_index, "mesh editability", subject or shape_type),
                )
                supported_operations = editability.get("supported_safe_operations")
                if isinstance(supported_operations, list) and supported_operations:
                    _hkx_editor_add_row(
                        rows_by_group,
                        "collision_shapes",
                        label=f"{subject}: supported mesh edit",
                        subject=subject or shape_type,
                        field="mesh_supported_safe_operation",
                        value="; ".join(str(operation) for operation in supported_operations[:3]),
                        value_type="guarded mesh edit",
                        importable=False,
                        editor_tab="Collision Editor",
                        record_index=shape_record_index,
                        confidence="strong inference",
                        edit_risk="guarded",
                        effect="mesh primitive winding/order",
                        explanation=(
                            "Primitive tuple winding can be edited when each primitive keeps the same vertex-index set. "
                            "This changes only tuple byte order and does not rebuild primitive counts, shape tags, or AABB data."
                        ),
                        safe_edit_hint="Use XML/JSON mesh_details primitive byte_indices for winding flips only.",
                        value_constraints="same primitive count; same four-byte tuple length; same non-0xFF index set per primitive",
                        source="mesh_details",
                        viewer_selection_id=_hkx_editor_selection_id("shape", shape_index),
                        **_context_kwargs_for_shape(shape_index, "supported mesh edit", subject or shape_type),
                    )
            primitive_analysis = mesh_details.get("primitive_analysis_summary")
            if isinstance(primitive_analysis, list):
                for analysis in primitive_analysis[:8]:
                    if not isinstance(analysis, Mapping):
                        continue
                    _hkx_editor_add_row(
                        rows_by_group,
                        "collision_shapes",
                        label=f"{subject}: primitive analysis record {analysis.get('record_index')}",
                        subject=subject or shape_type,
                        field="mesh_primitive_analysis",
                        value=(
                            f"count={analysis.get('count')}; vertex_index_range={analysis.get('candidate_index_range')}; "
                            f"quads={analysis.get('candidate_quad_count')}; triangles={analysis.get('candidate_triangle_count')}"
                        ),
                        value_type="read-only topology candidate",
                        importable=False,
                        editor_tab="Collision Editor",
                        record_index=analysis.get("record_index"),
                        confidence="experimental",
                        edit_risk="not editable",
                        effect="mesh primitive browser",
                        explanation=(
                            "Four-byte primitive tuple summary for schema recovery. It helps identify vertex-index "
                            "ranges and triangle/quad candidates, but is not a safe edit target yet."
                        ),
                        safe_edit_hint="Use this for comparing mesh-shape files; topology, AABB, and shape-tag rebuilds are still blocked.",
                        source="mesh_details",
                        viewer_selection_id=_hkx_editor_selection_id("shape", shape_index),
                        **_context_kwargs_for_shape(shape_index, "primitive analysis", subject or shape_type),
                    )

    if isinstance(physics_constraint_summary, Mapping):
        for constraint in physics_constraint_summary.get("constraints", []) if isinstance(physics_constraint_summary.get("constraints"), list) else []:
            if not isinstance(constraint, Mapping):
                continue
            constraint_name = str(constraint.get("name") or f"constraint {constraint.get('index') or ''}")
            descriptor_context = constraint.get("descriptor_context")
            constraint_context_kwargs: Dict[str, object] = {}
            if isinstance(descriptor_context, Mapping):
                context_label = _context_label(
                    descriptor_context,
                    constraint_name,
                )
                constraint_context_kwargs = {
                    "context_label": context_label,
                    "display_label": f"{context_label}: {constraint_name}" if context_label else constraint_name,
                    "body_name": descriptor_context.get("body_name"),
                    "socket_name": descriptor_context.get("socket_name"),
                    "fixed_socket_name": descriptor_context.get("fixed_socket_name"),
                    "context_source": descriptor_context.get("descriptor_path") or "constraint_descriptor_context",
                    "context_confidence": descriptor_context.get("confidence") or "descriptor_context",
                    "identity_path": _context_identity_path(descriptor_context, constraint_name),
                }
            _hkx_editor_add_row(
                rows_by_group,
                "constraints",
                label=constraint_name,
                subject=str(constraint.get("type_name") or ""),
                value=f"constraint_record={constraint.get('constraint_record_index')}; motor_record={constraint.get('motor_record_index')}",
                value_type="summary",
                confidence=str(constraint.get("confidence") or "experimental"),
                effect="joint limits / constraint behavior",
                explanation=str(constraint.get("description") or "Constraint summary; edit linked slots in Structured Editor."),
                source="physics_constraint_summary",
                viewer_selection_id=_hkx_editor_selection_id("constraint", constraint.get("index")),
                **constraint_context_kwargs,
            )
            for slot_group_name, group_name in (("constraint_slots", "constraints"), ("motor_slots", "motors")):
                for slot in constraint.get(slot_group_name, []) if isinstance(constraint.get(slot_group_name), list) else []:
                    if not isinstance(slot, Mapping):
                        continue
                    record_index = constraint.get("motor_record_index") if slot_group_name == "motor_slots" else constraint.get("constraint_record_index")
                    try:
                        item_index = int(slot.get("item_index"))
                        offset = int(slot.get("offset"))
                    except (TypeError, ValueError):
                        item_index = None
                        offset = None
                    guidance = _hkx_physics_tuning_user_guidance(str(slot.get("source_type_name") or constraint.get("type_name") or ""), int(offset or 0), str(slot.get("name") or ""))
                    _hkx_editor_add_row(
                        rows_by_group,
                        group_name,
                        label=f"{constraint_name}: {slot.get('name') or 'slot'}",
                        subject=constraint_name,
                        field=str(slot.get("name") or ""),
                        value=slot.get("value"),
                        value_type="float32",
                        importable=True,
                        patch_path=f"physics_tuning record {record_index} item {item_index} offset 0x{int(offset or 0):X}",
                        editor_tab="Structured Editor",
                        record_index=record_index,
                        item_index=item_index,
                        offset=offset,
                        confidence=str(slot.get("confidence") or "experimental"),
                        edit_risk=str(guidance.get("edit_risk") or ""),
                        effect=str(guidance.get("plain_language_effect") or ""),
                        explanation=str(slot.get("description") or ""),
                        if_increased=str(guidance.get("if_increased") or ""),
                        if_decreased=str(guidance.get("if_decreased") or ""),
                        safe_edit_hint=str(guidance.get("safe_edit_hint") or ""),
                        value_constraints=str(guidance.get("value_constraints") or ""),
                        source="physics_constraint_summary",
                        viewer_selection_id=_hkx_editor_selection_id("constraint", constraint.get("index")),
                        **{
                            **constraint_context_kwargs,
                            "display_label": (
                                f"{constraint_context_kwargs.get('context_label')}: {slot.get('name') or 'slot'}"
                                if constraint_context_kwargs.get("context_label")
                                else f"{constraint_name}: {slot.get('name') or 'slot'}"
                            ),
                            "identity_path": (
                                f"{constraint_context_kwargs.get('identity_path')} -> {slot.get('name') or 'slot'}"
                                if constraint_context_kwargs.get("identity_path")
                                else f"constraint/{constraint.get('index')} -> {slot.get('name') or 'slot'}"
                            ),
                        },
                    )

    if isinstance(physics_tuning, Mapping):
        for group_index, group in enumerate(physics_tuning.get("groups", []) if isinstance(physics_tuning.get("groups"), list) else []):
            if not isinstance(group, Mapping):
                continue
            category = str(group.get("category") or "physics_tuning")
            target_group = "motors" if category == "motor_force_response" else "motion_damping" if category == "motion_damping_solver" else "constraints" if category == "joint_limits_strength" else "bodies"
            linked_shape_index = body_record_shape_links.get(int(group.get("record_index"))) if isinstance(group.get("record_index"), int) else None
            group_viewer_selection_id = (
                _hkx_editor_selection_id("shape", linked_shape_index)
                if linked_shape_index is not None
                else _hkx_editor_selection_id("record", group.get("record_index"))
            )
            group_context_kwargs = _context_kwargs_for_shape(
                linked_shape_index,
                "",
                str(group.get("label") or group.get("type_name") or category),
            )
            group_owner_label = str(
                group_context_kwargs.get("context_label")
                or group.get("label")
                or group.get("type_name")
                or category
            )
            for vector_group in group.get("slot_vector_groups", []) if isinstance(group.get("slot_vector_groups"), list) else []:
                if not isinstance(vector_group, Mapping):
                    continue
                components = vector_group.get("components")
                value = ""
                if isinstance(components, Mapping):
                    value = " ".join(
                        f"{component}={_hkx_xml_scalar(components.get(component))}"
                        for component in ("x", "y", "z", "w")
                        if component in components
                    )
                _hkx_editor_add_row(
                    rows_by_group,
                    target_group,
                    label=f"{group_owner_label}: {vector_group.get('name') or 'vector'}",
                    subject=str(group_owner_label or group.get("type_name") or ""),
                    field=str(vector_group.get("name") or ""),
                    value=value,
                    value_type="vector group",
                    importable=False,
                    patch_path=f"physics_tuning.groups[{group_index}].slot_vector_groups",
                    editor_tab="Structured Editor",
                    record_index=group.get("record_index"),
                    item_index=vector_group.get("item_index"),
                    confidence=str(vector_group.get("confidence") or group.get("confidence") or "experimental"),
                    edit_risk=str(vector_group.get("edit_risk") or "high"),
                    effect=str(vector_group.get("likely_role") or category),
                    explanation=str(vector_group.get("description") or "Grouped adjacent float slots for readability."),
                    safe_edit_hint="Read-only grouping row. Edit the individual component rows below if you need to patch values.",
                    value_constraints="grouping metadata ignored on import; fixed-size component edits only",
                    source="physics_tuning",
                    viewer_selection_id=group_viewer_selection_id,
                    **{
                        **group_context_kwargs,
                        "display_label": f"{group_owner_label}: {vector_group.get('name') or 'vector'}",
                        "identity_path": (
                            f"{group_context_kwargs.get('identity_path')} -> {vector_group.get('name') or 'vector'}"
                            if group_context_kwargs.get("identity_path")
                            else f"record {group.get('record_index')} -> {vector_group.get('name') or 'vector'}"
                        ),
                    },
                )
            for slot_index, slot in enumerate(group.get("slots", []) if isinstance(group.get("slots"), list) else []):
                if not isinstance(slot, Mapping):
                    continue
                try:
                    item_index = int(slot.get("item_index"))
                    offset = int(slot.get("offset"))
                except (TypeError, ValueError):
                    item_index = None
                    offset = None
                _hkx_editor_add_row(
                    rows_by_group,
                    target_group,
                    label=f"{group_owner_label}: {slot.get('name') or slot_index}",
                    subject=str(group_owner_label or group.get("type_name") or ""),
                    field=str(slot.get("name") or ""),
                    value=slot.get("value"),
                    value_type="float32",
                    importable=True,
                    patch_path=f"physics_tuning.groups[{group_index}].slots[{slot_index}]",
                    editor_tab="Structured Editor",
                    record_index=group.get("record_index"),
                    item_index=item_index,
                    offset=offset,
                    confidence=str(slot.get("confidence") or group.get("confidence") or "experimental"),
                    edit_risk=str(slot.get("edit_risk") or ""),
                    effect=str(slot.get("plain_language_effect") or category),
                    explanation=str(slot.get("description") or group.get("description") or ""),
                    if_increased=str(slot.get("if_increased") or ""),
                    if_decreased=str(slot.get("if_decreased") or ""),
                    safe_edit_hint=str(slot.get("safe_edit_hint") or ""),
                    value_constraints=str(slot.get("value_constraints") or ""),
                    source="physics_tuning",
                    viewer_selection_id=group_viewer_selection_id,
                    **{
                        **group_context_kwargs,
                        "display_label": f"{group_owner_label}: {slot.get('name') or slot_index}",
                        "identity_path": (
                            f"{group_context_kwargs.get('identity_path')} -> {slot.get('name') or slot_index}"
                            if group_context_kwargs.get("identity_path")
                            else f"record {group.get('record_index')} item {item_index} offset {offset}"
                        ),
                    },
                )

    for object_info in objects:
        if not isinstance(object_info, Mapping):
            continue
        _hkx_editor_add_row(
            rows_by_group,
            "object_records",
            label=f"record {object_info.get('record_index')}: {object_info.get('type_name') or ''}",
            subject=str(object_info.get("type_name") or ""),
            value=f"{object_info.get('byte_length') or 0} bytes; status={object_info.get('status') or 'raw'}",
            value_type="object",
            record_index=object_info.get("record_index"),
            confidence=str(object_info.get("confidence") or object_info.get("status") or "raw"),
            explanation=str(object_info.get("description") or "Decoded or preserved ITEM object record."),
            source="objects",
            viewer_selection_id=_hkx_editor_selection_id("record", object_info.get("record_index")),
            context_label=str(object_info.get("type_name") or ""),
            display_label=f"record {object_info.get('record_index')}",
        )

    for payload in advanced_payloads:
        if not isinstance(payload, Mapping):
            continue
        if isinstance(payload.get("editable_values"), Mapping):
            continue
        _hkx_editor_add_row(
            rows_by_group,
            "raw_preserved_data",
            label=f"record {payload.get('record_index')}: {payload.get('type_name') or ''}",
            subject=str(payload.get("type_name") or ""),
            value=f"{payload.get('byte_length') or 0} bytes",
            value_type="raw_hex",
            record_index=payload.get("record_index"),
            confidence="raw",
            explanation=str(payload.get("description") or "Raw payload bytes preserved for byte-identical no-edit round-trip."),
            source="advanced_record_payloads",
            viewer_selection_id=_hkx_editor_selection_id("record", payload.get("record_index")),
            context_label=str(payload.get("type_name") or ""),
            display_label=f"record {payload.get('record_index')}",
        )

    groups = [
        {
            "key": group,
            "title": _hkx_editor_group_title(group),
            "row_count": len(rows_by_group[group]),
            "importable_row_count": sum(1 for row in rows_by_group[group] if bool(row.get("importable"))),
            "rows": rows_by_group[group],
        }
        for group in group_order
        if rows_by_group[group]
    ]
    importable_count = sum(int(group["importable_row_count"]) for group in groups)
    return {
        "status": "generated_from_current_decoder",
        "imported": False,
        "description": (
            "UI-ready HKX editor model. Rows are grouped for the guided workspace and are ignored on import; "
            "actual writes are validated against shapes, physics_tuning, advanced payloads, and byte lengths."
        ),
        "group_count": len(groups),
        "row_count": sum(int(group["row_count"]) for group in groups),
        "importable_row_count": importable_count,
        "groups": groups,
    }


def _hkx_graph_add_node(nodes: List[Dict[str, object]], seen: set[str], node_id: str, kind: str, label: str, **extra: object) -> None:
    if not node_id or node_id in seen:
        return
    seen.add(node_id)
    node = {"id": node_id, "kind": kind, "label": label}
    node.update({key: value for key, value in extra.items() if value is not None})
    nodes.append(node)


def _hkx_graph_add_edge(edges: List[Dict[str, object]], seen: set[Tuple[str, str, str]], source: str, target: str, relation: str, **extra: object) -> None:
    if not source or not target:
        return
    key = (source, target, relation)
    if key in seen:
        return
    seen.add(key)
    edge = {"source": source, "target": target, "relation": relation}
    edge.update({key: value for key, value in extra.items() if value is not None})
    edges.append(edge)


def _hkx_semantic_record_relation(source_type: str, target_type: str, raw_relation: str) -> Optional[Tuple[str, str]]:
    source = str(source_type or "")
    target = str(target_type or "")
    if source == "hknpPhysicsSystemData::ExtendedBodyCinfo" and (
        target.endswith("Shape") or target in {"hknpConvexShape", "hknpBoxShape", "hknpCapsuleShape", "hknpSphereShape", "hknpMeshShape"}
    ):
        return (
            "possible_body_shape",
            "A body construction record contains a word matching a shape ITEM offset. This likely links a body to its collision shape.",
        )
    if source in {"hknpRagdollConstraintData", "hknpLimitedHingeConstraintData", "hknpConstraintCinfo"} and target == "hknpPositionConstraintMotor":
        return (
            "possible_constraint_motor",
            "A constraint record contains a word matching a motor ITEM offset. This may link the joint/constraint to its motor tuning.",
        )
    if source == "hknpConstraintCinfo" and target == "hknpPhysicsSystemData::ExtendedBodyCinfo":
        return (
            "possible_constraint_body",
            "A constraint-info record contains a word matching a body-info ITEM offset. This may identify one constrained body.",
        )
    if source in {"hknpPhysicsSceneData", "hknpRagdollData"} and target == "hknpPhysicsSystemData::ExtendedBodyCinfo":
        return (
            "possible_system_body_array",
            "A scene/ragdoll container contains a word matching a body-info ITEM offset.",
        )
    if source in {"hknpPhysicsSceneData", "hknpRagdollData"} and target in {"hknpRagdollConstraintData", "hknpLimitedHingeConstraintData", "hknpConstraintCinfo"}:
        return (
            "possible_system_constraint_array",
            "A scene/ragdoll container contains a word matching a constraint ITEM offset.",
        )
    if source == "hknpCompoundShape" and target == "hknpShapeInstance":
        return (
            "possible_compound_shape_instances",
            "A compound shape contains a word matching shape-instance storage.",
        )
    if source == "hknpShapeInstance" and target.startswith("hknp") and "Shape" in target:
        return (
            "possible_child_shape",
            "A shape-instance row contains a word matching a child shape record.",
        )
    return None


def _hkx_relationship_link_evidence(reference: Mapping[str, object], relation: str = "") -> str:
    source = str(reference.get("reference_source") or reference.get("reference_category") or reference.get("source") or "").casefold()
    category = str(reference.get("reference_category") or reference.get("category") or "").casefold()
    confidence = str(reference.get("confidence") or "").casefold()
    if source.startswith(("ptch", "fixup")) or category.startswith(("ptch", "fixup")) or bool(reference.get("fixup_backed")):
        return "fixup_backed"
    if category == "array_data_reference" or source in {"native_owner_array", "owner_array"}:
        return "declared_owner_array"
    if source == "typed_layout":
        return "typed_layout"
    if confidence == "confirmed" or str(relation or "").casefold() in {"has_editable_value", "writes_byte_offset", "decoded_from"}:
        return "exact"
    if category in {"object_reference", "data_reference", "type_reference", "string_reference"}:
        return "inferred"
    return "inferred"


def _hkx_relationship_graph_document(
    summary: HkxTagfileSummary,
    shapes: Sequence[Mapping[str, object]],
    objects: Sequence[Mapping[str, object]],
    physics_tuning: Optional[Mapping[str, object]],
    physics_body_context: Optional[Mapping[str, object]],
    physics_body_summary: Optional[Mapping[str, object]],
    physics_constraint_summary: Optional[Mapping[str, object]],
    editable_field_catalog: Optional[Mapping[str, object]],
    descriptor_hints: Sequence[Mapping[str, object]],
    byte_patch_map: Optional[Mapping[str, object]],
) -> Dict[str, object]:
    nodes: List[Dict[str, object]] = []
    edges: List[Dict[str, object]] = []
    node_ids: set[str] = set()
    edge_ids: set[Tuple[str, str, str]] = set()

    file_id = "file:hkx"
    _hkx_graph_add_node(nodes, node_ids, file_id, "file", "HKX file", sdk_version=summary.sdk_version)
    payload_summary_by_record = {item.record_index: item for item in summary.item_payload_summaries}

    def _text_key(value: object) -> str:
        return re.sub(r"\s+", " ", str(value or "").strip()).casefold()

    def _viewer_id(kind: str, index: object) -> str:
        return _hkx_editor_selection_id(kind, index)

    def _record_node(record_index: object) -> str:
        return f"record:{record_index}" if record_index not in (None, "") else ""

    def _shape_viewer_id_from_path(path: object) -> str:
        match = re.search(r"shapes\[(\d+)\]", str(path or ""))
        return _viewer_id("shape", match.group(1)) if match else ""

    def _patch_identity_path(entry: Mapping[str, object]) -> str:
        parts = [str(entry.get("path") or "byte patch")]
        record_index = entry.get("record_index")
        if record_index not in (None, ""):
            parts.append(f"record {record_index}")
        if entry.get("hex_absolute_data_offset") not in (None, ""):
            parts.append(str(entry.get("hex_absolute_data_offset")))
        return " -> ".join(parts)

    patch_by_shape_index: Dict[str, List[Mapping[str, object]]] = defaultdict(list)
    patch_by_record_item_offset: Dict[Tuple[str, str, str], List[Mapping[str, object]]] = defaultdict(list)
    patch_by_record: Dict[str, List[Mapping[str, object]]] = defaultdict(list)
    if isinstance(byte_patch_map, Mapping):
        for entry in byte_patch_map.get("entries", []) if isinstance(byte_patch_map.get("entries"), list) else []:
            if not isinstance(entry, Mapping):
                continue
            patch_id = f"patch:{entry.get('index')}"
            patch_path = str(entry.get("path") or "")
            record_index = entry.get("record_index")
            if record_index not in (None, ""):
                patch_by_record[str(record_index)].append(entry)
            viewer_selection_id = _shape_viewer_id_from_path(patch_path)
            shape_match = re.search(r"shapes\[(\d+)\]", patch_path)
            if shape_match:
                patch_by_shape_index[shape_match.group(1)].append(entry)
            item_index = entry.get("item_index")
            relative_offset = entry.get("relative_offset")
            if record_index not in (None, "") and item_index not in (None, "") and isinstance(relative_offset, int):
                payload_summary = payload_summary_by_record.get(int(record_index)) if isinstance(record_index, int) else None
                stride_value = payload_summary.inferred_stride if payload_summary is not None else None
                try:
                    stride = int(stride_value) if stride_value is not None and abs(float(stride_value) - int(float(stride_value))) < 0.001 else 0
                    item_int = int(item_index)
                    local_offset = int(relative_offset) - item_int * stride if stride > 0 else int(relative_offset)
                except (TypeError, ValueError, OverflowError):
                    local_offset = -1
                if local_offset >= 0:
                    patch_by_record_item_offset[(str(record_index), str(item_index), str(local_offset))].append(entry)
            _hkx_graph_add_node(
                nodes,
                node_ids,
                patch_id,
                "byte_patch_target",
                str(patch_path or patch_id),
                category=entry.get("category"),
                name=entry.get("name"),
                subject=entry.get("subject"),
                record_index=entry.get("record_index"),
                item_index=entry.get("item_index"),
                row_index=entry.get("row_index"),
                component=entry.get("component"),
                relative_offset=entry.get("relative_offset"),
                hex_relative_offset=entry.get("hex_relative_offset"),
                absolute_data_offset=entry.get("absolute_data_offset"),
                hex_absolute_data_offset=entry.get("hex_absolute_data_offset"),
                byte_size=entry.get("byte_size"),
                value_type=entry.get("value_type"),
                confidence=entry.get("confidence"),
                effect=entry.get("effect"),
                viewer_selection_id=viewer_selection_id,
                identity_path=_patch_identity_path(entry),
                link_evidence="exact",
            )
            if record_index not in (None, ""):
                _hkx_graph_add_edge(
                    edges,
                    edge_ids,
                    patch_id,
                    f"record:{record_index}",
                    "writes_bytes",
                    record_index=record_index,
                    item_index=entry.get("item_index"),
                    offset=entry.get("relative_offset"),
                    hex_offset=entry.get("hex_relative_offset"),
                    hex_absolute_data_offset=entry.get("hex_absolute_data_offset"),
                    byte_size=entry.get("byte_size"),
                    value_type=entry.get("value_type"),
                    confidence=entry.get("confidence"),
                    viewer_selection_id=viewer_selection_id,
                    identity_path=_patch_identity_path(entry),
                    link_evidence="exact",
                )

    for section in summary.tag_items:
        node_id = f"section:{section.name}"
        _hkx_graph_add_node(
            nodes,
            node_ids,
            node_id,
            "tag_section",
            section.name,
            offset=section.offset,
            declared_length=section.declared_length,
        )
        _hkx_graph_add_edge(edges, edge_ids, file_id, node_id, "contains", link_evidence="exact")
    for record in summary.item_records:
        node_id = f"record:{record.index}"
        _hkx_graph_add_node(
            nodes,
            node_ids,
            node_id,
            "item_record",
            f"{record.index}: {record.type_name}",
            record_index=record.index,
            type_index=record.type_index,
            type_name=record.type_name,
            count=record.count,
            data_offset=record.data_offset,
        )
        _hkx_graph_add_edge(edges, edge_ids, "section:ITEM", node_id, "indexes", link_evidence="exact")
    reference_edge_count = 0
    record_type_by_index = {record.index: record.type_name for record in summary.item_records}
    fixup_backed_reference_edge_count = 0
    native_graph = summary.native_model_graph if isinstance(summary.native_model_graph, Mapping) else {}
    native_edges = native_graph.get("edges") if isinstance(native_graph, Mapping) else None
    if isinstance(native_edges, list):
        for native_edge in native_edges[:3000]:
            if not isinstance(native_edge, Mapping):
                continue
            source_id = str(native_edge.get("source") or "")
            target_id = str(native_edge.get("target") or "")
            relation = str(native_edge.get("relation") or "native_reference")
            if not source_id or not target_id:
                continue
            resolution_source = str(native_edge.get("resolution_source") or "")
            reference_category = str(native_edge.get("reference_category") or "")
            link_evidence = (
                "fixup_backed"
                if resolution_source == "ptch"
                else "declared_owner_array"
                if reference_category == "array_data_reference"
                else "typed_layout"
                if resolution_source == "typed_layout"
                else "inferred"
                if resolution_source == "inferred_offset"
                else "raw_observation"
            )
            source_record_index = native_edge.get("source_record_index")
            target_record_index = native_edge.get("target_record_index")
            source_type = record_type_by_index.get(source_record_index) if isinstance(source_record_index, int) else ""
            target_type = record_type_by_index.get(target_record_index) if isinstance(target_record_index, int) else ""
            owner_local_offset = native_edge.get("owner_local_offset")
            _hkx_graph_add_edge(
                edges,
                edge_ids,
                source_id,
                target_id,
                relation,
                record_index=source_record_index,
                target_record_index=target_record_index,
                owner_field=native_edge.get("owner_field_name"),
                offset=owner_local_offset,
                hex_offset=f"0x{owner_local_offset:X}" if isinstance(owner_local_offset, int) else "",
                reference_category=reference_category,
                reference_source=resolution_source or "native_model_graph",
                source_type=source_type,
                target_type=target_type,
                confidence=native_edge.get("confidence") or "experimental",
                description=(
                    "Native graph edge recovered from PTCH/fixup data."
                    if link_evidence == "fixup_backed"
                    else "Native graph edge recovered from owner-array context."
                    if link_evidence == "declared_owner_array"
                    else "Native graph edge recovered from decoded object layout."
                ),
                link_evidence=link_evidence,
            )
            reference_edge_count += 1
            if link_evidence == "fixup_backed":
                fixup_backed_reference_edge_count += 1
    native_owner_arrays = native_graph.get("owner_arrays") if isinstance(native_graph, Mapping) else None
    if isinstance(native_owner_arrays, list):
        for owner_array in native_owner_arrays[:1000]:
            if not isinstance(owner_array, Mapping):
                continue
            owner_record_index = owner_array.get("owner_record_index")
            target_record_index = owner_array.get("target_record_index")
            if not isinstance(owner_record_index, int) or not isinstance(target_record_index, int):
                continue
            field_name = str(owner_array.get("field_name") or "owner_array")
            _hkx_graph_add_edge(
                edges,
                edge_ids,
                f"record:{owner_record_index}",
                f"record:{target_record_index}",
                f"owner_array:{field_name}",
                record_index=owner_record_index,
                target_record_index=target_record_index,
                owner_field=field_name,
                offset=owner_array.get("owner_local_offset"),
                reference_category="array_data_reference",
                reference_source=owner_array.get("resolution_source") or "native_owner_array",
                array_type=owner_array.get("array_type"),
                element_type=owner_array.get("element_type"),
                numelements=owner_array.get("numelements"),
                confidence=owner_array.get("confidence") or "strong inference",
                description="Native owner-array mapping recovered from fixup/data pointer context.",
                link_evidence="declared_owner_array",
            )
            reference_edge_count += 1
    for object_info in objects:
        if not isinstance(object_info, Mapping):
            continue
        record_index = object_info.get("record_index")
        if not isinstance(record_index, int):
            continue
        references = object_info.get("references")
        if not isinstance(references, list):
            continue
        for reference in references:
            if not isinstance(reference, Mapping):
                continue
            target_record_index = reference.get("target_record_index")
            if not isinstance(target_record_index, int):
                continue
            relation = str(reference.get("reference_kind") or "possible_reference")
            link_evidence = _hkx_relationship_link_evidence(reference, relation)
            _hkx_graph_add_edge(
                edges,
                edge_ids,
                f"record:{record_index}",
                f"record:{target_record_index}",
                relation,
                offset=reference.get("offset"),
                hex_offset=reference.get("hex_offset"),
                raw_value=reference.get("raw_value"),
                raw_value_hex=reference.get("raw_value_hex"),
                reference_category=reference.get("reference_category"),
                confidence=reference.get("confidence") or "experimental",
                description=reference.get("description"),
                link_evidence=link_evidence,
            )
            reference_edge_count += 1
            if str(reference.get("reference_source") or reference.get("reference_category") or "").casefold().startswith(("ptch", "fixup")):
                fixup_backed_reference_edge_count += 1
            semantic_relation = _hkx_semantic_record_relation(
                str(object_info.get("type_name") or ""),
                str(reference.get("target_type_name") or ""),
                relation,
            )
            if semantic_relation is not None:
                semantic_name, semantic_description = semantic_relation
                _hkx_graph_add_edge(
                    edges,
                    edge_ids,
                    f"record:{record_index}",
                    f"record:{target_record_index}",
                    semantic_name,
                    offset=reference.get("offset"),
                    hex_offset=reference.get("hex_offset"),
                    raw_value=reference.get("raw_value"),
                    raw_relation=relation,
                    confidence="experimental",
                    description=semantic_description,
                    link_evidence=link_evidence if link_evidence == "fixup_backed" else "inferred",
                )
        layout = object_info.get("layout")
        fields = layout.get("fields") if isinstance(layout, Mapping) else None
        if not isinstance(fields, list):
            continue
        source_type_name = str(object_info.get("type_name") or "")
        for field in fields:
            if not isinstance(field, Mapping):
                continue
            value = field.get("value")
            if not isinstance(value, Mapping):
                continue
            target_record_index: Optional[int] = None
            relation = "possible_record_index_reference"
            description = "A decoded layout field contains a small integer that matches an ITEM record index."
            if source_type_name == "HavokShapeNameProperty" and isinstance(value.get("candidate_char_record_index"), int):
                target_record_index = int(value["candidate_char_record_index"])
                relation = "possible_shape_name_text"
                description = "Shape-name property likely points to a char/string record containing the body or shape label."
            elif source_type_name == "hkaSkeletonMapper" and isinstance(value.get("data_or_reference"), int):
                target_record_index = int(value["data_or_reference"])
                target_type = record_type_by_index.get(target_record_index, "")
                if target_type == "hkSkeleton":
                    relation = "possible_mapper_skeleton"
                    description = "Skeleton mapper header likely references one side of the source/target skeleton pair."
                elif target_type == "hkaSkeletonMapperData::SimpleMapping":
                    relation = "possible_mapper_simple_mapping"
                    description = "Skeleton mapper header likely references its compact SimpleMapping table."
                else:
                    relation = "possible_mapper_record"
                    description = "Skeleton mapper header contains a record-index-like value. Exact role is still inferred."
            elif source_type_name == "hkaAnimationContainer" and isinstance(value.get("data_or_reference"), int):
                target_record_index = int(value["data_or_reference"])
                relation = "possible_animation_container_record"
                description = "Animation container field contains a record-index-like value for a contained skeleton/animation object."
            if target_record_index is None or target_record_index not in record_type_by_index:
                continue
            _hkx_graph_add_edge(
                edges,
                edge_ids,
                f"record:{record_index}",
                f"record:{target_record_index}",
                relation,
                offset=field.get("offset"),
                hex_offset=field.get("hex_offset"),
                raw_value=target_record_index,
                confidence=field.get("confidence") or "experimental",
                description=description,
            )
    for shape in shapes:
        if not isinstance(shape, Mapping):
            continue
        shape_index = shape.get("index")
        shape_id = f"shape:{shape_index}"
        _hkx_graph_add_node(
            nodes,
            node_ids,
            shape_id,
            "collision_shape",
            f"{shape.get('shape_type') or 'shape'} {shape_index}",
            shape_index=shape_index,
            shape_type=shape.get("shape_type"),
            subject=_hkx_editable_shape_subject(shape),
        )
        record_index = shape.get("shape_record_index")
        if isinstance(record_index, int):
            _hkx_graph_add_edge(edges, edge_ids, shape_id, f"record:{record_index}", "decoded_from", link_evidence="exact")
        records = shape.get("records")
        if isinstance(records, Mapping):
            for name, record_value in records.items():
                if isinstance(record_value, int):
                    _hkx_graph_add_edge(edges, edge_ids, shape_id, f"record:{record_value}", f"uses_{name}", link_evidence="inferred")

    body_ids_by_key: Dict[str, List[str]] = defaultdict(list)

    def _register_body_key(body_id: str, value: object) -> None:
        key = _text_key(value)
        if key and body_id not in body_ids_by_key[key]:
            body_ids_by_key[key].append(body_id)

    if isinstance(physics_body_summary, Mapping):
        for body in physics_body_summary.get("bodies", []) if isinstance(physics_body_summary.get("bodies"), list) else []:
            if not isinstance(body, Mapping):
                continue
            body_index = body.get("index")
            body_id = f"body:{body_index}"
            shape_index = body.get("shape_index")
            viewer_selection_id = _viewer_id("shape", shape_index) if shape_index not in (None, "") else ""
            body_name = str(body.get("body_name") or body.get("socket_name") or body_id)
            material_name = str(body.get("physics_material_name") or "").strip()
            descriptor_contexts = body.get("descriptor_contexts")
            if isinstance(descriptor_contexts, list):
                for context in descriptor_contexts:
                    if not isinstance(context, Mapping):
                        continue
                    if not material_name and str(context.get("physics_material_name") or "").strip():
                        material_name = str(context.get("physics_material_name") or "").strip()
            identity_path = " -> ".join(
                part
                for part in (
                    f"body:{body_name}",
                    f"shape/{shape_index}" if shape_index not in (None, "") else "",
                    f"material:{material_name}" if material_name else "",
                )
                if part
            )
            _hkx_graph_add_node(
                nodes,
                node_ids,
                body_id,
                "body",
                body_name,
                body_index=body_index,
                shape_index=shape_index,
                shape_type=body.get("shape_type"),
                simulation_role=body.get("simulation_role"),
                socket_name=body.get("socket_name"),
                fixed_socket_name=body.get("fixed_socket_name"),
                physics_material_name=material_name,
                confidence=body.get("confidence"),
                viewer_selection_id=viewer_selection_id,
                identity_path=identity_path,
            )
            for key_name in ("body_name", "socket_name", "fixed_socket_name"):
                _register_body_key(body_id, body.get(key_name))
            if isinstance(descriptor_contexts, list):
                for context in descriptor_contexts:
                    if not isinstance(context, Mapping):
                        continue
                    for key_name in ("body_name", "socket_name", "fixed_socket_name"):
                        _register_body_key(body_id, context.get(key_name))
            if shape_index not in (None, ""):
                _hkx_graph_add_edge(
                    edges,
                    edge_ids,
                    body_id,
                    f"shape:{shape_index}",
                    "body_shape",
                    confidence=body.get("confidence"),
                    viewer_selection_id=viewer_selection_id,
                    identity_path=identity_path,
                    description="Body summary links this body/context row to the decoded collision shape.",
                    link_evidence="inferred",
                )
            if material_name:
                material_id = f"material:{_hkx_editor_selection_id(material_name)}"
                _hkx_graph_add_node(
                    nodes,
                    node_ids,
                    material_id,
                    "material",
                    material_name,
                    physics_material_name=material_name,
                    confidence=body.get("confidence") or "descriptor_context",
                    viewer_selection_id=viewer_selection_id,
                    identity_path=f"{identity_path} -> material:{material_name}" if identity_path else f"material:{material_name}",
                )
                _hkx_graph_add_edge(
                    edges,
                    edge_ids,
                    body_id,
                    material_id,
                    "uses_material",
                    confidence=body.get("confidence") or "descriptor_context",
                    viewer_selection_id=viewer_selection_id,
                    identity_path=f"{identity_path} -> material:{material_name}" if identity_path else f"material:{material_name}",
                    description="Descriptor/body context links this body to a material or simulation material name.",
                    link_evidence="inferred",
                )
            records = body.get("records")
            if isinstance(records, Mapping):
                for record_role, record_value in records.items():
                    if isinstance(record_value, int):
                        _hkx_graph_add_edge(
                            edges,
                            edge_ids,
                            body_id,
                            f"record:{record_value}",
                            f"body_uses_{record_role}",
                            confidence=body.get("confidence"),
                            viewer_selection_id=viewer_selection_id,
                            identity_path=identity_path,
                            link_evidence="inferred",
                        )
    if isinstance(physics_body_context, Mapping):
        for body_index, body in enumerate(physics_body_context.get("body_contexts", []) if isinstance(physics_body_context.get("body_contexts"), list) else []):
            if not isinstance(body, Mapping):
                continue
            body_id = f"body:{body_index}"
            _hkx_graph_add_node(nodes, node_ids, body_id, "body", str(body.get("body_name") or f"body {body_index}"), socket_name=body.get("socket_name"), simulation_role=body.get("simulation_role"))
            for key_name in ("body_name", "socket_name", "fixed_socket_name"):
                _register_body_key(body_id, body.get(key_name))
            for match in body.get("shape_matches", []) if isinstance(body.get("shape_matches"), list) else []:
                if isinstance(match, Mapping) and match.get("decoded_shape_index") is not None:
                    shape_index = match.get("decoded_shape_index")
                    _hkx_graph_add_edge(
                        edges,
                        edge_ids,
                        body_id,
                        f"shape:{shape_index}",
                        "matches_shape",
                        confidence=match.get("confidence"),
                        viewer_selection_id=_viewer_id("shape", shape_index),
                        identity_path=f"body:{body.get('body_name') or body_index} -> shape/{shape_index}",
                        link_evidence="inferred",
                    )
    tuning_owner_by_record: Dict[str, str] = {}
    if isinstance(physics_tuning, Mapping):
        for group_index, group in enumerate(physics_tuning.get("groups", []) if isinstance(physics_tuning.get("groups"), list) else []):
            if isinstance(group, Mapping) and group.get("record_index") not in (None, ""):
                tuning_owner_by_record[str(group.get("record_index"))] = f"tuning:{group_index}"
    constraint_owner_by_record_slot: Dict[Tuple[str, str, str], str] = {}
    if isinstance(physics_constraint_summary, Mapping):
        for constraint in physics_constraint_summary.get("constraints", []) if isinstance(physics_constraint_summary.get("constraints"), list) else []:
            if not isinstance(constraint, Mapping):
                continue
            constraint_index = constraint.get("index")
            constraint_id = f"constraint:{constraint_index}"
            viewer_selection_id = _viewer_id("constraint", constraint_index)
            constraint_name = str(constraint.get("name") or constraint_id)
            _hkx_graph_add_node(
                nodes,
                node_ids,
                constraint_id,
                "constraint",
                constraint_name,
                type_name=constraint.get("type_name"),
                confidence=constraint.get("confidence"),
                viewer_selection_id=viewer_selection_id,
                identity_path=f"constraint/{constraint_index}:{constraint_name}",
            )
            for key, relation in (("constraint_record_index", "decoded_from"), ("motor_record_index", "uses_motor")):
                record_index = constraint.get(key)
                if record_index not in (None, ""):
                    _hkx_graph_add_edge(
                        edges,
                        edge_ids,
                        constraint_id,
                        f"record:{record_index}",
                        relation,
                        record_index=record_index,
                        viewer_selection_id=viewer_selection_id,
                        identity_path=f"constraint/{constraint_index}:{constraint_name} -> record {record_index}",
                        link_evidence="exact" if relation == "decoded_from" else "inferred",
                    )
            descriptor_context = constraint.get("descriptor_context")
            if isinstance(descriptor_context, Mapping):
                body_keys = [
                    _text_key(descriptor_context.get(key_name))
                    for key_name in ("body_name", "socket_name", "fixed_socket_name")
                    if _text_key(descriptor_context.get(key_name))
                ]
                linked_body_ids: List[str] = []
                for body_key in body_keys:
                    for body_id in body_ids_by_key.get(body_key, []):
                        if body_id not in linked_body_ids:
                            linked_body_ids.append(body_id)
                for body_id in linked_body_ids[:4]:
                    _hkx_graph_add_edge(
                        edges,
                        edge_ids,
                        constraint_id,
                        body_id,
                        "constraint_body_context",
                        confidence=descriptor_context.get("confidence") or "descriptor_context",
                        viewer_selection_id=viewer_selection_id,
                        identity_path=f"constraint/{constraint_index}:{constraint_name} -> {body_id}",
                        description="Descriptor context names the body/socket this constraint is likely attached to.",
                        link_evidence="inferred",
                    )
            for slot_group_name, slot_source, record_key in (
                ("constraint_slots", "constraint", "constraint_record_index"),
                ("motor_slots", "motor", "motor_record_index"),
            ):
                slots = constraint.get(slot_group_name)
                if not isinstance(slots, list):
                    continue
                record_index = constraint.get(record_key)
                for slot in slots:
                    if not isinstance(slot, Mapping):
                        continue
                    item_index = slot.get("item_index")
                    offset = slot.get("offset")
                    if item_index in (None, "") or offset in (None, ""):
                        continue
                    value_id = f"value:constraint:{constraint_index}:{slot_source}:{item_index}:{offset}"
                    slot_name = str(slot.get("name") or f"{slot_source} slot")
                    constraint_owner_by_record_slot[(str(record_index), str(item_index), str(offset))] = constraint_id
                    identity_path = f"constraint/{constraint_index}:{constraint_name} -> {slot_name} -> record {record_index} item {item_index} offset {slot.get('hex_offset') or offset}"
                    _hkx_graph_add_node(
                        nodes,
                        node_ids,
                        value_id,
                        "editable_value",
                        slot_name,
                        category="constraint_motor",
                        field=slot_name,
                        value=slot.get("value"),
                        record_index=record_index,
                        item_index=item_index,
                        offset=offset,
                        hex_offset=slot.get("hex_offset"),
                        value_type="float32",
                        confidence=slot.get("confidence"),
                        editor_tab="Structured Editor",
                        importable=True,
                        viewer_selection_id=viewer_selection_id,
                        identity_path=identity_path,
                    )
                    _hkx_graph_add_edge(
                        edges,
                        edge_ids,
                        constraint_id,
                        value_id,
                        "has_editable_value",
                        confidence=slot.get("confidence"),
                        viewer_selection_id=viewer_selection_id,
                        identity_path=identity_path,
                        description="Constraint/motor slot exposed as a fixed-size editable value.",
                        link_evidence="exact",
                    )
                    if record_index not in (None, ""):
                        _hkx_graph_add_edge(
                            edges,
                            edge_ids,
                            value_id,
                            f"record:{record_index}",
                            "patches_record",
                            record_index=record_index,
                            item_index=item_index,
                            offset=offset,
                            hex_offset=slot.get("hex_offset"),
                            confidence=slot.get("confidence"),
                            viewer_selection_id=viewer_selection_id,
                            identity_path=identity_path,
                            link_evidence="exact",
                        )
                    for patch in patch_by_record_item_offset.get((str(record_index), str(item_index), str(offset)), [])[:8]:
                        patch_id = f"patch:{patch.get('index')}"
                        _hkx_graph_add_edge(
                            edges,
                            edge_ids,
                            value_id,
                            patch_id,
                            "writes_byte_offset",
                            record_index=record_index,
                            item_index=item_index,
                            offset=offset,
                            hex_offset=slot.get("hex_offset"),
                            hex_absolute_data_offset=patch.get("hex_absolute_data_offset"),
                            byte_size=patch.get("byte_size"),
                            value_type=patch.get("value_type"),
                            confidence=patch.get("confidence") or slot.get("confidence"),
                            viewer_selection_id=viewer_selection_id,
                            identity_path=f"{identity_path} -> {patch.get('hex_absolute_data_offset') or patch_id}",
                            description="Editable value is backed by this fixed byte patch target.",
                            link_evidence="exact",
                        )
    if isinstance(physics_tuning, Mapping):
        for group_index, group in enumerate(physics_tuning.get("groups", []) if isinstance(physics_tuning.get("groups"), list) else []):
            if not isinstance(group, Mapping):
                continue
            tuning_id = f"tuning:{group_index}"
            _hkx_graph_add_node(nodes, node_ids, tuning_id, "tuning_group", str(group.get("label") or group.get("category") or tuning_id), category=group.get("category"), type_name=group.get("type_name"))
            if group.get("record_index") is not None:
                _hkx_graph_add_edge(edges, edge_ids, tuning_id, f"record:{group.get('record_index')}", "patches_record", link_evidence="exact")
    if isinstance(editable_field_catalog, Mapping):
        fields = editable_field_catalog.get("fields")
        for field_index, field in enumerate(fields if isinstance(fields, list) else []):
            if not isinstance(field, Mapping):
                continue
            shape_index = field.get("shape_index")
            record_index = field.get("record_index")
            item_index = field.get("item_index")
            offset = field.get("offset")
            field_name = str(field.get("name") or field.get("field") or f"value {field_index}")
            viewer_selection_id = ""
            owner_id = ""
            owner_relation = "has_editable_value"
            if shape_index not in (None, ""):
                owner_id = f"shape:{shape_index}"
                viewer_selection_id = _viewer_id("shape", shape_index)
            elif (str(record_index), str(item_index), str(offset)) in constraint_owner_by_record_slot:
                owner_id = constraint_owner_by_record_slot[(str(record_index), str(item_index), str(offset))]
                viewer_selection_id = owner_id.replace(":", "/")
            elif record_index not in (None, "") and str(record_index) in tuning_owner_by_record:
                owner_id = tuning_owner_by_record[str(record_index)]
                viewer_selection_id = _viewer_id("record", record_index)
            elif record_index not in (None, ""):
                owner_id = _record_node(record_index)
                viewer_selection_id = _viewer_id("record", record_index)
                owner_relation = "record_editable_value"
            if not owner_id:
                continue
            value_id = f"value:catalog:{field_index}"
            identity_bits = [
                owner_id.replace(":", "/"),
                field_name,
            ]
            if record_index not in (None, ""):
                identity_bits.append(f"record {record_index}")
            if item_index not in (None, ""):
                identity_bits.append(f"item {item_index}")
            if offset not in (None, ""):
                identity_bits.append(f"offset {field.get('hex_offset') or offset}")
            identity_path = " -> ".join(identity_bits)
            _hkx_graph_add_node(
                nodes,
                node_ids,
                value_id,
                "editable_value",
                field_name,
                category=field.get("category"),
                subject=field.get("subject"),
                field=field_name,
                value=field.get("value_summary"),
                record_index=record_index,
                item_index=item_index,
                offset=offset,
                hex_offset=field.get("hex_offset"),
                shape_index=shape_index,
                shape_type=field.get("shape_type"),
                value_type=field.get("value_type") or "fixed-size value",
                confidence=field.get("confidence"),
                edit_risk=field.get("edit_risk"),
                effect=field.get("effect"),
                editor_tab=field.get("editor_tab"),
                importable=field.get("importable"),
                viewer_selection_id=viewer_selection_id,
                identity_path=identity_path,
            )
            _hkx_graph_add_edge(
                edges,
                edge_ids,
                owner_id,
                value_id,
                owner_relation,
                confidence=field.get("confidence"),
                viewer_selection_id=viewer_selection_id,
                identity_path=identity_path,
                description="Editable field catalog links this owner to a routed editor value.",
                link_evidence="exact",
            )
            if record_index not in (None, ""):
                _hkx_graph_add_edge(
                    edges,
                    edge_ids,
                    value_id,
                    f"record:{record_index}",
                    "patches_record",
                    record_index=record_index,
                    item_index=item_index,
                    offset=offset,
                    hex_offset=field.get("hex_offset"),
                    confidence=field.get("confidence"),
                    viewer_selection_id=viewer_selection_id,
                    identity_path=identity_path,
                    link_evidence="exact",
                )
            patch_matches: List[Mapping[str, object]] = []
            if shape_index not in (None, ""):
                path_prefix = f"shapes[{shape_index}].{field_name}"
                patch_matches = [
                    patch
                    for patch in patch_by_shape_index.get(str(shape_index), [])
                    if str(patch.get("path") or "").startswith(path_prefix) or str(patch.get("name") or "") == field_name
                ]
            elif record_index not in (None, "") and item_index not in (None, "") and offset not in (None, ""):
                patch_matches = patch_by_record_item_offset.get((str(record_index), str(item_index), str(offset)), [])
            for patch in patch_matches[:24]:
                patch_id = f"patch:{patch.get('index')}"
                _hkx_graph_add_edge(
                    edges,
                    edge_ids,
                    value_id,
                    patch_id,
                    "writes_byte_offset",
                    record_index=patch.get("record_index") or record_index,
                    item_index=patch.get("item_index") or item_index,
                    offset=offset,
                    hex_offset=field.get("hex_offset") or patch.get("hex_relative_offset"),
                    hex_absolute_data_offset=patch.get("hex_absolute_data_offset"),
                    byte_size=patch.get("byte_size"),
                    value_type=patch.get("value_type"),
                    confidence=patch.get("confidence") or field.get("confidence"),
                    viewer_selection_id=viewer_selection_id or _shape_viewer_id_from_path(patch.get("path")),
                    identity_path=f"{identity_path} -> {patch.get('hex_absolute_data_offset') or patch_id}",
                    description="Editable field is backed by this fixed byte patch target.",
                    link_evidence="exact",
                )
    for descriptor_index, descriptor in enumerate(descriptor_hints):
        descriptor_id = f"descriptor:{descriptor_index}"
        _hkx_graph_add_node(nodes, node_ids, descriptor_id, "descriptor_xml", str(descriptor.get("path") or descriptor.get("stem") or descriptor_id), root_tag=descriptor.get("root_tag"))
        _hkx_graph_add_edge(edges, edge_ids, file_id, descriptor_id, "related_context", link_evidence="inferred")
    identity_relations = {
        "body_shape",
        "matches_shape",
        "uses_material",
        "constraint_body_context",
        "has_editable_value",
        "record_editable_value",
        "patches_record",
        "writes_byte_offset",
        "writes_bytes",
    }
    identity_edge_count = sum(1 for edge in edges if str(edge.get("relation") or "") in identity_relations)
    byte_patch_edge_count = sum(1 for edge in edges if str(edge.get("relation") or "") in {"writes_byte_offset", "writes_bytes"})
    editable_value_node_count = sum(1 for node in nodes if str(node.get("kind") or "") == "editable_value")
    material_node_count = sum(1 for node in nodes if str(node.get("kind") or "") == "material")
    return {
        "status": "generated_from_current_decoder",
        "imported": False,
        "description": (
            "Best-effort graph for browsing HKX records, bodies, shapes, materials, constraints, editable values, "
            "and byte patch targets. Identity edges are for UI navigation only and are ignored on import."
        ),
        "node_count": len(nodes),
        "edge_count": len(edges),
        "reference_edge_count": reference_edge_count,
        "fixup_backed_reference_edge_count": fixup_backed_reference_edge_count,
        "identity_edge_count": identity_edge_count,
        "editable_value_node_count": editable_value_node_count,
        "byte_patch_edge_count": byte_patch_edge_count,
        "material_node_count": material_node_count,
        "nodes": nodes,
        "edges": edges,
    }


def _hkx_editor_model_preview_link_count(editor_model: object) -> int:
    if not isinstance(editor_model, Mapping):
        return 0
    count = 0
    groups = editor_model.get("groups")
    if not isinstance(groups, list):
        return 0
    for group in groups:
        if not isinstance(group, Mapping):
            continue
        rows = group.get("rows")
        if not isinstance(rows, list):
            continue
        count += sum(
            1
            for row in rows
            if isinstance(row, Mapping) and str(row.get("viewer_selection_id") or "").strip()
        )
    return count


def _hkx_compatibility_document(
    summary: HkxTagfileSummary,
    converter_report: Mapping[str, object],
    byte_patch_map: object,
    editor_model: object,
) -> Dict[str, object]:
    editable_target_count = 0
    if isinstance(byte_patch_map, Mapping):
        try:
            editable_target_count = int(byte_patch_map.get("entry_count") or 0)
        except (TypeError, ValueError, OverflowError):
            editable_target_count = 0
    if editable_target_count <= 0:
        try:
            editable_target_count = int(converter_report.get("editable_slot_count") or 0)
        except (TypeError, ValueError, OverflowError):
            editable_target_count = 0
    try:
        payload_record_count = int(converter_report.get("payload_record_count") or 0)
    except (TypeError, ValueError, OverflowError):
        payload_record_count = 0
    preview_linked_target_count = _hkx_editor_model_preview_link_count(editor_model)
    status = _hkx_compatibility_status_from_counts(
        sdk_version=summary.sdk_version,
        item_record_count=len(summary.item_records),
        payload_record_count=payload_record_count,
        size_matches=summary.size_matches,
        editable_target_count=editable_target_count,
        preview_linked_target_count=preview_linked_target_count,
    )
    return {
        "status": status,
        "status_scale": [
            "unsupported",
            "inspectable",
            "roundtrip_safe",
            "value_editable",
            "preview_linked",
        ],
        "description": (
            "CDMW Crimson Desert HKX compatibility classification for this export. "
            "Compatibility means CDMW JSON/XML preservation and fixed-size safe edits, not official Havok XML parity."
        ),
        "gates": {
            "sdkv20240200": summary.sdk_version == "20240200",
            "declared_size_matches_payload": summary.size_matches,
            "has_item_table": bool(summary.item_records),
            "payload_records_represented": payload_record_count,
            "item_record_count": len(summary.item_records),
            "unknown_bytes_preserved": payload_record_count >= len(summary.item_records) if summary.item_records else False,
            "editable_patch_targets": editable_target_count,
            "preview_linked_targets": preview_linked_target_count,
        },
        "unsupported_edits": [
            "changing record counts",
            "changing array lengths",
            "changing object references",
            "changing raw payload byte lengths",
            "adding/removing topology",
            "non-finite numeric values",
        ],
    }


def build_hkx_editable_geometry_document(
    data: bytes,
    virtual_path: str = "",
    companion_descriptor_hints: Optional[Sequence[Mapping[str, object]]] = None,
) -> Dict[str, object]:
    """Build a conservative editable JSON-like dump for decoded HKX geometry.

    The document is intentionally not Havok XML. It is a patch document for fixed-size numeric fields that
    can be written back into the original tagfile without rebuilding Havok object tables.
    """

    summary = parse_hkx_tagfile_summary(data)
    spans = _hkx_item_record_spans(data, summary.tag_items, summary.item_records)
    advanced_payloads = _hkx_advanced_record_payloads_document(data, summary, spans)
    shape_names = _hkx_shape_name_documents(advanced_payloads)
    char_strings = [
        {
            "record_index": record_index,
            "text": text,
            "simulation_role": _hkx_simulation_role_from_parts(text),
            "simulation_role_description": _hkx_simulation_role_description(_hkx_simulation_role_from_parts(text)),
            "confidence": "confirmed",
            "description": (
                "Decoded in-HKX char/string payload. It can name a body, shape, skeleton, container, material, "
                "or descriptor-owned physics part, but it is read-only context and is ignored on import."
            ),
        }
        for record_index, text in sorted(_hkx_char_record_texts_from_payloads(advanced_payloads).items())
    ]
    shapes: List[Dict[str, object]] = []
    for shape_index, hint in enumerate(summary.collision_geometry_hints):
        shape: Dict[str, object] = {
            "index": shape_index,
            "shape_type": hint.shape_type or "hknpShape",
            "shape_record_index": hint.shape_record_index,
            "editable_fields": [],
            "descriptions": {},
            "value_layouts": {},
            "records": {},
            "bounds_min": _hkx_json_number_vector(hint.bounds_min) if hint.bounds_min is not None else None,
            "bounds_max": _hkx_json_number_vector(hint.bounds_max) if hint.bounds_max is not None else None,
            "center": _hkx_json_number_vector(hint.center) if hint.center is not None else None,
            "extent": _hkx_json_number_vector(hint.extent) if hint.extent is not None else None,
        }
        records: Dict[str, object] = {}
        editable_fields: List[str] = []
        shape_record = _hkx_record_by_index(summary.item_records, hint.shape_record_index)
        vertex_record = _hkx_record_by_index(summary.item_records, hint.vertex_record_index)
        plane_record = _hkx_record_by_index(summary.item_records, hint.plane_record_index)
        mass_record = _hkx_record_by_index(summary.item_records, hint.mass_record_index)
        if hint.shape_type in {"hknpConvexShape", "hknpBoxShape", "hknpShape"}:
            vertices = _hkx_export_float_vectors_for_record(data, spans, vertex_record, 3, 12)
            planes = _hkx_export_float_vectors_for_record(data, spans, plane_record, 4, 16)
            if vertices:
                shape["vertices"] = vertices
                records["vertices"] = int(vertex_record.index) if vertex_record is not None else -1
                editable_fields.append("vertices")
            if planes:
                shape["planes"] = planes
                records["planes"] = int(plane_record.index) if plane_record is not None else -1
                editable_fields.append("planes")
            if hint.face_vertex_indices:
                shape["faces"] = [list(face) for face in hint.face_vertex_indices]
                shape["faces_read_only"] = True
            hull_topology = _hkx_export_hull_topology_document(data, spans, hint, summary.item_records)
            if hull_topology:
                shape["hull_topology"] = hull_topology
                topology_records = hull_topology.get("records")
                if isinstance(topology_records, Mapping):
                    for record_key, record_value in topology_records.items():
                        records[f"hull_topology.{record_key}"] = record_value  # type: ignore[assignment]
                editable_fields.append("hull_topology")
            mass_rows = _hkx_export_mass_property_rows_for_record(data, spans, mass_record)
            if mass_rows:
                shape["mass_properties"] = {
                    "float_rows": mass_rows,
                    "status": "experimental_fixed_size_edit",
                    "warning": "Havok 2024.2 mass-property field names are not fully recovered yet.",
                }
                records["mass_properties"] = int(mass_record.index) if mass_record is not None else -1
                editable_fields.append("mass_properties")
            shape_payload_slots = _hkx_export_shape_payload_float_slots_for_record(data, spans, shape_record)
            if shape_payload_slots:
                shape["shape_payload"] = {
                    "float_slots": shape_payload_slots,
                    "status": "experimental_fixed_offset_edit",
                    "warning": "hknp shape object field names are not fully recovered yet.",
                }
                records["shape_payload"] = int(shape_record.index) if shape_record is not None else -1
                editable_fields.append("shape_payload")
            if hint.shape_type == "hknpBoxShape":
                box_summary = _hkx_export_box_shape_summary_for_record(data, spans, shape_record)
                if box_summary:
                    shape["box_summary"] = box_summary
                    for vector_key in ("bounds_min", "bounds_max", "center"):
                        vector_value = box_summary.get(vector_key)
                        if isinstance(vector_value, list) and len(vector_value) == 3:
                            shape[vector_key] = vector_value
                    half_extents = box_summary.get("half_extents")
                    if isinstance(half_extents, list) and len(half_extents) == 3:
                        shape["extent"] = [float(value) * 2.0 for value in half_extents]
                    shape["read_only_reason"] = str(box_summary.get("warning") or "")
        elif hint.shape_type == "hknpSphereShape":
            center = _hkx_export_float_vectors_for_record(data, spans, vertex_record, 3, 12)
            if center:
                shape["sphere_center"] = center[0]
                records["sphere_center"] = int(vertex_record.index) if vertex_record is not None else -1
                editable_fields.append("sphere_center")
            if hint.radius is not None:
                shape["sphere_radius"] = float(hint.radius)
                if hint.shape_record_index is not None:
                    records["sphere_radius_shape"] = int(hint.shape_record_index)
                    editable_fields.append("sphere_radius")
            mass_rows = _hkx_export_mass_property_rows_for_record(data, spans, mass_record)
            if mass_rows:
                shape["mass_properties"] = {
                    "float_rows": mass_rows,
                    "status": "experimental_fixed_size_edit",
                    "warning": "Havok 2024.2 mass-property field names are not fully recovered yet.",
                }
                records["mass_properties"] = int(mass_record.index) if mass_record is not None else -1
                editable_fields.append("mass_properties")
        elif hint.shape_type == "hknpCapsuleShape":
            endpoints = _hkx_export_float_vectors_for_record(data, spans, vertex_record, 3, 12)
            capsule_summary: Dict[str, object] = {
                "radius": float(hint.radius) if hint.radius is not None else None,
                "length": float(hint.capsule_length) if hint.capsule_length is not None else None,
                "endpoint_count": len(endpoints),
                "status": "editable_when_records_available",
                "warning": "hknpCapsuleShape radius/endpoints are fixed-size edits only; do not add endpoint rows.",
            }
            if len(endpoints) >= 2:
                capsule_summary["start"] = endpoints[0]
                capsule_summary["end"] = endpoints[1]
                shape["capsule_endpoints"] = endpoints[:2]
                records["capsule_endpoints"] = int(vertex_record.index) if vertex_record is not None else -1
                editable_fields.append("capsule_endpoints")
            shape["capsule_summary"] = capsule_summary
            if hint.shape_record_index is not None:
                records["capsule_shape"] = int(hint.shape_record_index)
            if hint.radius is not None and shape_record is not None:
                shape["capsule_radius"] = float(hint.radius)
                records["capsule_radius_shape"] = int(shape_record.index)
                editable_fields.append("capsule_radius")
            mass_rows = _hkx_export_mass_property_rows_for_record(data, spans, mass_record)
            if mass_rows:
                shape["mass_properties"] = {
                    "float_rows": mass_rows,
                    "status": "experimental_fixed_size_edit",
                    "warning": "Havok 2024.2 mass-property field names are not fully recovered yet.",
                }
                records["mass_properties"] = int(mass_record.index) if mass_record is not None else -1
                editable_fields.append("mass_properties")
            shape_payload_slots = _hkx_export_shape_payload_float_slots_for_record(data, spans, shape_record)
            if shape_payload_slots:
                shape["shape_payload"] = {
                    "float_slots": shape_payload_slots,
                    "status": "experimental_fixed_offset_edit",
                    "warning": "hknp capsule shape object field names are not fully recovered yet.",
                }
                records["shape_payload"] = int(shape_record.index) if shape_record is not None else -1
                editable_fields.append("shape_payload")
        elif hint.shape_type == "hknpMeshShape":
            shape["mesh_summary"] = {
                "sections": hint.mesh_section_count,
                "primitives": hint.mesh_primitive_count,
                "aabb_nodes": hint.mesh_aabb_node_count,
                "shape_tags": hint.mesh_shape_tag_count,
                "data_bytes": hint.mesh_data_byte_count,
            }
            if hint.shape_record_index is not None:
                records["mesh_shape"] = int(hint.shape_record_index)
            mesh_details = _hkx_export_mesh_shape_details_document(data, spans, summary.item_records, shape_record)
            if mesh_details:
                shape["mesh_details"] = mesh_details
                mesh_records = mesh_details.get("records")
                if isinstance(mesh_records, Mapping):
                    for record_key, record_value in mesh_records.items():
                        records[f"mesh_details.{record_key}"] = record_value  # type: ignore[assignment]
            shape["read_only_reason"] = (
                "Mesh-shape topology is not editable yet; geometry section primitives and index buffers "
                "still need a dedicated decoder."
            )
        shape["editable_fields"] = editable_fields
        described_fields = [
            field_name
            for field_name in (
                "vertices",
                "planes",
                "faces",
                "sphere_center",
                "sphere_radius",
                "capsule_radius",
                "capsule_endpoints",
                "mass_properties",
                "shape_payload",
                "hull_topology",
                "bounds_min",
                "bounds_max",
                "center",
                "extent",
                "mesh_summary",
                "mesh_details",
                "capsule_summary",
                "box_summary",
            )
            if field_name in shape and field_name in _HKX_EDITABLE_GEOMETRY_FIELD_DESCRIPTIONS
        ]
        shape["descriptions"] = {
            field_name: _HKX_EDITABLE_GEOMETRY_FIELD_DESCRIPTIONS[field_name]
            for field_name in described_fields
        }
        shape["value_layouts"] = {
            field_name: _HKX_EDITABLE_GEOMETRY_VALUE_LAYOUTS[field_name]
            for field_name in editable_fields
            if field_name in _HKX_EDITABLE_GEOMETRY_VALUE_LAYOUTS
        }
        shape["records"] = records
        shapes.append(shape)
    hinted_shape_record_indices = {
        int(shape.get("shape_record_index"))
        for shape in shapes
        if isinstance(shape.get("shape_record_index"), int)
    }
    for record in summary.item_records:
        if record.type_name != "hknpBoxShape" or record.index in hinted_shape_record_indices:
            continue
        box_summary = _hkx_export_box_shape_summary_for_record(data, spans, record)
        if not box_summary:
            continue
        half_extents = box_summary.get("half_extents")
        shape: Dict[str, object] = {
            "index": len(shapes),
            "shape_type": "hknpBoxShape",
            "shape_record_index": int(record.index),
            "editable_fields": [],
            "descriptions": {"box_summary": _HKX_EDITABLE_GEOMETRY_FIELD_DESCRIPTIONS["box_summary"]},
            "value_layouts": {},
            "records": {"box_shape": int(record.index)},
            "bounds_min": box_summary.get("bounds_min"),
            "bounds_max": box_summary.get("bounds_max"),
            "center": box_summary.get("center"),
            "extent": [float(value) * 2.0 for value in half_extents]
            if isinstance(half_extents, list) and len(half_extents) == 3
            else None,
            "box_summary": box_summary,
            "read_only_reason": str(box_summary.get("warning") or ""),
        }
        shapes.append(shape)
    descriptor_hints = [dict(hint) for hint in companion_descriptor_hints or () if isinstance(hint, Mapping)]
    physics_body_context = _hkx_physics_body_context_document(shapes, descriptor_hints)
    _hkx_attach_shape_name_hints_to_shapes(shapes, shape_names)
    _hkx_attach_body_contexts_to_shapes(shapes, physics_body_context)
    physics_body_summary = _hkx_physics_body_summary_document(shapes)
    physics_constraint_summary = _hkx_physics_constraint_summary_document(advanced_payloads, descriptor_hints)
    physics_material_context = _hkx_material_simulation_context_document(descriptor_hints)
    physics_tuning = _hkx_attach_descriptor_context_to_physics_tuning(
        _hkx_physics_tuning_document(advanced_payloads),
        descriptor_hints,
    )
    editable_field_catalog = _hkx_editable_field_catalog_document(
        shapes,
        physics_tuning,
        physics_constraint_summary,
    )
    byte_patch_map = _hkx_byte_patch_map_document(data, shapes, physics_tuning, summary.item_records)
    hkx_edit_gate_v1 = _hkx_edit_gate_v1_document(
        byte_patch_map,
        summary.native_edit_candidate_map_v1,
        summary.native_hkx_edit_gate_v1,
    )
    converter_objects = _hkx_converter_objects_document(advanced_payloads)
    editor_model = _hkx_editor_model_document(
        shapes,
        physics_tuning,
        physics_body_summary,
        physics_constraint_summary,
        editable_field_catalog,
        byte_patch_map,
        converter_objects,
        advanced_payloads,
    )
    relationship_graph = _hkx_relationship_graph_document(
        summary,
        shapes,
        converter_objects,
        physics_tuning,
        physics_body_context,
        physics_body_summary,
        physics_constraint_summary,
        editable_field_catalog,
        descriptor_hints,
        byte_patch_map,
    )
    converter_report = _hkx_converter_report_document(data, summary, advanced_payloads)
    cdmw_compatibility = _hkx_compatibility_document(summary, converter_report, byte_patch_map, editor_model)
    converter_report["status"] = cdmw_compatibility["status"]
    converter_report["cdmw_hkx_compatibility_status"] = cdmw_compatibility["status"]
    native_backend = _hkx_native_backend_document(summary)
    decoder_evidence_v2 = _hkx_decoder_evidence_v2_document(summary, converter_report, native_backend)
    decode_gap_summary = _hkx_decode_gap_summary_document(converter_report, decoder_evidence_v2)
    tagfile_reference_fixups = _hkx_tagfile_reference_fixups_document(data, summary)
    fixup_semantics_report = _hkx_fixup_semantics_report_document(tagfile_reference_fixups)
    havok_xml_view = _hkx_havok_xml_view_document(
        converter_objects,
        summary,
        tagfile_reference_fixups=tagfile_reference_fixups,
    )
    hkx_xml_parity_report = _hkx_havok_xml_parity_report_document(
        havok_xml_view,
        converter_report,
        tagfile_reference_fixups=tagfile_reference_fixups,
    )
    hkclass_metadata_readiness = _hkx_hkclass_metadata_readiness_document(
        havok_xml_view,
        native_backend,
        relationship_graph,
    )
    modding_readiness = _hkx_modding_readiness_document(
        summary,
        converter_report,
        native_backend,
        decoder_evidence_v2,
        hkclass_metadata_readiness,
    )
    modding_workspace = _hkx_modding_workspace_document(
        byte_patch_map,
        summary.native_edit_candidate_map_v1,
        hkx_edit_gate_v1,
        modding_readiness,
    )
    collision_shapes = shapes
    return {
        "format": "cdmw_hkx_geometry_patch_v1",
        "converter_format": "cdmw_crimson_desert_hkx_converter_v1",
        "description": (
            "Crimson Desert Mod Workbench HKX converter document. Explanatory fields are comments for people and are ignored "
            "on import; unknown Havok 2024.2 bytes are preserved as same-length raw payloads."
        ),
        "source": {
            "path": virtual_path,
            "sdk_version": summary.sdk_version,
            "declared_size": summary.declared_size,
            "payload_size": len(data),
            "size_matches": summary.size_matches,
        },
        "cdmw_hkx_compatibility": cdmw_compatibility,
        "user_editing_guide": _hkx_user_editing_guide_document(cdmw_compatibility),
        "converter_report": converter_report,
        "decode_gap_summary": decode_gap_summary,
        "decoder_evidence_v2": decoder_evidence_v2,
        "real_hkclass_metadata_v2": summary.native_real_hkclass_metadata_v2,
        "fixup_semantics_v2": summary.native_fixup_semantics_v2,
        "semantic_model_v1": summary.native_semantic_model_v1,
        "semantic_writer_gate_v1": summary.native_semantic_writer_gate_v1,
        "edit_candidate_map_v1": summary.native_edit_candidate_map_v1,
        "hkx_edit_gate_v1": hkx_edit_gate_v1,
        "class_decoder_evidence_v2": summary.native_class_decoder_evidence_v2,
        "hkx_modding_readiness": modding_readiness,
        "modding_workspace_v1": modding_workspace,
        "tag_sections": _hkx_tag_sections_document(summary),
        "tagfile_reference_fixups": tagfile_reference_fixups,
        "fixup_semantics_report": fixup_semantics_report,
        "type_registry": _hkx_type_registry_document(summary),
        "native_backend": native_backend,
        "havok_xml_view": havok_xml_view,
        "hkx_xml_parity_report": hkx_xml_parity_report,
        "hkclass_metadata_readiness": hkclass_metadata_readiness,
        "objects": converter_objects,
        "editor_model": editor_model,
        "relationship_graph": relationship_graph,
        "editable_value_descriptions": dict(_HKX_EDITABLE_GEOMETRY_FIELD_DESCRIPTIONS),
        "editable_value_layouts": dict(_HKX_EDITABLE_GEOMETRY_VALUE_LAYOUTS),
        "schema_observations": _hkx_schema_observation_document(summary),
        "physics_system": _hkx_physics_system_document(summary),
        "physics_tuning": physics_tuning,
        "physics_names": {
            "status": "partial_reverse_engineering",
            "description": (
                "Decoded in-HKX char strings, body-part keywords, and HavokShapeNameProperty records. These names can "
                "identify ragdoll/body/cloth/hair-related collision shapes when the file contains labels. They are "
                "read-only context and are ignored on import."
            ),
            "char_strings": char_strings,
            "shape_name_properties": shape_names,
        }
        if shape_names or char_strings
        else None,
        "companion_descriptor_hints": descriptor_hints,
        "physics_body_context": physics_body_context,
        "physics_body_summary": physics_body_summary,
        "physics_material_context": physics_material_context,
        "physics_constraint_summary": physics_constraint_summary,
        "editable_field_catalog": editable_field_catalog,
        "byte_patch_map": byte_patch_map,
        "reimport_policy": _hkx_reimport_policy_document(),
        "collision_shapes": collision_shapes,
        "advanced_record_payloads": advanced_payloads,
        "raw_records": _hkx_raw_records_document(advanced_payloads),
        "limitations": [
            "This is not official Havok XML.",
            "Only fixed-size numeric edits are supported on reimport.",
            "Advanced record payload hex edits are same-length only and can break the HKX if object references or counts are changed incorrectly.",
            "Do not add/remove vertices, planes, faces, records, or shapes.",
            "Face loops are exported for inspection but are read-only until edge tables and mass properties can be rebuilt.",
            "Mesh-shape primitive tuple winding/order edits are supported only when each tuple keeps the same byte values.",
            "Changing mesh primitive vertex sets, shape-tag ranges, byte-buffer lengths, or AABB tree nodes is still blocked.",
        ],
        "shapes": shapes,
    }


def _hkx_overlay_vector(
    value: object,
    *,
    normalization_center: Sequence[object],
    normalization_scale: float,
) -> Tuple[float, float, float]:
    if not isinstance(value, (list, tuple)) or len(value) < 3:
        return ()
    try:
        center = tuple(float(component) for component in tuple(normalization_center)[:3])
        if len(center) < 3:
            center = (0.0, 0.0, 0.0)
        scale = float(normalization_scale or 1.0)
        return (
            (float(value[0]) - center[0]) * scale,
            (float(value[1]) - center[1]) * scale,
            (float(value[2]) - center[2]) * scale,
        )
    except (TypeError, ValueError, OverflowError):
        return ()


def _hkx_overlay_descriptor_vector(
    numeric_hints: object,
    hint_name: str,
    *,
    normalization_center: Sequence[object],
    normalization_scale: float,
) -> Tuple[float, float, float]:
    value = _hkx_descriptor_numeric_hint_lookup(numeric_hints, hint_name)
    if value is None:
        return ()
    components: List[float] = []
    for token in re.split(r"[\s,;]+", value.strip()):
        if not token:
            continue
        try:
            components.append(float(token))
        except (TypeError, ValueError, OverflowError):
            return ()
        if len(components) >= 3:
            break
    if len(components) < 3:
        return ()
    return _hkx_overlay_vector(
        components,
        normalization_center=normalization_center,
        normalization_scale=normalization_scale,
    )


def _hkx_overlay_tuning_hint_text(numeric_hints: object, names: set[str], *, limit: int = 6) -> Tuple[str, ...]:
    if not isinstance(numeric_hints, list):
        return ()
    rows: List[str] = []
    for hint in numeric_hints:
        if not isinstance(hint, Mapping):
            continue
        name = str(hint.get("name") or "").strip()
        if name not in names:
            continue
        value = str(hint.get("value") or " ".join(str(item) for item in hint.get("values", []) if item is not None)).strip()
        rows.append(f"{name}={value}" if value else name)
        if len(rows) >= limit:
            break
    return tuple(rows)


def _hkx_overlay_anchor_match_key(*values: object) -> str:
    for value in values:
        text = str(value or "").strip().casefold()
        if text:
            return text
    return ""


def _hkx_overlay_name_aliases(name: object) -> Tuple[str, ...]:
    text = str(name or "").strip()
    if not text:
        return ()
    lowered = text.casefold()
    compact = re.sub(r"[^a-z0-9]+", "", lowered)
    underscore = re.sub(r"[^a-z0-9]+", "_", lowered).strip("_")
    aliases = [lowered]
    for alias in (compact, underscore):
        if alias and alias not in aliases:
            aliases.append(alias)
    return tuple(aliases)


def _hkx_overlay_skeleton_bone_match(
    skeleton_bone_positions: Optional[Mapping[str, object]],
    *names: object,
    normalization_center: Sequence[object],
    normalization_scale: float,
) -> Tuple[Tuple[float, float, float], str, int, str]:
    if not isinstance(skeleton_bone_positions, Mapping) or not skeleton_bone_positions:
        return (), "", -1, ""
    lookup: Dict[str, Tuple[str, object]] = {}
    for bone_name, raw_value in skeleton_bone_positions.items():
        for alias in _hkx_overlay_name_aliases(bone_name):
            lookup.setdefault(alias, (str(bone_name), raw_value))

    def _matched_position(matched_name: str, raw_value: object) -> Tuple[Tuple[float, float, float], str, int, str]:
        metadata: Mapping[str, object] = {}
        raw_position: object = raw_value
        if isinstance(raw_value, Mapping):
            metadata = raw_value
            raw_position = raw_value.get("position")
        position = _hkx_overlay_vector(
            raw_position,
            normalization_center=normalization_center,
            normalization_scale=normalization_scale,
        )
        if position:
            bone_index = metadata.get("index")
            return (
                position,
                str(metadata.get("name") or matched_name),
                int(bone_index) if isinstance(bone_index, int) else -1,
                str(metadata.get("source_path") or ""),
            )
        return (), "", -1, ""

    for name in names:
        for alias in _hkx_overlay_name_aliases(name):
            match = lookup.get(alias)
            if match is None:
                continue
            matched_name, raw_value = match
            result = _matched_position(matched_name, raw_value)
            if result[0]:
                return result
    bone_aliases = sorted(
        ((alias, matched_name, raw_value) for alias, (matched_name, raw_value) in lookup.items() if len(alias) >= 5),
        key=lambda item: len(item[0]),
        reverse=True,
    )
    for name in names:
        for requested_alias in _hkx_overlay_name_aliases(name):
            if len(requested_alias) < 5:
                continue
            for bone_alias, matched_name, raw_value in bone_aliases:
                if requested_alias == bone_alias or requested_alias.endswith(bone_alias) or bone_alias in requested_alias:
                    result = _matched_position(matched_name, raw_value)
                    if result[0]:
                        return result
    return (), "", -1, ""


def _hkx_overlay_body_shape_targets(
    document: Mapping[str, object],
    skeleton_bone_positions: Optional[Mapping[str, object]],
    *,
    normalization_center: Sequence[object],
    normalization_scale: float,
) -> Dict[int, Dict[str, object]]:
    targets: Dict[int, Dict[str, object]] = {}
    physics_body_context = document.get("physics_body_context")
    if not isinstance(physics_body_context, Mapping):
        return targets
    body_contexts = physics_body_context.get("body_contexts")
    if not isinstance(body_contexts, list):
        return targets
    for body_context in body_contexts:
        if not isinstance(body_context, Mapping):
            continue
        socket_name = str(body_context.get("socket_name") or "")
        fixed_socket_name = str(body_context.get("fixed_socket_name") or "")
        body_name = str(body_context.get("body_name") or "")
        skeleton_position, skeleton_bone_name, skeleton_bone_index, skeleton_source_path = _hkx_overlay_skeleton_bone_match(
            skeleton_bone_positions,
            socket_name,
            fixed_socket_name,
            body_name,
            normalization_center=normalization_center,
            normalization_scale=normalization_scale,
        )
        if not skeleton_position:
            continue
        shape_matches = body_context.get("shape_matches")
        if not isinstance(shape_matches, list):
            continue
        for match in shape_matches:
            if not isinstance(match, Mapping) or not isinstance(match.get("decoded_shape_index"), int):
                continue
            shape_index = int(match["decoded_shape_index"])
            targets.setdefault(
                shape_index,
                {
                    "position": skeleton_position,
                    "source": "skeleton_socket",
                    "target": skeleton_bone_name or socket_name or fixed_socket_name or body_name,
                    "bone_index": skeleton_bone_index,
                    "source_path": skeleton_source_path,
                    "confidence": "skeleton_context",
                },
            )
    return targets


def _hkx_overlay_average_position(points: Sequence[Sequence[object]]) -> Tuple[float, float, float]:
    parsed: List[Tuple[float, float, float]] = []
    for point in points:
        if len(point) < 3:
            continue
        try:
            parsed.append((float(point[0]), float(point[1]), float(point[2])))
        except (TypeError, ValueError, OverflowError):
            continue
    if not parsed:
        return ()
    count = float(len(parsed))
    return (
        sum(point[0] for point in parsed) / count,
        sum(point[1] for point in parsed) / count,
        sum(point[2] for point in parsed) / count,
    )


def _hkx_overlay_shape_visual_center(
    *,
    center: Sequence[object] = (),
    bounds_min: Sequence[object] = (),
    bounds_max: Sequence[object] = (),
    capsule_start: Sequence[object] = (),
    capsule_end: Sequence[object] = (),
    vertices: Sequence[Sequence[object]] = (),
) -> Tuple[float, float, float]:
    for point in (center,):
        parsed = _hkx_overlay_average_position((point,))
        if parsed:
            return parsed
    if len(bounds_min) >= 3 and len(bounds_max) >= 3:
        parsed = _hkx_overlay_average_position((bounds_min, bounds_max))
        if parsed:
            return parsed
    if len(capsule_start) >= 3 and len(capsule_end) >= 3:
        parsed = _hkx_overlay_average_position((capsule_start, capsule_end))
        if parsed:
            return parsed
    return _hkx_overlay_average_position(vertices)


def _hkx_overlay_translate_point(
    point: Sequence[object],
    delta: Sequence[object],
) -> Tuple[float, float, float]:
    if len(point) < 3 or len(delta) < 3:
        return ()
    try:
        return (
            float(point[0]) + float(delta[0]),
            float(point[1]) + float(delta[1]),
            float(point[2]) + float(delta[2]),
        )
    except (TypeError, ValueError, OverflowError):
        return ()


def _hkx_overlay_bones_from_skeleton_positions(
    skeleton_bone_positions: Optional[Mapping[str, object]],
    *,
    normalization_center: Sequence[object],
    normalization_scale: float,
    limit: int = 384,
) -> Tuple[HkxPhysicsOverlayBone, ...]:
    if not isinstance(skeleton_bone_positions, Mapping) or not skeleton_bone_positions:
        return ()
    raw_rows: List[Tuple[str, Mapping[str, object]]] = [
        (str(name), value)
        for name, value in skeleton_bone_positions.items()
        if str(name or "").strip() and isinstance(value, Mapping)
    ]
    raw_rows.sort(key=lambda item: int(item[1].get("index")) if isinstance(item[1].get("index"), int) else 1_000_000)
    rows_by_index: Dict[int, Mapping[str, object]] = {}
    rows_by_name: Dict[str, Mapping[str, object]] = {}
    for name, row in raw_rows:
        bone_index = row.get("index")
        if isinstance(bone_index, int):
            rows_by_index[bone_index] = row
        rows_by_name[str(row.get("name") or name)] = row
    bones: List[HkxPhysicsOverlayBone] = []
    for fallback_name, row in raw_rows[:limit]:
        name = str(row.get("name") or fallback_name)
        position = _hkx_overlay_vector(
            row.get("position"),
            normalization_center=normalization_center,
            normalization_scale=normalization_scale,
        )
        if not position:
            continue
        parent_index = row.get("parent_index")
        parent_name = str(row.get("parent_name") or "")
        parent_row = rows_by_index.get(parent_index) if isinstance(parent_index, int) else None
        if parent_row is None and parent_name:
            parent_row = rows_by_name.get(parent_name)
        parent_position = (
            _hkx_overlay_vector(
                parent_row.get("position"),
                normalization_center=normalization_center,
                normalization_scale=normalization_scale,
            )
            if isinstance(parent_row, Mapping)
            else ()
        )
        index_value = row.get("index")
        bones.append(
            HkxPhysicsOverlayBone(
                name=name,
                source_path=str(row.get("source_path") or ""),
                index=int(index_value) if isinstance(index_value, int) else -1,
                parent_index=int(parent_index) if isinstance(parent_index, int) else -1,
                parent_name=parent_name or (str(parent_row.get("name") or "") if isinstance(parent_row, Mapping) else ""),
                position=position,
                parent_position=parent_position,
            )
        )
    return tuple(bones)


def build_hkx_physics_overlay_from_document(
    document: Mapping[str, object],
    *,
    source_path: str = "",
    normalization_center: Sequence[object] = (0.0, 0.0, 0.0),
    normalization_scale: float = 1.0,
    skeleton_bone_positions: Optional[Mapping[str, object]] = None,
    max_shapes: int = 96,
    max_vertices_per_shape: int = 512,
    max_faces_per_shape: int = 512,
) -> Optional[HkxPhysicsOverlayData]:
    """Build a model-preview overlay from a decoded Crimson Desert HKX converter document.

    This is intentionally visual-only. It draws recovered collision bodies in the same normalized coordinate
    space as the model preview and does not simulate Havok constraints or cloth.
    """

    shapes_value = document.get("collision_shapes") or document.get("shapes")
    if not isinstance(shapes_value, list):
        return None
    overlay_shapes: List[HkxPhysicsOverlayShape] = []
    shape_positions_by_index: Dict[int, Tuple[float, float, float]] = {}
    shape_placement_targets = _hkx_overlay_body_shape_targets(
        document,
        skeleton_bone_positions,
        normalization_center=normalization_center,
        normalization_scale=normalization_scale,
    )
    for shape in shapes_value:
        if len(overlay_shapes) >= max_shapes:
            break
        if not isinstance(shape, Mapping):
            continue
        shape_type = str(shape.get("shape_type") or "hknpShape")
        source_shape_index = int(shape.get("index")) if isinstance(shape.get("index"), int) else len(overlay_shapes)
        body_name = ""
        socket_name = ""
        fixed_socket_name = ""
        physics_material_name = ""
        simulation_role = ""
        simulation_role_description = ""
        label = ""
        name_hint = shape.get("name_hint")
        if isinstance(name_hint, Mapping):
            label = str(name_hint.get("name") or "")
        if not label:
            contexts = shape.get("body_contexts")
            if isinstance(contexts, list):
                first_context = next((context for context in contexts if isinstance(context, Mapping)), None)
                if first_context is not None:
                    label = str(first_context.get("body_name") or first_context.get("socket_name") or "")
                    body_name = str(first_context.get("body_name") or "")
                    socket_name = str(first_context.get("socket_name") or "")
                    fixed_socket_name = str(first_context.get("fixed_socket_name") or "")
                    physics_material_name = str(first_context.get("physics_material_name") or "")
                    simulation_role = str(first_context.get("simulation_role") or "")
                    simulation_role_description = str(first_context.get("simulation_role_description") or "")
        if not label:
            label = f"{shape_type} {shape.get('index')}"
        if not simulation_role:
            simulation_role = _hkx_simulation_role_from_parts(
                source_path,
                label,
                shape_type,
                body_name,
                socket_name,
                fixed_socket_name,
                physics_material_name,
            )
        if not simulation_role_description:
            simulation_role_description = _hkx_simulation_role_description(simulation_role)
        vertices: List[Tuple[float, float, float]] = []
        for raw_vertex in shape.get("vertices") if isinstance(shape.get("vertices"), list) else []:
            point = _hkx_overlay_vector(
                raw_vertex,
                normalization_center=normalization_center,
                normalization_scale=normalization_scale,
            )
            if len(point) == 3:
                vertices.append(point)
                if len(vertices) >= max_vertices_per_shape:
                    break
        faces: List[Tuple[int, ...]] = []
        raw_faces = shape.get("faces")
        if not isinstance(raw_faces, list):
            hull_topology = shape.get("hull_topology")
            if isinstance(hull_topology, Mapping):
                raw_faces = hull_topology.get("face_vertex_loops")
        if isinstance(raw_faces, list):
            for raw_face in raw_faces:
                if not isinstance(raw_face, (list, tuple)):
                    continue
                face = tuple(
                    int(index)
                    for index in raw_face
                    if isinstance(index, int) or (isinstance(index, str) and index.strip().lstrip("-").isdigit())
                )
                if len(face) >= 2:
                    faces.append(face)
                if len(faces) >= max_faces_per_shape:
                    break
        bounds_min = _hkx_overlay_vector(
            shape.get("bounds_min"),
            normalization_center=normalization_center,
            normalization_scale=normalization_scale,
        )
        bounds_max = _hkx_overlay_vector(
            shape.get("bounds_max"),
            normalization_center=normalization_center,
            normalization_scale=normalization_scale,
        )
        center = _hkx_overlay_vector(
            shape.get("center"),
            normalization_center=normalization_center,
            normalization_scale=normalization_scale,
        )
        if not center and bounds_min and bounds_max:
            center = tuple((bounds_min[index] + bounds_max[index]) * 0.5 for index in range(3))  # type: ignore[assignment]
        radius = 0.0
        for key in ("sphere_radius", "capsule_radius"):
            value = shape.get(key)
            if isinstance(value, (int, float)) and math.isfinite(float(value)):
                radius = max(radius, abs(float(value) * float(normalization_scale or 1.0)))
        capsule_start: Tuple[float, float, float] = ()
        capsule_end: Tuple[float, float, float] = ()
        endpoints = shape.get("capsule_endpoints")
        if isinstance(endpoints, list) and len(endpoints) >= 2:
            capsule_start = _hkx_overlay_vector(
                endpoints[0],
                normalization_center=normalization_center,
                normalization_scale=normalization_scale,
            )
            capsule_end = _hkx_overlay_vector(
                endpoints[1],
                normalization_center=normalization_center,
                normalization_scale=normalization_scale,
            )
        if not any((vertices, bounds_min and bounds_max, center, capsule_start and capsule_end, radius)):
            continue
        placement_source = ""
        placement_target = ""
        placement_delta: Tuple[float, float, float] = ()
        placement = shape_placement_targets.get(source_shape_index)
        if not isinstance(placement, Mapping):
            skeleton_position, skeleton_bone_name, skeleton_bone_index, skeleton_source_path = _hkx_overlay_skeleton_bone_match(
                skeleton_bone_positions,
                socket_name,
                fixed_socket_name,
                body_name,
                label,
                normalization_center=normalization_center,
                normalization_scale=normalization_scale,
            )
            if skeleton_position:
                placement = {
                    "position": skeleton_position,
                    "source": "skeleton_label",
                    "target": skeleton_bone_name or socket_name or fixed_socket_name or body_name or label,
                    "bone_index": skeleton_bone_index,
                    "source_path": skeleton_source_path,
                    "confidence": "skeleton_context",
                }
        if isinstance(placement, Mapping):
            target_position = placement.get("position")
            if isinstance(target_position, (list, tuple)) and len(target_position) >= 3:
                visual_center = _hkx_overlay_shape_visual_center(
                    center=center,
                    bounds_min=bounds_min,
                    bounds_max=bounds_max,
                    capsule_start=capsule_start,
                    capsule_end=capsule_end,
                    vertices=vertices,
                )
                if visual_center:
                    try:
                        target = (float(target_position[0]), float(target_position[1]), float(target_position[2]))
                        delta = (
                            target[0] - visual_center[0],
                            target[1] - visual_center[1],
                            target[2] - visual_center[2],
                        )
                    except (TypeError, ValueError, OverflowError):
                        delta = ()
                    if delta and math.sqrt((delta[0] * delta[0]) + (delta[1] * delta[1]) + (delta[2] * delta[2])) > 1e-5:
                        vertices = [
                            translated
                            for translated in (_hkx_overlay_translate_point(vertex, delta) for vertex in vertices)
                            if translated
                        ]
                        if bounds_min:
                            bounds_min = _hkx_overlay_translate_point(bounds_min, delta)
                        if bounds_max:
                            bounds_max = _hkx_overlay_translate_point(bounds_max, delta)
                        if center:
                            center = _hkx_overlay_translate_point(center, delta)
                        if capsule_start:
                            capsule_start = _hkx_overlay_translate_point(capsule_start, delta)
                        if capsule_end:
                            capsule_end = _hkx_overlay_translate_point(capsule_end, delta)
                        placement_source = str(placement.get("source") or "skeleton_socket")
                        placement_target = str(placement.get("target") or "")
                        placement_delta = delta
        visual_position = _hkx_overlay_shape_visual_center(
            center=center,
            bounds_min=bounds_min,
            bounds_max=bounds_max,
            capsule_start=capsule_start,
            capsule_end=capsule_end,
            vertices=vertices,
        )
        if visual_position:
            shape_positions_by_index[source_shape_index] = visual_position
        overlay_shapes.append(
            HkxPhysicsOverlayShape(
                shape_type=shape_type,
                label=label,
                source_path=source_path,
                source_shape_index=source_shape_index,
                simulation_role=simulation_role,
                simulation_role_description=simulation_role_description,
                body_name=body_name,
                socket_name=socket_name,
                fixed_socket_name=fixed_socket_name,
                physics_material_name=physics_material_name,
                confidence="strong inference" if shape_type in {"hknpConvexShape", "hknpBoxShape", "hknpSphereShape", "hknpCapsuleShape"} else "experimental",
                read_only_reason=str(shape.get("read_only_reason") or ""),
                bounds_min=bounds_min,
                bounds_max=bounds_max,
                center=center,
                radius=float(radius),
                capsule_start=capsule_start,
                capsule_end=capsule_end,
                vertices=tuple(vertices),
                faces=tuple(faces),
                placement_source=placement_source,
                placement_target=placement_target,
                placement_delta=placement_delta,
            )
        )
    if not overlay_shapes:
        return None
    overlay_bones = _hkx_overlay_bones_from_skeleton_positions(
        skeleton_bone_positions,
        normalization_center=normalization_center,
        normalization_scale=normalization_scale,
    )
    anchors: List[HkxPhysicsOverlayAnchor] = []
    anchors_by_key: Dict[str, HkxPhysicsOverlayAnchor] = {}
    physics_body_context = document.get("physics_body_context")
    if isinstance(physics_body_context, Mapping):
        body_contexts = physics_body_context.get("body_contexts")
        if isinstance(body_contexts, list):
            for body_context in body_contexts:
                if not isinstance(body_context, Mapping):
                    continue
                body_name = str(body_context.get("body_name") or "")
                socket_name = str(body_context.get("socket_name") or "")
                fixed_socket_name = str(body_context.get("fixed_socket_name") or "")
                shape_indices: List[int] = []
                positions: List[Tuple[float, float, float]] = []
                shape_matches = body_context.get("shape_matches")
                if isinstance(shape_matches, list):
                    for match in shape_matches:
                        if not isinstance(match, Mapping) or not isinstance(match.get("decoded_shape_index"), int):
                            continue
                        decoded_shape_index = int(match["decoded_shape_index"])
                        shape_indices.append(decoded_shape_index)
                        position = shape_positions_by_index.get(decoded_shape_index)
                        if position:
                            positions.append(position)
                skeleton_position, skeleton_bone_name, skeleton_bone_index, skeleton_source_path = _hkx_overlay_skeleton_bone_match(
                    skeleton_bone_positions,
                    socket_name,
                    fixed_socket_name,
                    body_name,
                    normalization_center=normalization_center,
                    normalization_scale=normalization_scale,
                )
                if skeleton_position:
                    position = skeleton_position
                elif positions:
                    position = tuple(sum(point[index] for point in positions) / float(len(positions)) for index in range(3))
                else:
                    position = _hkx_overlay_descriptor_vector(
                        body_context.get("numeric_hints"),
                        "_localTranslation",
                        normalization_center=normalization_center,
                        normalization_scale=normalization_scale,
                    )
                if not position:
                    continue
                label = body_name or socket_name or fixed_socket_name or f"body {len(anchors)}"
                simulation_role = str(body_context.get("simulation_role") or "")
                if not simulation_role:
                    simulation_role = _hkx_simulation_role_from_parts(
                        source_path,
                        label,
                        body_name,
                        socket_name,
                        fixed_socket_name,
                        body_context.get("physics_material_name"),
                        body_context.get("numeric_hints"),
                    )
                anchor = HkxPhysicsOverlayAnchor(
                    label=label,
                    source_path=source_path,
                    simulation_role=simulation_role,
                    simulation_role_description=str(
                        body_context.get("simulation_role_description")
                        or _hkx_simulation_role_description(simulation_role)
                    ),
                    body_name=body_name,
                    socket_name=socket_name,
                    fixed_socket_name=fixed_socket_name,
                    physics_material_name=str(body_context.get("physics_material_name") or ""),
                    skeleton_bone_name=skeleton_bone_name,
                    skeleton_bone_index=skeleton_bone_index,
                    skeleton_source_path=skeleton_source_path,
                    confidence="skeleton_context" if skeleton_bone_name else str(body_context.get("confidence") or "descriptor_context"),
                    position=position,
                    shape_indices=tuple(shape_indices),
                    tuning_hints=_hkx_overlay_tuning_hint_text(
                        body_context.get("numeric_hints"),
                        {"_angularDamping", "_linearDamping", "_inertiaFactor"},
                    ),
                )
                anchors.append(anchor)
                for key in {
                    _hkx_overlay_anchor_match_key(body_name),
                    _hkx_overlay_anchor_match_key(socket_name),
                    _hkx_overlay_anchor_match_key(fixed_socket_name),
                }:
                    if key and key not in anchors_by_key:
                        anchors_by_key[key] = anchor

    constraints: List[HkxPhysicsOverlayConstraint] = []
    constraint_summary = document.get("physics_constraint_summary")
    if isinstance(constraint_summary, Mapping):
        raw_constraints = constraint_summary.get("constraints")
        if isinstance(raw_constraints, list):
            for raw_constraint in raw_constraints[:128]:
                if not isinstance(raw_constraint, Mapping):
                    continue
                descriptor_context = raw_constraint.get("descriptor_context")
                descriptor_context = descriptor_context if isinstance(descriptor_context, Mapping) else {}
                body_name = str(descriptor_context.get("body_name") or "")
                socket_name = str(descriptor_context.get("socket_name") or "")
                fixed_socket_name = str(descriptor_context.get("fixed_socket_name") or "")
                simulation_role = str(descriptor_context.get("simulation_role") or "")
                if not simulation_role:
                    simulation_role = _hkx_simulation_role_from_parts(
                        source_path,
                        raw_constraint.get("name"),
                        raw_constraint.get("type_name"),
                        body_name,
                        socket_name,
                        fixed_socket_name,
                        descriptor_context.get("numeric_hints"),
                    )
                start_anchor = anchors_by_key.get(_hkx_overlay_anchor_match_key(body_name, socket_name))
                end_anchor = anchors_by_key.get(_hkx_overlay_anchor_match_key(fixed_socket_name))
                if isinstance(start_anchor, HkxPhysicsOverlayAnchor) and start_anchor.simulation_role:
                    simulation_role = str(start_anchor.simulation_role)
                start = start_anchor.position if isinstance(start_anchor, HkxPhysicsOverlayAnchor) else ()
                end = end_anchor.position if isinstance(end_anchor, HkxPhysicsOverlayAnchor) else ()
                end_bone_name = ""
                if not end:
                    end, end_bone_name, _bone_index, _bone_source = _hkx_overlay_skeleton_bone_match(
                        skeleton_bone_positions,
                        fixed_socket_name,
                        normalization_center=normalization_center,
                        normalization_scale=normalization_scale,
                    )
                if not end:
                    end = _hkx_overlay_descriptor_vector(
                        descriptor_context.get("numeric_hints"),
                        "_localTranslation",
                        normalization_center=normalization_center,
                        normalization_scale=normalization_scale,
                    )
                if not start and end:
                    start = (end[0], end[1] - 0.08, end[2])
                if not start and not end:
                    continue
                limit_hints = _hkx_overlay_tuning_hint_text(
                    descriptor_context.get("numeric_hints"),
                    {
                        "_maxFrictionTorque",
                        "_angularLimitMin",
                        "_angularLimitMax",
                        "_coneAngle",
                        "_twistMin",
                        "_twistMax",
                        "_planeMin",
                        "_planeMax",
                    },
                    limit=8,
                )
                motor_hints: List[str] = []
                for slot in raw_constraint.get("motor_slots", []) if isinstance(raw_constraint.get("motor_slots"), list) else []:
                    if not isinstance(slot, Mapping):
                        continue
                    name = str(slot.get("name") or "")
                    value = slot.get("value")
                    if name and isinstance(value, (int, float)):
                        motor_hints.append(f"{name}={float(value):.4g}")
                    if len(motor_hints) >= 4:
                        break
                constraint_confidence = str(raw_constraint.get("confidence") or descriptor_context.get("confidence") or "experimental")
                if (
                    (isinstance(start_anchor, HkxPhysicsOverlayAnchor) and start_anchor.confidence == "skeleton_context")
                    or (isinstance(end_anchor, HkxPhysicsOverlayAnchor) and end_anchor.confidence == "skeleton_context")
                    or bool(end_bone_name)
                ):
                    constraint_confidence = "skeleton_context"
                constraints.append(
                    HkxPhysicsOverlayConstraint(
                        label=str(raw_constraint.get("name") or f"constraint {len(constraints)}"),
                        source_path=source_path,
                        constraint_type=str(raw_constraint.get("type_name") or descriptor_context.get("tag") or "constraint"),
                        simulation_role=simulation_role,
                        simulation_role_description=str(
                            getattr(start_anchor, "simulation_role_description", "")
                            if isinstance(start_anchor, HkxPhysicsOverlayAnchor)
                            else descriptor_context.get("simulation_role_description")
                            or _hkx_simulation_role_description(simulation_role)
                        ),
                        body_name=body_name,
                        socket_name=socket_name,
                        fixed_socket_name=fixed_socket_name,
                        confidence=constraint_confidence,
                        start=start,
                        end=end,
                        motor_hints=tuple(motor_hints),
                        limit_hints=limit_hints,
                    )
                )
    if isinstance(physics_body_context, Mapping):
        descriptor_constraints = physics_body_context.get("constraint_contexts")
        if isinstance(descriptor_constraints, list):
            for descriptor_context in descriptor_constraints[:128]:
                if not isinstance(descriptor_context, Mapping):
                    continue
                body_name = str(descriptor_context.get("body_name") or "")
                socket_name = str(descriptor_context.get("socket_name") or "")
                fixed_socket_name = str(descriptor_context.get("fixed_socket_name") or "")
                simulation_role = str(descriptor_context.get("simulation_role") or "")
                if not simulation_role:
                    simulation_role = _hkx_simulation_role_from_parts(
                        source_path,
                        descriptor_context.get("tag"),
                        body_name,
                        socket_name,
                        fixed_socket_name,
                        descriptor_context.get("numeric_hints"),
                    )
                if any(
                    existing.body_name == body_name
                    and existing.socket_name == socket_name
                    and existing.fixed_socket_name == fixed_socket_name
                    for existing in constraints
                ):
                    continue
                start_anchor = anchors_by_key.get(_hkx_overlay_anchor_match_key(body_name, socket_name))
                end_anchor = anchors_by_key.get(_hkx_overlay_anchor_match_key(fixed_socket_name))
                if isinstance(start_anchor, HkxPhysicsOverlayAnchor) and start_anchor.simulation_role:
                    simulation_role = str(start_anchor.simulation_role)
                start = start_anchor.position if isinstance(start_anchor, HkxPhysicsOverlayAnchor) else ()
                end = end_anchor.position if isinstance(end_anchor, HkxPhysicsOverlayAnchor) else ()
                end_bone_name = ""
                if not end:
                    end, end_bone_name, _bone_index, _bone_source = _hkx_overlay_skeleton_bone_match(
                        skeleton_bone_positions,
                        fixed_socket_name,
                        normalization_center=normalization_center,
                        normalization_scale=normalization_scale,
                    )
                if not end:
                    end = _hkx_overlay_descriptor_vector(
                        descriptor_context.get("numeric_hints"),
                        "_localTranslation",
                        normalization_center=normalization_center,
                        normalization_scale=normalization_scale,
                    )
                if not start and end:
                    start = (end[0], end[1] - 0.08, end[2])
                if not start and not end:
                    continue
                constraint_confidence = str(descriptor_context.get("confidence") or "descriptor_context")
                if (
                    (isinstance(start_anchor, HkxPhysicsOverlayAnchor) and start_anchor.confidence == "skeleton_context")
                    or (isinstance(end_anchor, HkxPhysicsOverlayAnchor) and end_anchor.confidence == "skeleton_context")
                    or bool(end_bone_name)
                ):
                    constraint_confidence = "skeleton_context"
                constraints.append(
                    HkxPhysicsOverlayConstraint(
                        label=str(descriptor_context.get("tag") or f"constraint guide {len(constraints)}"),
                        source_path=source_path,
                        constraint_type=str(descriptor_context.get("tag") or "descriptor_constraint"),
                        simulation_role=simulation_role,
                        simulation_role_description=str(
                            getattr(start_anchor, "simulation_role_description", "")
                            if isinstance(start_anchor, HkxPhysicsOverlayAnchor)
                            else descriptor_context.get("simulation_role_description")
                            or _hkx_simulation_role_description(simulation_role)
                        ),
                        body_name=body_name,
                        socket_name=socket_name,
                        fixed_socket_name=fixed_socket_name,
                        confidence=constraint_confidence,
                        start=start,
                        end=end,
                        limit_hints=_hkx_overlay_tuning_hint_text(
                            descriptor_context.get("numeric_hints"),
                            {
                                "_maxFrictionTorque",
                                "_angularLimitMin",
                                "_angularLimitMax",
                                "_coneAngle",
                                "_twistMin",
                                "_twistMax",
                                "_planeMin",
                                "_planeMax",
                            },
                            limit=8,
                        ),
                    )
                )
    body_summary = document.get("physics_body_summary")
    body_count = int(body_summary.get("body_count") or 0) if isinstance(body_summary, Mapping) else 0
    constraint_count = int(constraint_summary.get("constraint_count") or 0) if isinstance(constraint_summary, Mapping) else 0
    skeleton_anchor_count = sum(1 for anchor in anchors if anchor.skeleton_bone_name)
    simulation_role_counts = _hkx_simulation_role_counts(anchors, constraints, overlay_shapes)
    role_text = ", ".join(f"{role}={count:,}" for role, count in simulation_role_counts)
    return HkxPhysicsOverlayData(
        summary=(
            f"HKX physics overlay: {len(overlay_shapes):,} decoded shape(s)"
            + (f", {len(anchors):,} body anchor(s)" if anchors else "")
            + (f", {skeleton_anchor_count:,} skeleton-linked" if skeleton_anchor_count else "")
            + (f", {len(overlay_bones):,} rig bone(s)" if overlay_bones else "")
            + (f", {len(constraints):,} constraint guide(s)" if constraints else "")
            + (f", {body_count:,} body label(s)" if body_count else "")
            + (f", {constraint_count:,} constraint hint(s)" if constraint_count else "")
            + (f", roles: {role_text}" if role_text else "")
        ),
        source_paths=(source_path,) if source_path else (),
        simulation_role_counts=simulation_role_counts,
        shapes=tuple(overlay_shapes),
        anchors=tuple(anchors),
        constraints=tuple(constraints),
        bones=overlay_bones,
        body_count=body_count,
        constraint_count=constraint_count,
        limitations=(
            "Visual collision/physics structure overlay only.",
            "Constraint and motor guides are descriptor/type correlations, not a Havok solver simulation.",
            "No Havok 2024.2 cloth, ragdoll, or solver simulation is run.",
            "Coordinates are transformed into the current normalized model-preview space.",
        ),
    )


def merge_hkx_physics_overlays(overlays: Sequence[Optional[HkxPhysicsOverlayData]]) -> Optional[HkxPhysicsOverlayData]:
    valid = [overlay for overlay in overlays if isinstance(overlay, HkxPhysicsOverlayData) and overlay.shapes]
    if not valid:
        return None
    shapes: List[HkxPhysicsOverlayShape] = []
    anchors: List[HkxPhysicsOverlayAnchor] = []
    constraints: List[HkxPhysicsOverlayConstraint] = []
    bones: List[HkxPhysicsOverlayBone] = []
    source_paths: List[str] = []
    body_count = 0
    constraint_count = 0
    limitations: List[str] = []
    role_counter: Counter[str] = Counter()
    for overlay in valid:
        shapes.extend(overlay.shapes)
        anchors.extend(overlay.anchors)
        constraints.extend(overlay.constraints)
        bones.extend(overlay.bones)
        body_count += int(overlay.body_count or 0)
        constraint_count += int(overlay.constraint_count or 0)
        for role, count in tuple(getattr(overlay, "simulation_role_counts", ()) or ()):
            role_counter[str(role)] += int(count)
        for source_path in overlay.source_paths:
            if source_path not in source_paths:
                source_paths.append(source_path)
        for limitation in overlay.limitations:
            if limitation not in limitations:
                limitations.append(limitation)
    return HkxPhysicsOverlayData(
        summary=f"HKX physics overlay: {len(shapes):,} decoded shape(s) from {len(source_paths):,} HKX file(s)",
        source_paths=tuple(source_paths),
        simulation_role_counts=tuple(sorted(role_counter.items())),
        shapes=tuple(shapes),
        anchors=tuple(anchors),
        constraints=tuple(constraints),
        bones=tuple(bones),
        body_count=body_count,
        constraint_count=constraint_count,
        limitations=tuple(limitations),
    )


def _hkx_preview_float(value: object, fallback: float = 0.0) -> float:
    try:
        result = float(value)
    except (TypeError, ValueError, OverflowError):
        return fallback
    return result if math.isfinite(result) else fallback


def _hkx_preview_vector(value: object) -> Tuple[float, float, float]:
    if not isinstance(value, (list, tuple)) or len(value) < 3:
        return ()
    try:
        point = (float(value[0]), float(value[1]), float(value[2]))
    except (TypeError, ValueError, OverflowError):
        return ()
    return point if all(math.isfinite(component) for component in point) else ()


def _hkx_preview_bounds(points: Sequence[Tuple[float, float, float]]) -> Tuple[Tuple[float, float, float], Tuple[float, float, float]]:
    if not points:
        return (), ()
    return (
        (
            min(point[0] for point in points),
            min(point[1] for point in points),
            min(point[2] for point in points),
        ),
        (
            max(point[0] for point in points),
            max(point[1] for point in points),
            max(point[2] for point in points),
        ),
    )


def _hkx_preview_dimension(points: Sequence[Tuple[float, float, float]]) -> float:
    bounds_min, bounds_max = _hkx_preview_bounds(points)
    if not bounds_min or not bounds_max:
        return 1.0
    return max(
        abs(bounds_max[0] - bounds_min[0]),
        abs(bounds_max[1] - bounds_min[1]),
        abs(bounds_max[2] - bounds_min[2]),
        1e-4,
    )


def _hkx_preview_vec_add(
    a: Tuple[float, float, float],
    b: Tuple[float, float, float],
) -> Tuple[float, float, float]:
    return (a[0] + b[0], a[1] + b[1], a[2] + b[2])


def _hkx_preview_vec_sub(
    a: Tuple[float, float, float],
    b: Tuple[float, float, float],
) -> Tuple[float, float, float]:
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])


def _hkx_preview_vec_scale(
    value: Tuple[float, float, float],
    scale: float,
) -> Tuple[float, float, float]:
    return (value[0] * scale, value[1] * scale, value[2] * scale)


def _hkx_preview_vec_cross(
    a: Tuple[float, float, float],
    b: Tuple[float, float, float],
) -> Tuple[float, float, float]:
    return (
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    )


def _hkx_preview_vec_length(value: Tuple[float, float, float]) -> float:
    return math.sqrt(value[0] * value[0] + value[1] * value[1] + value[2] * value[2])


def _hkx_preview_vec_normalize(
    value: Tuple[float, float, float],
    fallback: Tuple[float, float, float] = (0.0, 1.0, 0.0),
) -> Tuple[float, float, float]:
    length = _hkx_preview_vec_length(value)
    if length <= 1e-9 or not math.isfinite(length):
        return fallback
    return (value[0] / length, value[1] / length, value[2] / length)


def _hkx_preview_box_mesh(
    bounds_min: Tuple[float, float, float],
    bounds_max: Tuple[float, float, float],
    *,
    material_name: str,
    preview_color: Tuple[float, float, float],
    source_submesh_index: int = -1,
    preview_role: str = "",
) -> Optional[ModelPreviewMesh]:
    if len(bounds_min) < 3 or len(bounds_max) < 3:
        return None
    min_x, min_y, min_z = bounds_min
    max_x, max_y, max_z = bounds_max
    if max(abs(max_x - min_x), abs(max_y - min_y), abs(max_z - min_z)) <= 1e-9:
        return None
    positions = [
        (min_x, min_y, min_z),
        (max_x, min_y, min_z),
        (max_x, max_y, min_z),
        (min_x, max_y, min_z),
        (min_x, min_y, max_z),
        (max_x, min_y, max_z),
        (max_x, max_y, max_z),
        (min_x, max_y, max_z),
    ]
    indices = [
        0, 1, 2, 0, 2, 3,
        4, 6, 5, 4, 7, 6,
        0, 4, 5, 0, 5, 1,
        1, 5, 6, 1, 6, 2,
        2, 6, 7, 2, 7, 3,
        3, 7, 4, 3, 4, 0,
    ]
    return ModelPreviewMesh(
        material_name=material_name,
        preview_color=preview_color,
        positions=positions,
        indices=indices,
        source_submesh_index=source_submesh_index,
        source_vertex_indices=list(range(len(positions))),
        preview_role=preview_role,
    )


def _hkx_preview_triangulated_indices(
    raw_faces: object,
    vertex_count: int,
) -> List[int]:
    indices: List[int] = []
    if not isinstance(raw_faces, list):
        return indices
    for raw_face in raw_faces:
        if not isinstance(raw_face, (list, tuple)):
            continue
        face: List[int] = []
        for raw_index in raw_face:
            try:
                index = int(raw_index)
            except (TypeError, ValueError, OverflowError):
                continue
            if 0 <= index < vertex_count and index not in face:
                face.append(index)
        if len(face) < 3:
            continue
        for face_index in range(1, len(face) - 1):
            indices.extend((face[0], face[face_index], face[face_index + 1]))
    return indices


def _hkx_preview_cylinder_mesh(
    start: Tuple[float, float, float],
    end: Tuple[float, float, float],
    radius: float,
    *,
    material_name: str,
    preview_color: Tuple[float, float, float],
    source_submesh_index: int = -1,
    preview_role: str = "",
    sides: int = 8,
) -> Optional[ModelPreviewMesh]:
    axis = _hkx_preview_vec_sub(end, start)
    length = _hkx_preview_vec_length(axis)
    if length <= 1e-8:
        return _hkx_preview_marker_mesh(
            start,
            radius=max(radius * 2.0, 0.001),
            material_name=material_name,
            preview_color=preview_color,
            source_submesh_index=source_submesh_index,
            preview_role=preview_role,
        )
    direction = _hkx_preview_vec_scale(axis, 1.0 / length)
    up = (0.0, 1.0, 0.0) if abs(direction[1]) < 0.92 else (1.0, 0.0, 0.0)
    tangent = _hkx_preview_vec_normalize(_hkx_preview_vec_cross(direction, up), (1.0, 0.0, 0.0))
    bitangent = _hkx_preview_vec_normalize(_hkx_preview_vec_cross(direction, tangent), (0.0, 0.0, 1.0))
    radius = max(0.0005, abs(float(radius)))
    sides = max(5, int(sides))
    positions: List[Tuple[float, float, float]] = []
    for base in (start, end):
        for side in range(sides):
            angle = (math.tau * side) / float(sides)
            offset = _hkx_preview_vec_add(
                _hkx_preview_vec_scale(tangent, math.cos(angle) * radius),
                _hkx_preview_vec_scale(bitangent, math.sin(angle) * radius),
            )
            positions.append(_hkx_preview_vec_add(base, offset))
    start_center = len(positions)
    positions.append(start)
    end_center = len(positions)
    positions.append(end)
    indices: List[int] = []
    for side in range(sides):
        next_side = (side + 1) % sides
        a = side
        b = next_side
        c = sides + next_side
        d = sides + side
        indices.extend((a, b, c, a, c, d))
        indices.extend((start_center, b, a))
        indices.extend((end_center, d, c))
    return ModelPreviewMesh(
        material_name=material_name,
        preview_color=preview_color,
        positions=positions,
        indices=indices,
        source_submesh_index=source_submesh_index,
        source_vertex_indices=list(range(len(positions))),
        preview_role=preview_role,
    )


def _hkx_preview_marker_mesh(
    center: Tuple[float, float, float],
    radius: float,
    *,
    material_name: str,
    preview_color: Tuple[float, float, float],
    source_submesh_index: int = -1,
    preview_role: str = "",
) -> Optional[ModelPreviewMesh]:
    if len(center) < 3:
        return None
    radius = max(0.0005, abs(float(radius)))
    cx, cy, cz = center
    positions = [
        (cx + radius, cy, cz),
        (cx - radius, cy, cz),
        (cx, cy + radius, cz),
        (cx, cy - radius, cz),
        (cx, cy, cz + radius),
        (cx, cy, cz - radius),
    ]
    indices = [
        0, 2, 4, 2, 1, 4, 1, 3, 4, 3, 0, 4,
        2, 0, 5, 1, 2, 5, 3, 1, 5, 0, 3, 5,
    ]
    return ModelPreviewMesh(
        material_name=material_name,
        preview_color=preview_color,
        positions=positions,
        indices=indices,
        source_submesh_index=source_submesh_index,
        source_vertex_indices=list(range(len(positions))),
        preview_role=preview_role,
    )


def _hkx_preview_sphere_mesh(
    center: Tuple[float, float, float],
    radius: float,
    *,
    material_name: str,
    preview_color: Tuple[float, float, float],
    source_submesh_index: int = -1,
    preview_role: str = "",
    segments: int = 10,
    rings: int = 5,
) -> Optional[ModelPreviewMesh]:
    if len(center) < 3:
        return None
    radius = max(0.0005, abs(float(radius)))
    segments = max(6, int(segments))
    rings = max(3, int(rings))
    cx, cy, cz = center
    positions: List[Tuple[float, float, float]] = []
    for ring in range(rings + 1):
        phi = math.pi * float(ring) / float(rings)
        y = math.cos(phi) * radius
        ring_radius = math.sin(phi) * radius
        for segment in range(segments):
            theta = math.tau * float(segment) / float(segments)
            positions.append((cx + math.cos(theta) * ring_radius, cy + y, cz + math.sin(theta) * ring_radius))
    indices: List[int] = []
    for ring in range(rings):
        for segment in range(segments):
            next_segment = (segment + 1) % segments
            a = ring * segments + segment
            b = ring * segments + next_segment
            c = (ring + 1) * segments + next_segment
            d = (ring + 1) * segments + segment
            indices.extend((a, b, c, a, c, d))
    return ModelPreviewMesh(
        material_name=material_name,
        preview_color=preview_color,
        positions=positions,
        indices=indices,
        source_submesh_index=source_submesh_index,
        source_vertex_indices=list(range(len(positions))),
        preview_role=preview_role,
    )


def _hkx_preview_edges_from_faces(raw_faces: object, vertex_count: int) -> Tuple[Tuple[int, int], ...]:
    if not isinstance(raw_faces, list):
        return ()
    edges: set[Tuple[int, int]] = set()
    for raw_face in raw_faces:
        if not isinstance(raw_face, (list, tuple)):
            continue
        face: List[int] = []
        for raw_index in raw_face:
            try:
                index = int(raw_index)
            except (TypeError, ValueError, OverflowError):
                continue
            if 0 <= index < vertex_count:
                face.append(index)
        if len(face) < 2:
            continue
        for edge_index, start in enumerate(face):
            end = face[(edge_index + 1) % len(face)]
            if start == end:
                continue
            edges.add((min(start, end), max(start, end)))
    return tuple(sorted(edges))


def _hkx_preview_shape_meshes(
    shape: Mapping[str, object],
    *,
    source_path: str,
    shape_index: int,
    preview_extent: float,
) -> List[ModelPreviewMesh]:
    shape_type = str(shape.get("shape_type") or "hknpShape")
    label = shape_type
    name_hint = shape.get("name_hint")
    if isinstance(name_hint, Mapping) and str(name_hint.get("name") or "").strip():
        label = str(name_hint.get("name") or "").strip()
    elif isinstance(shape.get("body_contexts"), list):
        first_context = next((context for context in shape.get("body_contexts", []) if isinstance(context, Mapping)), None)
        if isinstance(first_context, Mapping):
            label = str(first_context.get("body_name") or first_context.get("socket_name") or label)
    material_name = f"HKX {shape_index}: {label}"
    mesh_color = (0.34, 0.62, 0.72)
    meshes: List[ModelPreviewMesh] = []
    raw_vertices = shape.get("vertices")
    vertices = [
        point
        for point in (_hkx_preview_vector(raw_vertex) for raw_vertex in (raw_vertices if isinstance(raw_vertices, list) else []))
        if point
    ]
    raw_faces = shape.get("faces")
    if not isinstance(raw_faces, list):
        hull_topology = shape.get("hull_topology")
        if isinstance(hull_topology, Mapping):
            raw_faces = hull_topology.get("face_vertex_loops")
    indices = _hkx_preview_triangulated_indices(raw_faces, len(vertices))
    if vertices and indices:
        meshes.append(
            ModelPreviewMesh(
                material_name=material_name,
                preview_color=mesh_color,
                positions=list(vertices),
                indices=indices,
                source_submesh_index=shape_index,
                source_vertex_indices=list(range(len(vertices))),
                preview_role="hkx_collision_shape",
            )
        )
        edge_radius = max(0.00035, float(preview_extent) * 0.0014)
        edge_meshes = [
            edge_mesh
            for edge_mesh in (
                _hkx_preview_cylinder_mesh(
                    vertices[start],
                    vertices[end],
                    edge_radius,
                    material_name=f"{material_name} outline",
                    preview_color=(0.08, 0.18, 0.21),
                    source_submesh_index=shape_index,
                    preview_role="hkx_collision_outline",
                    sides=6,
                )
                for start, end in _hkx_preview_edges_from_faces(raw_faces, len(vertices))[:128]
            )
            if edge_mesh is not None
        ]
        meshes.extend(edge_meshes)
        return meshes

    bounds_min = _hkx_preview_vector(shape.get("bounds_min"))
    bounds_max = _hkx_preview_vector(shape.get("bounds_max"))
    if bounds_min and bounds_max:
        box = _hkx_preview_box_mesh(
            bounds_min,
            bounds_max,
            material_name=material_name,
            preview_color=mesh_color,
            source_submesh_index=shape_index,
            preview_role="hkx_collision_bounds",
        )
        return [box] if box is not None else []

    center = _hkx_preview_vector(shape.get("center")) or _hkx_preview_vector(shape.get("sphere_center"))
    radius = 0.0
    for key in ("sphere_radius", "capsule_radius", "radius"):
        value = shape.get(key)
        if isinstance(value, (int, float)):
            radius = max(radius, abs(_hkx_preview_float(value)))
    endpoints = shape.get("capsule_endpoints")
    if isinstance(endpoints, list) and len(endpoints) >= 2:
        start = _hkx_preview_vector(endpoints[0])
        end = _hkx_preview_vector(endpoints[1])
        if start and end:
            capsule_meshes: List[ModelPreviewMesh] = []
            body = _hkx_preview_cylinder_mesh(
                start,
                end,
                max(radius, float(preview_extent) * 0.012),
                material_name=material_name,
                preview_color=mesh_color,
                source_submesh_index=shape_index,
                preview_role="hkx_collision_capsule",
                sides=10,
            )
            if body is not None:
                capsule_meshes.append(body)
            for marker_center in (start, end):
                marker = _hkx_preview_sphere_mesh(
                    marker_center,
                    max(radius, float(preview_extent) * 0.012),
                    material_name=f"{material_name} cap",
                    preview_color=mesh_color,
                    source_submesh_index=shape_index,
                    preview_role="hkx_collision_capsule_cap",
                )
                if marker is not None:
                    capsule_meshes.append(marker)
            return capsule_meshes
    if center and radius > 0.0:
        sphere = _hkx_preview_sphere_mesh(
            center,
            radius,
            material_name=material_name,
            preview_color=mesh_color,
            source_submesh_index=shape_index,
            preview_role="hkx_collision_sphere",
        )
        return [sphere] if sphere is not None else []
    return []


def _hkx_preview_skeleton_meshes(
    skeleton_bone_positions: Optional[Mapping[str, object]],
    *,
    preview_extent: float,
    limit: int = 384,
) -> List[ModelPreviewMesh]:
    if not isinstance(skeleton_bone_positions, Mapping) or not skeleton_bone_positions:
        return []
    rows: List[Mapping[str, object]] = [
        row
        for row in skeleton_bone_positions.values()
        if isinstance(row, Mapping) and _hkx_preview_vector(row.get("position"))
    ]
    rows.sort(key=lambda row: int(row.get("index")) if isinstance(row.get("index"), int) else 1_000_000)
    rows_by_index = {int(row.get("index")): row for row in rows if isinstance(row.get("index"), int)}
    rows_by_name = {str(row.get("name") or ""): row for row in rows if str(row.get("name") or "")}
    radius = max(0.0015, float(preview_extent) * 0.0045)
    meshes: List[ModelPreviewMesh] = []
    for row in rows[:limit]:
        name = str(row.get("name") or f"bone {len(meshes)}")
        position = _hkx_preview_vector(row.get("position"))
        parent_index = row.get("parent_index")
        parent_name = str(row.get("parent_name") or "")
        parent_row = rows_by_index.get(parent_index) if isinstance(parent_index, int) else None
        if parent_row is None and parent_name:
            parent_row = rows_by_name.get(parent_name)
        parent_position = _hkx_preview_vector(parent_row.get("position")) if isinstance(parent_row, Mapping) else ()
        if parent_position:
            mesh = _hkx_preview_cylinder_mesh(
                parent_position,
                position,
                radius,
                material_name=f"Skeleton: {parent_name or 'parent'} -> {name}",
                preview_color=(0.28, 0.68, 0.92),
                preview_role="hkx_skeleton_bone",
                sides=7,
            )
        else:
            mesh = _hkx_preview_marker_mesh(
                position,
                radius * 2.4,
                material_name=f"Skeleton: {name}",
                preview_color=(0.55, 0.78, 0.95),
                preview_role="hkx_skeleton_joint",
            )
        if mesh is not None:
            meshes.append(mesh)
    return meshes


def build_hkx_model_preview_from_document(
    document: Mapping[str, object],
    *,
    source_path: str = "",
    skeleton_bone_positions: Optional[Mapping[str, object]] = None,
    max_shapes: int = 96,
) -> Optional[ModelPreviewData]:
    """Convert decoded HKX collision and skeleton context into a real preview mesh.

    Native preview paths consume ModelPreviewData triangle batches.
    This visual model is not a Havok simulation; it is a display mesh for recovered
    collision surfaces plus related skeleton bones when PAB context is available.
    """

    shapes_value = document.get("collision_shapes") or document.get("shapes")
    if not isinstance(shapes_value, list):
        return None
    shape_points: List[Tuple[float, float, float]] = []
    for shape in shapes_value[:max_shapes]:
        if not isinstance(shape, Mapping):
            continue
        for raw_vertex in shape.get("vertices") if isinstance(shape.get("vertices"), list) else []:
            point = _hkx_preview_vector(raw_vertex)
            if point:
                shape_points.append(point)
        for key in ("bounds_min", "bounds_max", "center", "sphere_center"):
            point = _hkx_preview_vector(shape.get(key))
            if point:
                shape_points.append(point)
        endpoints = shape.get("capsule_endpoints")
        if isinstance(endpoints, list):
            for endpoint in endpoints[:2]:
                point = _hkx_preview_vector(endpoint)
                if point:
                    shape_points.append(point)
    skeleton_points = [
        point
        for point in (
            _hkx_preview_vector(row.get("position"))
            for row in (
                skeleton_bone_positions.values()
                if isinstance(skeleton_bone_positions, Mapping)
                else ()
            )
            if isinstance(row, Mapping)
        )
        if point
    ]
    preview_extent = _hkx_preview_dimension(tuple(shape_points + skeleton_points))
    meshes: List[ModelPreviewMesh] = []
    for shape_index, shape in enumerate(shapes_value[:max_shapes]):
        if not isinstance(shape, Mapping):
            continue
        meshes.extend(
            _hkx_preview_shape_meshes(
                shape,
                source_path=source_path,
                shape_index=int(shape.get("index")) if isinstance(shape.get("index"), int) else shape_index,
                preview_extent=preview_extent,
            )
        )
    meshes.extend(_hkx_preview_skeleton_meshes(skeleton_bone_positions, preview_extent=preview_extent))
    if not meshes:
        return None
    preview = _build_model_preview(source_path, "hkx", meshes, "HKX preview batch")
    overlay = build_hkx_physics_overlay_from_document(
        document,
        source_path=source_path,
        normalization_center=preview.normalization_center,
        normalization_scale=preview.normalization_scale,
        skeleton_bone_positions=skeleton_bone_positions,
    )
    preview.physics_overlay = overlay
    collision_shape_count = sum(1 for shape in shapes_value if isinstance(shape, Mapping))
    skeleton_bone_count = len(skeleton_points)
    preview.summary = (
        f"{source_path}\n"
        f"HKX collision/skeleton preview\n"
        f"{collision_shape_count:,} decoded shape(s)\n"
        f"{skeleton_bone_count:,} skeleton bone(s)\n"
        f"{preview.vertex_count:,} vertices\n"
        f"{preview.face_count:,} faces"
    )
    return preview


def build_hkx_editable_geometry_json(
    data: bytes,
    virtual_path: str = "",
    companion_descriptor_hints: Optional[Sequence[Mapping[str, object]]] = None,
) -> str:
    return json.dumps(
        build_hkx_editable_geometry_document(data, virtual_path, companion_descriptor_hints),
        indent=2,
        sort_keys=True,
    )


_HKX_DESCRIPTOR_NUMERIC_HINT_DESCRIPTIONS: Dict[str, str] = {
    "_angularDamping": "Likely angular damping for a dynamic attachment body; higher values usually reduce rotation/jiggle.",
    "_linearDamping": "Likely linear damping for a dynamic attachment body; higher values usually reduce positional swing.",
    "_inertiaFactor": "Likely inertia scaling for a dynamic body; higher values usually make it resist motion changes more.",
    "_sphereRadius": "Capsule end-sphere radius from descriptor XML.",
    "_cylinderHeight": "Capsule cylinder length/height from descriptor XML.",
    "_radius": "Sphere radius from descriptor XML.",
    "_maxFrictionTorque": "Constraint friction torque; often controls how strongly a joint resists free rotation.",
    "_angularLimitMin": "Minimum angular limits from descriptor XML, usually a three-component vector.",
    "_angularLimitMax": "Maximum angular limits from descriptor XML, usually a three-component vector.",
    "_coneAngle": "Ragdoll cone angle limit from descriptor XML.",
    "_twistMin": "Ragdoll twist minimum limit from descriptor XML.",
    "_twistMax": "Ragdoll twist maximum limit from descriptor XML.",
    "_planeMin": "Ragdoll plane minimum limit from descriptor XML.",
    "_planeMax": "Ragdoll plane maximum limit from descriptor XML.",
    "_localTranslation": "Body/socket local translation hint from descriptor XML.",
    "_shapeLocalTranslation": "Shape local translation hint from descriptor XML.",
    "_localRotation": "Body/socket local rotation quaternion hint from descriptor XML.",
    "_shapeLocalRotation": "Shape local rotation quaternion hint from descriptor XML.",
}


def _hkx_descriptor_element_local_name(element: ET.Element) -> str:
    return str(element.tag).rsplit("}", 1)[-1]


def _hkx_descriptor_numeric_hint_values(element: ET.Element) -> List[Dict[str, object]]:
    hints: List[Dict[str, object]] = []
    for name, description in _HKX_DESCRIPTOR_NUMERIC_HINT_DESCRIPTIONS.items():
        value = str(element.get(name) or "").strip()
        if not value:
            continue
        hints.append({"name": name, "value": value, "description": description})
    return hints


def _hkx_descriptor_core_attributes(element: ET.Element) -> Dict[str, str]:
    result: Dict[str, str] = {}
    for source_name, target_name in (
        ("_bodyName", "body_name"),
        ("_socketName", "socket_name"),
        ("_fixedSocketName", "fixed_socket_name"),
        ("_physicsMaterialName", "physics_material_name"),
        ("_name", "name"),
    ):
        value = str(element.get(source_name) or "").strip()
        if value:
            result[target_name] = value
    return result


def _hkx_descriptor_shape_type(tag_name: str) -> str:
    lowered = tag_name.lower()
    if "capsule" in lowered:
        return "capsule"
    if "sphere" in lowered:
        return "sphere"
    if "box" in lowered:
        return "box"
    if "convex" in lowered:
        return "convex"
    if "mesh" in lowered:
        return "mesh"
    return "shape"


def _hkx_descriptor_body_documents(root: ET.Element) -> List[Dict[str, object]]:
    bodies: List[Dict[str, object]] = []
    for element in root.iter():
        tag_name = _hkx_descriptor_element_local_name(element)
        if not tag_name.endswith("BodyCreationDesc"):
            continue
        body: Dict[str, object] = {
            "index": len(bodies),
            "tag": tag_name,
            "numeric_hints": _hkx_descriptor_numeric_hint_values(element),
            "shape_descriptors": [],
        }
        body.update(_hkx_descriptor_core_attributes(element))
        shape_descriptors: List[Dict[str, object]] = []
        for child in list(element):
            child_tag = _hkx_descriptor_element_local_name(child)
            if not child_tag.endswith("ShapeDesc"):
                continue
            shape: Dict[str, object] = {
                "index": len(shape_descriptors),
                "tag": child_tag,
                "shape_kind": _hkx_descriptor_shape_type(child_tag),
                "numeric_hints": _hkx_descriptor_numeric_hint_values(child),
            }
            shape.update(_hkx_descriptor_core_attributes(child))
            shape_descriptors.append(shape)
        body["shape_descriptors"] = shape_descriptors
        bodies.append(body)
    return bodies


def _hkx_descriptor_material_simulation_documents(root: ET.Element) -> List[Dict[str, object]]:
    hints: List[Dict[str, object]] = []
    seen: set[Tuple[str, str, str]] = set()
    for element in root.iter():
        tag_name = _hkx_descriptor_element_local_name(element)
        values = {
            "pbd_simulation_material": str(element.get("_pbdSimulationMaterialName") or "").strip(),
            "material_name": str(element.get("_materialName") or "").strip(),
            "submesh_name": str(element.get("_subMeshName") or "").strip(),
            "jiggle_wind_weight": str(element.get("_jiggleWindWeight") or "").strip(),
            "parameter_name": str(element.get("_name") or "").strip(),
            "parameter_value": str(element.get("_value") or "").strip(),
        }
        role = _hkx_simulation_role_from_parts(tag_name, *values.values())
        if role == "collision":
            continue
        key = (values["pbd_simulation_material"], values["material_name"], values["submesh_name"] or values["parameter_name"])
        if key in seen:
            continue
        seen.add(key)
        hint = {
            "index": len(hints),
            "tag": tag_name,
            "simulation_role": role,
            "simulation_role_description": _hkx_simulation_role_description(role),
            "description": (
                "Model/material sidecar simulation hint. This helps classify rendered meshes as cloth, hair, or "
                "dynamic attachments; it is read-only context and is ignored by HKX import."
            ),
        }
        for key_name, value in values.items():
            if value:
                hint[key_name] = value
        hints.append(hint)
        if len(hints) >= 256:
            break
    return hints


def _hkx_descriptor_constraint_documents(root: ET.Element) -> List[Dict[str, object]]:
    constraints: List[Dict[str, object]] = []
    consumed_element_ids: set[int] = set()
    for instance in root.iter():
        instance_tag = _hkx_descriptor_element_local_name(instance)
        if "Instance" not in instance_tag:
            continue
        body_elements = [
            child
            for child in list(instance)
            if _hkx_descriptor_element_local_name(child).endswith("BodyCreationDesc")
        ]
        if len(body_elements) < 2:
            continue
        constraint_elements = [
            child
            for child in instance.iter()
            if "ConstraintDesc" in _hkx_descriptor_element_local_name(child)
        ]
        if not constraint_elements:
            continue
        parent_body = next(
            (
                body
                for body in body_elements
                if str(body.get("Name") or "").strip().casefold() == "_parentbodydesc"
            ),
            body_elements[0],
        )
        child_body = next(
            (
                body
                for body in body_elements
                if str(body.get("Name") or "").strip().casefold() == "_childbodydesc"
            ),
            body_elements[1],
        )
        parent_attributes = _hkx_descriptor_core_attributes(parent_body)
        child_attributes = _hkx_descriptor_core_attributes(child_body)
        for element in constraint_elements:
            tag_name = _hkx_descriptor_element_local_name(element)
            constraint: Dict[str, object] = {
                "index": len(constraints),
                "tag": tag_name,
                "numeric_hints": _hkx_descriptor_numeric_hint_values(element),
            }
            constraint.update(_hkx_descriptor_core_attributes(element))
            constraint.setdefault("body_name", child_attributes.get("body_name"))
            constraint.setdefault("socket_name", child_attributes.get("socket_name"))
            constraint.setdefault("fixed_socket_name", parent_attributes.get("socket_name") or parent_attributes.get("body_name"))
            if parent_attributes.get("body_name"):
                constraint["fixed_body_name"] = parent_attributes.get("body_name")
            if parent_attributes.get("socket_name"):
                constraint["parent_socket_name"] = parent_attributes.get("socket_name")
            constraints.append(constraint)
            consumed_element_ids.add(id(element))
    for element in root.iter():
        tag_name = _hkx_descriptor_element_local_name(element)
        if "ConstraintDesc" not in tag_name:
            continue
        if id(element) in consumed_element_ids:
            continue
        constraint: Dict[str, object] = {
            "index": len(constraints),
            "tag": tag_name,
            "numeric_hints": _hkx_descriptor_numeric_hint_values(element),
        }
        constraint.update(_hkx_descriptor_core_attributes(element))
        constraints.append(constraint)
    return constraints


def _hkx_descriptor_unique_values(root: ET.Element, attribute_names: Sequence[str], *, limit: int = 128) -> Dict[str, List[str]]:
    values: Dict[str, List[str]] = {name: [] for name in attribute_names}
    seen: Dict[str, set[str]] = {name: set() for name in attribute_names}
    for element in root.iter():
        for name in attribute_names:
            value = str(element.get(name) or "").strip()
            if not value or value in seen[name]:
                continue
            seen[name].add(value)
            values[name].append(value)
            if len(values[name]) >= limit:
                break
    return {name: collected for name, collected in values.items() if collected}


def _hkx_descriptor_hint_from_root(root: ET.Element, source_path: str) -> Optional[Dict[str, object]]:
    body_values = _hkx_descriptor_unique_values(root, ("_bodyName", "_socketName", "_fixedSocketName", "_physicsMaterialName"))
    numeric_values = _hkx_descriptor_unique_values(root, tuple(_HKX_DESCRIPTOR_NUMERIC_HINT_DESCRIPTIONS))
    body_descriptors = _hkx_descriptor_body_documents(root)
    constraint_descriptors = _hkx_descriptor_constraint_documents(root)
    material_simulation_hints = _hkx_descriptor_material_simulation_documents(root)
    if not body_values and not numeric_values and not body_descriptors and not constraint_descriptors and not material_simulation_hints:
        return None
    body_desc_count = sum(1 for element in root.iter() if element.tag.endswith("BodyCreationDesc"))
    constraint_desc_count = sum(1 for element in root.iter() if "ConstraintDesc" in element.tag)
    shape_desc_count = sum(1 for element in root.iter() if element.tag.endswith("ShapeDesc"))
    source = Path(source_path.replace("\\", "/")).name if source_path else ""
    return {
        "path": source_path,
        "stem": Path(source).stem if source else "",
        "root_tag": root.tag,
        "body_desc_count": body_desc_count,
        "constraint_desc_count": constraint_desc_count,
        "shape_desc_count": shape_desc_count,
        "material_simulation_hint_count": len(material_simulation_hints),
        "body_names": body_values.get("_bodyName", []),
        "socket_names": body_values.get("_socketName", []),
        "fixed_socket_names": body_values.get("_fixedSocketName", []),
        "physics_material_names": body_values.get("_physicsMaterialName", []),
        "numeric_hints": [
            {
                "name": name,
                "values": values,
                "description": _HKX_DESCRIPTOR_NUMERIC_HINT_DESCRIPTIONS.get(name, "Descriptor XML numeric hint."),
            }
            for name, values in sorted(numeric_values.items())
        ],
        "body_descriptors": body_descriptors,
        "constraint_descriptors": constraint_descriptors,
        "material_simulation_hints": material_simulation_hints,
        "description": (
            "Physics descriptor XML hints. These names and values are not imported into HKX automatically, "
            "but they help label likely body, socket, damping, inertia, shape, friction, and angular-limit roles."
        ),
    }


def build_hkx_descriptor_hint_from_xml_text(text: str, virtual_path: str = "") -> Optional[Dict[str, object]]:
    """Extract readable physics/body naming hints from a companion descriptor XML string."""

    try:
        root = ET.fromstring(text)
    except Exception:
        return None
    return _hkx_descriptor_hint_from_root(root, virtual_path)


def _hkx_descriptor_hint_document(path: Path) -> Optional[Dict[str, object]]:
    try:
        root = ET.parse(path).getroot()
    except Exception:
        return None
    return _hkx_descriptor_hint_from_root(root, str(path))


def _hkx_descriptor_hints_by_stem(
    paths: Sequence[Path | str],
    hkx_stems: set[str],
    *,
    stop_event: Optional[threading.Event] = None,
) -> Dict[str, List[Dict[str, object]]]:
    descriptor_paths: List[Path] = []
    for raw_path in paths:
        raise_if_cancelled(stop_event)
        path = Path(raw_path)
        if path.is_file() and path.suffix.lower() == ".xml":
            descriptor_paths.append(path)
        elif path.is_dir():
            for candidate in path.rglob("*.xml"):
                raise_if_cancelled(stop_event)
                candidate_text = str(candidate).casefold()
                if candidate.stem in hkx_stems or "physics" in candidate_text:
                    descriptor_paths.append(candidate)
    hints_by_stem: Dict[str, List[Dict[str, object]]] = defaultdict(list)
    for path in sorted(dict.fromkeys(descriptor_paths), key=lambda item: str(item).casefold()):
        raise_if_cancelled(stop_event)
        hint = _hkx_descriptor_hint_document(path)
        if hint is not None:
            hints_by_stem[path.stem].append(hint)
    return hints_by_stem


def _hkx_corpus_role_for_document(path: Path, document: Mapping[str, object], report: Mapping[str, object]) -> str:
    path_text = str(path).replace("\\", "/").casefold()
    type_names: set[str] = set()
    type_registry = document.get("type_registry")
    if isinstance(type_registry, Mapping):
        raw_type_names = type_registry.get("type_names")
        if isinstance(raw_type_names, list):
            type_names.update(str(value) for value in raw_type_names if str(value))
    collision_shapes = document.get("collision_shapes")
    shape_types: set[str] = set()
    if isinstance(collision_shapes, list):
        for shape in collision_shapes:
            if isinstance(shape, Mapping):
                shape_types.add(str(shape.get("shape_type") or ""))
    physics_constraint_summary = document.get("physics_constraint_summary")
    constraint_count = (
        int(physics_constraint_summary.get("constraint_count") or 0)
        if isinstance(physics_constraint_summary, Mapping)
        else 0
    )
    if "meshphysics" in path_text or "/cloak/" in path_text or "cloak" in path_text:
        return "cloak_or_meshphysics"
    if "havokphysics" in path_text or "ragdoll" in path_text or constraint_count > 0 or "hknpRagdollData" in type_names:
        return "character_havokphysics_or_ragdoll"
    has_mesh_shape = "hknpMeshShape" in type_names or "hknpMeshShape" in shape_types
    has_convex_or_simple_shape = any(
        type_name in type_names or type_name in shape_types
        for type_name in ("hknpConvexShape", "hknpBoxShape", "hknpSphereShape", "hknpCapsuleShape")
    )
    if has_mesh_shape:
        return "mesh_shape_heavy"
    if has_convex_or_simple_shape and "/object/" in path_text:
        return "small_object_convex"
    if "animation" in path_text or "/motion/" in path_text or "hka" in " ".join(type_names).casefold():
        return "animation_or_metadata"
    if has_convex_or_simple_shape:
        return "small_object_convex"
    if any(type_name.startswith("hknp") for type_name in type_names):
        return "generic_hknp_physics"
    return "unknown_or_nonphysics_hkx"


def _hkx_corpus_role_hint_from_path(path: Path) -> str:
    path_text = str(path).replace("\\", "/").casefold()
    if "meshphysics" in path_text or "/cloak/" in path_text or "cloak" in path_text:
        return "cloak_or_meshphysics"
    if "havokphysics" in path_text or "ragdoll" in path_text:
        return "character_havokphysics_or_ragdoll"
    if "meshshape" in path_text or "mesh_shape" in path_text:
        return "mesh_shape_heavy"
    if "animation" in path_text or "/motion/" in path_text or "/anim" in path_text:
        return "animation_or_metadata"
    if "/object/" in path_text or path_text.endswith(".hkx"):
        return "small_object_convex"
    return "unknown_or_nonphysics_hkx"


def _hkx_path_contains_binary_marker(
    path: Path,
    marker: bytes,
    *,
    chunk_size: int = 262_144,
    stop_event: Optional[threading.Event] = None,
) -> bool:
    if not marker:
        return False
    overlap = max(0, len(marker) - 1)
    previous_tail = b""
    try:
        with path.open("rb") as handle:
            while True:
                raise_if_cancelled(stop_event)
                chunk = handle.read(chunk_size)
                if not chunk:
                    return False
                haystack = previous_tail + chunk
                if marker in haystack:
                    return True
                previous_tail = haystack[-overlap:] if overlap else b""
    except OSError:
        return False


def _hkx_enrich_balanced_corpus_content_hints(
    by_role: MutableMapping[str, List[Path]],
    paths: Sequence[Path],
    *,
    stop_event: Optional[threading.Event] = None,
) -> None:
    """Promote likely mesh-shape files into the limited representative sample.

    Path names alone cannot reliably distinguish small convex object HKX from object HKX that carry
    hknpMeshShape topology. This bounded marker pass keeps limited corpus reports representative
    without requiring a full Python decode of every file.
    """

    scan_limit = 2048
    try:
        env_limit = os.environ.get("CDMW_HKX_CORPUS_BALANCE_CONTENT_LIMIT")
        if env_limit is not None and str(env_limit).strip():
            scan_limit = max(0, int(str(env_limit).strip()))
    except (TypeError, ValueError, OverflowError):
        scan_limit = 2048
    if scan_limit <= 0:
        return
    scanned = 0
    promoted: List[Path] = []
    for path in paths:
        raise_if_cancelled(stop_event)
        hint = _hkx_corpus_role_hint_from_path(path)
        if hint not in {"small_object_convex", "unknown_or_nonphysics_hkx", "generic_hknp_physics"}:
            continue
        scanned += 1
        if _hkx_path_contains_binary_marker(path, b"hknpMeshShape", stop_event=stop_event):
            promoted.append(path)
            if len(promoted) >= 8:
                break
        if scanned >= scan_limit:
            break
    if promoted:
        existing_mesh_paths = [path for path in by_role.get("mesh_shape_heavy", []) if path not in set(promoted)]
        by_role["mesh_shape_heavy"] = list(promoted) + existing_mesh_paths
        promoted_set = set(promoted)
        for role in ("small_object_convex", "unknown_or_nonphysics_hkx", "generic_hknp_physics"):
            if role in by_role:
                by_role[role] = [path for path in by_role[role] if path not in promoted_set]


def _hkx_select_balanced_corpus_paths(
    paths: Sequence[Path],
    limit: int,
    *,
    stop_event: Optional[threading.Event] = None,
) -> List[Path]:
    if limit <= 0 or len(paths) <= limit:
        return list(paths)
    by_role: Dict[str, List[Path]] = defaultdict(list)
    for path in paths:
        raise_if_cancelled(stop_event)
        by_role[_hkx_corpus_role_hint_from_path(path)].append(path)
    _hkx_enrich_balanced_corpus_content_hints(by_role, paths, stop_event=stop_event)
    selected: List[Path] = []
    selected_set: set[Path] = set()
    role_order = list(_HKX_REQUIRED_COMPATIBILITY_CORPUS_ROLES) + [
        "generic_hknp_physics",
        "unknown_or_nonphysics_hkx",
    ]
    while len(selected) < limit:
        raise_if_cancelled(stop_event)
        added = False
        for role in role_order:
            candidates = by_role.get(role)
            if not candidates:
                continue
            while candidates and candidates[0] in selected_set:
                candidates.pop(0)
            if not candidates:
                continue
            candidate = candidates.pop(0)
            selected.append(candidate)
            selected_set.add(candidate)
            added = True
            if len(selected) >= limit:
                break
        if not added:
            break
    for path in paths:
        raise_if_cancelled(stop_event)
        if len(selected) >= limit:
            break
        if path not in selected_set:
            selected.append(path)
            selected_set.add(path)
    return sorted(selected, key=lambda item: str(item).casefold())


_HKX_REQUIRED_COMPATIBILITY_CORPUS_ROLES = (
    "small_object_convex",
    "cloak_or_meshphysics",
    "character_havokphysics_or_ragdoll",
    "mesh_shape_heavy",
    "animation_or_metadata",
)


